package holdem

import "errors"

// Streets.
const (
	Preflop = iota
	Flop
	Turn
	River
)

// Player is one hand player's betting state.
type Player struct {
	Stack       int64 // chips behind
	StreetBet   int64 // chips put in on the current street
	Contributed int64 // chips put in during the whole hand
	Folded      bool
	AllIn       bool
	Acted       bool  // acted since the bet last increased
	LastActBet  int64 // current bet right after this player's last action this street, -1 if none
}

// Betting is the no-limit betting state of one hand. Players are indexed from
// the small blind (heads-up: index 0 is the button and small blind).
type Betting struct {
	Players    []*Player
	SmallBlind int64
	BigBlind   int64
	Street     int
	CurrentBet int64 // highest street bet
	MinRaise   int64 // size of the last full bet or raise on this street
	Turn       int   // index to act, -1 when the street needs no more action
}

// NewBetting posts the blinds and sets the first player to act preflop.
func NewBetting(stacks []int64, smallBlind, bigBlind int64) *Betting {
	n := len(stacks)
	if n < 2 {
		panic("need at least 2 players")
	}
	if smallBlind <= 0 || bigBlind < smallBlind {
		panic("invalid blinds")
	}
	b := &Betting{SmallBlind: smallBlind, BigBlind: bigBlind, Street: Preflop, MinRaise: bigBlind}
	for _, s := range stacks {
		if s <= 0 {
			panic("player without chips")
		}
		b.Players = append(b.Players, &Player{Stack: s, LastActBet: -1})
	}
	b.post(0, smallBlind)
	b.post(1, bigBlind)
	b.CurrentBet = b.Players[0].StreetBet
	if b.Players[1].StreetBet > b.CurrentBet {
		b.CurrentBet = b.Players[1].StreetBet
	}
	if b.CurrentBet < bigBlind {
		b.CurrentBet = bigBlind
	}
	first := 2 % n
	if n == 2 {
		first = 0
	}
	b.Turn = b.nextToAct(first)
	return b
}

func (b *Betting) post(i int, amount int64) {
	p := b.Players[i]
	if amount > p.Stack {
		amount = p.Stack
	}
	p.Stack -= amount
	p.StreetBet += amount
	p.Contributed += amount
	if p.Stack == 0 {
		p.AllIn = true
	}
}

// Live returns the number of players who have not folded.
func (b *Betting) Live() int {
	n := 0
	for _, p := range b.Players {
		if !p.Folded {
			n++
		}
	}
	return n
}

func (b *Betting) canAct(p *Player) bool {
	return !p.Folded && !p.AllIn
}

func (b *Betting) needsAction(p *Player) bool {
	return b.canAct(p) && (!p.Acted || p.StreetBet < b.CurrentBet)
}

// nextToAct returns the first player from index `from` (inclusive, clockwise)
// who still has to act, or -1 when the street is complete.
func (b *Betting) nextToAct(from int) int {
	if b.Live() <= 1 {
		return -1
	}
	actors := 0
	for _, p := range b.Players {
		if b.canAct(p) {
			actors++
		}
	}
	n := len(b.Players)
	for k := 0; k < n; k++ {
		i := (from + k) % n
		p := b.Players[i]
		if !b.needsAction(p) {
			continue
		}
		// A lone player who can still act and has matched the bet has nobody
		// to bet against.
		if actors == 1 && p.StreetBet >= b.CurrentBet {
			continue
		}
		return i
	}
	return -1
}

// StreetComplete reports whether nobody has to act on this street.
func (b *Betting) StreetComplete() bool {
	return b.Turn < 0
}

// Closed reports whether no further betting is possible in the hand: one live
// player left, or the street is complete and at most one live player still
// has chips.
func (b *Betting) Closed() bool {
	if b.Live() <= 1 {
		return true
	}
	if b.Turn >= 0 {
		return false
	}
	actors := 0
	for _, p := range b.Players {
		if b.canAct(p) {
			actors++
		}
	}
	return actors <= 1
}

// CanCheck reports whether player i may check.
func (b *Betting) CanCheck(i int) bool {
	return b.Players[i].StreetBet == b.CurrentBet
}

// CanRaise reports whether player i may bet or raise: they have chips beyond a
// call, and either have not acted on this street or face at least a full
// raise since they last acted (a short all-in does not reopen the betting).
func (b *Betting) CanRaise(i int) bool {
	p := b.Players[i]
	if p.StreetBet+p.Stack <= b.CurrentBet {
		return false
	}
	return p.LastActBet < 0 || b.CurrentBet-p.LastActBet >= b.MinRaise
}

// MinRaiseTo returns the smallest legal total street bet for a non all-in
// bet or raise.
func (b *Betting) MinRaiseTo() int64 {
	return b.CurrentBet + b.MinRaise
}

// Act applies an action by player i. For "raise", amount is the player's total
// street bet after the action; it also opens the betting when nobody has bet.
func (b *Betting) Act(i int, action string, amount int64) error {
	if b.Turn < 0 || i != b.Turn {
		return errors.New("not this player's turn")
	}
	p := b.Players[i]
	raised := false
	switch action {
	case "fold":
		p.Folded = true
	case "check":
		if !b.CanCheck(i) {
			return errors.New("cannot check facing a bet")
		}
	case "call":
		if p.StreetBet >= b.CurrentBet {
			return errors.New("nothing to call")
		}
		b.post(i, b.CurrentBet-p.StreetBet)
	case "raise":
		if amount <= b.CurrentBet {
			return errors.New("raise must exceed the current bet")
		}
		max := p.StreetBet + p.Stack
		if amount > max {
			return errors.New("raise exceeds stack")
		}
		if !b.CanRaise(i) {
			return errors.New("betting is not reopened for this player")
		}
		allIn := amount == max
		if !allIn && amount < b.CurrentBet+b.MinRaise {
			return errors.New("raise below minimum")
		}
		if amount-b.CurrentBet >= b.MinRaise {
			b.MinRaise = amount - b.CurrentBet
		}
		b.post(i, amount-p.StreetBet)
		b.CurrentBet = amount
		raised = true
	default:
		return errors.New("unknown action")
	}
	p.Acted = true
	p.LastActBet = b.CurrentBet
	if raised {
		for k, q := range b.Players {
			if k != i && b.canAct(q) {
				q.Acted = false
			}
		}
	}
	b.Turn = b.nextToAct((i + 1) % len(b.Players))
	return nil
}

// NextStreet resets street state and sets the first player to act. It must
// only be called when the current street is complete and betting not closed.
func (b *Betting) NextStreet() {
	if b.Street >= River {
		panic("no street after the river")
	}
	b.Street++
	b.CurrentBet = 0
	b.MinRaise = b.BigBlind
	for _, p := range b.Players {
		p.StreetBet = 0
		p.Acted = false
		p.LastActBet = -1
	}
	first := 0
	if len(b.Players) == 2 {
		first = 1
	}
	b.Turn = b.nextToAct(first)
}

// Pot returns the total contributed by all players.
func (b *Betting) Pot() int64 {
	t := int64(0)
	for _, p := range b.Players {
		t += p.Contributed
	}
	return t
}

// Package holdem implements the chain-independent rules of no-limit Texas
// Hold'em: hand evaluation, side pots and the betting state machine of one
// hand. Cards are indices 0..51 with rank = c % 13 (0 = Two .. 12 = Ace) and
// suit = c / 13.
package holdem

// Hand categories, the high bits of a score.
const (
	HighCard = iota
	OnePair
	TwoPair
	Trips
	Straight
	Flush
	FullHouse
	Quads
	StraightFlush
)

var categoryNames = []string{
	"high card", "pair", "two pair", "three of a kind", "straight",
	"flush", "full house", "four of a kind", "straight flush",
}

// CategoryName names the category of a score.
func CategoryName(score int) string {
	c := Category(score)
	if c < 0 || c >= len(categoryNames) {
		return "?"
	}
	return categoryNames[c]
}

// Category returns the hand category of a score.
func Category(score int) int {
	return score >> 20
}

func makeScore(cat int, ranks ...int) int {
	s := cat << 20
	for i := 0; i < 5; i++ {
		r := 0
		if i < len(ranks) {
			r = ranks[i]
		}
		s |= r << uint(16-4*i)
	}
	return s
}

// straightHigh returns the top rank of the best straight in a rank bitmask,
// 3 for the wheel (A-2-3-4-5), or -1.
func straightHigh(mask int) int {
	for hi := 12; hi >= 4; hi-- {
		m := 0x1f << uint(hi-4)
		if mask&m == m {
			return hi
		}
	}
	wheel := 0xf | 1<<12
	if mask&wheel == wheel {
		return 3
	}
	return -1
}

// topRanks returns up to n highest ranks set in mask, skipping excluded ranks.
func topRanks(mask int, n int, exclude ...int) []int {
	out := []int{}
	for r := 12; r >= 0 && len(out) < n; r-- {
		if mask&(1<<uint(r)) == 0 {
			continue
		}
		skip := false
		for _, e := range exclude {
			if e == r {
				skip = true
			}
		}
		if !skip {
			out = append(out, r)
		}
	}
	return out
}

// Evaluate scores the best five-card hand among 5 to 7 cards. Higher is better;
// equal scores tie.
func Evaluate(cards []int) int {
	if len(cards) < 5 || len(cards) > 7 {
		panic("evaluate needs 5 to 7 cards")
	}
	var counts [13]int
	var suitCount [4]int
	var suitMask [4]int
	rankMask := 0
	for _, c := range cards {
		if c < 0 || c >= 52 {
			panic("invalid card")
		}
		r, s := c%13, c/13
		counts[r]++
		suitCount[s]++
		suitMask[s] |= 1 << uint(r)
		rankMask |= 1 << uint(r)
	}
	flushSuit := -1
	for s := 0; s < 4; s++ {
		if suitCount[s] >= 5 {
			flushSuit = s
		}
	}
	if flushSuit >= 0 {
		if hi := straightHigh(suitMask[flushSuit]); hi >= 0 {
			return makeScore(StraightFlush, hi)
		}
	}
	quad, trip, trip2 := -1, -1, -1
	pairs := []int{}
	for r := 12; r >= 0; r-- {
		switch counts[r] {
		case 4:
			if quad < 0 {
				quad = r
			}
		case 3:
			if trip < 0 {
				trip = r
			} else if trip2 < 0 {
				trip2 = r
			}
		case 2:
			pairs = append(pairs, r)
		}
	}
	if quad >= 0 {
		return makeScore(Quads, append([]int{quad}, topRanks(rankMask, 1, quad)...)...)
	}
	if trip >= 0 {
		pairRank := -1
		if trip2 >= 0 {
			pairRank = trip2
		}
		if len(pairs) > 0 && pairs[0] > pairRank {
			pairRank = pairs[0]
		}
		if pairRank >= 0 {
			return makeScore(FullHouse, trip, pairRank)
		}
	}
	if flushSuit >= 0 {
		return makeScore(Flush, topRanks(suitMask[flushSuit], 5)...)
	}
	if hi := straightHigh(rankMask); hi >= 0 {
		return makeScore(Straight, hi)
	}
	if trip >= 0 {
		return makeScore(Trips, append([]int{trip}, topRanks(rankMask, 2, trip)...)...)
	}
	if len(pairs) >= 2 {
		return makeScore(TwoPair, pairs[0], pairs[1], topRanks(rankMask, 1, pairs[0], pairs[1])[0])
	}
	if len(pairs) == 1 {
		return makeScore(OnePair, append([]int{pairs[0]}, topRanks(rankMask, 3, pairs[0])...)...)
	}
	return makeScore(HighCard, topRanks(rankMask, 5)...)
}

package holdem

// MaxPlayers is the largest number of players in one hand.
const MaxPlayers = 6

// Pot is one main or side pot.
type Pot struct {
	Amount   int64
	Eligible []int // player indices that can win this pot
}

// BuildPots splits contributions into a main pot and side pots. Folded
// players' chips go into the pots but they are never eligible. Chips above the
// largest contribution of any live player form a last pot that only the live
// players with that contribution can win (an uncalled bet returns to its
// owner this way).
func BuildPots(contrib []int64, folded []bool) []Pot {
	levels := []int64{}
	for i, c := range contrib {
		if folded[i] {
			continue
		}
		pos := len(levels)
		dup := false
		for k, l := range levels {
			if l == c {
				dup = true
				break
			}
			if l > c {
				pos = k
				break
			}
		}
		if dup {
			continue
		}
		levels = append(levels, 0)
		copy(levels[pos+1:], levels[pos:])
		levels[pos] = c
	}
	if len(levels) == 0 {
		panic("no live players")
	}
	pots := []Pot{}
	prev := int64(0)
	for li, lvl := range levels {
		last := li == len(levels)-1
		amount := int64(0)
		for _, c := range contrib {
			hi := c
			if !last && hi > lvl {
				hi = lvl
			}
			if hi > prev {
				amount += hi - prev
			}
		}
		eligible := []int{}
		for i, c := range contrib {
			if !folded[i] && c >= lvl {
				eligible = append(eligible, i)
			}
		}
		prev = lvl
		if amount == 0 {
			continue
		}
		if n := len(pots); n > 0 && sameInts(pots[n-1].Eligible, eligible) {
			pots[n-1].Amount += amount
			continue
		}
		pots = append(pots, Pot{Amount: amount, Eligible: eligible})
	}
	return pots
}

func sameInts(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// Distribute awards each pot to its best eligible scores, splitting ties
// equally. The odd chips of a split pot all go to the winner that comes first
// in oddOrder (player indices clockwise from the button). It returns the
// amount won per player; the sum always equals the sum of the pots. It panics
// for more than MaxPlayers scores.
func Distribute(pots []Pot, scores []int, oddOrder []int) []int64 {
	if len(scores) > MaxPlayers {
		panic("too many players")
	}
	var buf [MaxPlayers]int64
	won := buf[:len(scores):len(scores)]
	for _, p := range pots {
		best := -1
		for _, i := range p.Eligible {
			if scores[i] > best {
				best = scores[i]
			}
		}
		winners := []int{}
		for _, i := range p.Eligible {
			if scores[i] == best {
				winners = append(winners, i)
			}
		}
		share := p.Amount / int64(len(winners))
		for _, i := range winners {
			won[i] += share
		}
		rem := p.Amount - share*int64(len(winners))
		if rem > 0 {
			for _, i := range oddOrder {
				if scores[i] == best && contains(winners, i) {
					won[i] += rem
					rem = 0
					break
				}
			}
			if rem > 0 {
				panic("odd chip order misses a winner")
			}
		}
	}
	return won
}

func contains(xs []int, x int) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}

// OddChipOrder returns player indices clockwise starting left of the button,
// for hand players indexed from the small blind (heads-up: index 0 is the
// button). It panics unless 0 <= n <= MaxPlayers.
func OddChipOrder(n int) []int {
	if n < 0 || n > MaxPlayers {
		panic("bad player count")
	}
	var buf [MaxPlayers]int
	out := buf[:n:n]
	if n == 2 {
		out[0], out[1] = 1, 0
		return out
	}
	for i := range out {
		out[i] = i
	}
	return out
}

package poker

import (
	"bytes"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/poker/cards"
)

// Challenge disputes one element of a shuffle or rekey pass during the
// challenge window (protocol.md section 5).
func Challenge(cur realm, tableID, handNo uint64, accused int, kind string, index int, inB64, inProofHex, outB64, outProofHex string) {
	if !challengesEnabled {
		panic("challenges are disabled on this deployment")
	}
	ctx := newCtx(cur)
	sent := sentUgnot(cur)
	t, h, c := handFor(cur, tableID, handNo)
	if h.Phase != phChallenge {
		panic("not in challenge window")
	}
	if ctx.height > h.Deadline {
		panic("challenge window has passed")
	}
	n := h.n()
	if accused < 0 || accused >= n {
		panic("invalid accused index")
	}
	if accused == c {
		panic("cannot challenge yourself")
	}
	if index < 0 || index >= cards.DeckSize {
		panic("invalid deck index")
	}
	bond := t.ChallengeBond
	challengerSeat := t.Seats[h.Players[c].Seat]
	if sent > 0 {
		if sent != bond {
			panic("attached ugnot must equal the challenge bond")
		}
	} else if challengerSeat.Stack < bond {
		panic("stack too small for the challenge bond")
	}

	in, err := cards.DecodeElement(inB64)
	if err != nil {
		panic("in: " + err.Error())
	}
	out, err := cards.DecodeElement(outB64)
	if err != nil {
		panic("out: " + err.Error())
	}
	inProof, err := cards.DecodeHex(inProofHex, cards.ProofLen)
	if err != nil {
		panic("in proof: " + err.Error())
	}
	outProof, err := cards.DecodeHex(outProofHex, cards.ProofLen)
	if err != nil {
		panic("out proof: " + err.Error())
	}
	seed := seedBytes(h.Players[accused])

	var inRoot, outRoot []byte
	inPos := index
	switch kind {
	case "shuffle":
		if accused == 0 {
			inRoot = cards.CanonRoot()
		} else {
			inRoot = rootAt(h, accused-1)
		}
		outRoot = rootAt(h, accused)
		inPos = cards.Permutation(seed)[index]
	case "rekey":
		inRoot = rootAt(h, n+accused-1)
		outRoot = rootAt(h, n+accused)
	default:
		panic("kind must be shuffle or rekey")
	}
	if !cards.VerifyProof(inRoot, in, inPos, inProof) {
		panic("invalid input proof")
	}
	if !cards.VerifyProof(outRoot, out, index, outProof) {
		panic("invalid output proof")
	}

	e := cards.ShuffleKey(seed)
	var guilty bool
	if kind == "shuffle" {
		guilty = !bytes.Equal(powModP(in, e), out)
	} else {
		k := cards.CardKey(seed, index)
		guilty = !bytes.Equal(powModP(out, e), powModP(in, k))
	}

	rec := ChallengeRecord{Challenger: c, Accused: accused, Kind: kind, Index: index, Guilty: guilty}
	h.Result.Challenges = append(h.Result.Challenges, rec)
	accusedSeat := t.Seats[h.Players[accused].Seat]
	if guilty {
		if sent > 0 {
			ctx.pay(ctx.caller, sent)
		}
		t.abort(ctx, []int{accused}, true)
		return
	}
	if sent == 0 {
		challengerSeat.Stack -= bond
	}
	accusedSeat.Stack += bond
}

func rootAt(h *Hand, pass int) []byte {
	b, err := cards.DecodeHex(h.Roots[pass], 32)
	if err != nil {
		panic("corrupt root")
	}
	return b
}

package poker

import (
	"strconv"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/poker/cards"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/poker/holdem"
)

// Hand phases.
const (
	phShuffle = iota
	phRekey
	phDealHole
	phPreflop
	phDealFlop
	phFlop
	phDealTurn
	phTurn
	phDealRiver
	phRiver
	phReveal
	phChallenge
	phDone
)

var phaseNames = []string{
	"shuffle", "rekey", "deal_hole", "preflop", "deal_flop", "flop",
	"deal_turn", "turn", "deal_river", "river", "reveal", "challenge", "done",
}

// HandPlayer is a seat's participation in one hand.
type HandPlayer struct {
	Seat     int
	Owner    address
	Commit   string         // hex
	Seed     string         // hex, after reveal
	Keys     map[int]string // position -> hex card key
	Revealed bool
	Accepted bool
}

// ChallengeRecord is one resolved challenge.
type ChallengeRecord struct {
	Challenger int
	Accused    int
	Kind       string
	Index      int
	Guilty     bool
}

// Result is the outcome of a hand. Credits are what settlement adds to each
// hand player's stack (winnings, or refund plus penalty share on abort).
type Result struct {
	Aborted    bool
	Convicted  []int
	Stallers   []int
	Credits    []int64
	Scores     []int
	Challenges []ChallengeRecord
}

// Hand is the state of the current or last hand of a table.
type Hand struct {
	No       uint64
	Phase    int
	Players  []*HandPlayer
	Bet      *holdem.Betting
	Roots    []string // hex root per accepted deck pass
	Owing    []bool   // per player, for deal steps
	Deadline int64
	Cards    []int // official card per position, after reveal
	Result   *Result
	Settled  bool // contributions have been paid out or refunded
}

// maxSeats is the largest table; per-player buffers are sized by it.
const maxSeats = holdem.MaxPlayers

// n is the number of players in the hand, at most maxSeats.
func (h *Hand) n() int { return len(h.Players) }

func (h *Hand) playerIndex(seat int) int {
	for j, p := range h.Players {
		if p.Seat == seat {
			return j
		}
	}
	return -1
}

func isBettingPhase(ph int) bool {
	return ph == phPreflop || ph == phFlop || ph == phTurn || ph == phRiver
}

func isDealPhase(ph int) bool {
	return ph == phDealHole || ph == phDealFlop || ph == phDealTurn || ph == phDealRiver
}

// turnIndex is the player expected to act in an in-turn phase, else -1.
func (h *Hand) turnIndex() int {
	switch {
	case h.Phase == phShuffle:
		return len(h.Roots)
	case h.Phase == phRekey:
		return len(h.Roots) - h.n()
	case isBettingPhase(h.Phase):
		return h.Bet.Turn
	}
	return -1
}

// owedPositions lists the positions player j must share keys for in the
// current deal step, ascending.
func (h *Hand) owedPositions(j int) []int {
	n := h.n()
	out := []int{}
	switch h.Phase {
	case phDealHole:
		for i := 0; i < 2*n; i++ {
			if i/2 != j {
				out = append(out, i)
			}
		}
	case phDealFlop:
		out = append(out, 2*n, 2*n+1, 2*n+2)
	case phDealTurn:
		out = append(out, 2*n+3)
	case phDealRiver:
		out = append(out, 2*n+4)
	}
	return out
}

func (t *Table) eligible(i int) bool {
	s := t.Seats[i]
	return s != nil && !s.SittingOut && !s.Leaving && s.Stack >= t.BigBlind
}

// StartHand moves the button, posts blinds and opens the shuffle.
func StartHand(cur realm, tableID uint64) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t := getTable(tableID)
	t.authSeat(ctx.caller)
	if t.Hand != nil && t.Hand.Phase != phDone {
		panic("a hand is in progress")
	}
	m := t.MaxPlayers
	seats := []int{}
	for k := 1; k <= m; k++ {
		i := (t.Button + k + m) % m
		if t.eligible(i) {
			seats = append(seats, i)
		}
	}
	if len(seats) < 2 {
		panic("need at least 2 active players with a stack of at least the big blind")
	}
	// seats starts with the new button.
	button := seats[0]
	order := []int{}
	if len(seats) == 2 {
		order = append(order, seats[0], seats[1])
	} else {
		order = append(order, seats[1:]...)
		order = append(order, button)
	}
	t.Button = button
	t.HandNo++
	for _, s := range t.Seats {
		if s != nil {
			s.Waiting = false
		}
	}
	if len(order) > maxSeats {
		panic("too many players")
	}
	var stackBuf [maxSeats]int64
	stacks := stackBuf[:len(order):len(order)]
	players := make([]*HandPlayer, len(order))
	for j, si := range order {
		stacks[j] = t.Seats[si].Stack
		players[j] = &HandPlayer{Seat: si, Owner: t.Seats[si].Owner, Keys: map[int]string{}}
	}
	h := &Hand{
		No:       t.HandNo,
		Phase:    phShuffle,
		Players:  players,
		Bet:      holdem.NewBetting(stacks, t.SmallBlind, t.BigBlind),
		Deadline: ctx.height + t.ActionTimeout,
	}
	t.Hand = h
	t.syncStacks()
}

func (t *Table) syncStacks() {
	for j, p := range t.Hand.Players {
		t.Seats[p.Seat].Stack = t.Hand.Bet.Players[j].Stack
	}
}

// handFor validates the table, hand number and caller, and returns the hand
// and the caller's hand index.
func handFor(cur realm, tableID, handNo uint64) (*Table, *Hand, int) {
	t := getTable(tableID)
	h := t.Hand
	if h == nil || h.No != handNo || handNo != t.HandNo {
		panic("stale or unknown hand number")
	}
	if h.Phase == phDone {
		panic("hand is over")
	}
	seat := t.authSeat(cur.Previous().Address())
	j := h.playerIndex(seat)
	if j < 0 {
		panic("caller is not in this hand")
	}
	return t, h, j
}

// SubmitShuffle records the caller's commitment and shuffled deck.
func SubmitShuffle(cur realm, tableID, handNo uint64, commitHex, deckB64 string) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t, h, j := handFor(cur, tableID, handNo)
	if h.Phase != phShuffle {
		panic("not in shuffle phase")
	}
	if j != h.turnIndex() {
		panic("not this player's turn to shuffle")
	}
	if _, err := cards.DecodeHex(commitHex, 32); err != nil {
		panic("commit: " + err.Error())
	}
	t.acceptDeck(h, deckB64)
	h.Players[j].Commit = commitHex
	h.Deadline = ctx.height + t.ActionTimeout
	if len(h.Roots) == h.n() {
		h.Phase = phRekey
	}
}

// SubmitRekey records the caller's re-keyed deck.
func SubmitRekey(cur realm, tableID, handNo uint64, deckB64 string) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t, h, j := handFor(cur, tableID, handNo)
	if h.Phase != phRekey {
		panic("not in rekey phase")
	}
	if j != h.turnIndex() {
		panic("not this player's turn to rekey")
	}
	t.acceptDeck(h, deckB64)
	h.Deadline = ctx.height + t.ActionTimeout
	if len(h.Roots) == 2*h.n() {
		h.startDeal(ctx, t, phDealHole)
	}
}

func (t *Table) acceptDeck(h *Hand, deckB64 string) {
	deck, root, err := cards.ParseDeck(deckB64)
	if err != nil {
		panic("deck: " + err.Error())
	}
	h.Roots = append(h.Roots, cards.EncodeHex(root))
	t.Deck = string(deck)
	t.DeckHand = h.No
}

func (h *Hand) startDeal(ctx *txCtx, t *Table, phase int) {
	h.Phase = phase
	var owing [maxSeats]bool
	h.Owing = owing[:h.n():h.n()]
	for j := range h.Owing {
		h.Owing[j] = true
	}
	h.Deadline = ctx.height + t.ActionTimeout
}

// ShareKeys publishes the caller's card keys for the current deal step.
func ShareKeys(cur realm, tableID, handNo uint64, keysHex string) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t, h, j := handFor(cur, tableID, handNo)
	if !isDealPhase(h.Phase) {
		panic("not in a deal phase")
	}
	if !h.Owing[j] {
		panic("keys already shared")
	}
	pos := h.owedPositions(j)
	if len(keysHex) != 64*len(pos) {
		panic("expected " + strconv.Itoa(len(pos)) + " keys")
	}
	if _, err := cards.DecodeHex(keysHex, 32*len(pos)); err != nil {
		panic("keys: " + err.Error())
	}
	p := h.Players[j]
	for k, i := range pos {
		p.Keys[i] = keysHex[64*k : 64*(k+1)]
	}
	h.Owing[j] = false
	for _, o := range h.Owing {
		if o {
			return
		}
	}
	h.Owing = nil
	switch h.Phase {
	case phDealHole:
		h.Phase = phPreflop
	case phDealFlop:
		h.Bet.NextStreet()
		h.Phase = phFlop
	case phDealTurn:
		h.Bet.NextStreet()
		h.Phase = phTurn
	case phDealRiver:
		h.Bet.NextStreet()
		h.Phase = phRiver
	}
	h.Deadline = ctx.height + t.ActionTimeout
	t.afterBetting(ctx)
}

// Act applies a betting action by the player to act.
func Act(cur realm, tableID, handNo uint64, action string, amount int64) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t, h, j := handFor(cur, tableID, handNo)
	if !isBettingPhase(h.Phase) {
		panic("not in a betting phase")
	}
	t.applyAction(ctx, j, action, amount)
}

func (t *Table) applyAction(ctx *txCtx, j int, action string, amount int64) {
	h := t.Hand
	if err := h.Bet.Act(j, action, amount); err != nil {
		panic(err.Error())
	}
	t.syncStacks()
	h.Deadline = ctx.height + t.ActionTimeout
	t.afterBetting(ctx)
}

// afterBetting moves on once the street needs no more action.
func (t *Table) afterBetting(ctx *txCtx) {
	h := t.Hand
	if !isBettingPhase(h.Phase) || !h.Bet.StreetComplete() {
		return
	}
	if h.Bet.Closed() || h.Phase == phRiver {
		h.Phase = phReveal
		h.Deadline = ctx.height + t.ActionTimeout
		return
	}
	switch h.Phase {
	case phPreflop:
		h.startDeal(ctx, t, phDealFlop)
	case phFlop:
		h.startDeal(ctx, t, phDealTurn)
	case phTurn:
		h.startDeal(ctx, t, phDealRiver)
	}
}

// RevealSeed opens the caller's seed; published card keys are checked at once.
func RevealSeed(cur realm, tableID, handNo uint64, seedHex string) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t, h, j := handFor(cur, tableID, handNo)
	if h.Phase != phReveal {
		panic("not in reveal phase")
	}
	p := h.Players[j]
	if p.Revealed {
		panic("seed already revealed")
	}
	seed, err := cards.DecodeHex(seedHex, 32)
	if err != nil {
		panic("seed: " + err.Error())
	}
	if cards.EncodeHex(cards.Commit(seed)) != p.Commit {
		panic("seed does not match commitment")
	}
	p.Seed = seedHex
	p.Revealed = true
	for pos, key := range p.Keys {
		if cards.EncodeHex(cards.CardKey(seed, pos)) != key {
			t.abort(ctx, []int{j}, true)
			return
		}
	}
	for _, q := range h.Players {
		if !q.Revealed {
			return
		}
	}
	t.showdown(ctx)
}

func seedBytes(p *HandPlayer) []byte {
	b, err := cards.DecodeHex(p.Seed, 32)
	if err != nil {
		panic("seed missing")
	}
	return b
}

// showdown derives all cards from the seeds and computes the payouts.
func (t *Table) showdown(ctx *txCtx) {
	h := t.Hand
	n := h.n()
	perms := make([][]int, n)
	for j, p := range h.Players {
		perms[j] = cards.Permutation(seedBytes(p))
	}
	h.Cards = cards.OfficialCards(perms)
	board := h.Cards[2*n : 2*n+5]
	var contribBuf [maxSeats]int64
	var foldedBuf [maxSeats]bool
	var scoreBuf [maxSeats]int
	contrib, folded, scores := contribBuf[:n:n], foldedBuf[:n:n], scoreBuf[:n:n]
	for j, bp := range h.Bet.Players {
		contrib[j] = bp.Contributed
		folded[j] = bp.Folded
		if !bp.Folded {
			seven := []int{h.Cards[2*j], h.Cards[2*j+1]}
			seven = append(seven, board...)
			scores[j] = holdem.Evaluate(seven)
		} else {
			scores[j] = -1
		}
	}
	pots := holdem.BuildPots(contrib, folded)
	won := holdem.Distribute(pots, scores, holdem.OddChipOrder(n))
	h.Result = &Result{Credits: won, Scores: scores}
	if !challengesEnabled {
		t.finalize(ctx)
		return
	}
	h.Phase = phChallenge
	h.Deadline = ctx.height + t.ChallengeWindow
}

// finalize pays the recorded result and ends the hand.
func (t *Table) finalize(ctx *txCtx) {
	h := t.Hand
	for j, p := range h.Players {
		t.Seats[p.Seat].Stack += h.Result.Credits[j]
	}
	h.Settled = true
	h.Phase = phDone
	t.cleanupSeats(ctx)
}

// cleanupSeats pays out and frees seats marked leaving.
func (t *Table) cleanupSeats(ctx *txCtx) {
	for i, s := range t.Seats {
		if s != nil && s.Leaving {
			t.removeSeat(ctx, i)
		}
	}
}

// abort ends the hand without a showdown: all contributions are refunded and
// each penalized player's whole stack is split equally among the other hand
// players (remainder to the lowest hand index), then the penalized players
// are removed from the table.
func (t *Table) abort(ctx *txCtx, penalized []int, convicted bool) {
	h := t.Hand
	n := h.n()
	var creditBuf [maxSeats]int64
	credits := creditBuf[:n:n]
	if !h.Settled {
		for j, p := range h.Players {
			c := h.Bet.Players[j].Contributed
			t.Seats[p.Seat].Stack += c
			credits[j] = c
		}
	}
	var penBuf [maxSeats]bool
	isPen := penBuf[:n:n]
	for _, j := range penalized {
		isPen[j] = true
	}
	recipients := []int{}
	for j := 0; j < n; j++ {
		if !isPen[j] {
			recipients = append(recipients, j)
		}
	}
	if len(recipients) > 0 {
		for _, j := range penalized {
			s := t.Seats[h.Players[j].Seat]
			amount := s.Stack
			s.Stack = 0
			credits[j] = 0
			share := amount / int64(len(recipients))
			rem := amount - share*int64(len(recipients))
			for k, r := range recipients {
				add := share
				if k == 0 {
					add += rem
				}
				t.Seats[h.Players[r].Seat].Stack += add
				credits[r] += add
			}
		}
	}
	res := &Result{Aborted: true, Credits: credits}
	if h.Result != nil {
		res.Challenges = h.Result.Challenges
	}
	if convicted {
		res.Convicted = penalized
	} else {
		res.Stallers = penalized
	}
	h.Result = res
	h.Settled = true
	h.Phase = phDone
	for _, j := range penalized {
		t.removeSeat(ctx, h.Players[j].Seat)
	}
	t.cleanupSeats(ctx)
}

// Accept agrees with the result; when all hand players accept, the hand is
// finalized without waiting for the window.
func Accept(cur realm, tableID, handNo uint64) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t, h, j := handFor(cur, tableID, handNo)
	if h.Phase != phChallenge {
		panic("not in challenge window")
	}
	h.Players[j].Accepted = true
	for _, p := range h.Players {
		if !p.Accepted {
			return
		}
	}
	t.finalize(ctx)
}

// Finalize settles the hand once the challenge window has passed.
func Finalize(cur realm, tableID uint64) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t := getTable(tableID)
	h := t.Hand
	if h == nil || h.Phase != phChallenge {
		panic("no hand in challenge window")
	}
	if ctx.height <= h.Deadline {
		panic("challenge window still open")
	}
	t.finalize(ctx)
}

// Timeout applies the stall rules once the current deadline has passed.
func Timeout(cur realm, tableID uint64) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t := getTable(tableID)
	h := t.Hand
	if h == nil || h.Phase == phDone {
		panic("no hand in progress")
	}
	if ctx.height <= h.Deadline {
		panic("deadline not reached")
	}
	switch {
	case isBettingPhase(h.Phase):
		j := h.Bet.Turn
		if h.Bet.CanCheck(j) {
			t.applyAction(ctx, j, "check", 0)
		} else {
			t.applyAction(ctx, j, "fold", 0)
		}
	case h.Phase == phShuffle || h.Phase == phRekey:
		t.abort(ctx, []int{h.turnIndex()}, false)
	case isDealPhase(h.Phase):
		stallers := []int{}
		for j, o := range h.Owing {
			if o {
				stallers = append(stallers, j)
			}
		}
		t.abort(ctx, stallers, false)
	case h.Phase == phReveal:
		stallers := []int{}
		for j, p := range h.Players {
			if !p.Revealed {
				stallers = append(stallers, j)
			}
		}
		t.abort(ctx, stallers, false)
	case h.Phase == phChallenge:
		t.finalize(ctx)
	}
}

// Package poker is a trustless no-limit Texas Hold'em realm. See
// docs/protocol.md for the normative protocol and API.
package poker

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
)

const denom = "ugnot"

// Seat is an occupied table seat.
type Seat struct {
	Owner      address
	Session    address // empty when the owner acts directly
	Stack      int64
	SittingOut bool
	Leaving    bool // pay out and free the seat when the current hand ends
	Waiting    bool // joined during a hand, plays from the next one
}

// Table is a persistent cash table.
type Table struct {
	ID              uint64
	SmallBlind      int64
	BigBlind        int64
	MinBuyIn        int64
	MaxBuyIn        int64
	MaxPlayers      int
	ActionTimeout   int64
	ChallengeWindow int64
	ChallengeBond   int64

	Seats    []*Seat
	Button   int // seat index of the last button, -1 before the first hand
	HandNo   uint64
	Hand     *Hand
	Deck     string // raw bytes of the latest deck pass of hand DeckHand
	DeckHand uint64
}

var tables []*Table

// txCtx carries per-transaction values into helpers.
type txCtx struct {
	bk     banker.Banker
	self   address
	caller address
	height int64
}

func newCtx(cur realm) *txCtx {
	return &txCtx{
		bk:     banker.NewBanker(banker.BankerTypeRealmSend, cur),
		self:   cur.Address(),
		caller: cur.Previous().Address(),
		height: runtime.ChainHeight(),
	}
}

func (c *txCtx) pay(to address, amount int64) {
	if amount <= 0 {
		return
	}
	c.bk.SendCoins(c.self, to, chain.Coins{chain.NewCoin(denom, amount)})
}

// sentUgnot returns the ugnot attached to a direct user call and rejects any
// other denomination.
func sentUgnot(cur realm) int64 {
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		return 0
	}
	if !cur.Previous().IsUserCall() {
		panic("coins are only accepted from a direct user call")
	}
	total := int64(0)
	for _, c := range sent {
		if c.Denom != denom {
			panic("only ugnot is accepted")
		}
		total += c.Amount
	}
	return total
}

func assertNoSend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this call does not accept coins")
	}
}

func getTable(id uint64) *Table {
	if id == 0 || id > uint64(len(tables)) {
		panic("table not found")
	}
	return tables[id-1]
}

// seatOf returns the seat index for which addr is owner or session, or -1.
func (t *Table) seatOf(addr address) int {
	for i, s := range t.Seats {
		if s != nil && (s.Owner == addr || (s.Session != "" && s.Session == addr)) {
			return i
		}
	}
	return -1
}

func (t *Table) ownerSeat(addr address) int {
	for i, s := range t.Seats {
		if s != nil && s.Owner == addr {
			return i
		}
	}
	return -1
}

// handLive reports whether a hand is in progress with chips still escrowed.
func (t *Table) handLive() bool {
	return t.Hand != nil && !t.Hand.Settled
}

// inLiveHand reports whether seat i plays the live hand.
func (t *Table) inLiveHand(seat int) bool {
	if !t.handLive() {
		return false
	}
	return t.Hand.playerIndex(seat) >= 0
}

// CreateTable creates a table and returns its id.
func CreateTable(cur realm, smallBlind, bigBlind, minBuyIn, maxBuyIn int64, maxPlayers int, actionTimeoutBlocks, challengeWindowBlocks, challengeBond int64) uint64 {
	assertNoSend(cur)
	if smallBlind <= 0 || bigBlind < smallBlind {
		panic("invalid blinds")
	}
	if minBuyIn < bigBlind || maxBuyIn < minBuyIn {
		panic("invalid buy-in limits")
	}
	if maxPlayers < 2 || maxPlayers > maxSeats {
		panic("maxPlayers must be between 2 and 6")
	}
	if actionTimeoutBlocks <= 0 || challengeWindowBlocks <= 0 {
		panic("timeouts must be positive")
	}
	if challengeBond <= 0 {
		panic("challenge bond must be positive")
	}
	t := &Table{
		ID:              uint64(len(tables) + 1),
		SmallBlind:      smallBlind,
		BigBlind:        bigBlind,
		MinBuyIn:        minBuyIn,
		MaxBuyIn:        maxBuyIn,
		MaxPlayers:      maxPlayers,
		ActionTimeout:   actionTimeoutBlocks,
		ChallengeWindow: challengeWindowBlocks,
		ChallengeBond:   challengeBond,
		Seats:           make([]*Seat, maxPlayers),
		Button:          -1,
	}
	tables = append(tables, t)
	return t.ID
}

// Join takes a free seat with the attached ugnot minus gasAllowance as stack and
// forwards gasAllowance to the session address.
func Join(cur realm, tableID uint64, session string, gasAllowance int64) {
	ctx := newCtx(cur)
	t := getTable(tableID)
	sent := sentUgnot(cur)
	owner := ctx.caller
	if t.seatOf(owner) >= 0 {
		panic("already seated at this table")
	}
	if gasAllowance < 0 {
		panic("negative gas allowance")
	}
	sess := address(session)
	if session == "" {
		if gasAllowance != 0 {
			panic("gas allowance needs a session address")
		}
	} else {
		if !sess.IsValid() {
			panic("invalid session address")
		}
		if sess == owner {
			panic("session must differ from owner")
		}
		if t.seatOf(sess) >= 0 {
			panic("session address already used at this table")
		}
	}
	stack := sent - gasAllowance
	if stack < t.MinBuyIn || stack > t.MaxBuyIn {
		panic("buy-in must be between " + strconv.FormatInt(t.MinBuyIn, 10) + " and " + strconv.FormatInt(t.MaxBuyIn, 10) + " ugnot")
	}
	free := -1
	for i, s := range t.Seats {
		if s == nil {
			free = i
			break
		}
	}
	if free < 0 {
		panic("table is full")
	}
	t.Seats[free] = &Seat{Owner: owner, Session: sess, Stack: stack, Waiting: t.handLive()}
	if gasAllowance > 0 {
		ctx.pay(sess, gasAllowance)
	}
}

// TopUp adds the attached ugnot to the caller's stack between hands.
func TopUp(cur realm, tableID uint64) {
	ctx := newCtx(cur)
	t := getTable(tableID)
	sent := sentUgnot(cur)
	i := t.ownerSeat(ctx.caller)
	if i < 0 {
		panic("only the seat owner can top up")
	}
	if t.inLiveHand(i) {
		panic("cannot top up during a hand")
	}
	if sent <= 0 {
		panic("no ugnot attached")
	}
	s := t.Seats[i]
	if s.Stack+sent > t.MaxBuyIn {
		panic("stack would exceed max buy-in")
	}
	s.Stack += sent
}

// Leave pays out the stack, or marks the seat leaving until the hand ends.
func Leave(cur realm, tableID uint64) {
	assertNoSend(cur)
	ctx := newCtx(cur)
	t := getTable(tableID)
	i := t.ownerSeat(ctx.caller)
	if i < 0 {
		panic("only the seat owner can leave")
	}
	if t.inLiveHand(i) {
		t.Seats[i].Leaving = true
		return
	}
	t.removeSeat(ctx, i)
}

func (t *Table) removeSeat(ctx *txCtx, i int) {
	s := t.Seats[i]
	if s == nil {
		return
	}
	stack := s.Stack
	t.Seats[i] = nil
	ctx.pay(s.Owner, stack)
}

// SitOut skips the caller from the next hand on.
func SitOut(cur realm, tableID uint64) {
	assertNoSend(cur)
	t := getTable(tableID)
	i := t.authSeat(cur.Previous().Address())
	t.Seats[i].SittingOut = true
}

// SitIn makes the caller eligible again from the next hand.
func SitIn(cur realm, tableID uint64) {
	assertNoSend(cur)
	t := getTable(tableID)
	i := t.authSeat(cur.Previous().Address())
	t.Seats[i].SittingOut = false
}

func (t *Table) authSeat(addr address) int {
	i := t.seatOf(addr)
	if i < 0 {
		panic("caller is not seated at this table")
	}
	return i
}

// escrow returns the ugnot the realm must hold for this table.
func (t *Table) escrow() int64 {
	total := int64(0)
	for _, s := range t.Seats {
		if s != nil {
			total += s.Stack
		}
	}
	if t.handLive() {
		total += t.Hand.Bet.Pot()
	}
	return total
}

// totalEscrow is the ugnot the realm must hold across all tables.
func totalEscrow() int64 {
	total := int64(0)
	for _, t := range tables {
		total += t.escrow()
	}
	return total
}

// ChallengesEnabled reports whether this deployment accepts challenges.
func ChallengesEnabled() bool {
	return challengesEnabled
}

package poker

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/poker/cards"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/poker/holdem"
)

func i64s(v int64) string { return "\"" + strconv.FormatInt(v, 10) + "\"" }
func itoa(v int) string   { return strconv.Itoa(v) }
func qs(s string) string  { return "\"" + s + "\"" }

func bools(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func intList(xs []int) string {
	var b strings.Builder
	b.WriteByte('[')
	for i, x := range xs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(itoa(x))
	}
	b.WriteByte(']')
	return b.String()
}

func (t *Table) summaryJSON(b *strings.Builder) {
	b.WriteString("{\"id\":" + strconv.FormatUint(t.ID, 10))
	b.WriteString(",\"smallBlind\":" + i64s(t.SmallBlind))
	b.WriteString(",\"bigBlind\":" + i64s(t.BigBlind))
	b.WriteString(",\"minBuyIn\":" + i64s(t.MinBuyIn))
	b.WriteString(",\"maxBuyIn\":" + i64s(t.MaxBuyIn))
	b.WriteString(",\"maxPlayers\":" + itoa(t.MaxPlayers))
	b.WriteString(",\"actionTimeoutBlocks\":" + strconv.FormatInt(t.ActionTimeout, 10))
	b.WriteString(",\"challengeWindowBlocks\":" + strconv.FormatInt(t.ChallengeWindow, 10))
	b.WriteString(",\"challengeBond\":" + i64s(t.ChallengeBond))
	b.WriteString(",\"button\":" + itoa(t.Button))
	b.WriteString(",\"handNo\":" + strconv.FormatUint(t.HandNo, 10))
	seated := 0
	for _, s := range t.Seats {
		if s != nil {
			seated++
		}
	}
	b.WriteString(",\"seated\":" + itoa(seated))
	phase := ""
	if t.Hand != nil {
		phase = phaseNames[t.Hand.Phase]
	}
	b.WriteString(",\"phase\":" + qs(phase) + "}")
}

// ListTables returns a JSON array of table summaries.
func ListTables() string {
	var b strings.Builder
	b.WriteString("[")
	for i, t := range tables {
		if i > 0 {
			b.WriteString(",")
		}
		t.summaryJSON(&b)
	}
	b.WriteString("]")
	return b.String()
}

// GetTable returns the full table and hand state as JSON.
func GetTable(tableID uint64) string {
	t := getTable(tableID)
	var b strings.Builder
	b.WriteString("{\"id\":" + strconv.FormatUint(t.ID, 10))
	b.WriteString(",\"smallBlind\":" + i64s(t.SmallBlind))
	b.WriteString(",\"bigBlind\":" + i64s(t.BigBlind))
	b.WriteString(",\"minBuyIn\":" + i64s(t.MinBuyIn))
	b.WriteString(",\"maxBuyIn\":" + i64s(t.MaxBuyIn))
	b.WriteString(",\"maxPlayers\":" + itoa(t.MaxPlayers))
	b.WriteString(",\"actionTimeoutBlocks\":" + strconv.FormatInt(t.ActionTimeout, 10))
	b.WriteString(",\"challengeWindowBlocks\":" + strconv.FormatInt(t.ChallengeWindow, 10))
	b.WriteString(",\"challengeBond\":" + i64s(t.ChallengeBond))
	b.WriteString(",\"height\":" + strconv.FormatInt(runtime.ChainHeight(), 10))
	b.WriteString(",\"button\":" + itoa(t.Button))
	b.WriteString(",\"handNo\":" + strconv.FormatUint(t.HandNo, 10))
	b.WriteString(",\"seats\":[")
	for i, s := range t.Seats {
		if i > 0 {
			b.WriteString(",")
		}
		if s == nil {
			b.WriteString("null")
			continue
		}
		b.WriteString("{\"seat\":" + itoa(i))
		b.WriteString(",\"owner\":" + qs(s.Owner.String()))
		b.WriteString(",\"session\":" + qs(s.Session.String()))
		b.WriteString(",\"stack\":" + i64s(s.Stack))
		b.WriteString(",\"sittingOut\":" + bools(s.SittingOut))
		b.WriteString(",\"leaving\":" + bools(s.Leaving))
		b.WriteString(",\"waiting\":" + bools(s.Waiting) + "}")
	}
	b.WriteString("],\"hand\":")
	if t.Hand == nil {
		b.WriteString("null}")
		return b.String()
	}
	t.Hand.writeJSON(&b)
	b.WriteString("}")
	return b.String()
}

func (h *Hand) writeJSON(b *strings.Builder) {
	n := h.n()
	b.WriteString("{\"handNo\":" + strconv.FormatUint(h.No, 10))
	b.WriteString(",\"phase\":" + qs(phaseNames[h.Phase]))
	b.WriteString(",\"players\":[")
	for j, p := range h.Players {
		bp := h.Bet.Players[j]
		if j > 0 {
			b.WriteString(",")
		}
		b.WriteString("{\"seat\":" + itoa(p.Seat))
		b.WriteString(",\"owner\":" + qs(p.Owner.String()))
		b.WriteString(",\"commit\":" + qs(p.Commit))
		b.WriteString(",\"contributed\":" + i64s(bp.Contributed))
		b.WriteString(",\"streetBet\":" + i64s(bp.StreetBet))
		b.WriteString(",\"folded\":" + bools(bp.Folded))
		b.WriteString(",\"allIn\":" + bools(bp.AllIn))
		b.WriteString(",\"acted\":" + bools(bp.Acted))
		canRaise := isBettingPhase(h.Phase) && !bp.Folded && !bp.AllIn && h.Bet.CanRaise(j)
		b.WriteString(",\"canRaise\":" + bools(canRaise))
		b.WriteString(",\"revealed\":" + bools(p.Revealed))
		b.WriteString(",\"accepted\":" + bools(p.Accepted))
		b.WriteString(",\"seed\":" + qs(p.Seed))
		b.WriteString(",\"keys\":{")
		first := true
		for pos := 0; pos < cards.DeckSize; pos++ {
			k, ok := p.Keys[pos]
			if !ok {
				continue
			}
			if !first {
				b.WriteString(",")
			}
			first = false
			b.WriteString(qs(itoa(pos)) + ":" + qs(k))
		}
		b.WriteString("}}")
	}
	b.WriteString("]")
	b.WriteString(",\"turn\":" + itoa(h.turnIndex()))
	owing := []int{}
	if isDealPhase(h.Phase) {
		for j, o := range h.Owing {
			if o {
				owing = append(owing, j)
			}
		}
	} else if h.Phase == phReveal {
		for j, p := range h.Players {
			if !p.Revealed {
				owing = append(owing, j)
			}
		}
	}
	b.WriteString(",\"owing\":" + intList(owing))
	b.WriteString(",\"deadline\":" + strconv.FormatInt(h.Deadline, 10))
	b.WriteString(",\"pot\":" + i64s(h.Bet.Pot()))
	b.WriteString(",\"currentBet\":" + i64s(h.Bet.CurrentBet))
	b.WriteString(",\"minRaise\":" + i64s(h.Bet.MinRaise))
	b.WriteString(",\"deckSeq\":" + itoa(len(h.Roots)))
	b.WriteString(",\"roots\":[")
	for i, r := range h.Roots {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(qs(r))
	}
	b.WriteString("]")
	if h.Cards != nil {
		b.WriteString(",\"board\":" + intList(h.Cards[2*n:2*n+5]))
		b.WriteString(",\"cards\":{")
		for i, c := range h.Cards {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(qs(itoa(i)) + ":" + itoa(c))
		}
		b.WriteString("}")
	} else {
		b.WriteString(",\"board\":[],\"cards\":{}")
	}
	b.WriteString(",\"result\":")
	if h.Result == nil {
		b.WriteString("null}")
		return
	}
	r := h.Result
	b.WriteString("{\"aborted\":" + bools(r.Aborted))
	b.WriteString(",\"convicted\":" + intList(r.Convicted))
	b.WriteString(",\"stallers\":" + intList(r.Stallers))
	b.WriteString(",\"payouts\":{")
	for j, c := range r.Credits {
		if j > 0 {
			b.WriteString(",")
		}
		b.WriteString(qs(itoa(j)) + ":" + i64s(c))
	}
	b.WriteString("},\"hands\":{")
	first := true
	for j, s := range r.Scores {
		if s < 0 {
			continue
		}
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString(qs(itoa(j)) + ":" + qs(holdem.CategoryName(s)))
	}
	b.WriteString("},\"challenges\":[")
	for i, c := range r.Challenges {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("{\"challenger\":" + itoa(c.Challenger) + ",\"accused\":" + itoa(c.Accused) +
			",\"kind\":" + qs(c.Kind) + ",\"index\":" + itoa(c.Index) + ",\"guilty\":" + bools(c.Guilty) + "}")
	}
	b.WriteString("]}}")
}

// GetDeck returns the latest deck pass of the current hand as standard base64,
// or "" before the first pass.
func GetDeck(tableID uint64) string {
	t := getTable(tableID)
	if t.Hand == nil || t.DeckHand != t.HandNo || len(t.Hand.Roots) == 0 {
		return ""
	}
	return cards.EncodeDeck([]byte(t.Deck))
}

// Render shows the table list, or one table at path "<id>".
func Render(path string) string {
	if path == "" {
		var b strings.Builder
		b.WriteString("# Poker tables\n\n")
		if len(tables) == 0 {
			b.WriteString("No tables yet.\n")
			return b.String()
		}
		b.WriteString("| Table | Blinds | Buy-in | Seated | Hand | Phase |\n|---|---|---|---|---|---|\n")
		for _, t := range tables {
			seated := 0
			for _, s := range t.Seats {
				if s != nil {
					seated++
				}
			}
			phase := "-"
			if t.Hand != nil {
				phase = phaseNames[t.Hand.Phase]
			}
			id := strconv.FormatUint(t.ID, 10)
			b.WriteString("| [" + id + "](:" + id + ") | " + strconv.FormatInt(t.SmallBlind, 10) + "/" + strconv.FormatInt(t.BigBlind, 10) +
				" | " + strconv.FormatInt(t.MinBuyIn, 10) + "-" + strconv.FormatInt(t.MaxBuyIn, 10) +
				" | " + itoa(seated) + "/" + itoa(t.MaxPlayers) + " | " + strconv.FormatUint(t.HandNo, 10) + " | " + phase + " |\n")
		}
		return b.String()
	}
	id, err := strconv.ParseUint(path, 10, 64)
	if err != nil || id == 0 || id > uint64(len(tables)) {
		return "# Not found\n"
	}
	t := tables[id-1]
	var b strings.Builder
	b.WriteString("# Table " + path + "\n\n")
	b.WriteString("Blinds " + strconv.FormatInt(t.SmallBlind, 10) + "/" + strconv.FormatInt(t.BigBlind, 10) + " ugnot, hand " + strconv.FormatUint(t.HandNo, 10) + "\n\n")
	b.WriteString("| Seat | Player | Stack | Status |\n|---|---|---|---|\n")
	for i, s := range t.Seats {
		if s == nil {
			b.WriteString("| " + itoa(i) + " | (empty) | | |\n")
			continue
		}
		status := []string{}
		if i == t.Button {
			status = append(status, "button")
		}
		if s.SittingOut {
			status = append(status, "sitting out")
		}
		if s.Leaving {
			status = append(status, "leaving")
		}
		if s.Waiting {
			status = append(status, "waiting")
		}
		b.WriteString("| " + itoa(i) + " | " + s.Owner.String() + " | " + strconv.FormatInt(s.Stack, 10) + " | " + strings.Join(status, ", ") + " |\n")
	}
	h := t.Hand
	if h == nil {
		return b.String()
	}
	n := h.n()
	b.WriteString("\n## Hand " + strconv.FormatUint(h.No, 10) + ": " + phaseNames[h.Phase] + "\n\n")
	b.WriteString("Pot " + strconv.FormatInt(h.Bet.Pot(), 10) + " ugnot, deadline block " + strconv.FormatInt(h.Deadline, 10) + "\n\n")
	if h.Cards != nil {
		board := []string{}
		for _, c := range h.Cards[2*n : 2*n+5] {
			board = append(board, cards.CardString(c))
		}
		b.WriteString("Board: " + strings.Join(board, " ") + "\n\n")
	}
	b.WriteString("| # | Seat | Bet | Status | Cards | Result |\n|---|---|---|---|---|---|\n")
	for j, p := range h.Players {
		bp := h.Bet.Players[j]
		status := ""
		if bp.Folded {
			status = "folded"
		} else if bp.AllIn {
			status = "all-in"
		}
		hole := ""
		if h.Cards != nil {
			hole = cards.CardString(h.Cards[2*j]) + " " + cards.CardString(h.Cards[2*j+1])
		}
		res := ""
		if h.Result != nil && j < len(h.Result.Credits) {
			res = "+" + strconv.FormatInt(h.Result.Credits[j], 10)
		}
		b.WriteString("| " + itoa(j) + " | " + itoa(p.Seat) + " | " + strconv.FormatInt(bp.Contributed, 10) + " | " + status + " | " + hole + " | " + res + " |\n")
	}
	return b.String()
}

package poker

import (
	"crypto/modexp"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/poker/cards"
)

// This file is the only one importing crypto/modexp. For networks without it,
// replace it with verify_nomodexp.gno.txt (renamed to verify.gno).

const challengesEnabled = true

var primeP = cards.P()

// powModP returns base^exp mod P as 256 bytes.
func powModP(base, exp []byte) []byte {
	return modexp.ModExp(base, exp, primeP)
}

package nsnft

import (
	"chain"
	"encoding/base64"
	"strings"

	"gno.land/p/nt/grc721/v0"
)

/*
WHAT A WALLET SHOWS, AND WHY THIS FROZEN REALM DOES NOT DRAW IT.

Adena puts TokenURI(tid) straight into an <img src>, so it must return
the image itself (a data:image/svg+xml URI), and it reads TokenMetadata
as a camelCase JSON string. Both have to be answered HERE, because the
collection id names this realm. But the card is the most cosmetic and
most-revised thing in the project, and this realm can never change — so
the drawing is delegated to a view realm through a Renderer, and only
the delegation is frozen.

This realm cannot import the view: the view reads the registry, which
reads this ledger, and imports may not form a cycle. So the view hands
this realm an object at runtime instead. gno runs a method declared in
another realm with THAT realm's storage authority (the declaring-realm
borrow), so the renderer can read anything and write nothing of ours —
it gets no `cur`, so it cannot cross into anything as us either. What it
can do is draw something wrong, slow or broken, which is a display
problem: ClearRenderer withdraws it in one transaction (admin, recovery
or guardian) and wallets fall back to the built-in card below.

Who may register is pinned to ONE package path, approved through the
timelock (ProposeRenderer), because what every wallet shows for every
name is worth a waiting period: a hostile card could tell holders to pay
somebody. The ledger is born approving its own generation's view.
*/

// Renderer draws one token for wallets. Implemented by the view realm.
type Renderer interface {
	// TokenImage returns the image itself, as a data: URI.
	TokenImage(tid string) string
	// TokenMetadata returns the metadata as a JSON string: name,
	// description, externalUrl, attributes [{traitType, value}].
	TokenMetadata(tid string) string
}

var (
	// The one realm allowed to register a renderer; "" for none.
	rendererPath string
	// What it registered; nil means the built-in card.
	renderer Renderer
)

// RegisterRenderer is called BY the approved view realm, handing over
// the object that draws. Refused from anywhere else.
func RegisterRenderer(cur realm, r Renderer) {
	assertNoSend(cur)
	registerRenderer(cur.Previous().PkgPath(), r)
}

func registerRenderer(callerPath string, r Renderer) {
	if rendererPath == "" || callerPath != rendererPath {
		panic("nsnft: only the approved view realm may register a renderer")
	}
	if r == nil {
		panic("nsnft: no renderer given")
	}
	renderer = r
	chain.Emit("RendererRegistered", "path", callerPath)
}

// ClearRenderer withdraws the art at once, approval included, so the
// realm that drew it cannot simply register again: approving one takes
// the timelock. Admin, recovery or guardian.
func ClearRenderer(cur realm) {
	assertNoSend(cur)
	clearRenderer(cur.Previous().Address())
}

func clearRenderer(caller address) {
	assertCanRevoke(caller)
	prev := rendererPath
	rendererPath = ""
	renderer = nil
	chain.Emit("RendererCleared", "path", prev, "by", caller.String())
}

func RendererPath() string { return rendererPath }
func HasRenderer() bool    { return renderer != nil }

// TokenURI is the token's image, as a data: URI, for a token that exists.
// A renderer that answers nothing gets the built-in card instead: an
// empty <img src> is a broken picture in every wallet.
func TokenURI(tid string) (string, error) {
	if !Exists(tid) {
		return "", grc721.ErrInvalidTokenId
	}
	if renderer != nil {
		if img := renderer.TokenImage(tid); img != "" {
			return img, nil
		}
	}
	return builtinImage(tid), nil
}

// TokenMetadata is the token's metadata as a camelCase JSON string, the
// shape Adena reads. The image is not in it; that is TokenURI.
func TokenMetadata(tid string) (string, error) {
	if !Exists(tid) {
		return "", grc721.ErrInvalidTokenId
	}
	if renderer != nil {
		if meta := renderer.TokenMetadata(tid); meta != "" {
			return meta, nil
		}
	}
	return builtinMetadata(tid), nil
}

/*
THE BUILT-IN CARD, for when no view is registered: the name, plainly.

Deliberately plain and deliberately free of anything that could go
stale. No URL — a domain this realm named could lapse and be bought by
somebody else, and the link would then live in every wallet forever — and
no colours or claims that a policy change could make wrong.
*/
func builtinImage(tid string) string {
	size := 40
	if n := len(tid); n > 16 {
		size = 640 / n
		if size < 8 {
			size = 8
		}
	}
	svg := `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">` +
		`<rect width="400" height="400" fill="#0b0d10"/>` +
		`<text x="200" y="200" text-anchor="middle" font-family="monospace" font-size="` +
		itoa(int64(size)) + `" fill="#f4f4f5">` + escapeXML(tid) + `</text>` +
		`<text x="200" y="372" text-anchor="middle" font-family="monospace" font-size="13"` +
		` letter-spacing="3" fill="#71717a">MEME NAME SERVICE</text></svg>`
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
}

func builtinMetadata(tid string) string {
	return `{"name":"` + escapeJSON(tid) + `",` +
		`"description":"A name on the Meme Name Service.",` +
		`"attributes":[]}`
}

func escapeXML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	s = strings.ReplaceAll(s, "'", "&apos;")
	return s
}

func escapeJSON(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c < 0x20:
			const hex = "0123456789abcdef"
			b.WriteString(`\u00`)
			b.WriteByte(hex[c>>4])
			b.WriteByte(hex[c&0xf])
		default:
			b.WriteByte(c)
		}
	}
	return b.String()
}

package nsnft

import (
	"chain"
	"chain/runtime"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

/*
GOVERNANCE, AND WHY THE SMALLEST REALM NEEDED SOME.

The first version had one admin key and an instant Trust. Whoever held
that key could trust a realm of their own, burn any name and mint it to
themselves, in one block — and none of the vault's protections applied,
because its timelock, recovery role and guardian all live in nsdata and
nothing in that flow touches nsdata. In the generation where this is the
realm that can never change, it had the weakest governance of all. Two
audits (2026-10-15, H2/H3 and H-2) asked for this before it ships.

The model mirrors nsdata/governance.gno, with the two lessons its own
audit taught applied from the start:

	admin     the warm key. Proposes every power-granting change. Can
	          withdraw a registry's trust or the art instantly.
	recovery  the cold key, a multisig in production. Operates nothing.
	          Cancels ANY pending change, rotates admin, withdraws trust.
	guardian  hot (a monitoring bot), seated by recovery. Withdraws trust
	          or the art, and cancels the admin's grants (a registry, the
	          art, the timelock) but never a rotation. Nothing else, so its
	          theft costs an outage, never a name.

GRANTING IS SLOW, REVOKING IS INSTANT. Trusting a registry (the only way
anything can mint or burn), approving a view realm for the art, changing
the timelock and rotating either role all wait `timelockDelay` (an admin
replacing recovery waits twice that), are announced with an event, and
can be cancelled in the meantime. Withdrawing a registry's trust or the
art takes one transaction.

RECOVERY IS THE ROOT, AND THAT IS A DELIBERATE DEPARTURE. nsdata lets
each role rotate the other with neither able to cancel its own
replacement, which means a stolen admin key can propose a recovery
rotation recovery cannot stop. Here recovery may cancel anything and the
admin only what the admin proposed. A stolen admin key therefore gets
nothing that survives the timelock: every proposal it makes can be
cancelled and recovery can evict it. What it CAN do at once is withdraw
— untrust the registry, clear the art — which stops registrations until
an honest admin re-grants them, an outage and not a theft. The admin can
still replace a LOST recovery key — nobody cancels that proposal, so it
lands after twice the delay — which is the case the symmetry was there
for. The price is that a stolen recovery key is the one theft this realm
cannot contain, which is why it must be a cold multisig.

A ROTATION TAKES ITS PREDECESSOR'S PROPOSALS WITH IT. nsdata's audit (M-1)
found an evicted admin's pending grant surviving the eviction, executable
by anyone a delay later. Here, whenever a role changes hands, every
pending change proposed by an address that no longer holds a role is
dropped, with an event.

RECOVERY WINS THE EVICTION RACE, BY RULE AND NOT BY TIMING (re-audit
2026-10-16, M-1). An eviction used to drop the thief's proposals only at
the moment it executed, and anybody — the thief included — chose the order
in which matured proposals ran. So the thief re-proposed a cancelled trust
the block after recovery's sitting, executed it the moment it matured
(seconds after the eviction did), and minted through its registry in the
same transaction; or it executed recovery's own move to a new cold key
first, which orphaned recovery's eviction. Three rules close it:

	recovery proposing the eviction DROPS everything the admin had
	pending, and while the eviction is pending the admin proposes nothing
	and nothing it proposed may execute — so nothing of the admin's is
	held to spring back if the eviction lapses or is cancelled;

	a veto holds: when recovery or the guardian cancels what the admin
	proposed, the admin may not propose that kind again for one timelock,
	so recovery's sitting cannot be re-proposed around while it is still
	gathering signatures. Recovery's eviction landing clears the vetoes;
	replacing or standing down a guardian clears that guardian's; nothing
	else does, not an admin moving to a key of its own;

	recovery moving to a new key HANDS its eviction to that key (it was
	recovery's, and recovery still holds the role), so executing
	recovery's own rotation first no longer voids it. An admin replacing a
	lost recovery still drops the old key's plans.

Cancelling what is no longer pending does nothing, so a thief withdrawing
its own proposal first cannot make a batched sitting revert.

PROPOSALS EXPIRE. A matured change stays executable for executeWindow and
is void after it, so a forgotten proposal cannot be executed by a stranger
a year later (nsdata audit L-1).

ROLES NEVER MERGE. A rotation that would leave admin and recovery the
same key is refused, at proposal and again at execution: with one key in
both seats every protection above silently disappears (nsdata audit I-5).
They start merged on the deployer, which hands them out while the
timelock is still zero.

ExecutePending is open to anyone, as in nsdata: applying a change that
was announced and survived its window must not depend on a particular key
still being available. Every entry point below is a thin wrapper that
reads the caller and the clock and hands them to an unexported function,
so the rules themselves can be tested directly.
*/

const (
	// The ceiling on the timelock: a constant, not a setting, so a stolen
	// key cannot raise it and an absurd value cannot brick governance.
	maxTimelock int64 = 30 * 24 * 60 * 60
	// How long a matured proposal stays executable before it is void.
	executeWindow int64 = 14 * 24 * 60 * 60
	maxPathLen          = 256

	kindAdmin    = "admin"
	kindRecovery = "recovery"
	kindTrust    = "trust"
	kindDelay    = "delay"
	kindRenderer = "renderer"
)

type pendingOp struct {
	kind     string
	target   string  // what it changes to, as text: an address, a package path, or seconds
	addr     address // admin and recovery: the new holder; trust: the registry's address
	secs     int64   // delay: the new timelock
	at       int64   // unix seconds: executable from
	until    int64   // unix seconds: void after
	proposer address
}

var (
	admin    address
	recovery address
	guardian address

	// Seconds every power-granting change waits. Starts at zero so the
	// deploy can wire and hand out roles in one sitting; the deploy raises
	// it before anything is worth stealing. Changing it is itself
	// timelocked, or a thief would simply set it to zero.
	timelockDelay int64

	// One slot per kind (kind -> *pendingOp), so one in-flight proposal
	// cannot freeze the whole governance surface.
	pending avl.Tree

	// kind -> *veto: until when the admin may not propose that kind again,
	// because recovery or the guardian vetoed it, and who did (see the note
	// at the top).
	vetoes avl.Tree
)

type veto struct {
	until int64
	by    address
}

// -- roles: an empty role matches nobody --

func isAdmin(a address) bool    { return admin.IsValid() && a == admin }
func isRecovery(a address) bool { return recovery.IsValid() && a == recovery }
func isGuardian(a address) bool { return guardian.IsValid() && a == guardian }

func assertAdmin(caller address) {
	if !isAdmin(caller) {
		panic("nsnft: admin only")
	}
}

func assertAdminOrRecovery(caller address) {
	if !isAdmin(caller) && !isRecovery(caller) {
		panic("nsnft: admin or recovery only")
	}
}

func assertCanRevoke(caller address) {
	if !isAdmin(caller) && !isRecovery(caller) && !isGuardian(caller) {
		panic("nsnft: admin, recovery or guardian only")
	}
}

/*
isRealmPath accepts only a realm package path on this chain. A registry
or a view proves what it is by BEING that realm, and its address is
derived from the path here, so a wallet can never be trusted (nsdata
audit L-4): no wallet address is the hash of a realm path. Ephemeral
`maketx run` realms (gno.land/e/...), pure packages (/p/) and sub-realm
paths (with ':') are refused with it.
*/
func isRealmPath(p string) bool {
	prefix := runtime.ChainDomain() + "/r/"
	if len(p) <= len(prefix) || len(p) > maxPathLen || !strings.HasPrefix(p, prefix) {
		return false
	}
	if strings.HasSuffix(p, "/") || strings.Contains(p, "//") {
		return false
	}
	for i := 0; i < len(p); i++ {
		c := p[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '/' || c == '_' || c == '-' || c == '.' {
			continue
		}
		return false
	}
	return true
}

// -- the pending slots --

// liveOp is the pending change of one kind, or nil — an expired one is
// treated as absent everywhere, so it can be neither executed nor used to
// block a new proposal.
func liveOp(kind string, now int64) *pendingOp {
	v := pending.Get(kind)
	if v == nil {
		return nil
	}
	op := v.(*pendingOp)
	if now > op.until {
		return nil
	}
	return op
}

/*
canCancel: recovery may cancel anything; the admin what the admin
proposed; the guardian the admin's GRANTS — a registry, the art, the
timelock — and never a rotation. A hot key able to block rotations
could, with recovery lost, block the one change that replaces recovery
(and with it, the guardian) for good.
*/
func canCancel(op *pendingOp, caller address) bool {
	if isRecovery(caller) {
		return true
	}
	if isAdmin(caller) && caller == op.proposer {
		return true
	}
	if isGuardian(caller) && op.proposer != recovery &&
		(op.kind == kindTrust || op.kind == kindRenderer || op.kind == kindDelay) {
		return true
	}
	return false
}

// delayFor is the wait a proposal gets. An admin replacing RECOVERY waits
// twice the timelock: it is the one move by which a stolen admin key
// could eventually take the root role, so it gets the longest window for
// recovery to see it and cancel it. The case it exists for — recovery
// lost — only costs a slower replacement.
func delayFor(kind string, caller address) int64 {
	if kind == kindRecovery && !isRecovery(caller) {
		return 2 * timelockDelay
	}
	return timelockDelay
}

/*
evicting reports a live rotation of the admin that recovery proposed —
recovery replacing a key it no longer trusts. While admin and recovery are
still one key, at the deploy, nothing is an eviction.
*/
func evicting(now int64) bool {
	op := liveOp(kindAdmin, now)
	return op != nil && isRecovery(op.proposer) && !isAdmin(op.proposer)
}

// byTheAdminAlone: proposed by the admin, and the admin is not also recovery.
func byTheAdminAlone(a address) bool { return isAdmin(a) && !isRecovery(a) }

// vetoedUntil is when the admin may propose `kind` again, or 0.
func vetoedUntil(kind string, now int64) int64 {
	if v := vetoes.Get(kind); v != nil && now < v.(*veto).until {
		return v.(*veto).until
	}
	return 0
}

// dropVetoesBy lifts the vetoes one key sent: a guardian replaced or stood
// down, perhaps because it was stolen, does not keep the admin shut out.
func dropVetoesBy(by address) {
	var gone []string
	vetoes.Iterate("", "", func(k string, v any) bool {
		if v.(*veto).by == by {
			gone = append(gone, k)
		}
		return false
	})
	for _, k := range gone {
		vetoes.Remove(k)
		chain.Emit("GovernanceVetoLifted", "kind", k, "by", by.String())
	}
}

// dropProposalsOf removes every pending change `who` proposed: the admin's
// plans, the moment recovery proposes to evict it.
func dropProposalsOf(who address, reason string) {
	var gone []string
	pending.Iterate("", "", func(k string, v any) bool {
		if op := v.(*pendingOp); op.proposer == who && k != kindAdmin {
			gone = append(gone, k)
		}
		return false
	})
	for _, k := range gone {
		op := pending.Get(k).(*pendingOp)
		pending.Remove(k)
		chain.Emit("GovernanceInvalidated", "kind", k, "target", op.target,
			"proposer", op.proposer.String(), "reason", reason)
	}
}

func setPending(caller address, op *pendingOp, now int64) {
	if existing := liveOp(op.kind, now); existing != nil {
		// You may replace only what you could cancel.
		if !canCancel(existing, caller) {
			panic("nsnft: a change of this kind is pending and you may not replace it")
		}
		chain.Emit("GovernanceDisplaced", "kind", existing.kind, "target", existing.target, "by", caller.String())
	}
	if byTheAdminAlone(caller) {
		if evicting(now) {
			panic("nsnft: recovery is replacing the admin; the admin proposes nothing until that lands or lapses")
		}
		if until := vetoedUntil(op.kind, now); until > 0 {
			panic("nsnft: recovery or the guardian vetoed a " + op.kind + " change; the admin may propose one again from unix " + itoa(until))
		}
	}
	op.proposer = caller
	op.at = now + delayFor(op.kind, caller)
	op.until = op.at + executeWindow
	pending.Set(op.kind, op)
	chain.Emit("GovernanceProposed",
		"kind", op.kind,
		"target", op.target,
		"executableAt", itoa(op.at),
		"expiresAt", itoa(op.until),
		"by", caller.String())
}

func proposeTrust(caller address, pkgPath string, now int64) {
	assertAdmin(caller)
	if !isRealmPath(pkgPath) {
		panic("nsnft: a registry must be a realm package path under " + runtime.ChainDomain() + "/r/")
	}
	a := chain.PackageAddress(pkgPath)
	if trusted.Has(a.String()) {
		panic("nsnft: that registry is already trusted")
	}
	setPending(caller, &pendingOp{kind: kindTrust, target: pkgPath, addr: a}, now)
}

func proposeRenderer(caller address, pkgPath string, now int64) {
	assertAdmin(caller)
	if !isRealmPath(pkgPath) {
		panic("nsnft: a renderer must be a realm package path under " + runtime.ChainDomain() + "/r/")
	}
	if pkgPath == rendererPath {
		panic("nsnft: that realm is already the approved renderer")
	}
	setPending(caller, &pendingOp{kind: kindRenderer, target: pkgPath}, now)
}

// proposeDelay bounds the value before anything is computed from it, so
// no input can wrap (nsdata audit L-3), and the proposal shows the value
// it would set, so a monitor can tell "to zero" from "up".
func proposeDelay(caller address, seconds int64, now int64) {
	assertAdmin(caller)
	if seconds < 0 || seconds > maxTimelock {
		panic("nsnft: timelock out of range (0 to " + itoa(maxTimelock) + " seconds)")
	}
	setPending(caller, &pendingOp{kind: kindDelay, target: itoa(seconds), secs: seconds}, now)
}

func proposeAdmin(caller, next address, now int64) {
	assertAdminOrRecovery(caller)
	if !next.IsValid() {
		panic("nsnft: invalid address")
	}
	if next == admin {
		panic("nsnft: that address is already the admin")
	}
	if next == recovery {
		panic("nsnft: admin and recovery must stay separate keys")
	}
	setPending(caller, &pendingOp{kind: kindAdmin, target: next.String(), addr: next}, now)
	if isRecovery(caller) && !isAdmin(caller) && admin.IsValid() {
		// The eviction drops the admin's plans now, not when it lands (see
		// the note at the top).
		dropProposalsOf(admin, "recovery is replacing the admin")
	}
}

func proposeRecovery(caller, next address, now int64) {
	assertAdminOrRecovery(caller)
	if !next.IsValid() {
		panic("nsnft: invalid address")
	}
	if next == recovery {
		panic("nsnft: that address is already recovery")
	}
	if next == admin {
		panic("nsnft: admin and recovery must stay separate keys")
	}
	setPending(caller, &pendingOp{kind: kindRecovery, target: next.String(), addr: next}, now)
}

func cancelPending(caller address, kind string, now int64) {
	op := liveOp(kind, now)
	if op == nil {
		if !isAdmin(caller) && !isRecovery(caller) && !isGuardian(caller) {
			panic("nsnft: admin, recovery or guardian only")
		}
		return // idempotent, so a batched sitting cannot be made to revert
	}
	if !canCancel(op, caller) {
		panic("nsnft: you may not cancel this change")
	}
	pending.Remove(kind)
	// A veto holds for one timelock (see the note at the top): what recovery
	// or the guardian cancelled, the admin cannot simply propose again in the
	// next block. The admin withdrawing its own proposal costs nothing.
	if byTheAdminAlone(op.proposer) && !isAdmin(caller) && timelockDelay > 0 {
		vetoes.Set(kind, &veto{until: now + timelockDelay, by: caller})
		chain.Emit("GovernanceVetoed", "kind", kind, "until", itoa(now+timelockDelay), "by", caller.String())
	}
	chain.Emit("GovernanceCancelled", "kind", kind, "target", op.target, "by", caller.String())
}

func executePending(caller address, kind string, now int64) {
	op := liveOp(kind, now)
	if op == nil {
		panic("nsnft: nothing pending of that kind")
	}
	if now < op.at {
		panic("nsnft: still in the timelock window")
	}
	// The eviction lands first, whoever picks the order (see the note at
	// the top): nothing the admin proposed runs while recovery is replacing
	// it, and the eviction then drops all of it.
	if kind != kindAdmin && byTheAdminAlone(op.proposer) && evicting(now) {
		panic("nsnft: recovery is replacing the admin; the admin's pending changes wait for that, and die with it")
	}
	pending.Remove(kind)
	prev := ""
	switch kind {
	case kindAdmin:
		if op.addr == recovery {
			panic("nsnft: admin and recovery must stay separate keys")
		}
		prev = admin.String()
		admin = op.addr
		// Recovery's eviction landing clears the vetoes it was fighting
		// with; an admin moving to a key of its own choosing does not.
		if isRecovery(op.proposer) {
			vetoes = avl.Tree{}
		}
	case kindRecovery:
		if op.addr == admin {
			panic("nsnft: admin and recovery must stay separate keys")
		}
		prev = recovery.String()
		old := recovery
		recovery = op.addr
		// Recovery moving ITSELF keeps its eviction: it is handed to the new
		// key rather than orphaned. Only the eviction — recovery proposes
		// nothing else that could still be pending — so the new key never
		// inherits what an old deploy key proposed while it held both seats.
		// An admin replacing a lost recovery does not inherit that key's
		// eviction; it is dropped below with every other orphan.
		if op.proposer == old && old != admin {
			if e := liveOp(kindAdmin, now); e != nil && e.proposer == old {
				e.proposer = recovery
				chain.Emit("GovernanceHandedOver", "kind", kindAdmin, "target", e.target,
					"from", old.String(), "to", recovery.String())
			}
		}
	case kindTrust:
		trusted.Set(op.addr.String(), op.target)
		chain.Emit("RegistryTrusted", "addr", op.addr.String(), "path", op.target)
	case kindDelay:
		prev = itoa(timelockDelay)
		timelockDelay = op.secs
	case kindRenderer:
		// The approval moves; whatever the previous view registered stops
		// drawing, and wallets see the built-in card until the newly
		// approved realm registers itself.
		prev = rendererPath
		rendererPath = op.target
		renderer = nil
	default:
		panic("nsnft: unknown pending kind")
	}
	chain.Emit("GovernanceExecuted", "kind", kind, "target", op.target, "previous", prev, "by", caller.String())
	if kind == kindAdmin || kind == kindRecovery {
		dropOrphans()
	}
}

// dropOrphans removes every pending change whose proposer no longer
// holds a role. Called after each rotation; see the note at the top.
func dropOrphans() {
	var gone []string
	pending.Iterate("", "", func(k string, v any) bool {
		op := v.(*pendingOp)
		if op.proposer != admin && op.proposer != recovery {
			gone = append(gone, k)
		}
		return false
	})
	for _, k := range gone {
		op := pending.Get(k).(*pendingOp)
		pending.Remove(k)
		chain.Emit("GovernanceInvalidated", "kind", k, "target", op.target,
			"proposer", op.proposer.String(), "reason", "proposer no longer holds a role")
	}
}

func untrust(caller, registry address) {
	assertCanRevoke(caller)
	v := trusted.Get(registry.String())
	if v == nil {
		panic("nsnft: that registry is not trusted")
	}
	trusted.Remove(registry.String())
	chain.Emit("RegistryUntrusted", "addr", registry.String(), "path", v.(string), "by", caller.String())
}

/*
setGuardian takes recovery, to seat a guardian as much as to replace or
stand down a live one — otherwise the first move of a thief holding the
admin key would be to point the guardian at themselves, disarming the
emergency stop; and seating an EMPTY seat with its own bot left the thief a
key that outlived its eviction, untrusting the registry and vetoing the new
admin's grants, removable only by recovery (re-audit 2026-10-16, L-4). The
deploy seats it while its key still holds recovery. The address must be
real (nsdata audit I-4).
*/
func setGuardian(caller, g address) {
	if !g.IsValid() {
		panic("nsnft: invalid address")
	}
	if !isRecovery(caller) {
		if guardian.IsValid() {
			panic("nsnft: replacing a live guardian takes the recovery key")
		}
		panic("nsnft: seating a guardian takes the recovery key")
	}
	if guardian.IsValid() && guardian != g {
		dropVetoesBy(guardian)
	}
	guardian = g
	chain.Emit("GuardianSet", "addr", g.String(), "by", caller.String())
}

func clearGuardian(caller address) {
	if guardian.IsValid() {
		if !isRecovery(caller) {
			panic("nsnft: standing down a live guardian takes the recovery key")
		}
		dropVetoesBy(guardian)
	} else {
		assertAdminOrRecovery(caller)
	}
	guardian = ""
	chain.Emit("GuardianSet", "addr", "", "by", caller.String())
}

// -- entry points: each reads the caller and the clock, nothing more --

// ProposeTrust starts trusting a registry, by package path, after the
// timelock. Admin only.
func ProposeTrust(cur realm, pkgPath string) {
	assertNoSend(cur)
	proposeTrust(cur.Previous().Address(), pkgPath, time.Now().Unix())
}

// ProposeRenderer approves a view realm to draw the art, after the
// timelock. Admin only. The realm then registers itself (art.gno).
func ProposeRenderer(cur realm, pkgPath string) {
	assertNoSend(cur)
	proposeRenderer(cur.Previous().Address(), pkgPath, time.Now().Unix())
}

// ProposeTimelockDelay changes the timelock, after the current one.
// Admin only.
func ProposeTimelockDelay(cur realm, seconds int64) {
	assertNoSend(cur)
	proposeDelay(cur.Previous().Address(), seconds, time.Now().Unix())
}

// ProposeAdminTransfer rotates the admin after the timelock. Admin or
// recovery; when recovery proposes it, the admin cannot cancel it.
func ProposeAdminTransfer(cur realm, next address) {
	assertNoSend(cur)
	proposeAdmin(cur.Previous().Address(), next, time.Now().Unix())
}

// ProposeRecoveryTransfer rotates recovery after the timelock — twice the
// timelock when the admin proposes it. Admin or recovery; recovery can
// cancel either, so a stolen admin key cannot take it.
func ProposeRecoveryTransfer(cur realm, next address) {
	assertNoSend(cur)
	proposeRecovery(cur.Previous().Address(), next, time.Now().Unix())
}

func CancelPending(cur realm, kind string) {
	assertNoSend(cur)
	cancelPending(cur.Previous().Address(), kind, time.Now().Unix())
}

// ExecutePending applies a matured change. Anyone may call it.
func ExecutePending(cur realm, kind string) {
	assertNoSend(cur)
	executePending(cur.Previous().Address(), kind, time.Now().Unix())
}

// Untrust withdraws a registry's power to mint and burn, at once. Admin,
// recovery or guardian: removing a power is the safe direction, and a
// registry that has gone wrong must be stoppable in one transaction.
func Untrust(cur realm, registry address) {
	assertNoSend(cur)
	untrust(cur.Previous().Address(), registry)
}

func SetGuardian(cur realm, g address) {
	assertNoSend(cur)
	setGuardian(cur.Previous().Address(), g)
}

func ClearGuardian(cur realm) {
	assertNoSend(cur)
	clearGuardian(cur.Previous().Address())
}

// -- reads --

func Admin() address       { return admin }
func Recovery() address    { return recovery }
func Guardian() address    { return guardian }
func TimelockDelay() int64 { return timelockDelay }

// PendingAdmin is the address a pending admin rotation would install, or
// empty.
func PendingAdmin() address {
	if op := liveOp(kindAdmin, time.Now().Unix()); op != nil {
		return op.addr
	}
	return ""
}

// GetPending describes the live pending change of one kind: what it sets,
// when it becomes executable and when it lapses (unix seconds), and who
// proposed it. All empty when nothing is pending.
func GetPending(kind string) (target string, executableAt, expiresAt int64, proposer address) {
	op := liveOp(kind, time.Now().Unix())
	if op == nil {
		return "", 0, 0, ""
	}
	return op.target, op.at, op.until, op.proposer
}

// ListPending names the kinds with a live pending change, comma-separated.
func ListPending() string {
	now := time.Now().Unix()
	out := ""
	pending.Iterate("", "", func(k string, v any) bool {
		if now > v.(*pendingOp).until {
			return false
		}
		if out != "" {
			out += ","
		}
		out += k
		return false
	})
	return out
}

func IsTrusted(registry address) bool { return registry.IsValid() && trusted.Has(registry.String()) }

// Trusted lists every address that may mint or burn, comma-separated.
// nsdata compares this with its own address before adopting tokens, so
// the format is part of the contract: addresses only, no spaces.
func Trusted() string {
	out := ""
	trusted.Iterate("", "", func(a string, _ any) bool {
		if out != "" {
			out += ","
		}
		out += a
		return false
	})
	return out
}

// TrustedPath reports the package path a registry was trusted as, or "".
func TrustedPath(registry address) string {
	if v := trusted.Get(registry.String()); v != nil {
		return v.(string)
	}
	return ""
}

// Package nsnft is the token, and only the token.
//
// WHY THIS REALM EXISTS AT ALL.
//
// A name here is a GRC-721. An external marketplace that wants to list
// one has to hard-code an address, and whatever address that is becomes
// the thing we can never move. Until now the interface was split: the
// READS lived on nsdata, which is permanent, and the WRITES — Approve,
// SetApprovalForAll, TransferFrom — lived on nslogic, which changed
// address three times in a single day. So the half an integrator needs
// in order to settle a sale was the half that kept moving, and the reads
// kept answering while it did, which is the worst way for it to break.
//
// The fix is to pick ONE realm to freeze and make it the smallest, most
// boring one there is. That is this realm: an ownership ledger, the
// approval bookkeeping GRC-721 requires, the governance that decides who
// may mint, and nothing else. No prices, no expiry, no profiles, no
// policy — none of the things that will certainly need changing.
//
// Everything with an opinion in it stays in the registry, which becomes
// replaceable BECAUSE ownership no longer lives there. A migration then
// moves records, not tokens: nobody's holdings are stranded and no
// listing anywhere goes stale, because the token contract never moved.
//
// THE LEDGER IS THE CHAIN'S OWN gno.land/p/nt/grc721/v0, NOT A COPY.
//
// chain.Emit stamps the package whose code emits, and wallets and
// indexers (Adena, the Onbloc indexer) accept only Transfer and NewToken
// events stamped gno.land/p/nt/grc721/v0. The first version of this realm
// minted on a vendored GRC-721 deployed under our own p/ path, so every
// event it would ever have emitted carried OUR path, and no wallet would
// ever have listed a single name — permanently, because events cannot be
// re-emitted and this realm cannot be replaced. The ledger object lives
// here, created once in init; only this realm holds its PrivateLedger,
// and no Teller is ever handed out (see the note on holds below).
//
// THIS REALM HAS ITS OWN GOVERNANCE, AND THAT IS THE POINT.
//
// It would be shorter to ask nsdata who the admin is. It would also
// re-couple this realm to the exact thing it exists to let us replace —
// nsnft would then depend on one nsdata forever and we would have moved
// the problem rather than solved it. So roles, trust and the timelock are
// local (governance.gno), and nsdata is not imported.
//
// WHAT MAY BE CHANGED LATER AND WHAT MAY NOT.
//
// May, slowly: which registries are trusted, the roles, the timelock,
// and which view realm draws the art. May, instantly: withdrawing a
// registry's trust or the art, which only ever removes a power. Through a
// trusted registry only: the hold bits on a token. May not: anything
// else. If this realm ever needs a new function, the design has failed
// and the honest answer is that it was not small enough to freeze.
package nsnft

import (
	"chain"
	"chain/runtime/unsafe" // OriginSend only; this realm never moves coins
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	collectionName   = "Meme Name Service"
	collectionSymbol = "MNS"

	/* THE REGISTRY AND THE VIEW THIS LEDGER IS BORN WITH.

	   Placeholders, exactly like an import path: the deploy tooling
	   (tools/deploy-gen.sh, tools/bundle-sources.py) rewrites every
	   quoted gno.land/r/demo/<realm> string to the generation's real path,
	   so the ledger is born trusting the one registry that is deployed
	   beside it — and no wallet is ever trusted, not even for the first
	   wiring. The previous version trusted the deployer's key at birth and
	   relied on somebody remembering to untrust it.

	   Fail-safe if the rewrite is ever skipped: nobody can deploy under
	   gno.land/r/demo on a public chain, so an unrewritten placeholder
	   trusts an address no transaction can come from. */
	genesisRegistry = "gno.land/r/nym-mnsrehearsal001/nsdata/v3"
	genesisView     = "gno.land/r/nym-mnsrehearsal001/nsview/v3"
)

var (
	// Created once, in init, by the chain's own GRC-721. token is the
	// read side; ledger is the write side and never leaves this realm.
	token  *grc721.Token
	ledger *grc721.PrivateLedger

	/* THE REGISTRIES PERMITTED TO MINT AND BURN: registry address -> the
	   package path it was trusted as. A set rather than a single value so
	   a migration can have the old and the new registry both live for the
	   window in which records are moving. An avl.Tree, so it is both a
	   lookup and an enumeration — whoever can mint names is the most
	   important fact about this contract, and it must be legible without
	   an indexer — and so a write touches one node rather than the whole
	   set. */
	trusted avl.Tree

	/* HOLDS, set by a trusted registry and never interpreted here.

	   A small bitmask per token (tid -> int). While any bit is set the
	   token cannot be approved or transferred — by its owner, by an
	   operator, by any marketplace — through any path in this realm.

	   WHY THE FROZEN REALM NEEDED THIS. The registry has two reasons to
	   hold a token in place: a free-tier name that has not been paid for
	   must not be sellable, and a name frozen by an admin during a
	   dispute must not be moved. Both used to be enforced in nslogic's
	   transfer wrappers — which only worked while nslogic was the only
	   way to transfer. The point of this realm is that it is NOT: any
	   GRC-721 marketplace calls TransferFrom here directly. A rule that
	   lives anywhere else is a rule an external marketplace skips.

	   WHY BITS AND NOT NAMED REASONS. What a bit MEANS is policy, and
	   policy changes; this realm cannot. So it stores numbers and the
	   registry owns the vocabulary. Separate bits, not one flag, so that
	   unfreezing a free-tier name cannot accidentally make it sellable.

	   Absent key = no hold. Burn clears it. */
	locks avl.Tree

	/* THE OWNERSHIP EPOCH (tid -> int64). Moves on every mint and every
	   transfer.

	   The registry stamps a name's profile data with the epoch it was
	   written in, and treats data from any other epoch as belonging to a
	   previous holder. That is how a sale that settles HERE — on a
	   marketplace the registry never hears from — still stops the
	   seller's payment addresses from answering for the buyer's name.

	   AN EPOCH, NOT AN OWNER ADDRESS, because a name can go A to B and
	   back to A. Compared by address, A's data from before the sale would
	   come back to life — including a pay address A may have abandoned.

	   Drawn from one global counter rather than counted per token, so a
	   token burned and minted again can never repeat an epoch it had in
	   a previous life.

	   avl.Tree and not a map: a Go map is persisted as ONE object, so
	   every mint and transfer re-wrote every token's epoch — measured at
	   ~784 gas per existing token per write, growing forever, in the one
	   realm that could never be fixed. A tree write touches a path. */
	epochs  avl.Tree
	lastSeq int64
)

// Bits a lock value may use. Eight is plenty for a registry and keeps a
// caller from storing arbitrary integers in a realm that cannot be
// patched to reject them later.
const maxLockBit = 7

// validLockBits is the range check, alone, so it can be tested directly.
func validLockBits(b int) bool { return b >= 0 && b < 1<<(maxLockBit+1) }

// validLockBit checks a bit INDEX, for SetLock. Separate from
// validLockBits, which checks a whole mask, because confusing the two is
// exactly the bug SetLock shipped with for one commit.
func validLockBit(bit int) bool { return bit >= 0 && bit <= maxLockBit }

func lockBitsOf(tid string) int {
	if v := locks.Get(tid); v != nil {
		return v.(int)
	}
	return 0
}

func bump(tid string) {
	lastSeq++
	epochs.Set(tid, lastSeq)
}

/*
THE HOLDS AND THE EPOCH LIVE IN THE LEDGER'S OWN HOOKS.

grc721/v0 calls an issuer-registered extension on every mint, transfer
and burn, after the ledger write and before the event, and a panic in a
hook aborts the movement. So the two rules this realm exists to keep are
enforced at the one place EVERY movement passes through — not in the
wrappers below, which merely repeat the hold check to give a clearer
error first.

Why that matters in a realm that never hands out a Teller: it makes the
rules a property of the ledger rather than of whichever entry point a
future reader adds or a marketplace finds. A transfer that reaches the
ledger by any route moves the epoch, and a held token does not move.
Approvals do not pass through a hook, so Approve checks the hold itself.

The type is unexported and the only instance is attached to the private
ledger, so no other realm can reach these methods.
*/
type holds struct{}

func (holds) ExtensionKind() string { return "nsnft/holds" }

func (holds) OnMint(to address, tid grc721.TokenID) {
	// A fresh token starts unheld; Mint applies the bits it was asked for
	// straight after. Burn already cleared any old hold, so this is the
	// belt to that brace.
	locks.Remove(string(tid))
	bump(string(tid))
}

func (holds) OnTransfer(from, to address, tid grc721.TokenID) {
	assertUnlocked(string(tid))
	bump(string(tid))
}

func (holds) OnBurn(tid grc721.TokenID) {
	// A hold on a token that no longer exists would silently apply to the
	// NEXT token minted with this id — a reclaimed name arriving frozen.
	locks.Remove(string(tid))
	// The epoch goes too. The next mint draws a fresh one from lastSeq,
	// which can never equal anything this token had before.
	epochs.Remove(string(tid))
}

func init(cur realm) {
	// Emits NewToken from gno.land/p/nt/grc721/v0; the collection id is
	// "<this realm's path>.MNS.0000000", the shape wallets parse.
	token, ledger = grc721.NewToken(collectionName, collectionSymbol, seqid.ID(0), cur)
	ledger.RegisterExtension(holds{})

	/* BOTH ROLES START ON THE DEPLOYER, AND ONLY IF IT IS REAL.

	   The deployer hands recovery to a cold key and admin to a multisig
	   as part of the deploy (tools/deploy-gen.sh), while the timelock is
	   still zero; then the timelock goes up. An invalid deployer cannot
	   happen on chain, and under `gno test` (which has none) it leaves
	   both roles empty — and every role check below refuses an empty
	   role, so nobody, not even a caller whose address stringifies to
	   nothing, can act as an absent admin. */
	if d := cur.Previous().Address(); d.IsValid() {
		admin = d
		recovery = d
	}

	reg := chain.PackageAddress(genesisRegistry)
	trusted.Set(reg.String(), genesisRegistry)
	chain.Emit("RegistryTrusted", "addr", reg.String(), "path", genesisRegistry)
	rendererPath = genesisView
	chain.Emit("RendererApproved", "path", genesisView)
}

/*
COINS SENT HERE ARE DESTROYED, SO REFUSE THEM.

This realm has no banker, no withdrawal and no sweep, and it can never
gain one — that is the whole premise of freezing it. Anything attached to
a call would sit at its address until the chain ends.

Checked only for a direct user call: when another realm calls in, any
coins the user attached went to THAT realm, not to this one, and
refusing them here would break legitimate registry calls.
*/
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return
	}
	if !unsafe.OriginSend().IsZero() {
		panic("nsnft: this realm takes no payment and cannot return it; do not attach coins")
	}
}

/*
assertTrusted is the whole security model for minting.

A caller that can mint can invent a name, and a name is the product. So
this is checked against the REALM address of the caller rather than an
address it hands us — a registry proves what it is by being it. Only
package paths can be trusted (governance.gno), so a wallet can never be
in this set.
*/
func assertTrusted(caller address) {
	if !caller.IsValid() || !trusted.Has(caller.String()) {
		panic("nsnft: only a trusted registry may do that")
	}
}

// ---------------------------------------------------------------------
// mint and burn — registry only
// ---------------------------------------------------------------------

/*
Mint creates a token, optionally already held in place.

`lockBits` is the hold it starts with — a free-tier name is minted locked
so there is never an instant in which it could be approved and sold
before the registry got round to locking it (nothing runs between the
ledger write and the line that sets the bits). Zero for an ordinary
paid name.
*/
func Mint(cur realm, to address, tid string, lockBits int) {
	assertNoSend(cur)
	assertTrusted(cur.Previous().Address())
	if !to.IsValid() {
		panic("nsnft: invalid recipient")
	}
	if tid == "" {
		panic("nsnft: empty token id")
	}
	if !validLockBits(lockBits) {
		panic("nsnft: lock bits out of range")
	}
	if err := ledger.Mint(to, grc721.TokenID(tid)); err != nil {
		panic("nsnft: " + err.Error())
	}
	if lockBits != 0 {
		locks.Set(tid, lockBits)
		chain.Emit("Locked", "tid", tid, "bits", itoa(int64(lockBits)))
	}
}

/*
Burn destroys a token. Reachable only by a trusted registry, which calls
it when a name lapses past its grace period and is reclaimed.

NOT reachable by the holder. A GRC-721 that lets an owner burn is
correct for collectibles and wrong here: the token is a lease on a name,
and destroying it would leave the registry holding a record for a name
whose token no longer exists. Letting go of a name is letting it expire.

The hold and the epoch are cleared by the burn hook (holds.OnBurn), the
per-token approval by the ledger itself.
*/
func Burn(cur realm, tid string) {
	assertNoSend(cur)
	assertTrusted(cur.Previous().Address())
	if err := ledger.Burn(grc721.TokenID(tid)); err != nil {
		panic("nsnft: " + err.Error())
	}
}

/*
SetLock turns one hold bit on or off. Trusted registry only.

The registry decides what a bit means; this realm only guarantees that
while any bit is set, nothing moves the token.
*/
func SetLock(cur realm, tid string, bit int, on bool) {
	assertNoSend(cur)
	assertTrusted(cur.Previous().Address())
	/* THE BIT IS RANGE-CHECKED BEFORE IT IS SHIFTED. An earlier check
	   tested 1<<bit, and an audit caught what that does: a bit of 64 or
	   more shifts to zero, passes, and the call quietly changes nothing
	   while still emitting LockChanged. Unacceptable in the one realm
	   that can never be patched. */
	if !validLockBit(bit) {
		panic("nsnft: lock bit out of range")
	}
	owner := OwnerOf(tid)
	if owner == "" {
		panic("nsnft: no such token")
	}
	v := lockBitsOf(tid)
	if on {
		v |= 1 << bit
	} else {
		v &^= 1 << bit
	}
	if v == 0 {
		locks.Remove(tid)
	} else {
		locks.Set(tid, v)
	}
	/* A NEW HOLD WITHDRAWS THE STANDING APPROVAL. A hold stops an
	   approval being USED, not the approval itself — so a name frozen
	   mid-dispute kept whatever approval it had, and it became live again
	   the moment the name was unfrozen. An audit caught it. The owner can
	   re-approve afterwards; nobody else's pre-dispute permission
	   survives. Operator grants are per owner, not per token, and are the
	   owner's to revoke. Approving the zero address is grc721/v0's
	   revoke, and it emits the standard Approval event. */
	if on && GetApproved(tid) != "" {
		if err := ledger.Approve(owner, "", grc721.TokenID(tid)); err != nil {
			panic("nsnft: " + err.Error())
		}
	}
	chain.Emit("LockChanged", "tid", tid, "bits", itoa(int64(v)))
}

func assertUnlocked(tid string) {
	if lockBitsOf(tid) != 0 {
		panic("nsnft: this token is held by the registry and cannot be approved or moved")
	}
}

// LockBits reports the current hold; 0 means free to move.
func LockBits(tid string) int { return lockBitsOf(tid) }

func IsLocked(tid string) bool { return lockBitsOf(tid) != 0 }

// Epoch reports the ownership epoch of a token, or 0 for one that does
// not exist. See epochs.
func Epoch(tid string) int64 {
	if v := epochs.Get(tid); v != nil {
		return v.(int64)
	}
	return 0
}

// ---------------------------------------------------------------------
// GRC-721, public — this is the surface the outside world holds
// ---------------------------------------------------------------------

// Approve grants (or, to the empty address, withdraws) the per-token
// approval. Refused while the token is held: approvals do not pass
// through a ledger hook, so this is the one place the hold is checked.
func Approve(cur realm, to address, tid string) {
	assertNoSend(cur)
	assertUnlocked(tid)
	if err := ledger.Approve(cur.Previous().Address(), to, grc721.TokenID(tid)); err != nil {
		panic("nsnft: " + err.Error())
	}
}

/*
RevokeApproval withdraws a token's per-token approval.

grc721/v0 revokes by approving the empty address; this keeps the named
entry point the site and tools already call, and allows it while the
token is held — withdrawing a permission is the safe direction. The
owner, or an operator acting for the owner, the same two callers Approve
accepts.
*/
func RevokeApproval(cur realm, tid string) {
	assertNoSend(cur)
	if OwnerOf(tid) == "" {
		panic("nsnft: no such token")
	}
	if err := ledger.Approve(cur.Previous().Address(), "", grc721.TokenID(tid)); err != nil {
		panic("nsnft: only the owner or an operator may revoke an approval: " + err.Error())
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	assertNoSend(cur)
	if err := ledger.SetApprovalForAll(cur.Previous().Address(), operator, approved); err != nil {
		panic("nsnft: " + err.Error())
	}
}

/*
TransferFrom carries NO expiry check, and that is a deliberate reversal
of what nslogic once did.

Refusing to transfer an expired token is an anti-scam measure, and it
belongs in the REGISTRY, not here: this realm does not know what expiry
is and must not learn, because the moment it holds policy it stops being
the small frozen thing it exists to be. The registry keeps the rule by
refusing to RESOLVE an expired name. A buyer can still acquire a
worthless token from a careless seller, which is true of every NFT on
every chain, and the marketplace disclaimers say so.

The hold is checked here for a clear error and again by the ledger hook,
which also moves the epoch.
*/
func TransferFrom(cur realm, from, to address, tid string) {
	assertNoSend(cur)
	assertUnlocked(tid)
	if err := ledger.TransferFrom(cur.Previous().Address(), from, to, grc721.TokenID(tid)); err != nil {
		panic("nsnft: " + err.Error())
	}
}

// SafeTransferFrom is kept for the standard signature. grc721/v0 has no
// receiver hook (gno has no contract-receiver registry to check), so it
// is TransferFrom — as the vendored version effectively was, its
// receiver check being a stub that always said yes.
func SafeTransferFrom(cur realm, from, to address, tid string) {
	assertNoSend(cur)
	assertUnlocked(tid)
	if err := ledger.TransferFrom(cur.Previous().Address(), from, to, grc721.TokenID(tid)); err != nil {
		panic("nsnft: " + err.Error())
	}
}

// ---------------------------------------------------------------------
// reads
// ---------------------------------------------------------------------

/*
OwnerOf answers the zero address for a token that does not exist, rather
than panicking or returning an error.

The registry calls this on EVERY resolve — that is the whole design, one
truth rather than a cached copy that goes stale the moment a sale settles
somewhere we did not watch. A panic on an unknown id would make every
caller wrap it, and the wrapper that gets forgotten is the one that turns
a missing name into a broken page. (nsdata and nsmarket are written
against exactly this signature.)
*/
func OwnerOf(tid string) address {
	owner, err := token.OwnerOf(grc721.TokenID(tid))
	if err != nil {
		return ""
	}
	return owner
}

func Exists(tid string) bool { return OwnerOf(tid) != "" }

func BalanceOf(owner address) int64 {
	n, err := token.BalanceOf(owner)
	if err != nil {
		return 0
	}
	return n
}

// GetApproved answers totally: the zero address means nobody is approved
// or there is no such token.
func GetApproved(tid string) address {
	a, err := token.GetApproved(grc721.TokenID(tid))
	if err != nil {
		return ""
	}
	return a
}

func IsApprovedForAll(owner, operator address) bool {
	return token.IsApprovedForAll(owner, operator)
}

func Name() string       { return token.GetName() }
func Symbol() string     { return token.GetSymbol() }
func GetName() string    { return token.GetName() }
func GetSymbol() string  { return token.GetSymbol() }
func TokenCount() int64  { return token.TotalSupply() }
func TotalSupply() int64 { return token.TotalSupply() }

// ID is the collection id wallets and indexers key on:
// "<this realm's path>.MNS.0000000".
func ID() string { return token.ID() }

/*
Render builds its string by concatenation rather than with ufmt.

NO DEPENDENCIES THIS REALM DOES NOT ABSOLUTELY NEED. It is meant to be
deployed once and never replaced, so every import is a permanent
commitment to somebody else's package. grc721/v0 (with avl and seqid,
which it already depends on) is here because it IS the thing this realm
is; a formatter, for one page of text, is not worth that.
*/
func Render(path string) string {
	out := "# Meme Name Service — tokens\n\n" +
		"This realm is the ownership ledger and nothing else. Prices, expiry,\n" +
		"profiles and every rule live in the registry.\n\n" +
		"- collection: `" + token.ID() + "`\n" +
		"- tokens: " + itoa(token.TotalSupply()) + "\n" +
		"- admin: `" + admin.String() + "`\n" +
		"- recovery: `" + recovery.String() + "`\n" +
		"- guardian: `" + guardian.String() + "`\n" +
		"- timelock: " + itoa(timelockDelay) + " s\n" +
		"- renderer: `" + rendererPath + "`"
	if renderer == nil {
		out += " (not registered: wallets see the built-in card)"
	}
	out += "\n\n## Trusted registries\n\n"
	trusted.Iterate("", "", func(a string, v any) bool {
		out += "- `" + v.(string) + "` (`" + a + "`)\n"
		return false
	})
	out += "\n## Pending governance\n\n"
	n := 0
	now := time.Now().Unix()
	pending.Iterate("", "", func(k string, v any) bool {
		op := v.(*pendingOp)
		if now > op.until {
			return false // void: lapsed unexecuted (re-audit 2026-10-16, I-6)
		}
		out += "- " + k + " -> `" + op.target + "`, executable " + itoa(op.at) +
			" to " + itoa(op.until) + ", by `" + op.proposer.String() + "`\n"
		n++
		return false
	})
	if n == 0 {
		out += "none\n"
	}
	out += "\nIntegrators: this address is stable. The registry behind it is not,\n" +
		"and is meant not to be.\n"
	return out
}

// itoa, because importing a package to print one number would outlast
// every reason we had for wanting it.
func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	// Work in uint64 so the most negative int64 does not overflow when
	// its sign is flipped.
	u := uint64(n)
	if neg {
		u = uint64(-(n + 1)) + 1
	}
	var b []byte
	for u > 0 {
		b = append([]byte{byte('0' + u%10)}, b...)
		u /= 10
	}
	if neg {
		return "-" + string(b)
	}
	return string(b)
}

package nsdata

import (
	"strconv"
	"strings"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
)

/*
TIMELOCKED ADMIN ACTIONS: the vault's clock behind the logic realm's most
dangerous calls.

THE GAP THIS CLOSES. The timelock above guarded two things — granting a
logic realm and rotating a role — and everything the logic realm let the
admin do was instant. An audit took a paid name from its holder, made
names in grace reclaimable by anybody, deleted live names and redirected
all revenue, each in one multi-message transaction with a 48-hour delay
in force and nothing ever proposed. No monitor could act between the
steps.

THE SHAPE. The policy stays in the logic realm — which calls are
dangerous, and what exactly a call's arguments are — and the delay lives
here, where no logic swap can shorten it:

	ProposeAction(id)   admin only, as a direct wallet call; stamped with
	                    the timelock delay in force; emits ActionProposed.
	CancelAction(id)    admin or recovery, instantly; CancelAllActions for
	                    an incident.
	ConsumeAction(id)   trusted logic only; panics unless the action has
	                    matured and has not expired; removes it.

An id names one call and its arguments, canonically — nslogic uses
"<Function> <arg> <arg>…" — so a proposal authorizes exactly one change,
and the event a monitor sees is the change itself rather than a hash it
has to trust. The vault does not interpret ids at all.

A matured action stays executable for actionWindow and is void after it,
so a proposal nobody acted on cannot be executed by surprise a year later.
At most maxPendingActions wait at once; expired ones make room. Every
pending action dies when the admin rotates (dropAdminProposals): an
evicted key's plans do not outlive the key.
*/

type pendingAction struct {
	at      int64 // unix second it becomes executable
	expires int64 // unix second it stops being executable
	by      address
}

var (
	pendingActions avl.Tree // id -> *pendingAction

	maxPendingActions = 32

	// Seconds a matured action stays executable. Settable within bounds by
	// admin or recovery: shortening it only voids proposals sooner, and
	// lengthening it cannot make anything mature faster.
	actionWindow int64 = 7 * 24 * 60 * 60
)

const (
	maxActionIDLen   = 2048
	minActionWindow  = int64(60 * 60)
	maxActionWindowS = int64(90 * 24 * 60 * 60)
)

func getAction(id string) *pendingAction {
	if v := pendingActions.Get(id); v != nil {
		return v.(*pendingAction)
	}
	return nil
}

func assertActionID(id string) {
	if id == "" || len(id) > maxActionIDLen {
		panic("nsdata: an action id is 1-" + strconv.Itoa(maxActionIDLen) + " bytes")
	}
	if strings.ContainsAny(id, "\n\r") {
		panic("nsdata: an action id may not contain newlines")
	}
}

// ProposeAction starts the clock on one admin action. Proposing an id
// already pending restarts its clock: the latest proposal is the one that
// must survive its window.
func ProposeAction(cur realm, id string) {
	assertIsAdmin(cur)
	assertActionID(id)
	// Not while recovery is replacing the admin, nor for one timelock after
	// recovery vetoed one of its actions (governance.gno, re-audit M-1).
	assertAdminMayPropose(cur.Previous().Address(), "action")
	now := time.Now().Unix()
	if getAction(id) == nil {
		pruneExpiredActions(now)
		if pendingActions.Size() >= maxPendingActions {
			panic("nsdata: " + strconv.Itoa(maxPendingActions) + " actions are already pending; cancel some first")
		}
	}
	at := now + int64(timelockDelay/time.Second)
	a := &pendingAction{at: at, expires: at + actionWindow, by: cur.Previous().Address()}
	pendingActions.Set(id, a)
	chain.Emit("ActionProposed", "id", id,
		"executableAt", strconv.FormatInt(a.at, 10),
		"expiresAt", strconv.FormatInt(a.expires, 10),
		"by", a.by.String())
}

// CancelAction withdraws one pending action. Admin or recovery: the admin
// changing its mind, or recovery vetoing a key it no longer trusts.
func CancelAction(cur realm, id string) {
	assertIsAdminOrRecovery(cur)
	a := getAction(id)
	if a == nil {
		return // idempotent: see CancelPending
	}
	pendingActions.Remove(id)
	veto(cur.Previous().Address(), "action", a.by)
	chain.Emit("ActionCancelled", "id", id, "by", cur.Previous().Address().String())
}

// CancelAllActions withdraws every pending action at once — the incident
// call, when nobody wants to read a list before acting. From recovery it
// is a veto: the admin proposes no action for one timelock.
func CancelAllActions(cur realm) {
	assertIsAdminOrRecovery(cur)
	n := dropAllActions("cancelled")
	if n > 0 {
		veto(cur.Previous().Address(), "action", admin)
	}
	chain.Emit("ActionsCancelled", "count", strconv.Itoa(n), "by", cur.Previous().Address().String())
}

/*
ConsumeAction spends a matured action. Trusted logic only, so it is also
gated by the pause: a paused registry executes nothing, timelocked or not.

It refuses an action proposed by anybody but the CURRENT admin. Rotation
already drops them all; this is the second lock on the same door, because
a matured proposal is a loaded instruction and the vault should not rely
on one rule to unload it.
*/
func ConsumeAction(cur realm, id string) {
	assertIsTrustedLogic(cur)
	if EvictionPending() {
		panic("nsdata: recovery is replacing the admin; timelocked actions wait for that, and die with it")
	}
	a := getAction(id)
	if a == nil {
		panic("nsdata: action `" + id + "` was never proposed; the admin proposes it with ProposeAction and it waits out the timelock")
	}
	now := time.Now().Unix()
	if now < a.at {
		panic("nsdata: action `" + id + "` is in its timelock until unix " + strconv.FormatInt(a.at, 10))
	}
	if now >= a.expires {
		panic("nsdata: action `" + id + "` expired at unix " + strconv.FormatInt(a.expires, 10) + "; propose it again")
	}
	if a.by != admin {
		panic("nsdata: action `" + id + "` was proposed by a previous admin")
	}
	pendingActions.Remove(id)
	chain.Emit("ActionExecuted", "id", id, "by", cur.Previous().Address().String())
}

// ActionReady reports whether an action could be consumed right now.
func ActionReady(id string) bool {
	a := getAction(id)
	if a == nil {
		return false
	}
	now := time.Now().Unix()
	return now >= a.at && now < a.expires && a.by == admin && !EvictionPending()
}

// GetAction reports a pending action: when it matures, when it expires,
// and who proposed it. All zero when nothing by that id is pending.
func GetAction(id string) (executableAt, expiresAt int64, by address) {
	a := getAction(id)
	if a == nil {
		return 0, 0, ""
	}
	return a.at, a.expires, a.by
}

// ListActions pages through pending action ids, ONE PER LINE: an id may
// contain commas (a price rule does), never a newline.
func ListActions(after string, limit int) (ids, next string) {
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	var b strings.Builder
	n := 0
	last, more := "", false
	pendingActions.Iterate("", "", func(key string, v any) bool {
		if after != "" && key <= after {
			return false
		}
		if n >= limit {
			more = true
			return true
		}
		if n > 0 {
			b.WriteString("\n")
		}
		b.WriteString(key)
		last = key
		n++
		return false
	})
	if !more {
		last = ""
	}
	return b.String(), last
}

func GetActionWindow() int64 { return actionWindow }

// SetActionWindow sets how long a matured action stays executable,
// between an hour and ninety days.
func SetActionWindow(cur realm, seconds int64) {
	assertIsAdminOrRecovery(cur)
	if seconds < minActionWindow || seconds > maxActionWindowS {
		panic("nsdata: the action window is 3600-7776000 seconds")
	}
	actionWindow = seconds
	chain.Emit("ActionWindowSet", "seconds", strconv.FormatInt(seconds, 10),
		"by", cur.Previous().Address().String())
}

// pruneExpiredActions frees the slots of actions nobody can execute any
// more. Bounded by maxPendingActions.
func pruneExpiredActions(now int64) {
	var dead []string
	pendingActions.Iterate("", "", func(key string, v any) bool {
		if now >= v.(*pendingAction).expires {
			dead = append(dead, key)
		}
		return false
	})
	for _, k := range dead {
		pendingActions.Remove(k)
		chain.Emit("ActionExpired", "id", k)
	}
}

func dropAllActions(reason string) int {
	var ids []string
	pendingActions.Iterate("", "", func(key string, v any) bool {
		ids = append(ids, key)
		return false
	})
	for _, k := range ids {
		pendingActions.Remove(k)
		chain.Emit("ActionInvalidated", "id", k, "reason", reason)
	}
	return len(ids)
}

package nsdata

import (
	"chain"

	"gno.land/r/nym-mnsrehearsal001/nsnft/v3"
)

// isFresh reports whether a name's profile data belongs to the token's
// CURRENT ownership epoch. See Name.epoch and freshen.
func isFresh(n *Name, tid string) bool { return freshAt(n, nsnft.Epoch(tid)) }

// freshAt is isFresh with the ledger's answer passed in. See freshenTo.
func freshAt(n *Name, epoch int64) bool { return n.epoch == epoch }

// ownsNow reports whether `addr` holds the token right now, per the ledger.
func ownsNow(addr address, tid string) bool {
	return addr != "" && nsnft.OwnerOf(tid) == addr
}

// isValidNow / isReclaimable are pure integer math over `termLength` and
// `gracePeriod`, both of which are settable — so the lifecycle rules
// themselves can be retuned after deployment. All times are unix seconds.
func isValidNow(expires, now int64) bool {
	return now < expires
}

// isReclaimable compares the elapsed time with the grace period instead of
// adding the grace period to the expiry. The sum wrapped: an expiry of
// math.MaxInt64 — the natural "never expires" value — read as valid AND
// reclaimable at once, and a stranger could take the name (audit L-2). A
// name that has not expired is never reclaimable, whatever grace says.
func isReclaimable(expires, now int64) bool {
	if now < expires {
		return false
	}
	return now-expires >= gracePeriod
}

// streakOf derives how many whole terms a holder has actually lived
// through, replacing the counter that used to be stored on the record.
//
// The stored version counted RENEWAL CALLS, so it measured transactions
// rather than time: prepaying five years bumped it five times on a name
// registered that morning, and an earlier version could be run up
// arbitrarily by calling renew in a loop within one block. Deriving it
// from the registration date makes it unbuyable by construction — the
// only way to increase it is for time to pass — and it resets on its own
// when a lapsed name is reclaimed, because a reclaim writes a fresh
// record with a new `registered`.
//
// termLength is settable and could legitimately be zero, which would
// otherwise divide by zero in a realm that cannot be redeployed.
func streakOf(registered, now int64) int64 {
	if termLength <= 0 || now <= registered {
		return 0
	}
	return (now - registered) / termLength
}

// assertIsTrustedLogic is the gate on every mutation function below.
// cur.Previous().Address() resolves to the CALLING realm's own address
// when invoked via cross(cur) from another realm — same idiom already
// used for assertIsAdmin, just checking a different address. A stray
// call from anywhere else (a different realm, a direct user tx trying
// to call these directly) is rejected.
func assertIsTrustedLogic(cur realm) {
	// The pause check lives here rather than in each mutation so it can
	// never be forgotten on a new one: every write in the realm passes
	// through this gate.
	if paused {
		panic("nsdata: registry is paused")
	}
	// A WALLET IS NEVER LOGIC, even if somebody trusted one (audit L-4).
	// The trust set takes any address, and a wallet granted by mistake —
	// or "temporarily", for a migration — could call every write here
	// directly, policy-free. A run script carries its signer's address, so
	// it is refused too.
	if prev := cur.Previous(); prev.IsUser() || prev.IsEphemeral() {
		panic("nsdata: trusted logic is a deployed realm, never a wallet or a run script")
	}
	if trustedLogicSet.Get(cur.Previous().Address().String()) == nil {
		panic("nsdata: restricted to a trusted logic realm")
	}
}

// -- key encodings --
//
// Two DIFFERENT orderings, deliberately, and it matters which is which:
//
//   storage key : domain + "*" + label   (nameTreeKey)
//   token ID    : label  + "*" + domain  (nameTokenID)
//
// The storage key is DOMAIN-first so that every per-domain query is a
// RANGED scan over a contiguous key span instead of a full-tree scan
// with a filter. Before this, ListNames/CountNames walked every name in
// the registry to answer a question about one domain, which made the
// gnoweb home page O(domains × names) — a permanent, unfixable DoS in an
// immutable realm once the registry grew. Since this realm is deployed
// exactly once, the key layout is a forever decision; it is made here.
//
// The token ID stays label-first because that is the user-facing
// identity (`alice*meme`), it is what the NFT exposes to every external
// tool, and it is what `primary` stores for reverse resolution.
//
// Neither a label nor a domain may contain "*" (enforced by
// validateLabel in the logic realm), so both encodings split
// unambiguously on the first "*".

func nameTreeKey(label, domain string) string { return domain + "*" + label }

func nameTokenID(label, domain string) string { return label + "*" + domain }

// There is no domainTokenID any more: domains are records, not tokens.
// See MIGRATION.md, second attempt, rule 7.

// domainRange returns the [start, end) key bounds covering exactly the
// names stored under `domain`. '+' (0x2B) is the next byte after '*'
// (0x2A), so `domain+"+"` sorts immediately past every `domain+"*"+...`
// key while still sorting before any longer domain (e.g. "meme+" falls
// between "meme*zzz" and "memes*a").
func domainRange(domain string) (start, end string) {
	return domain + "*", domain + "+"
}

// accountKey is the per-address store's key: the address, a colon, the
// field. A bech32 address never contains ":" and a field may not (see
// assertAccountKey), so the split is unambiguous, and every field of one
// address sorts into one span.
func accountKey(owner address, field string) string { return owner.String() + ":" + field }

// accountRange bounds exactly one address's fields. ';' (0x3B) is the byte
// after ':' (0x3A), the same trick domainRange plays with '*' and '+'.
func accountRange(owner address) (start, end string) {
	s := owner.String()
	return s + ":", s + ";"
}

// splitTokenID splits a `label*domain` TOKEN ID. Do not use it on a
// storage key — see the ordering note above.
func splitTokenID(tid string) (label, domain string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

// -- lookups --

func mustGetDomain(label string) *Domain {
	v := domains.Get(label)
	if v == nil {
		panic("nsdata: unknown domain: " + label)
	}
	return v.(*Domain)
}

func getDomain(label string) (*Domain, bool) {
	v := domains.Get(label)
	if v == nil {
		return nil, false
	}
	return v.(*Domain), true
}

func mustGetName(label, domain string) *Name {
	v := names.Get(nameTreeKey(label, domain))
	if v == nil {
		panic("nsdata: unknown name: " + nameTokenID(label, domain))
	}
	return v.(*Name)
}

func getName(label, domain string) (*Name, bool) {
	v := names.Get(nameTreeKey(label, domain))
	if v == nil {
		return nil, false
	}
	return v.(*Name), true
}

// clearPrimaryIfPointingAt drops `owner`'s reverse-resolution pointer
// when (and only when) it still points at `tid`. Called on every
// ownership change — transfer and reclaim.
//
// Without this, `primary` was a write-only tree: it had a Set path and
// no Remove path anywhere in the realm, so selling or losing a name left
// the previous holder permanently reverse-resolving to a name somebody
// else now owns. Reverse resolution asserting ownership that is no
// longer true is the one thing a name service must never do.
func clearPrimaryIfPointingAt(owner address, tid string) {
	k := owner.String()
	if v := primary.Get(k); v != nil && v.(string) == tid {
		primary.Remove(k)
		chain.Emit("PrimaryCleared", "owner", k, "tid", tid, "auto", "true")
	}
}

package nsdata

import (
	"strconv"

	"chain"
)

/*
EVERY RECORD AND CONFIG CHANGE EMITS, FROM THE VAULT.

There were no events here outside governance, and none in the logic realm
at all, so the audit's stolen-admin attacks were invisible until the
ledger's Burn and Mint showed the result (audit M-6). PREFLIGHT.md and
MAINNET.md make monitoring the mitigation — "a timelock is worthless if
nobody watches it" — and there was nothing to watch.

They are emitted here rather than in nslogic so the coverage survives a
logic swap: whatever realm writes, the vault says what changed. Each one
carries `by`, the realm that made the write. For record writes that is a
trusted logic realm, which is the point — a write from a realm a monitor
did not expect IS the incident. nslogic adds its own AdminAction event with
the signer and the call.

Profile writes name the field and never the value: the value is in the
transaction already, and an event index is not the place to collect
people's addresses a second time.
*/

func emitBy(cur realm, typ string, kv ...string) {
	kv = append(kv, "by", cur.Previous().Address().String())
	chain.Emit(typ, kv...)
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// emitConfig is the one event for every typed vault setting.
func emitConfig(cur realm, key, value string) {
	emitBy(cur, "ConfigSet", "key", key, "value", value)
}

package nsdata

import (
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Snapshot support: the other half of the contingency plan.
//
// Governance protects against a stolen or lost key. This file protects
// against the case no key can fix — a VM-level corruption, a chain
// migration, a defect in this realm discovered too late — where the only
// way out is to reconstruct the registry somewhere else. That is
// possible only if the whole state can be read out reliably and
// repeatably, which needs pagination: an unpaginated listing of a
// registry with tens of thousands of names is one query that is too
// large to ever return, and a snapshot you cannot take is not a backup.
//
// Recovery shape, should it ever be needed:
//   1. Pause() — freeze the registry so it cannot drift from the snapshot.
//   2. Page through the exports here to reconstruct state off-chain.
//   3. Deploy a successor, import the snapshot.
//   4. SetSuccessor() on this realm so readers can follow the move.
//
// The exports are also just useful: an operator who takes a snapshot
// every week has an off-chain record independent of any single chain.

const maxPage = 200

// pageKeys walks a key span and returns up to `limit` keys after the
// `after` cursor, plus the cursor to pass next (empty when exhausted).
func pageKeys(t *avl.Tree, start, end, after string, limit int) (csv, next string) {
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	from := start
	if after != "" && after > from {
		from = after
	}
	var b strings.Builder
	n := 0
	hasMore := false
	last := ""
	t.Iterate(from, end, func(key string, v any) bool {
		if after != "" && key <= after {
			return false
		}
		if n >= limit {
			hasMore = true
			return true
		}
		if n > 0 {
			b.WriteString(",")
		}
		b.WriteString(key)
		last = key
		n++
		return false
	})
	if !hasMore {
		last = ""
	}
	return b.String(), last
}

// ExportDomains pages through every domain label.
func ExportDomains(after string, limit int) (labels, next string) {
	return pageKeys(&domains, "", "", after, limit)
}

// ExportNames pages through every name in the registry, as raw storage
// keys (`domain*label`). Pass an empty domainLabel to walk the whole
// tree, or a domain to walk just that domain's span.
func ExportNames(domainLabel, after string, limit int) (keys, next string) {
	if domainLabel == "" {
		return pageKeys(&names, "", "", after, limit)
	}
	start, end := domainRange(domainLabel)
	return pageKeys(&names, start, end, after, limit)
}

// ExportPrimary pages through the reverse-resolution table as owner
// addresses; pair with GetPrimary to read each value.
func ExportPrimary(after string, limit int) (owners, next string) {
	return pageKeys(&primary, "", "", after, limit)
}

// ExportGlobalKeys lists the package-level extension slot's keys; pair
// with GetGlobal for values.
func ExportGlobalKeys(after string, limit int) (keys, next string) {
	return pageKeys(&globals, "", "", after, limit)
}

// ExportAccounts pages through the per-address store as raw keys
// `<address>:<field>`; pair with GetAccount for each value. Field names
// are comma-free by construction (see assertAccountKey).
func ExportAccounts(after string, limit int) (keys, next string) {
	return pageKeys(&accounts, "", "", after, limit)
}

// AccountCount is how many per-address fields exist, so a snapshot of
// the store can be checked for completeness. A separate read rather than
// a fifth value from Sizes, whose shape the snapshot tools already parse.
func AccountCount() int { return accounts.Size() }

// ExportDomainExtraKeys / ExportNameExtraKeys list a record's extension
// keys so a snapshot can capture data this realm has no schema for.
// Keys are comma-free by construction (see assertExtraKey), so a CSV
// listing is unambiguous.
func ExportDomainExtraKeys(label, after string, limit int) (keys, next string) {
	d := mustGetDomain(label)
	return pageKeys(&d.extra, "", "", after, limit)
}

// A previous holder's keys are not exported. A snapshot that captured them
// would carry the seller's payment addresses into a restore as the buyer's.
func ExportNameExtraKeys(label, domainLabel, after string, limit int) (keys, next string) {
	n := mustGetName(label, domainLabel)
	if !isFresh(n, nameTokenID(label, domainLabel)) {
		return "", ""
	}
	return pageKeys(&n.extra, "", "", after, limit)
}

// KNOWN SNAPSHOT GAP, recorded rather than left to be discovered during
// an actual recovery: GRC-721 OPERATOR APPROVALS live inside nsnft's
// token state and are not enumerable
// through any read this realm exposes. Every other piece of state is
// reachable — record fields via GetDomainInfo/GetNameInfo, extension keys
// via the Export*ExtraKeys pagers, reverse resolution via ExportPrimary,
// globals via ExportGlobalKeys, per-address state via ExportAccounts —
// but operator approvals are not, so a
// reconstructed registry will silently lack them and holders would need
// to re-grant. Treated as acceptable (an approval is a revocable
// convenience, not ownership) but it must not be assumed complete.

// Sizes let an operator verify a snapshot is complete rather than
// trusting that pagination terminated correctly.
func Sizes() (domainCount, nameCount, primaryCount, globalCount int) {
	return domains.Size(), names.Size(), primary.Size(), globals.Size()
}

package nsdata

import "gno.land/p/nt/avl/v0"

/*
GENESIS — the state a registry is born with.

WHY IT LIVES IN THE PACKAGE. This project has been through three chains
(topaz-1, sapphire-1, pearl-1), and every time the price list, the
referral tiers and the domain list existed only as somebody's memory of an
afternoon spent in the admin panel. A value set by hand after deployment
is a value that is lost with the chain. A value in this file ships with
the realm.

WHY nsdata AND NOT nslogic. This realm owns the state it writes, so init
can write it with no permission from anybody. nslogic cannot: it writes
through this realm's trust gate, and trust is granted by a timelocked
proposal AFTER deployment — an init in nslogic would panic before the
grant existed and take the deploy down with it.

WHY DOMAINS CAN BE CREATED HERE AT ALL. They used to be tokens, and
minting one needs nsnft to trust this realm, which it cannot yet do during
init. Domains are records now (MIGRATION.md, rule 7), so creating one is a
tree write and nothing more.

WHAT IS NOT HERE. Names. No holder's records carry from one chain to the
next — that is the owner's decision (see the mainnet checklist): testnet
wallets get an entitlement, not their old records. And nothing that names
a generation — the token URI base, the lab domain — because this file is
meant to be the same for the sandbox and for mainnet.

EVERY VALUE IS VALIDATED AND A BAD ONE PANICS. A genesis file that quietly
skipped a malformed global would deploy a registry that looks configured
and is missing its price list, and nothing would say so until somebody was
charged the fallback. Failing the deploy costs one retry.

The data itself is generated into genesis_data.gno by
tools/freeze-genesis.py, from a snapshot of a chain that was configured by
hand. Edit the chain, snapshot it, regenerate; do not edit the data file.
*/

// Genesis domains get a long runway. They are project-owned and all
// created in the same block, so a single term would have every one of them
// lapse on the same day a year later — and a lapsed domain refuses every
// registration under it. Renewing them is still the admin's job; this
// just stops the first renewal being a cliff.
const genesisDomainTerms = 10

/*
refusedInGenesis names what may never be baked into a registry's birth.

Anything whose VALUE is an address: a key that holds power — the free-tier
granter was the one that shipped by accident — is set deliberately, after
deploy, on the chain it belongs to, never inherited from whatever chain a
snapshot was taken on. And the lab nomination, which belongs to a sandbox
generation and would otherwise let a hand-edited data file ship a lab on
a real domain.

No regexp: one compiled pattern costs more storage than this whole file.
*/
func refusedInGenesis(key, value string) bool {
	if key == "labdomain" || key == "granter" {
		return true
	}
	return looksLikeAddress(value)
}

func looksLikeAddress(v string) bool {
	if len(v) != 40 || v[0] != 'g' || v[1] != '1' {
		return false
	}
	for i := 2; i < len(v); i++ {
		c := v[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

type genesisCfg struct {
	termLength, gracePeriod                           int64
	minLabelLen, maxLabelLen                          int
	maxExtraKeyLen, maxExtraValueLen, maxExtraEntries int
	maxDeletePerCall                                  int
}

type genesisDomain struct {
	label string
	extra [][2]string
}

func applyGenesis(deployer address, now int64) {
	// Limits first, so every extra written below is held to them.
	c := genesisConfig()
	if c.maxExtraKeyLen > 0 {
		maxExtraKeyLen = c.maxExtraKeyLen
	}
	if c.maxExtraValueLen > 0 {
		maxExtraValueLen = c.maxExtraValueLen
	}
	if c.maxExtraEntries > 0 {
		maxExtraEntries = c.maxExtraEntries
	}
	if c.maxDeletePerCall > 0 {
		maxDeletePerCall = c.maxDeletePerCall
	}
	if c.minLabelLen > 0 {
		minLabelLen = c.minLabelLen
	}
	if c.maxLabelLen > 0 {
		maxLabelLen = c.maxLabelLen
	}
	if c.termLength > 0 {
		termLength = c.termLength
	}
	if c.gracePeriod > 0 {
		gracePeriod = c.gracePeriod
	}
	// The one invariant the lifecycle setters guard, guarded here too:
	// anchoring a renewal to its previous due date only makes sense while a
	// renewal cannot land more than one term late.
	if gracePeriod > termLength {
		panic("nsdata genesis: grace period is longer than the term")
	}

	for _, kv := range genesisGlobals() {
		for _, r := range reservedGlobals {
			if kv[0] == r {
				panic("nsdata genesis: " + r + " belongs to the restore machinery")
			}
		}
		if refusedInGenesis(kv[0], kv[1]) {
			panic("nsdata genesis: " + kv[0] + " holds an address or names a generation; set it after deploy, deliberately")
		}
		if err := setGlobal(kv[0], kv[1]); err != nil {
			panic("nsdata genesis: global " + kv[0] + ": " + err.Error())
		}
	}

	for _, g := range genesisDomains() {
		if err := assertLabelKeySafe(g.label); err != nil {
			panic("nsdata genesis: domain " + g.label + ": " + err.Error())
		}
		if len(g.label) < minLabelLen || len(g.label) > maxLabelLen {
			panic("nsdata genesis: domain " + g.label + " is outside the label length limits")
		}
		if _, dup := getDomain(g.label); dup {
			panic("nsdata genesis: domain " + g.label + " is listed twice")
		}
		// Owned by the deployer, like every domain the admin registers.
		// Under `gno test` there is no deployer, and the domains are still
		// created so the tests exercise the same registry a chain gets.
		d := &Domain{owner: deployer, registered: now,
			expires: now + genesisDomainTerms*termLength, extra: avl.Tree{}}
		for _, kv := range g.extra {
			if err := setExtra(&d.extra, kv[0], kv[1]); err != nil {
				panic("nsdata genesis: domain " + g.label + " key " + kv[0] + ": " + err.Error())
			}
		}
		domains.Set(g.label, d)
	}
}

package nsdata

import (
	"strconv"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
)

// Governance and emergency response for a realm that can never be
// redeployed. Everything here is callable ONLY by a direct wallet
// transaction — never through a logic realm — so a compromised or buggy
// logic realm can never touch it.
//
// Three powers, deliberately not held by the same key:
//
//	admin     — day-to-day authority: grants/revokes logic realms, tunes
//	            config. The warm key.
//	recovery  — cannot operate the registry at all. Can only rotate
//	            admin, cancel a pending change, revoke a logic realm,
//	            and pause. MUST be a multisig in production; see the
//	            trust note below for why that is not optional.
//	guardian  — can ONLY pause. Nothing else. Safe to keep hot (a
//	            monitoring bot), because its compromise costs an
//	            outage, never the registry.
//
// GRANTING POWER IS SLOW, REVOKING IT IS INSTANT. Handing authority to a
// new admin or a new logic realm goes through a timelock, and so — since
// actions.gno — does every admin action in the logic realm that destroys
// or moves names or money (deletion, lifecycle and treasury changes,
// unfreezing, reassigning, pricing rules, large price moves). Revocation,
// cancellation and pause are immediate; undoing a pause takes recovery or
// the timelock. An attacker holding one key cannot act instantly: they
// must announce and wait, and every step emits an event.
//
// EACH ROLE CAN ROTATE THE OTHER, AND THE ADMIN CANNOT VETO ITS OWN
// REPLACEMENT. A rotation recovery proposes — of the admin, or of itself —
// can be cancelled or displaced only by recovery. An admin-initiated
// rotation of recovery is the admin's to withdraw and, since the re-audit
// of 2026-10-16, recovery's to veto too: recovery is the root (see the
// trust note below), and a veto it could not send in its incident sitting
// reverted the whole sitting, eviction included. A LOST recovery cancels
// nothing, so the admin can still replace it. Proposals live in PER-KIND
// slots so an admin rotation and a recovery rotation can never contend for
// the same slot — an earlier single-slot design let one in-flight proposal
// freeze the entire governance surface, which meant the honest key could
// not even propose a response.
//
// THE TRUST ASYMMETRY, chosen rather than papered over. Both roles rotate
// the other on the same timelock, and it used to be that whichever proposed
// FIRST matured first and won — so a thief holding the admin key, acting
// before anybody noticed, could take recovery too. Since the re-audit of
// 2026-10-16 (M-1) RECOVERY WINS: once recovery's eviction is pending,
// nothing the admin proposed executes before it, a rotation of recovery the
// admin queued earlier included, and the eviction drops all of it. Every
// asymmetry hands the mirror-image power to whoever steals the favoured
// role, and this one is deliberate, the same as the ledger's (nsnft
// governance.gno): a stolen RECOVERY key now beats an honest admin, which
// is why recovery must be the cold multisig and the admin the key that is
// used.
//
// The mitigation is therefore operational as well as contractual:
//   - recovery MUST be a multisig, so no single stolen key can use it;
//   - timelockDelay must be long enough that you will actually notice an
//     event within it;
//   - watch for GovernanceProposed and ActionProposed and treat one you
//     did not initiate as an active incident.
//
// THE INCIDENT RUNBOOK, in this order (MAINNET.md §1b has it in full).
// First RevokeTrustedLogic on every entry of ListTrustedLogic(): guardian,
// admin or recovery may, it is instant, and re-granting needs the
// timelock, so no stolen key can switch the logic back on. Then Pause, and
// Disarm (incident.gno). Then, from recovery: the counter-rotation FIRST and
// alone — proposing it drops everything the admin had pending — then
// VoidGrantsSince and SetQuarantine (incident.gno), and CancelAllActions /
// CancelPending on anything left, which cannot revert; execute the eviction
// at maturity, before anything else.
//
// Pause does NOT stop ExecutePending — it stops registry mutations, which
// limits damage but does not stop a rotation. Do not rely on it for that.
//
// RECOVERY'S EVICTION LANDS FIRST, by rule (re-audit 2026-10-16, M-1). An
// eviction used to drop the admin's plans only when it executed, and anyone
// chose the order matured proposals ran in: the thief could re-propose a
// cancelled grant the block after recovery's sitting, or execute recovery's
// own move to a new cold key first, which dropped recovery's eviction. Now:
//
//	recovery proposing the eviction DROPS everything the admin had pending
//	— grants, delay, unpause, a rotation of recovery, every timelocked
//	action — so nothing of the admin's is held to spring back if the
//	eviction is cancelled; while it is pending (EvictionPending) the admin
//	proposes nothing, nothing it proposed may execute, and logic can spend
//	none of its actions;
//
//	a veto holds: what recovery cancels of the admin's, the admin may not
//	propose again for one timelock (any action, after an action veto), so
//	the sitting cannot be re-proposed around; recovery's eviction landing
//	clears the vetoes, and nothing else does;
//
//	recovery moving ITSELF keeps its eviction: the eviction is protected by
//	the recovery role, which the new key holds, and recovery's rotation of
//	itself is recovery's alone to cancel or displace. Only an
//	admin-initiated replacement of recovery drops the replaced key's
//	eviction.
//
//	recovery's cancellations are idempotent: cancelling what is no longer
//	pending does nothing, so a thief withdrawing its own proposal first
//	cannot make recovery's batched sitting revert.
type pendingOp struct {
	kind string // "admin" | "recovery" | "grantLogic" | "delay" | "unpause"
	addr address
	dur  time.Duration
	at   time.Time // when it becomes executable

	// protectorRole names the role that has EXCLUSIVE control of this
	// proposal — "" means either admin or recovery may cancel it. Set to
	// "recovery" on a recovery-initiated admin rotation, and to "admin"
	// on an admin-initiated recovery rotation, so the role being replaced
	// cannot veto its own replacement.
	protectorRole string

	// by is who proposed it. Recorded so that nobody has to reconstruct
	// it from events, and so the rotation rule below is checkable.
	by address
}

var (
	recovery address
	guardian address
	paused   bool

	// Delay applied to every power-granting change. Starts at zero so
	// local development and initial wiring are not painful; raise it
	// before the registry holds anything worth stealing. Changing it is
	// itself timelocked, or an attacker would simply set it to zero.
	timelockDelay time.Duration

	// Upper bound on timelockDelay. Without it, one execution of an
	// absurd delay would stamp every FUTURE proposal with an unreachable
	// maturity and permanently brick governance in a realm that cannot be
	// redeployed. Settable, but itself bounded by absoluteMaxTimelock.
	maxTimelockDelay = 30 * 24 * time.Hour

	// One genuine hard ceiling: a bound that could itself be raised
	// without limit would not be a bound.
	absoluteMaxTimelock = 365 * 24 * time.Hour

	// Per-kind proposal slots, keyed by kind. Per-kind rather than a
	// single slot so that one in-flight proposal cannot freeze the whole
	// governance surface.
	pendingOps avl.Tree

	// If this registry is ever abandoned in favour of a successor
	// deployment, this is how readers discover where it went.
	successor string

	// kind -> unix second until which the admin may not propose that kind
	// again, because recovery vetoed it; "action" for timelocked actions.
	// See the note above pendingOp. Cleared when the admin rotates.
	vetoUntil avl.Tree
)

// -- role checks --

func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("nsdata: restricted to admin")
	}
}

func assertIsAdminOrRecovery(cur realm) {
	a := cur.Previous().Address()
	if a != admin && a != recovery {
		panic("nsdata: restricted to admin or recovery")
	}
}

func assertCanPause(cur realm) {
	a := cur.Previous().Address()
	if a != admin && a != recovery && a != guardian {
		panic("nsdata: restricted to admin, recovery or guardian")
	}
}

// -- emergency stop --

// Pause halts every registry mutation, timelocked actions included.
// Reads are unaffected, so names stay resolvable while writes are frozen.
//
// It deliberately does NOT gate ExecutePending: governance must keep
// working during an incident — recovery's counter-rotation above all.
//
// A pause also drops a pending admin-proposed unpause, so the guardian
// bot can hold the registry paused against a stolen admin key simply by
// pausing again whenever it sees UnpauseProposed.
func Pause(cur realm) {
	assertCanPause(cur)
	paused = true
	if getPendingOp("unpause") != nil {
		pendingOps.Remove("unpause")
		chain.Emit("GovernanceInvalidated", "kind", "unpause", "reason", "paused again")
	}
	chain.Emit("Paused", "by", cur.Previous().Address().String())
}

/*
Unpause restarts the registry at once, and only RECOVERY may do that.

It used to be open to the admin too, which made a pause useless against
the key most likely to be stolen: the admin could unpause in the same
multi-message transaction as whatever it did next, so a pause stopped only
writers that did not hold admin. An audit showed it. The admin can still
unpause — ProposeUnpause, then the timelock — so a false alarm costs a
delay rather than the cold key; recovery can cancel that proposal, and any
new pause drops it. The guardian is excluded as before: a hot key that can
stop the system must not also be able to restart it.
*/
func Unpause(cur realm) {
	if cur.Previous().Address() != recovery {
		panic("nsdata: an instant unpause takes the recovery key; the admin may ProposeUnpause and wait out the timelock")
	}
	paused = false
	if getPendingOp("unpause") != nil {
		pendingOps.Remove("unpause")
	}
	chain.Emit("Unpaused", "by", cur.Previous().Address().String())
}

// ProposeUnpause is the admin's way back from a pause: a proposal like
// any grant of power, executable by anyone once it matures.
func ProposeUnpause(cur realm) {
	assertIsAdmin(cur)
	if !paused {
		panic("nsdata: the registry is not paused")
	}
	setPending(cur, &pendingOp{kind: "unpause"})
}

func IsPaused() bool { return paused }

// -- trusted logic realms (a set, not a single slot) --

func IsTrustedLogic(addr address) bool {
	return trustedLogicSet.Get(addr.String()) != nil
}

func ListTrustedLogic() string {
	out := ""
	trustedLogicSet.Iterate("", "", func(key string, v any) bool {
		if out != "" {
			out += ","
		}
		out += key
		return false
	})
	return out
}

// RevokeTrustedLogic is INSTANT and available to the guardian, because
// cutting off a misbehaving logic realm is the emergency action that must
// never wait on a timelock.
func RevokeTrustedLogic(cur realm, logicAddr address) {
	assertCanPause(cur)
	trustedLogicSet.Remove(logicAddr.String())
	chain.Emit("TrustedLogicRevoked", "addr", logicAddr.String(), "by", cur.Previous().Address().String())
}

// -- timelocked proposals --

// ProposeAdminTransfer starts an admin rotation. When recovery initiates
// it, only recovery may cancel it — the admin being replaced gets no veto
// over their own replacement.
func ProposeAdminTransfer(cur realm, newAdmin address) {
	assertIsAdminOrRecovery(cur)
	if !newAdmin.IsValid() {
		panic("nsdata: invalid address")
	}
	role := ""
	if cur.Previous().Address() == recovery && recovery != admin {
		role = "recovery"
	}
	setPending(cur, &pendingOp{kind: "admin", addr: newAdmin, protectorRole: role})
	if role == "recovery" {
		// AN EVICTION DROPS THE ADMIN'S PLANS WHEN IT IS PROPOSED, not only
		// when it lands: held instead, they all sprang back the moment the
		// eviction was cancelled — to fix a typo in its target, say — and a
		// rotation of recovery the admin queued outlived it (re-audit
		// follow-up, 2026-10-16).
		dropPendingProtectedBy("recovery", "admin")
		dropAdminProposals("recovery is replacing the admin")
	}
}

// ProposeRecoveryTransfer is the mirror image: when admin initiates it,
// only admin may cancel it, so a compromised recovery key cannot block
// its own replacement either.
func ProposeRecoveryTransfer(cur realm, newRecovery address) {
	assertIsAdminOrRecovery(cur)
	if !newRecovery.IsValid() {
		panic("nsdata: invalid address")
	}
	role := ""
	if cur.Previous().Address() == admin && recovery != admin {
		role = "admin"
	}
	// Recovery's rotation of itself is recovery's alone: unprotected, the
	// admin could cancel it, or displace it with a rotation of its own that
	// recovery could then neither cancel nor replace.
	if cur.Previous().Address() == recovery && recovery != admin {
		role = "recovery"
	}
	setPending(cur, &pendingOp{kind: "recovery", addr: newRecovery, protectorRole: role})
}

func ProposeTrustedLogicGrant(cur realm, logicAddr address) {
	assertIsAdmin(cur)
	if !logicAddr.IsValid() {
		panic("nsdata: invalid address")
	}
	setPending(cur, &pendingOp{kind: "grantLogic", addr: logicAddr})
}

// ProposeTimelockDelay is bounded on BOTH sides. An unbounded delay would
// let a single execution stamp every future proposal with an unreachable
// maturity, permanently disabling governance in an unredeployable realm.
func ProposeTimelockDelay(cur realm, seconds int64) {
	assertIsAdmin(cur)
	if seconds < 0 {
		panic("nsdata: delay cannot be negative")
	}
	d := time.Duration(seconds) * time.Second
	// Guard the multiplication itself, not just the input: seconds is
	// attacker-chosen and time.Duration is int64 nanoseconds, so a large
	// value would overflow to a negative (instantly-mature) delay.
	if seconds > int64(absoluteMaxTimelock/time.Second) || d < 0 || d > maxTimelockDelay {
		panic("nsdata: delay out of range")
	}
	setPending(cur, &pendingOp{kind: "delay", dur: d})
}

// SetMaxTimelockDelay raises or lowers the ceiling on timelockDelay.
// Bounded by absoluteMaxTimelock, and it cannot be set below the delay
// currently in force.
func SetMaxTimelockDelay(cur realm, seconds int64) {
	assertIsAdminOrRecovery(cur)
	// Bound the input before multiplying: a huge value used to wrap to a
	// sub-second ceiling and be accepted (audit L-3a).
	if seconds < 0 || seconds > int64(absoluteMaxTimelock/time.Second) {
		panic("nsdata: max delay out of range")
	}
	d := time.Duration(seconds) * time.Second
	if d < 0 || d > absoluteMaxTimelock || d < timelockDelay {
		panic("nsdata: max delay out of range")
	}
	maxTimelockDelay = d
	chain.Emit("MaxTimelockDelaySet", "seconds", strconv.FormatInt(int64(d/time.Second), 10),
		"by", cur.Previous().Address().String())
}

func canControl(op *pendingOp, caller address) bool {
	switch op.protectorRole {
	case "recovery":
		return caller == recovery
	case "admin":
		// The admin's rotation of recovery: the admin's to withdraw, and
		// recovery's to veto (see the note at the top).
		return caller == admin || caller == recovery
	default:
		return caller == admin || caller == recovery
	}
}

func getPendingOp(kind string) *pendingOp {
	if v := pendingOps.Get(kind); v != nil {
		return v.(*pendingOp)
	}
	return nil
}

// EvictionPending reports a pending rotation of the admin that recovery
// proposed while the two roles are separate keys: recovery replacing an
// admin it no longer trusts. See the note above pendingOp.
func EvictionPending() bool {
	op := getPendingOp("admin")
	return op != nil && op.protectorRole == "recovery"
}

// adminAlone: the address is the admin and not also recovery — the case
// every eviction rule is about. While one key holds both, nothing is.
func adminAlone(a address) bool { return a == admin && a != recovery }

// assertAdminMayPropose refuses the admin while recovery is replacing it,
// and for one timelock after recovery vetoed a proposal of this kind.
func assertAdminMayPropose(caller address, kind string) {
	if !adminAlone(caller) {
		return
	}
	if EvictionPending() {
		panic("nsdata: recovery is replacing the admin; the admin proposes nothing until that lands")
	}
	if v := vetoUntil.Get(kind); v != nil && time.Now().Unix() < v.(int64) {
		panic("nsdata: recovery vetoed the admin's " + kind + "; the admin may propose one again from unix " +
			strconv.FormatInt(v.(int64), 10))
	}
}

// veto starts the cooldown on a kind, when recovery has just cancelled
// something the admin proposed.
func veto(caller address, kind string, proposer address) {
	if caller != recovery || caller == admin || !adminAlone(proposer) || timelockDelay <= 0 {
		return
	}
	until := time.Now().Unix() + int64(timelockDelay/time.Second)
	vetoUntil.Set(kind, until)
	chain.Emit("GovernanceVetoed", "kind", kind, "until", strconv.FormatInt(until, 10), "by", caller.String())
}

func setPending(cur realm, op *pendingOp) {
	caller := cur.Previous().Address()
	if existing := getPendingOp(op.kind); existing != nil {
		// You may replace only what you could cancel. Slots are per-kind,
		// so this contends only with another proposal of the SAME kind.
		if !canControl(existing, caller) {
			panic("nsdata: a change of this kind is pending and you may not replace it")
		}
		chain.Emit("GovernanceDisplaced", "kind", existing.kind, "by", caller.String())
	}
	assertAdminMayPropose(caller, op.kind)
	op.at = time.Now().Add(timelockDelay)
	op.by = caller
	pendingOps.Set(op.kind, op)
	// `seconds` carries a delay proposal's value, which this event used to
	// leave out, so "set the delay to zero" and "raise it" looked the same
	// to a monitor (audit L-3c).
	chain.Emit("GovernanceProposed",
		"kind", op.kind,
		"addr", op.addr.String(),
		"seconds", strconv.FormatInt(int64(op.dur/time.Second), 10),
		"executableAt", op.at.Format(time.RFC3339),
		"by", caller.String())
}

// CancelPending cancels the pending change of one kind. A proposal with a
// protectorRole can be cancelled only by that role, so a compromised key
// cannot veto its own replacement.
func CancelPending(cur realm, kind string) {
	assertIsAdminOrRecovery(cur)
	op := getPendingOp(kind)
	if op == nil {
		return // idempotent, so a batched incident sitting cannot be made to revert
	}
	if !canControl(op, cur.Previous().Address()) {
		panic("nsdata: only the " + op.protectorRole + " key may cancel this change")
	}
	pendingOps.Remove(kind)
	veto(cur.Previous().Address(), kind, op.by)
	chain.Emit("GovernanceCancelled", "kind", kind, "by", cur.Previous().Address().String())
}

// ExecutePending applies a matured change. Callable by anyone on purpose:
// execution must not depend on a particular key still being available,
// since key unavailability is one of the things being recovered from. It
// only applies what was already proposed and survived its window.
func ExecutePending(cur realm, kind string) {
	op := getPendingOp(kind)
	if op == nil {
		panic("nsdata: nothing pending of that kind")
	}
	if time.Now().Before(op.at) {
		panic("nsdata: still in the timelock window")
	}
	// The ceiling may have been lowered since this was proposed; the
	// ceiling in force wins (audit L-3b). Checked before anything moves.
	if op.kind == "delay" && op.dur > maxTimelockDelay {
		panic("nsdata: that delay is above the ceiling now in force")
	}
	// The eviction lands first, whoever picks the order: nothing the admin
	// proposed runs while recovery is replacing it (see above pendingOp).
	if op.kind != "admin" && adminAlone(op.by) && EvictionPending() {
		panic("nsdata: recovery is replacing the admin; the admin's pending changes wait for that, and die with it")
	}
	pendingOps.Remove(kind)
	switch op.kind {
	case "admin":
		admin = op.addr
		// Recovery's eviction landing clears the vetoes it was fighting with;
		// an admin moving to a key of its own choosing does not.
		if op.protectorRole == "recovery" {
			vetoUntil = avl.Tree{}
		}
		// The admin that was just replaced cannot leave behind a live
		// proposal to replace recovery...
		dropPendingProtectedBy("recovery", "admin")
		// ...nor anything else only an admin could have proposed. This
		// used to drop the recovery rotation alone, so an evicted thief's
		// grantLogic survived the eviction — re-proposed just before it,
		// it matured a delay later and the thief, holding no role at all,
		// executed it (anyone may): a realm of their choosing trusted with
		// every vault write. An audit proved it. The new admin re-proposes
		// whatever it actually wants.
		dropAdminProposals("admin rotated")
	case "recovery":
		recovery = op.addr
		// Likewise: a superseded recovery key's pending admin rotation
		// dies with it, so a stolen key cannot keep acting after the
		// operator has rotated it out — when the ADMIN replaced it. Recovery
		// moving itself keeps its eviction, which the recovery role (now the
		// new key) still protects: executing that rotation first used to be
		// the thief's way to void the eviction (re-audit M-1 b).
		if op.protectorRole == "admin" {
			dropPendingProtectedBy("admin", "recovery")
		}
	case "grantLogic":
		trustedLogicSet.Set(op.addr.String(), true)
	case "delay":
		timelockDelay = op.dur
	case "unpause":
		paused = false
	default:
		panic("nsdata: unknown pending kind")
	}
	chain.Emit("GovernanceExecuted", "kind", op.kind, "addr", op.addr.String(),
		"seconds", strconv.FormatInt(int64(op.dur/time.Second), 10),
		"proposedBy", op.by.String(), "by", cur.Previous().Address().String())
}

// dropPendingProtectedBy removes the pending change of `kind` when it is
// protected by `role` — used when that role's key has just been replaced.
func dropPendingProtectedBy(kind, role string) {
	if op := getPendingOp(kind); op != nil && op.protectorRole == role {
		pendingOps.Remove(kind)
		chain.Emit("GovernanceInvalidated", "kind", kind, "reason", role+" rotated")
	}
}

// adminOnlyKinds are the proposals only the admin can make. Every one of
// them dies when the admin rotates: whoever proposed it no longer holds
// the key that could, and an eviction that leaves the evicted key's plans
// running has not evicted anybody.
var adminOnlyKinds = []string{"grantLogic", "delay", "unpause"}

func dropAdminProposals(reason string) {
	for _, k := range adminOnlyKinds {
		if getPendingOp(k) != nil {
			pendingOps.Remove(k)
			chain.Emit("GovernanceInvalidated", "kind", k, "reason", reason)
		}
	}
	// Timelocked admin actions too (actions.gno): every one was proposed
	// by the key that just lost the role, or is about to.
	dropAllActions(reason)
}

func GetPending(kind string) (addr address, executableAt time.Time, protectorRole string) {
	op := getPendingOp(kind)
	if op == nil {
		return "", time.Time{}, ""
	}
	return op.addr, op.at, op.protectorRole
}

// GetPendingDetail is GetPending with the rest of the proposal: the delay
// a "delay" proposal would install, in seconds — which GetPending could
// not show, so "set the delay to zero" and "raise it" looked identical —
// and who proposed it.
func GetPendingDetail(kind string) (addr address, seconds int64, executableAt time.Time, protectorRole string, by address) {
	op := getPendingOp(kind)
	if op == nil {
		return "", 0, time.Time{}, "", ""
	}
	return op.addr, int64(op.dur / time.Second), op.at, op.protectorRole, op.by
}

func ListPending() string {
	out := ""
	pendingOps.Iterate("", "", func(key string, v any) bool {
		if out != "" {
			out += ","
		}
		out += key
		return false
	})
	return out
}

// -- instant, low-risk admin settings --

// SetGuardian takes the RECOVERY key, to seat a guardian as much as to
// replace one.
//
// Replacing took recovery from the start: otherwise the first move of
// anyone who steals the admin key is to point the guardian at themselves,
// disarming the emergency stop before you can use it. Seating an EMPTY
// seat used to be the admin's too, and that was the same hole: a stolen
// admin key seated its own bot, and after its eviction that bot could
// still pause and revoke, removable only by recovery (re-audit 2026-10-16,
// L-4). The deploy seats the guardian while its key still holds recovery.
func SetGuardian(cur realm, addr address) {
	if cur.Previous().Address() != recovery {
		if guardian == "" {
			panic("nsdata: seating a guardian takes the recovery key")
		}
		panic("nsdata: replacing an existing guardian requires the recovery key")
	}
	guardian = addr
	chain.Emit("GuardianSet", "addr", addr.String(), "by", cur.Previous().Address().String())
}

/*
ClearGuardian stands the pause capability down.

"Removing a power is never the dangerous direction" was the old
reasoning here, and it is wrong in one specific way: removing this power
restores the state in which SetGuardian is admin-callable. SetGuardian
demands the RECOVERY key whenever a guardian is already set, and says
why — a stolen admin key must not be able to disarm the emergency stop.
ClearGuardian then SetGuardian was a two-transaction admin-only
replacement of a live guardian, which defeats exactly that rule.

So standing down a LIVE guardian now takes the same key that replacing
one takes. Clearing when there is no guardian stays open to either role,
because then there is nothing to defeat.

The practical stakes are small — assertCanPause admits admin, recovery
and guardian, so an operator holding recovery keeps Pause and
RevokeTrustedLogic either way. It is fixed because this realm can never
be redeployed, and a documented authorization rule that a two-call
sequence walks around is not something to leave in permanent code.
*/
func ClearGuardian(cur realm) {
	assertIsAdminOrRecovery(cur)
	if guardian != "" && cur.Previous().Address() != recovery {
		panic("nsdata: standing down a live guardian takes the recovery key, the same as replacing one")
	}
	guardian = ""
	chain.Emit("GuardianSet", "addr", "", "by", cur.Previous().Address().String())
}

// SetSuccessor records where this registry moved, if it ever has to be
// abandoned. Pair it with Pause() so the retired registry cannot drift
// away from the snapshot its successor was built from.
func SetSuccessor(cur realm, s string) {
	assertIsAdminOrRecovery(cur)
	successor = s
	chain.Emit("SuccessorSet", "successor", s, "by", cur.Previous().Address().String())
}

func GetAdmin() address                  { return admin }
func GetRecovery() address               { return recovery }
func GetGuardian() address               { return guardian }
func GetSuccessor() string               { return successor }
func GetTimelockDelay() time.Duration    { return timelockDelay }
func GetMaxTimelockDelay() time.Duration { return maxTimelockDelay }

package nsdata

import (
	"strconv"
	"time"

	"chain"
)

/*
THE INCIDENT SWITCHES: the undo for what a stolen admin key set instantly
(re-audit 2026-10-16, M-2).

The admin's instant powers leave their marks in this realm — credits it
granted its own wallets, the claim window it opened, the granter's and the
keeper's seats — and those outlive its eviction. The incident runbook could
not undo them in time: every logic write passes the trust gate and the
pause, so while the logic was revoked and the registry paused nothing could
be disarmed, and the moment recovery unpaused, the thief's wallets redeemed
in the same block. So these are DIRECT WALLET CALLS on the vault, by the
governance roles, that work while paused and with every logic realm
revoked — which is exactly when they are needed — and that only ever take
something away:

	Disarm           admin, recovery or guardian. Deletes the globals whose
	                 presence is a power (disarmKeys): the claim window, the
	                 granter and the keeper. Instant and idempotent, so the
	                 guardian bot may send it without reading first.

	VoidGrantsSince  recovery. Everything a logic realm granted at or after
	                 `since`, up to this second, is void — nslogic reads its
	                 credits through GrantVoided. Windows only accumulate;
	                 none is ever lifted, so nothing voided comes back to
	                 life. Past maxGrantVoids the two with the smallest gap
	                 merge. The admin grants again what was legitimate.

	SetQuarantine    recovery. Until `until`, nothing that gives a name away
	                 runs — nslogic: credit redemption, RegisterFor, free
	                 grants — whatever the claim window says, so the registry
	                 can be unpaused before the new admin has finished
	                 cleaning up. At most maxQuarantine ahead; recovery may
	                 shorten or lift it.

THE REGISTRY STILL DOES NOT DECIDE. The key names below are the logic
realm's, like the restore machinery's own keys, and a logic realm must keep
"absent" the safe reading of each: no claim window is a closed one, no
granter and no keeper is nobody. What a void or a quarantine covers is the
logic realm's to say; the vault keeps the clocks and the roles.
*/

// disarmKeys are the globals whose presence is a power and whose absence is
// the safe reading (nslogic: credits.gno, freetier.gno, keeper.gno).
var disarmKeys = []string{"claimend", "granter", "keeper"}

const (
	maxGrantVoids = 8                       // void windows kept; the oldest two merge past it
	maxQuarantine = int64(30 * 24 * 60 * 60) // the furthest a quarantine may reach, in seconds
)

var (
	// grantVoids are [from, to] windows, unix seconds inclusive, oldest
	// first: a grant whose time falls inside any of them is void.
	grantVoids [][2]int64

	// quarantineUntil is the unix second giveaways may run again; 0 none.
	quarantineUntil int64
)

func assertIsRecovery(cur realm) {
	if a := cur.Previous().Address(); a == "" || a != recovery {
		panic("nsdata: restricted to recovery")
	}
}

// Disarm deletes the claim window, the granter and the keeper at once.
// Admin, recovery or guardian, as a direct wallet call; it works while the
// registry is paused and with every logic realm revoked.
func Disarm(cur realm) {
	assertCanPause(cur)
	had := ""
	for _, k := range disarmKeys {
		if globals.Get(k) != nil {
			globals.Remove(k)
			if had != "" {
				had += ","
			}
			had += k
		}
	}
	chain.Emit("Disarmed", "keys", had, "by", cur.Previous().Address().String())
}

// VoidGrantsSince voids every grant made at or after `since`, up to now.
// Recovery only. `since` may be 0 (everything so far) and may not be in the
// future. The window joins the ones already in force; past maxGrantVoids
// the two oldest merge, which can only void more, never less.
func VoidGrantsSince(cur realm, since int64) {
	assertIsRecovery(cur)
	now := time.Now().Unix()
	if since < 0 || since > now {
		panic("nsdata: a void starts in the past, at 0 or later")
	}
	grantVoids = insertVoid(grantVoids, [2]int64{since, now})
	for len(grantVoids) > maxGrantVoids {
		// Merge the two windows with the smallest gap between them, so the
		// fewest legitimate grants fall into the merged span (re-audit
		// follow-up), and say what was merged.
		best := 0
		for i := 1; i+1 < len(grantVoids); i++ {
			if grantVoids[i+1][0]-grantVoids[i][1] < grantVoids[best+1][0]-grantVoids[best][1] {
				best = i
			}
		}
		a, b := grantVoids[best], grantVoids[best+1]
		m := [2]int64{a[0], a[1]}
		if b[1] > m[1] {
			m[1] = b[1]
		}
		chain.Emit("GrantVoidsMerged", "from", strconv.FormatInt(m[0], 10), "to", strconv.FormatInt(m[1], 10))
		grantVoids = append(append(append([][2]int64{}, grantVoids[:best]...), m), grantVoids[best+2:]...)
	}
	chain.Emit("GrantsVoided", "from", strconv.FormatInt(since, 10), "to", strconv.FormatInt(now, 10),
		"by", cur.Previous().Address().String())
}

// insertVoid keeps the windows sorted by start and folds overlapping ones
// together, so "the gap between two windows" means what it says.
func insertVoid(ws [][2]int64, w [2]int64) [][2]int64 {
	out := [][2]int64{}
	placed := false
	for _, x := range ws {
		if !placed && w[0] < x[0] {
			out = append(out, w)
			placed = true
		}
		out = append(out, x)
	}
	if !placed {
		out = append(out, w)
	}
	merged := [][2]int64{}
	for _, x := range out {
		if n := len(merged); n > 0 && x[0] <= merged[n-1][1] {
			if x[1] > merged[n-1][1] {
				merged[n-1][1] = x[1]
			}
			continue
		}
		merged = append(merged, x)
	}
	return merged
}

// GrantVoided reports whether a grant made at unix second `at` falls inside
// a void recovery declared.
func GrantVoided(at int64) bool {
	for _, w := range grantVoids {
		if at >= w[0] && at <= w[1] {
			return true
		}
	}
	return false
}

// GrantVoids lists the void windows, "from-to" comma-separated, oldest first.
func GrantVoids() string {
	out := ""
	for i, w := range grantVoids {
		if i > 0 {
			out += ","
		}
		out += strconv.FormatInt(w[0], 10) + "-" + strconv.FormatInt(w[1], 10)
	}
	return out
}

// SetQuarantine holds every giveaway shut until `until` (unix seconds), at
// most maxQuarantine ahead; 0 lifts it. Recovery only.
func SetQuarantine(cur realm, until int64) {
	assertIsRecovery(cur)
	now := time.Now().Unix()
	if until != 0 && (until <= now || until > now+maxQuarantine) {
		panic("nsdata: a quarantine ends in the future and at most " +
			strconv.FormatInt(maxQuarantine/86400, 10) + " days ahead; 0 lifts it")
	}
	quarantineUntil = until
	chain.Emit("QuarantineSet", "until", strconv.FormatInt(until, 10), "by", cur.Previous().Address().String())
}

// QuarantineUntil is the unix second giveaways may run again, 0 for none.
func QuarantineUntil() int64 { return quarantineUntil }

// Quarantined reports whether a quarantine holds right now.
func Quarantined() bool { return time.Now().Unix() < quarantineUntil }

package nsdata

import (
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsnft/v3"
)

/*
The token reads, answered by the ledger.

These used to be the vault's own grc721 state. They are now read-throughs
to nsnft, kept here under the same names so nsview, nsskin, nsvote and
the site can go on asking the registry — while an external marketplace
asks nsnft directly and gets the identical answer, because there is only
one ledger to ask.

Token ids here are plain strings. The grc721.TokenID type was the vault's
import; this realm no longer imports grc721 at all.
*/

func isTokenValid(tid string) bool {
	label, domainLabel := splitTokenID(tid)
	n, ok := getName(label, domainLabel)
	return ok && isValidNow(n.expires, time.Now().Unix())
}

// BalanceOf counts every token an address holds — including free-tier
// tokens, which are held rather than absent. That is a real change from
// the previous generation, where a free name had no token and counted
// for nothing; nsvote gates on this, so free-tier holders now have a vote.
func BalanceOf(owner address) int64 { return nsnft.BalanceOf(owner) }

// OwnerOf hides the owner of an expired token — the anti-scam pattern,
// so our own pages never present a lapsed name as somebody's. nsnft
// itself answers regardless; see MIGRATION.md, rule 6.
func OwnerOf(tid string) address {
	owner := nsnft.OwnerOf(tid)
	if owner == "" {
		panic("nsdata: no such token: " + tid)
	}
	if !isTokenValid(tid) {
		panic("nsdata: token is expired, no current owner")
	}
	return owner
}

// GetApproved answers totally: the zero address means nobody is approved
// or there is no such token. See the long note this replaced in git
// history for why a panic here broke the marketplace once already.
func GetApproved(tid string) address { return nsnft.GetApproved(tid) }

// IsApprovedFor is the question a marketplace actually has: may this
// operator move this token, by either route?
func IsApprovedFor(tid string, operator address) bool {
	owner := nsnft.OwnerOf(tid)
	if owner == "" {
		return false
	}
	if owner == operator || nsnft.IsApprovedForAll(owner, operator) {
		return true
	}
	return nsnft.GetApproved(tid) == operator
}

func IsApprovedForAll(owner, operator address) bool {
	return nsnft.IsApprovedForAll(owner, operator)
}

// TokenURI returns a pointer at whichever view realm renders the art.
// nsnft has its own URI base for external marketplaces; both are set to
// the same view realm at wiring time.
func TokenURI(tid string) string {
	return tokenURIBase + tid
}

package nsdata

import (
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsnft/v3"
)

// Plain reads — no `cur realm` parameter, no authentication, since there
// is no caller identity to check on a read. Everything here returns raw
// stored values; formatting them for display is the view realm's job,
// not the vault's. (Status strings like "VALID (363 days left)" used to
// live here. They were display logic in a realm that can never be
// redeployed, so they moved to nsview.)

func ListDomains() string {
	var b strings.Builder
	first := true
	domains.Iterate("", "", func(key string, v any) bool {
		if !first {
			b.WriteString(",")
		}
		b.WriteString(key)
		first = false
		return false
	})
	return b.String()
}

// ListNames and CountNames scan only the key span belonging to
// `domainLabel` (see domainRange in auth.gno), costing O(names in that
// domain) rather than O(every name in the registry).
func ListNames(domainLabel string) string {
	var b strings.Builder
	first := true
	start, end := domainRange(domainLabel)
	// The label is the part of the key after "domain*". Records no
	// longer carry their own label — the key already held it, and
	// storing it twice cost storage forever to say the same thing.
	cut := len(domainLabel) + 1
	names.Iterate(start, end, func(key string, v any) bool {
		if !first {
			b.WriteString(",")
		}
		b.WriteString(key[cut:])
		first = false
		return false
	})
	return b.String()
}

func CountNames(domainLabel string) int64 {
	var count int64
	start, end := domainRange(domainLabel)
	names.Iterate(start, end, func(key string, v any) bool {
		count++
		return false
	})
	return count
}

func CountDomains() int64 { return int64(domains.Size()) }

func DomainExists(label string) bool            { _, ok := getDomain(label); return ok }
func NameExists(label, domainLabel string) bool { _, ok := getName(label, domainLabel); return ok }

func GetDomainOwner(label string) address { return mustGetDomain(label).owner }

// GetNameOwner asks the ledger. It still panics for an unknown NAME, as it
// always did, so callers that relied on that are unchanged.
func GetNameOwner(label, domainLabel string) address {
	mustGetName(label, domainLabel)
	return nsnft.OwnerOf(nameTokenID(label, domainLabel))
}

// GetDomainInfo / GetNameInfo return a whole record in one call, so a
// view realm can render a page without six round trips.
// Timestamps come back as unix SECONDS. They used to be time.Time,
// which vm/qeval rendered using gno's internal epoch, so every consumer
// had to know to subtract 62135596800 — our own frontend did exactly
// that. Returning unix seconds stops leaking that offset into every
// integration, and it is what the records now hold anyway.
//
// `streak` is computed from the registration date rather than read from
// a stored field. See streakOf.
func GetDomainInfo(label string) (owner address, registered, expires, streak int64, frozen bool) {
	d := mustGetDomain(label)
	return d.owner, d.registered, d.expires, streakOf(d.registered, time.Now().Unix()), d.frozen
}

/*
GetNameInfo keeps its six-value shape so every existing reader — nslogic,
nsview, nsskin, nsvote, the site, both snapshot tools — goes on parsing it
unchanged. Two of the six are now answered differently:

	owner  is read from nsnft, never stored here. The snapshot tools record
	       whatever this returns, so they now record the real owner — the
	       restore-hands-sold-names-back bug the first attempt had cannot
	       happen, because there is no stale copy for them to read.

	paid   replaces isNFT and means exactly one thing: the name is NOT
	       held as an un-upgraded free-tier record. It is deliberately not
	       "transferable" — a frozen paid name is locked too, and reading
	       the lock would have made a frozen paid name look free, which is
	       precisely the proxy bug that let free renewals renew paid names.
*/
func GetNameInfo(label, domainLabel string) (owner address, registered, expires, streak int64, frozen, paid bool) {
	n := mustGetName(label, domainLabel)
	tid := nameTokenID(label, domainLabel)
	return nsnft.OwnerOf(tid), n.registered, n.expires,
		streakOf(n.registered, time.Now().Unix()), n.frozen,
		nsnft.LockBits(tid)&(1<<lockBitFree) == 0
}

// GetNameTTL / GetDomainTTL report how long a resolver may cache an
// answer about this record, in seconds, where 0 MEANS NEVER CACHE — the
// ENS registry's rule, deliberately, so integrators need not read
// anything of ours to handle it correctly.
// A TTL written for a previous holder is not this holder's cache policy.
// A stale one reads as 0 — never cache — which is the safe answer during
// exactly the window after a sale when a cached answer pays the seller.
func GetNameTTL(label, domainLabel string) int64 {
	n := mustGetName(label, domainLabel)
	if !isFresh(n, nameTokenID(label, domainLabel)) {
		return 0
	}
	return n.ttl
}
func GetDomainTTL(label string) int64 { return mustGetDomain(label).ttl }

// GetNameHeldSince is when the current holder's holding began, in unix
// seconds — or 0 when the ledger has moved on since this registry last
// saw the record (a sale it has not yet observed). It can understate a
// holding, never overstate one. See Name.since.
func GetNameHeldSince(label, domainLabel string) int64 {
	n := mustGetName(label, domainLabel)
	if !isFresh(n, nameTokenID(label, domainLabel)) {
		return 0
	}
	return n.since
}

// RestoredFor reports whom a restore wrote this record for, or empty.
// See Name.restoredFor.
func RestoredFor(label, domainLabel string) address {
	return mustGetName(label, domainLabel).restoredFor
}

// IsNamePaid reports that a name is not held as an un-upgraded free-tier
// record. See GetNameInfo on why this is not "transferable".
func IsNamePaid(label, domainLabel string) bool {
	mustGetName(label, domainLabel)
	return nsnft.LockBits(nameTokenID(label, domainLabel))&(1<<lockBitFree) == 0
}

func IsDomainValid(label string) bool {
	d, ok := getDomain(label)
	return ok && isValidNow(d.expires, time.Now().Unix())
}

func IsNameValid(label, domainLabel string) bool {
	n, ok := getName(label, domainLabel)
	return ok && isValidNow(n.expires, time.Now().Unix())
}

// -- extension slots --

func GetDomainExtra(label, key string) string {
	v := mustGetDomain(label).extra.Get(key)
	if v == nil {
		return ""
	}
	return v.(string)
}

/*
GetNameExtra answers EMPTY for data written in a previous ownership epoch.

This is the read half of the lazy wipe. A sale that settles on nsnft —
through our marketplace or anybody else's — never calls this realm, so
nothing here can clear the seller's payment addresses at the moment it
happens. What this CAN do is refuse to repeat them: the instant the
ledger's epoch moves, every extra on the name stops answering, for every
reader, before anybody has written anything.

The write half, which destroys the stale data rather than hiding it, is
freshen in write.gno. Both halves are needed: hiding alone is what the
first attempt shipped, and the buyer's first edit brought the seller's
Bitcoin address back as the buyer's.
*/
func GetNameExtra(label, domainLabel, key string) string {
	n := mustGetName(label, domainLabel)
	if !isFresh(n, nameTokenID(label, domainLabel)) {
		return ""
	}
	v := n.extra.Get(key)
	if v == nil {
		return ""
	}
	return v.(string)
}

func GetGlobal(key string) string {
	v := globals.Get(key)
	if v == nil {
		return ""
	}
	return v.(string)
}

// GetAccount reads one field of an address's own record, or "" when it
// has none. See `accounts` in types.gno.
func GetAccount(owner address, key string) string {
	v := accounts.Get(accountKey(owner, key))
	if v == nil {
		return ""
	}
	return v.(string)
}

// GetPrimary is a raw pointer lookup. It reports what an address last
// SELECTED, not what it still owns — callers presenting this as reverse
// resolution must re-check ownership (see nslogic.ResolveAddress).
func GetPrimary(owner address) string {
	v := primary.Get(owner.String())
	if v == nil {
		return ""
	}
	return v.(string)
}

// -- config reads --

func GetTreasury() address                { return treasury }
func GetTermLength() int64                { return termLength }
func GetGracePeriod() int64               { return gracePeriod }
func GetMaxDeletePerCall() int            { return maxDeletePerCall }
func GetLabelPattern() string             { return labelPattern }
func GetLabelLength() (min, max int)      { return minLabelLen, maxLabelLen }
func GetTokenURIBase() string             { return tokenURIBase }
func GetExtraLimits() (k, v, entries int) { return maxExtraKeyLen, maxExtraValueLen, maxExtraEntries }
func GetGlobalEntryLimit() int            { return maxGlobalEntries }
func GetAccountLimits() (k, v, entries int) {
	return maxAccountKeyLen, maxAccountValueLen, maxAccountEntries
}

package nsdata

// The real human-facing view moved OUT of this realm into `nsview`
// (2026-08-21), after an adversarial review found three separate
// defects in the old Render() — unescaped profile-field injection into
// the markdown, an O(domains × names) home page any user could inflate
// into a permanent DoS, and links that 404'd — none of which could ever
// be fixed, because this realm is deployed once and never replaced.
//
// The lesson generalised: "it's only display code, it has no
// authorization surface" was the wrong test for what belongs in an
// immutable realm. The right test is whether a bug in it would be
// permanent. Display code changes far more often than storage schemas
// do, so it belongs in something swappable.
//
// What remains here is deliberately a fixed string: no user-authored
// data, no iteration over state, nothing that can be wrong later.
func Render(path string) string {
	return "# Meme Name Service — data realm\n\n" +
		"This realm stores records only: name and domain ownership, " +
		"configuration, and the NFT state.\n\n" +
		"The human-facing view lives in the `nsview` realm; writes go " +
		"through `nslogic`.\n"
}

// Package nsdata is the registry — the records behind every name.
//
// IT IS REPLACEABLE NOW, and that changes what every comment below means.
//
// Until this generation the vault held ownership as well as records, which
// made it the one realm that could never be redeployed: a "new nsdata"
// was an empty registry and everybody's names with it. So everything here
// was written as if it would ship forever — no constants, no policy, no
// display code — and the comments say "can never be replaced" throughout.
//
// Ownership has moved to nsnft, the small frozen token realm. This realm
// keeps records — dates, the frozen bit, TTL, profile data, reverse
// resolution, pricing globals, domains — and reads every owner from the
// ledger rather than storing one. Replacing it is a new package plus one
// Trust call on nsnft; no token moves, no holder notices. The integration
// address the outside world keeps is nsnft's, not this one's.
//
// The two old rules still hold, for a better reason than before:
//
//  1. NOTHING IS A CONSTANT. Term length, grace period, size caps — all
//     settable. Not because a mistake would be permanent any more, but
//     because a registry that needs a redeploy to change a number is a
//     registry that gets redeployed carelessly.
//
//  2. THE REGISTRY STORES, IT DOES NOT DECIDE. Pricing math, validation,
//     what a profile field means — all of it lives in nslogic. Anything
//     this realm "knows" is a rule that needs a migration to change.
//
// Rule 2 is why Domain and Name carry an `extra` tree instead of a
// growing list of typed fields.
package nsdata

import (
	"time"

	"gno.land/p/nt/avl/v0"
)

// Timestamps are unix SECONDS, not time.Time, and that is the single
// biggest storage decision in this file. Measured on three throwaway
// realms (MAINNET.md §3d-i): two time.Time fields were 70% of a record,
// because each carries an unused nanosecond field and a *Location
// pointer for a value that is always UTC. Switching to int64 takes a
// real 7,385-byte domain record to 6,246 bytes on its own, and turns
// every lifecycle comparison into integer arithmetic.
//
// Nothing here stores a label. The AVL key already holds it — `label`
// for a domain, `domain*label` for a name — so a copy inside the record
// was paying storage forever to duplicate the thing used to find it.
type Domain struct {
	owner      address
	registered int64 // unix seconds
	expires    int64 // unix seconds
	frozen     bool

	// How long a resolver may cache an answer about this record, in
	// seconds, where 0 MEANS NEVER CACHE. Copied deliberately from the
	// ENS registry, which stores exactly this field with exactly this
	// rule, so integrators already know what to do with it.
	//
	// It exists because a name can be sold at any moment, and a cached
	// resolution then sends funds to the previous owner. A blanket
	// policy would be wrong for somebody receiving payments and
	// wastefully strict for somebody using a name as a handle, so the
	// person who knows the risk sets it. Typed rather than an `extra`
	// key because an avl entry costs an order of magnitude more than
	// eight bytes, and because integrators read it.
	ttl int64

	// Pricing, and anything a future logic realm needs. Not typed
	// fields, because pricing is policy and policy belongs in the
	// swappable half — the vault only has to remember the values.
	extra avl.Tree
}

/*
Name has NO OWNER FIELD, and that absence is the whole design.

The first attempt at moving ownership into a token realm kept a copy of
the owner here, and every bug it had followed from the copy: renewal
checked the copy and refused the real owner after a sale, snapshots
recorded the copy and would have handed sold names back to their sellers
on restore. There is one owner and it lives in nsnft. Every read asks it.

It also has no isNFT flag. Every name is a token; a free-tier name is a
token with a hold on it (lockBitFree). Four separate places used to read
"has no token" as "is free", and deleting the flag deletes that class of
bug rather than fixing four instances of it.
*/
type Name struct {
	registered int64
	expires    int64
	frozen     bool
	ttl        int64

	/* THE OWNERSHIP EPOCH this record's profile data belongs to.

	   nsnft moves a token's epoch on every mint and transfer. When the two
	   disagree, the extras and TTL here were written for a previous holder
	   — possibly through a sale on a marketplace this realm never hears
	   about — and they are treated as absent on read and destroyed before
	   the next write. See freshen in write.gno. */
	epoch int64

	/* WHEN THE CURRENT HOLDING BEGAN, as far as this registry has seen.

	   Unix seconds, stamped together with `epoch`: at registration, at the
	   paid upgrade, at a restore, and at the first write after a transfer
	   (freshen). Meaningful only while `epoch` matches the ledger. A sale
	   that settles on nsnft moves the epoch without telling this realm, so
	   a buyer's clock starts at their first write here and never earlier:
	   it can understate how long somebody has held a name, never overstate
	   it. The paid upgrade restarts it, because a held free-tier name and a
	   sellable one are not the same holding.

	   A fact, not a policy: nslogic decides what it is good for (a
	   referral code earns only once its holder has kept a paid name for
	   thirty days). See GetNameHeldSince. */
	since int64

	/* WHO A RESTORE WROTE THIS RECORD FOR, or empty if no restore did.

	   nslogic.RestoreNameField replays profile data — pay addresses among
	   it — and may do so only onto a record a restore created, and only
	   while the ledger still says the snapshot's owner holds it. Without
	   this, a name sold between the snapshot and the restore had the
	   seller's pay addresses written onto the buyer's name, and any name a
	   user registered during the restore window could have its pay fields
	   rewritten with the admin key alone. */
	restoredFor address

	// Profile fields, cross-chain addresses, management-key hashes,
	// referrer — see the package comment. Only meaningful while `epoch`
	// matches the ledger.
	extra avl.Tree
}

/*
THE REGISTRY'S HOLD BITS on a token in nsnft. nsnft stores them and

	never interprets them; the vocabulary is this realm's.

	Separate bits so the two holds cannot undo each other: unfreezing a
	free-tier name must not make it sellable, and upgrading a frozen name
	must not unfreeze it.
*/
const (
	lockBitFree   = 0 // free tier, not yet paid for: not sellable
	lockBitFrozen = 1 // frozen by an admin: not movable while disputed
)

// There is deliberately no `streak` field. It used to be stored and
// incremented on renewal, which breaks the moment multi-year
// registration exists: prepaying five years bumps it five times, so a
// name minted this morning would render "5 years held". A streak is
// meant to say how long somebody stuck around, and buying time is not
// the same as spending it. It is now derived from `registered` — see
// streakOf in auth.gno — which is always truthful, cannot be bought,
// resets naturally on reclaim, and removes a field instead of adding
// one.

var (
	domains avl.Tree
	names   avl.Tree
	primary avl.Tree

	// Package-level extension slot, same reasoning as Domain/Name.extra:
	// somewhere to put global CONFIGURATION nobody has thought of yet
	// without needing a new package var. Not per-wallet state: that is
	// `accounts`, below.
	globals avl.Tree

	/* PER-ADDRESS STATE, in a tree of its own.

	   Credits for a free registration, and per-wallet counters such as
	   referrals, are about an ADDRESS, and there was nowhere to put them.
	   globals caps a key at 32 bytes and an address alone is 40, and its
	   entry cap was shared with every name's and domain's extras, so each
	   new wallet would have competed with the price list for the same 24
	   slots. An audit found the referral counter had never once been
	   written, for exactly that reason, and that every referred
	   registration reverted because of it.

	   Keyed address + ":" + field (see accountKey), so one wallet's fields
	   are one contiguous span. Bounded three ways — field name, value and
	   fields per address — so a wallet's footprint is small whatever a
	   logic realm writes. Written only by trusted logic, like every record;
	   what a field MEANS is the logic realm's business. */
	accounts avl.Tree

	admin address // the vault door — see governance.gno for the full role model

	// The set of realms currently allowed to call mutations. A set, not a
	// single address, because the project will plausibly grow more than
	// one writer (a free-tier realm, a custodial relayer) and a single
	// slot would force them all into one realm.
	trustedLogicSet avl.Tree

	// -- config: every value below is settable, none is a const --
	treasury address

	// Seconds, matching the record timestamps. These were time.Duration,
	// which meant every lifecycle comparison converted, and every read
	// through vm/qeval printed a nanosecond count that each caller had to
	// know to divide.
	termLength  int64 = 365 * 24 * 60 * 60
	gracePeriod int64 = 90 * 24 * 60 * 60

	labelPattern = `^[a-z0-9]+(-[a-z0-9]+)*$`
	minLabelLen  = 1
	maxLabelLen  = 63

	// Bounds on the extension slots. Storage written here is permanent
	// and paid for by the realm, so unbounded strings are griefing.
	maxExtraKeyLen   = 32
	maxExtraValueLen = 512
	maxExtraEntries  = 24

	// globals' OWN entry cap. It used to be maxExtraEntries, shared with
	// every record, and the logic realm's fixed keys alone (prices, rate,
	// fee, free tier, eight premium pages, eight block-list chunks,
	// referral rules, restore state) number more than 24 — so raising it
	// meant loosening every name and domain by the same factor.
	maxGlobalEntries = 64

	// Bounds on the per-address store. Small on purpose: a field is a
	// counter or a short tuple, and these are paid for by whoever's
	// transaction writes them.
	maxAccountKeyLen   = 16
	maxAccountValueLen = 128
	maxAccountEntries  = 8

	// Upper bound on how many name records a single DeleteDomainRecord
	// call will destroy. Deletion is unbounded work over a domain that
	// may hold any number of names, and an unbounded loop in a realm
	// that cannot be redeployed is a domain that can never be deleted
	// at all once it grows past one block's gas. Settable, because the
	// right number depends on chain parameters nobody knows yet.
	maxDeletePerCall = 100

	// Prefix for TokenURI. Points at whichever view realm currently
	// renders the artwork; settable so the art can be replaced without
	// touching this realm. See nft.gno.
	tokenURIBase = "/r/demo/nsview:token/"
)

func init(cur realm) {
	deployer := cur.Previous().Address()
	admin = deployer
	recovery = deployer
	treasury = deployer

	// THE REGISTRY ARRIVES CONFIGURED. Domains, prices, referral tiers and
	// lifecycle settings are baked into genesis_data.gno and written here,
	// so a fresh chain is usable the moment this package lands — no trust
	// grant and no admin call needed, because this realm owns the state
	// it is writing. See genesis.gno.
	applyGenesis(deployer, time.Now().Unix())
	// The trusted-logic set starts EMPTY and timelockDelay starts at
	// zero: deploy nsdata, deploy nslogic, then propose+execute the
	// grant. No mutation is callable until that happens.
	//
	// FIRST OPERATIONAL STEP AFTER DEPLOY, before anything of value
	// exists here: move `recovery` to a key held separately from
	// `admin` (ideally cold, ideally a multisig), then raise
	// timelockDelay. Until that is done both roles are the same key and
	// the whole recovery design is inert — it protects against one key
	// being lost or stolen, not against one key being both.
}

package nsdata

import (
	"unicode/utf8"
	"errors"
	"math"
	"strings"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/nym-mnsrehearsal001/nsnft/v3"
)

// Every function here is gated to trustedLogic and does exactly what it
// is told. Authorization beyond "is this the current logic realm" is
// deliberately NOT duplicated here: the vault stores, the logic realm
// decides. Re-checking policy in an unfixable realm sounds safer but
// bakes today's rules in permanently — a future feature that legitimately
// needs an admin to touch someone's record would be unbuildable.

// -- domains --

func RegisterDomainRecord(cur realm, label string, owner address, now int64) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	if d, ok := getDomain(label); ok {
		if d.frozen {
			return errStr("domain is frozen")
		}
		if !isReclaimable(d.expires, now) {
			return errStr("domain already registered and not yet reclaimable")
		}
		// No token to burn and no reverse pointer to clear: domains are
		// records, not tokens, and `primary` only ever held name ids.
		domains.Remove(label)
	}
	domains.Set(label, &Domain{
		owner: owner, registered: now, expires: now + termLength,
		extra: avl.Tree{},
	})
	emitBy(cur, "DomainRegistered", "label", label, "owner", owner.String(), "expires", i64(now+termLength))
	return nil
}

/*
ReassignDomainRecord moves a domain to a new owner and leaves its
configuration exactly where it was.

This is the durable fix nslogic.ReassignDomain's comment was waiting for.
The old path moved a domain through the name-transfer machinery, whose
wipe exists to clear a SELLER'S payment addresses — and so it silently
reopened closed domains, dropped their pricing to the default and released
their term caps, during the key-compromise recovery it exists for. A
domain's extras are its settings, not a previous holder's data, and there
is no previous holder: domains never reach a third party.

TTL resets, because it is the one field that is a caching promise made by
whoever held the record.
*/
func ReassignDomainRecord(cur realm, label string, to address) error {
	assertIsTrustedLogic(cur)
	if !to.IsValid() {
		return errStr("invalid owner address")
	}
	d, ok := getDomain(label)
	if !ok {
		return errStr("unknown domain")
	}
	d.owner = to
	d.ttl = 0
	emitBy(cur, "DomainReassigned", "label", label, "to", to.String())
	return nil
}

func RenewDomainRecord(cur realm, label string, caller address, now int64) error {
	assertIsTrustedLogic(cur)
	d, ok := getDomain(label)
	if !ok {
		return errStr("unknown domain")
	}
	if isReclaimable(d.expires, now) {
		return errStr("domain expired beyond grace period")
	}
	if caller != d.owner {
		return errStr("restricted to domain owner")
	}
	d.expires = advanceTerm(d.expires, now)
	emitBy(cur, "DomainRenewed", "label", label, "expires", i64(d.expires))
	return nil
}

// advanceTerm extends a term by exactly one term-length from its
// PREVIOUS due date — never from `now`, because the grace period must
// not silently extend the term somebody paid for.
//
// It no longer returns a streak. The streak used to be maintained here,
// with a guard against renewing repeatedly in one block to inflate it;
// that whole class of problem disappeared when the streak became a
// function of the registration date instead of a stored counter. See
// streakOf in auth.gno.
func advanceTerm(expires, now int64) int64 {
	// Anchoring to the previous due date is only safe while a renewal
	// cannot happen more than one term after it — i.e. while
	// gracePeriod <= termLength. That invariant held silently under the
	// old hardcoded constants and stopped holding the moment both became
	// settable: with a grace period longer than the term, a renewal paid
	// late in grace would return an expiry ALREADY IN THE PAST, leaving
	// the payer with a name that is still expired. Clamp forward so a
	// paid renewal always buys a live term, while keeping the anchor
	// behaviour in every normal case.
	// Saturate rather than wrap: renewing a far-future expiry used to
	// overflow and SHORTEN it to now + term (audit L-2).
	if expires > math.MaxInt64-termLength {
		return math.MaxInt64
	}
	next := expires + termLength
	if next <= now {
		next = now + termLength
	}
	return next
}

func SetDomainFrozen(cur realm, label string, frozen bool) {
	assertIsTrustedLogic(cur)
	mustGetDomain(label).frozen = frozen
	emitBy(cur, "DomainFrozen", "label", label, "frozen", boolStr(frozen))
}

func SetDomainExpiryRecord(cur realm, label string, expires int64) {
	assertIsTrustedLogic(cur)
	mustGetDomain(label).expires = expires
	emitBy(cur, "DomainExpirySet", "label", label, "expires", i64(expires))
}

// SetDomainTTLRecord sets how long a resolver may cache answers about
// this domain, in seconds, where 0 means never cache. See Domain.ttl.
func SetDomainTTLRecord(cur realm, label string, ttl int64) error {
	assertIsTrustedLogic(cur)
	if ttl < 0 {
		return errStr("ttl may not be negative")
	}
	d, ok := getDomain(label)
	if !ok {
		return errStr("unknown domain")
	}
	d.ttl = ttl
	emitBy(cur, "DomainTTLSet", "label", label, "ttl", i64(ttl))
	return nil
}

// SetDomainExtraRecord writes one arbitrary key on a domain — pricing,
// or whatever a future logic realm needs. An empty value deletes the
// key, so storage can be reclaimed.
func SetDomainExtraRecord(cur realm, label, key, value string) error {
	assertIsTrustedLogic(cur)
	d, ok := getDomain(label)
	if !ok {
		return errStr("unknown domain")
	}
	if err := setExtra(&d.extra, key, value); err != nil {
		return err
	}
	emitBy(cur, "DomainExtraSet", "label", label, "key", key, "value", value)
	return nil
}

// DeleteDomainRecord destroys a domain and the names beneath it: it
// burns every token, drops every reverse-resolution pointer into them,
// removes the records, and finally removes the domain itself.
//
// WHY IT EXISTS. Retiring a domain after a brand complaint, recovering
// the storage deposit on a domain that never sold, and clearing out fad
// domains nobody renewed. A logic realm cannot provide any of this,
// because the vault owns the trees and exposed no delete path — the only
// Remove call for a domain lived inside RegisterDomainRecord as the
// evict-and-replace step of re-registration.
//
// IT DELIBERATELY WORKS ON A DOMAIN WITH LIVE NAMES UNDER IT. The case
// this exists for is a demand to remove a domain entirely, where waiting
// for names to lapse is not an option. Compensating the holders is
// handled off chain and is deliberately not a contract concern.
//
// WHERE THIS DEPARTS FROM THE SPEC, stated plainly because it is a real
// difference: MAINNET.md §3d asks for all of it "in one call". It is
// bounded instead, deleting at most maxDeletePerCall names per call and
// reporting whether it finished. An unbounded loop over a tree that may
// hold any number of names is a transaction that stops fitting in a
// block once a domain gets popular — which would mean the domains most
// likely to attract a complaint are exactly the ones that could never be
// deleted, in a realm that can never be fixed. The caller repeats until
// `done`; for any domain of realistic size that is one call, so the
// no-preconditions requirement is preserved. What is NOT preserved is
// atomicity: a multi-call deletion is visible half-done between calls.
// Freeze the domain first if that matters, so nothing new lands under it
// meanwhile. Not Pause(): a paused registry deletes nothing at all, since
// this passes the same trust gate as every write.
//
// Calling it on a domain that does not exist is a no-op reporting done,
// so a repeat loop terminates cleanly rather than panicking on the call
// that follows the last one.
func DeleteDomainRecord(cur realm, label string) (removed int64, done bool) {
	assertIsTrustedLogic(cur)
	d, ok := getDomain(label)
	if !ok {
		return 0, true
	}

	// Collect first, mutate second. Removing entries from the tree while
	// iterating it is undefined, and this loop exists precisely to remove
	// entries.
	start, end := domainRange(label)
	var keys []string
	names.Iterate(start, end, func(key string, v any) bool {
		if len(keys) >= maxDeletePerCall {
			return true
		}
		keys = append(keys, key)
		return false
	})

	for _, key := range keys {
		v := names.Get(key)
		if v == nil {
			continue
		}
		n := v.(*Name)
		// The name label is whatever follows "domain*" in the storage
		// key — the record no longer stores its own label.
		nameLabel := key[len(label)+1:]
		tid := nameTokenID(nameLabel, label)
		_ = n
		owner := nsnft.OwnerOf(tid)
		clearPrimaryIfPointingAt(owner, tid)
		// Every name has a token, but a registry swapped in mid-migration
		// could meet a record whose token was already dealt with. Burning a
		// token that does not exist panics and would strand the domain
		// half-deleted, so ask first.
		if owner != "" {
			nsnft.Burn(cross(cur), tid)
		}
		names.Remove(key)
		removed++
	}

	// Anything left means the cap was hit; the domain record has to stay
	// so the next call can still find its name span.
	more := false
	names.Iterate(start, end, func(key string, v any) bool {
		more = true
		return true
	})
	if more {
		emitBy(cur, "DomainDeleted", "label", label, "removed", i64(removed), "done", "false")
		return removed, false
	}

	_ = d
	domains.Remove(label)
	emitBy(cur, "DomainDeleted", "label", label, "removed", i64(removed), "done", "true")
	return removed, true
}

// -- names --

/*
RegisterNameRecord creates `label*domain` and mints its token in nsnft.

`paid` false registers a FREE-TIER name: the token is minted with the free
hold already set, so there is never an instant in which it could be
approved and sold before a lock arrived. There is no longer any such thing
as a name without a token — see Name.

RECLAIM burns the previous holder's token first. The owner is read from
the ledger, never from the record, because the record has no owner.

AN ORPHAN TOKEN IS REFUSED. A token that exists with no record behind it
means a registry swap is mid-migration or something has gone wrong; either
way, registering over it would mint a second claim to a name somebody
already holds. RestoreNameRecord is the door for adopting one.
*/
func RegisterNameRecord(cur realm, label, domainLabel string, owner address, now int64, paid bool) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	d, ok := getDomain(domainLabel)
	if !ok {
		return errStr("unknown domain")
	}
	if d.frozen {
		return errStr("domain is frozen")
	}
	if isReclaimable(d.expires, now) {
		return errStr("domain has lapsed past its grace period")
	}
	treeKey := nameTreeKey(label, domainLabel)
	tid := nameTokenID(label, domainLabel)
	var reclaimedFrom address
	if n, ok := getName(label, domainLabel); ok {
		if n.frozen {
			return errStr("name is frozen")
		}
		if !isReclaimable(n.expires, now) {
			return errStr("name already registered and not yet reclaimable")
		}
		// Evict the previous holder completely. The reverse pointer goes
		// first: leaving it would make the old owner resolve to a name the
		// reclaimer now owns.
		prev := nsnft.OwnerOf(tid)
		reclaimedFrom = prev
		clearPrimaryIfPointingAt(prev, tid)
		if prev != "" {
			nsnft.Burn(cross(cur), tid)
		}
		names.Remove(treeKey)
	} else if nsnft.OwnerOf(tid) != "" {
		return errStr("a token for " + tid + " exists with no record behind it; restore it rather than registering over it")
	}

	nsnft.Mint(cross(cur), owner, tid, holdBits(paid, false))
	names.Set(treeKey, &Name{
		registered: now, expires: now + termLength,
		epoch: nsnft.Epoch(tid), since: now, extra: avl.Tree{},
	})
	setPrimaryIfNone(owner, tid)
	emitBy(cur, "NameRegistered", "tid", tid, "owner", owner.String(),
		"expires", i64(now+termLength), "paid", boolStr(paid), "reclaimedFrom", reclaimedFrom.String())
	return nil
}

func holdBits(paid, frozen bool) int {
	b := 0
	if !paid {
		b |= 1 << lockBitFree
	}
	if frozen {
		b |= 1 << lockBitFrozen
	}
	return b
}

/*
setPrimaryIfNone gives an address a reverse pointer when it has none — or
when the one it has points at a name it no longer holds.

The second half is new. A pointer used to be cleared on every transfer,
because transfers went through this realm. They no longer do: a sale that
settles on nsnft leaves the seller's pointer aimed at a name they sold.
nslogic.ResolveAddress already refuses to answer with it, so it never
misleads anybody — but left in place it also blocked the seller's NEXT
registration from becoming their primary, which would have looked like a
bug in registration rather than a stale pointer.
*/
func setPrimaryIfNone(owner address, tid string) {
	k := owner.String()
	if v := primary.Get(k); v == nil || !ownsNow(owner, v.(string)) {
		primary.Set(k, tid)
		// Reverse resolution is the one record that publishes a wallet's
		// persona, so even the automatic pointer says so.
		chain.Emit("PrimarySet", "owner", k, "tid", tid, "auto", "true")
	}
}

/*
UpgradeFreeRecord lifts the free-tier hold — the paid upgrade.

Preserves the dates: this is not a re-registration.

`newOwner` exists because the common case is somebody who decided to sell
and, in the same moment, wants the name in a wallet they control rather
than the key they were given. That move is a burn and a mint here, because
a held token cannot be transferred by design.

THE PROFILE DOES NOT GO WITH IT, and it used to. The move re-stamped the
old data to the new epoch and gave the recipient a reverse pointer — and
`newOwner` can be ANY address. An audit spelled out the attack: fill a
free name's profile with your own pay addresses, pay list price to upgrade
it into a victim's wallet, and the victim's name now asks people to pay
you, their address reverse-resolves to it, and their own later edits do
not clear it because the epoch is already current. So the data is left in
the previous epoch, where every read hides it and the next write destroys
it, and the recipient gets no pointer they never chose. A person moving
their own name to a new wallet re-enters their profile once; that is the
price of the move not being usable against somebody else.

Refused for a frozen name. Upgrading must never be the way a disputed name
gets out of its hold.
*/
func UpgradeFreeRecord(cur realm, label, domainLabel string, newOwner address) error {
	assertIsTrustedLogic(cur)
	if !newOwner.IsValid() {
		return errStr("invalid owner address")
	}
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if n.frozen {
		return errStr("name is frozen")
	}
	tid := nameTokenID(label, domainLabel)
	owner := nsnft.OwnerOf(tid)
	if owner == "" {
		return errStr("name has no token")
	}
	bits := nsnft.LockBits(tid)
	if bits&(1<<lockBitFree) == 0 {
		return errStr("name is already paid for")
	}
	if newOwner == owner {
		nsnft.SetLock(cross(cur), tid, lockBitFree, false)
		// Paid from now: time spent on the free tier is not time spent
		// holding a sellable name. See Name.since.
		n.since = time.Now().Unix()
		emitBy(cur, "NameUpgraded", "tid", tid, "owner", owner.String())
		return nil
	}
	nsnft.Burn(cross(cur), tid)
	nsnft.Mint(cross(cur), newOwner, tid, bits&^(1<<lockBitFree))
	clearPrimaryIfPointingAt(owner, tid)
	// n.epoch is deliberately NOT moved, and no pointer is given — see
	// above. n.since belongs to that old epoch too; the new owner's clock
	// starts at their first write.
	emitBy(cur, "NameUpgraded", "tid", tid, "owner", newOwner.String(), "from", owner.String())
	return nil
}

/*
RestoreNameRecord is the migration door: records move, tokens do not.

A registry swapped in behind the same nsnft finds tokens that already
exist. This writes the record for one and ADOPTS its token, or mints one
when the ledger has none. It never moves a token: a snapshot must never
take a name from its current holder.

WHEN THE LEDGER DISAGREES WITH THE SNAPSHOT, IT WINS. This used to refuse,
and an audit showed where refusing leads: a name sold between the snapshot
and the restore panics the batch, gets dropped to finish the rest, and the
window seals — leaving the buyer's token with no record behind it, unable
to be renewed, resolved or registered, forever. So the record is written
for whoever holds the token now, and the snapshot's profile data is NOT
replayable onto it (restoredFor stays empty), because it was the seller's.

Gated like every write, and nslogic only reaches it through the restore
window, which is one-shot.
*/
func RestoreNameRecord(cur realm, label, domainLabel string, owner address, registered int64, paid bool) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	if _, ok := getDomain(domainLabel); !ok {
		return errStr("unknown domain")
	}
	if _, ok := getName(label, domainLabel); ok {
		return errStr("name already has a record")
	}
	tid := nameTokenID(label, domainLabel)
	held := nsnft.OwnerOf(tid)
	if held == "" {
		nsnft.Mint(cross(cur), owner, tid, holdBits(paid, false))
		held = owner
	} else {
		/* NEVER ADOPT WHILE ANOTHER REGISTRY CAN STILL MINT.

		   The ledger's trust set is a set so an old and a new registry can
		   both be live during a migration — and an audit showed what that
		   allows: a name adopted here and renewed here still has its OLD
		   record, with its old expiry, in the old registry. Once that
		   lapses past grace, anyone registers the name through the old
		   logic realm, which burns the token and mints it to them. The
		   holder's paid, renewed name is gone. So adoption requires that
		   this registry is the only one the ledger trusts: pause and
		   untrust the old registry first, then restore. */
		if nsnft.Trusted() != cur.Address().String() {
			return errStr("adopting " + tid + " while the ledger trusts another registry would let that registry reclaim it; untrust the old registry first")
		}
		// Adopt. BOTH holds are set from what is being restored: the free
		// hold from the snapshot, and the frozen hold cleared, so a freeze
		// left by the old registry cannot linger on a record that reads
		// unfrozen. nslogic re-freezes after this if the snapshot says so.
		nsnft.SetLock(cross(cur), tid, lockBitFree, !paid)
		nsnft.SetLock(cross(cur), tid, lockBitFrozen, false)
	}
	// `since` is the restore, not the snapshot's registration date: this
	// registry cannot know when the holder acquired the token, and the
	// clock may understate a holding but never overstate one.
	rec := &Name{
		registered: registered, expires: registered + termLength,
		epoch: nsnft.Epoch(tid), since: time.Now().Unix(), extra: avl.Tree{},
	}
	if held == owner {
		rec.restoredFor = owner
		setPrimaryIfNone(owner, tid)
	}
	names.Set(nameTreeKey(label, domainLabel), rec)
	emitBy(cur, "NameRestored", "tid", tid, "owner", held.String(), "snapshotOwner", owner.String())
	return nil
}

func RenewNameRecord(cur realm, label, domainLabel string, caller address, now int64) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if isReclaimable(n.expires, now) {
		return errStr("name expired beyond grace period")
	}
	/* THE CHECK THE FIRST ATTEMPT GOT WRONG. It compared the caller to the
	   record's own owner copy, which stopped updating the moment ownership
	   moved to the token — so a buyer could not renew what they bought,
	   watched it lapse, and lost it to whoever re-registered. There is no
	   copy now. The ledger answers. */
	if caller != nsnft.OwnerOf(nameTokenID(label, domainLabel)) {
		return errStr("restricted to name owner")
	}
	n.expires = advanceTerm(n.expires, now)
	emitBy(cur, "NameRenewed", "tid", nameTokenID(label, domainLabel), "expires", i64(n.expires))
	return nil
}

/*
SetNameFrozen sets the record's frozen bit AND the matching hold on the
token, in the same call.

The record bit alone used to be the whole mechanism, and it bound nothing
outside our own transfer wrappers — a disputed name could be moved on any
marketplace that called the token directly. The hold in nsnft binds every
path there is.
*/
func SetNameFrozen(cur realm, label, domainLabel string, frozen bool) {
	assertIsTrustedLogic(cur)
	mustGetName(label, domainLabel).frozen = frozen
	nsnft.SetLock(cross(cur), nameTokenID(label, domainLabel), lockBitFrozen, frozen)
	emitBy(cur, "NameFrozen", "tid", nameTokenID(label, domainLabel), "frozen", boolStr(frozen))
}

// SetNameExpiryRecord sets an expiry directly. Backs the admin
// free-extension lever (SPEC.md §19) and any future term mechanic;
// the logic realm decides who may call it.
func SetNameExpiryRecord(cur realm, label, domainLabel string, expires int64) {
	assertIsTrustedLogic(cur)
	mustGetName(label, domainLabel).expires = expires
	emitBy(cur, "NameExpirySet", "tid", nameTokenID(label, domainLabel), "expires", i64(expires))
}

// SetNameTTLRecord sets how long a resolver may cache answers about this
// name, in seconds, where 0 means never cache. See Domain.ttl for why
// this exists and why the owner rather than the registry sets it.
func SetNameTTLRecord(cur realm, label, domainLabel string, ttl int64) error {
	assertIsTrustedLogic(cur)
	if ttl < 0 {
		return errStr("ttl may not be negative")
	}
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	freshen(n, nameTokenID(label, domainLabel))
	n.ttl = ttl
	emitBy(cur, "NameTTLSet", "tid", nameTokenID(label, domainLabel), "ttl", i64(ttl))
	return nil
}

// SetNameExtraRecord writes one arbitrary key on a name. This is where
// profile fields, cross-chain addresses, management-key hashes and tier
// markers live. An empty value deletes the key.
func SetNameExtraRecord(cur realm, label, domainLabel, key, value string) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	freshen(n, nameTokenID(label, domainLabel))
	if err := setExtra(&n.extra, key, value); err != nil {
		return err
	}
	// The field, never the value: see events.gno.
	emitBy(cur, "NameExtraSet", "tid", nameTokenID(label, domainLabel), "key", key)
	return nil
}

/*
freshen is the WRITE half of the lazy wipe, and it is the half the first
attempt described in prose and never wrote.

If a name's data belongs to a previous ownership epoch, every extra and the
TTL are destroyed, and the record is re-stamped to the current epoch —
BEFORE the new value is written. So the buyer's first edit cannot carry
the seller's Bitcoin address forward as the buyer's: by the time the edit
lands, the address is gone.

It wipes everything rather than a list of sensitive keys, for the same
reason the old transfer wipe did: which keys matter is policy, and a list
kept here would be wrong the first time nslogic invents a key.

The read half — hiding stale data from everybody the instant the epoch
moves — is isFresh, used by every name read.

It is also where a buyer's holding clock starts (Name.since): the first
moment this realm can see that the ledger has moved on.
*/
func freshen(n *Name, tid string) {
	before := n.epoch
	freshenTo(n, nsnft.Epoch(tid), time.Now().Unix())
	if n.epoch != before {
		chain.Emit("NameFreshened", "tid", tid, "since", i64(n.since))
	}
}

// freshenTo is freshen with the ledger's answer and the clock passed in,
// so the rule itself can be tested without a registry the ledger trusts.
func freshenTo(n *Name, epoch, now int64) {
	if n.epoch != epoch {
		n.extra = avl.Tree{}
		n.ttl = 0
		n.epoch = epoch
		n.since = now
	}
}

// FreshenNameRecord applies freshen and writes nothing else: the way a
// holder who bought a name starts its clock (Name.since) without having
// to invent a profile edit. For the current holder, freshen destroys only
// data every read already hides.
func FreshenNameRecord(cur realm, label, domainLabel string) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	freshen(n, nameTokenID(label, domainLabel)) // emits NameFreshened when it changed anything
	return nil
}

func SetPrimaryRecord(cur realm, owner address, label, domainLabel string) error {
	assertIsTrustedLogic(cur)
	if _, ok := getName(label, domainLabel); !ok {
		return errStr("unknown name")
	}
	tid := nameTokenID(label, domainLabel)
	// nslogic checks this too. Checked here as well because a pointer at a
	// name somebody does not hold is the one thing reverse resolution must
	// never be able to say, and the ledger is one read away.
	if !ownsNow(owner, tid) {
		return errStr("restricted to the name's current owner")
	}
	primary.Set(owner.String(), tid)
	emitBy(cur, "PrimarySet", "owner", owner.String(), "tid", tid)
	return nil
}

func ClearPrimaryRecord(cur realm, owner address) {
	assertIsTrustedLogic(cur)
	primary.Remove(owner.String())
	emitBy(cur, "PrimaryCleared", "owner", owner.String())
}

// -- there are no raw NFT operations here any more --
//
// RawTransferNFT, RawApprove, RawSetApprovalForAll and TransferRecordOwner
// are gone. Transfers and approvals happen on nsnft, called directly by the
// holder or by a marketplace they approved — exactly how an external
// marketplace does it, so ours has no privileged path. A registry that
// could move tokens would be a registry that could steal them.

// -- config: all settable, none constant --

func SetTreasuryRecord(cur realm, addr address) {
	assertIsTrustedLogic(cur)
	treasury = addr
	emitConfig(cur, "treasury", addr.String())
}

// The lifecycle setters refuse the two values that would break the
// lifecycle for everybody: a term of zero or less, and a negative grace
// period, which made live names reclaimable early (audit L-2). nslogic
// bounds both too; a future logic realm need not.
func SetTermLengthRecord(cur realm, seconds int64) {
	assertIsTrustedLogic(cur)
	if seconds <= 0 {
		panic("nsdata: a term must be positive")
	}
	termLength = seconds
	emitConfig(cur, "termLength", i64(seconds))
}

func SetGracePeriodRecord(cur realm, seconds int64) {
	assertIsTrustedLogic(cur)
	if seconds < 0 {
		panic("nsdata: a grace period cannot be negative")
	}
	gracePeriod = seconds
	emitConfig(cur, "gracePeriod", i64(seconds))
}

// SetMaxDeletePerCallRecord tunes how much work one DeleteDomainRecord
// call will do. See maxDeletePerCall in types.gno.
func SetMaxDeletePerCallRecord(cur realm, n int) {
	assertIsTrustedLogic(cur)
	if n < 1 {
		n = 1
	}
	maxDeletePerCall = n
	emitConfig(cur, "maxDeletePerCall", i64(int64(n)))
}
func SetLabelPatternRecord(cur realm, pattern string) {
	assertIsTrustedLogic(cur)
	labelPattern = pattern
	emitConfig(cur, "labelPattern", pattern)
}

func SetTokenURIBaseRecord(cur realm, base string) {
	assertIsTrustedLogic(cur)
	tokenURIBase = base
	emitConfig(cur, "tokenURIBase", base)
}

func SetLabelLengthRecord(cur realm, minLen, maxLen int) {
	assertIsTrustedLogic(cur)
	minLabelLen, maxLabelLen = minLen, maxLen
	emitConfig(cur, "labelLength", i64(int64(minLen))+","+i64(int64(maxLen)))
}

func SetExtraLimitsRecord(cur realm, keyLen, valueLen, entries int) {
	assertIsTrustedLogic(cur)
	maxExtraKeyLen, maxExtraValueLen, maxExtraEntries = keyLen, valueLen, entries
	emitConfig(cur, "extraLimits", i64(int64(keyLen))+","+i64(int64(valueLen))+","+i64(int64(entries)))
}

// SetGlobalEntryLimitRecord sets how many keys globals may hold, apart
// from the per-record extras cap. See maxGlobalEntries.
func SetGlobalEntryLimitRecord(cur realm, entries int) {
	assertIsTrustedLogic(cur)
	if entries < 1 {
		panic("nsdata: the globals cap must be at least 1")
	}
	maxGlobalEntries = entries
	emitConfig(cur, "globalEntries", i64(int64(entries)))
}

// SetAccountLimitsRecord bounds the per-address store. Lowering a cap
// never deletes anything; it only refuses the next write that exceeds it.
func SetAccountLimitsRecord(cur realm, keyLen, valueLen, entries int) {
	assertIsTrustedLogic(cur)
	if keyLen < 1 || valueLen < 1 || entries < 1 {
		panic("nsdata: account limits must be positive")
	}
	maxAccountKeyLen, maxAccountValueLen, maxAccountEntries = keyLen, valueLen, entries
	emitConfig(cur, "accountLimits", i64(int64(keyLen))+","+i64(int64(valueLen))+","+i64(int64(entries)))
}

// -- per-address state --

/*
SetAccountRecord writes one field of an address's own record: a credit
balance, a counter, whatever a logic realm keeps per wallet. An empty
value deletes the field, so its storage can be reclaimed.

Bounded like the extras, with caps of its own: the field name, the value,
and how many fields one address may hold. The fields-per-address cap is
what keeps any single wallet's footprint small, whoever pays for it.
*/
func SetAccountRecord(cur realm, owner address, key, value string) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid address")
	}
	// Deleting first, before the field-name limit, as setExtraCapped does
	// (re-audit L-2): a delete frees storage and grants nothing.
	if value == "" {
		if key == "" || strings.ContainsAny(key, ":\n\r") {
			return errStr("bad account field")
		}
		accounts.Remove(accountKey(owner, key))
		emitBy(cur, "AccountSet", "addr", owner.String(), "key", key, "value", "")
		return nil
	}
	if err := assertAccountKey(key); err != nil {
		return err
	}
	k := accountKey(owner, key)
	if len(value) > maxAccountValueLen {
		return errStr("account value too long")
	}
	if !utf8.ValidString(value) {
		return errStr("account values must be valid UTF-8")
	}
	if accounts.Get(k) == nil && accountFields(owner) >= maxAccountEntries {
		return errStr("too many fields on this address")
	}
	accounts.Set(k, value)
	emitBy(cur, "AccountSet", "addr", owner.String(), "key", key, "value", value)
	return nil
}

// accountFields counts one address's fields, stopping at the cap: the
// only question asked of it is whether the cap is reached, and an
// unbounded walk is not something a write path should contain.
func accountFields(owner address) int {
	n := 0
	start, end := accountRange(owner)
	accounts.Iterate(start, end, func(key string, v any) bool {
		n++
		return n >= maxAccountEntries
	})
	return n
}

// assertAccountKey keeps field names short and free of the characters
// that would make a snapshot listing ambiguous, and of ':', which
// separates the address from the field.
func assertAccountKey(key string) error {
	if key == "" || len(key) > maxAccountKeyLen {
		return errStr("bad account field")
	}
	if strings.ContainsAny(key, ",:\n\r") {
		return errStr("account field may not contain commas, colons or newlines")
	}
	return nil
}

// SetGlobalRecord writes one arbitrary package-level key — fee rates,
// default prices, a custodian address, points balances, claim records.
// Anything global that does not exist yet goes here instead of needing a
// package variable that could never be added after deployment.
// Keys the restore machinery owns. Written only by RestoreGlobal's own
// path, never by a general setter — because nslogic's SetGlobal forwards
// whatever key an admin passes, and one call writing "restore" reopened
// a seal that restore.gno calls irreversible. Enforced HERE as well as
// there, so a future logic realm cannot drop the guard by forgetting it.
var reservedGlobals = []string{"restore", "restored"}

func SetGlobalRecord(cur realm, key, value string) error {
	assertIsTrustedLogic(cur)
	for _, r := range reservedGlobals {
		if key == r {
			return errStr("that key belongs to the restore machinery and is not settable here")
		}
	}
	if err := setGlobal(key, value); err != nil {
		return err
	}
	emitBy(cur, "GlobalSet", "key", key, "value", value)
	return nil
}

// setGlobal is setExtra held to globals' own entry cap.
func setGlobal(key, value string) error {
	return setExtraCapped(&globals, key, value, maxGlobalEntries)
}

// SetReservedGlobalRecord is the restore machinery's own door to the
// keys above. Same trust gate; separate name, so a general-purpose
// setter can never reach them by accident.
func SetReservedGlobalRecord(cur realm, key, value string) error {
	assertIsTrustedLogic(cur)
	found := false
	for _, r := range reservedGlobals {
		if key == r {
			found = true
		}
	}
	if !found {
		return errStr("not a reserved key; use SetGlobalRecord")
	}
	// THE RESTORE DOOR MOVES ONE WAY, here as well as in the logic realm:
	// never opened, then opened once, then sealed — and from "sealed"
	// nowhere. The seal is the public promise that this registry's history
	// can no longer be rewritten on request, and "opened exactly once" is
	// what keeps a window from being closed quietly and opened again later;
	// a promise any trusted logic could undo with one write was only as
	// good as the newest logic generation. Re-writing "sealed" is harmless.
	if key == "restore" {
		if state := GetGlobal("restore"); state == "sealed" && value != "sealed" {
			return errStr("restore is sealed, and a seal does not come undone")
		} else if state != "" && value != "sealed" {
			return errStr("the restore window opens once; from here it can only be sealed")
		}
	}
	if err := setGlobal(key, value); err != nil {
		return err
	}
	emitBy(cur, "ReservedGlobalSet", "key", key, "value", value)
	return nil
}

// setExtra applies the shared bounds and the delete-on-empty rule to a
// name's or a domain's extras.
func setExtra(t *avl.Tree, key, value string) error {
	return setExtraCapped(t, key, value, maxExtraEntries)
}

func setExtraCapped(t *avl.Tree, key, value string, maxEntries int) error {
	// DELETING COMES FIRST, before any limit is checked: removing a key
	// frees storage and grants nothing, and with the key check in front a
	// single SetExtraLimits(1, ...) made every global undeletable — the
	// guardian's ClearKeeper, SetGranter(""), SetClaimWindow(0) included
	// (re-audit 2026-10-16, L-2).
	if value == "" {
		if key == "" {
			return errStr("bad extra key")
		}
		t.Remove(key)
		return nil
	}
	if err := assertExtraKey(key); err != nil {
		return err
	}
	// Bytes the snapshot can carry back. The vault used to store anything,
	// and a value with invalid UTF-8 came back from a snapshot three bytes
	// per bad byte, too long to replay (re-audit L-8).
	if !utf8.ValidString(key) || !utf8.ValidString(value) {
		return errStr("extra keys and values must be valid UTF-8")
	}
	if len(value) > maxExtraValueLen {
		return errStr("extra value too long")
	}
	if t.Get(key) == nil && t.Size() >= maxEntries {
		return errStr("too many extra entries")
	}
	t.Set(key, value)
	return nil
}

// assertExtraKey keeps extension keys free of the characters that would
// make a snapshot ambiguous. Export lists keys as CSV, so a key
// containing a comma or a newline would silently corrupt a backup — and
// a backup you cannot trust is the one thing this realm cannot afford.
func assertExtraKey(key string) error {
	if key == "" || len(key) > maxExtraKeyLen {
		return errStr("bad extra key")
	}
	if strings.ContainsAny(key, ",\n\r") {
		return errStr("extra key may not contain commas or newlines")
	}
	return nil
}

// assertLabelKeySafe is a STRUCTURAL check, not a policy one. Character
// policy lives in the logic realm's tunable labelPattern; this is the
// narrow set of characters that would break the vault's own machinery no
// matter what policy is in force:
//
//	"*"  is the separator in both key encodings, so a label containing
//	     one makes storage keys and token ids ambiguous;
//	","  and newlines would corrupt the CSV snapshot exports, which are
//	     the disaster-recovery guarantee — assertExtraKey already refuses
//	     them for extension keys, and labels become keys just as much;
//	""   cannot address a record at all.
//
// Enforcing it here rather than trusting the logic realm matters because
// labelPattern is admin-tunable: loosening it must never be able to
// silently corrupt a backup in a realm that cannot be redeployed.
func assertLabelKeySafe(label string) error {
	if label == "" {
		return errStr("empty label")
	}
	if strings.ContainsAny(label, "*,\n\r") {
		return errStr("label may not contain '*', commas or newlines")
	}
	return nil
}

func errStr(s string) error { return errors.New(s) }

package nsreserve

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/ed25519"
	"crypto/sha256"
	"sort"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

/*
RESERVATIONS: a free name's place on chain before anybody mints it.

A free name is claimed with an X sign-in and nothing else: no wallet. The
claim is a record in our worker. What the chain holds is the smallest thing
that keeps everybody else off the label: a hashed name and an expiry.
Nothing here says who holds a name, not even as a commitment, and nothing
here says which name a hash is, except to somebody who guesses the label.

	hash = sha256(domain + ":" + label)[:16]

WHY A REALM OF ITS OWN. The ledger (nsnft) and the vault (nsdata) are the
core and do not change. This is a satellite: it holds its own small store,
reads every role from the vault, and answers to three parties:

	the GRANTER, a hot key, which can only ADD reservations and EXTEND
	them, inside a daily cap it cannot raise. It deletes nothing and
	mints nothing;

	the MINT APPROVER, another key, which writes nothing at all: it signs
	vouchers, off chain, that let one wallet mint or renew one name. The
	chain checks the signature (ed25519) against the public key the admin
	named behind the timelock, inside a daily cap of its own;

	a TRUSTED LOGIC REALM (today nslogic), which spends a voucher when
	its holder mints, and carries the admin's timelocked changes.

WHAT A STOLEN KEY CAN DO. The granter: squat one day's cap of labels until
the guardian disarms it; none becomes a name. The mint approver: mint, to
wallets of its choosing, up to one day's cap of names, reserved ones
included, since a reservation commits to nobody (the owner's decision,
2026-11-12: a claim needs no wallet). That is name theft bounded by the
approver's cap, undone by the admin's timelocked RevokeFreeNames, and
stopped at once by ClearVoucherKey or Pause. Keep that cap small.

THE CLOCK STARTS AT THE REQUEST, not when a batch or a mint lands: every
entry and every voucher carries the second its claimant asked
(requestedAt), and the expiry is that plus the vault's term. A request
time is accepted only from the last three days and never from the future,
so neither key can hand out longer terms. A name minted from a reservation
keeps the reservation's expiry exactly.

A BATCH DOES NOT SHARE A FATE. An entry that cannot be written (already
reserved, a request time out of bounds, past the cap) is skipped and
counted, never a revert, and sending the same batch twice writes nothing
the second time.

HOW IT IS STORED, and why not one tree entry per name. Measured on a local
node, an avl node costs about a kilobyte of storage deposit whatever it
holds (two of them per new key), and a reservation is 20 bytes. So
reservations are packed, 20 raw bytes each and sorted, into LEAVES: strings
of up to leafMax entries. The leaves hang off a binary trie over the bits
of the hash, kept in one avl tree whose keys are the bit prefixes ("", "0",
"01", ...): a leaf that fills up splits in two on its next bit, and its old
key stays behind as a marker. One name costs its 20 bytes plus its share of
a leaf's nodes, a few bytes; a lookup walks a few prefixes and binary-
searches one leaf.
*/

const (
	hashLen  = 16
	entryLen = hashLen + 4 // hash, expiry (unix seconds, big-endian)

	// A leaf holds at most leafMax entries before it splits on its next
	// bit. The trie never goes deeper than maxDepth; a leaf there simply
	// grows. 24 bits is room for sixteen million leaves, far past any real
	// registry, and it bounds what hashes CHOSEN to share a long prefix can
	// cost: every split leaves a marker node behind, paid from the
	// granter's balance, so a stolen granter key could otherwise buy
	// dozens of nodes with one small batch.
	leafMax  = 512
	maxDepth = 24

	splitMark = "+" // the value left at a prefix that has split

	// Batch entry widths, in hex characters.
	freezeWidth = 2*hashLen + 8 // hash, requestedAt
	hashWidth   = 2 * hashLen

	// maxBatch is the most entries one call may carry. Sized from the gas
	// measurement on a local node (docs/launch-review-2026-11-12/build-contracts.md).
	maxBatch = 2000

	// A request time is accepted from this far back, and never from the
	// future: the daily batch plus two days of a relay being down.
	maxBackSecs = int64(3 * 86400)

	// "Never from the future", give or take the clocks: a block's time can
	// trail the issuer's by some seconds (seen on a local node: an entry
	// stamped 30 seconds ago was "in the future" for a chain that had been
	// idle), so a request time up to maxSkewSecs ahead is taken.
	maxSkewSecs = int64(300)

	// A reservation is renewed only inside its last renewWindow, by one
	// term, so renewals cannot be stacked years ahead (audit L-1).
	renewWindow = int64(60 * 86400)

	// A voucher is good for at most this long from now.
	maxVoucherSecs = int64(86400)

	maxDailyCap = 100000

	maxPrune = 4096 // tree keys one Prune call may walk

	keyGranter = "granter" // the vault global nslogic.SetGranter writes
)

var (
	buckets avl.Tree // bit prefix -> a leaf of packed entries, or splitMark

	total int // entries stored, expired ones included until pruned

	// The granter's daily cap: entries it may write in one UTC day. ZERO
	// until the deploy sets it, so a fresh realm freezes nothing.
	dailyCap int
	dayNo    int64
	dayUsed  int

	paused bool

	pruneCursor string

	// voucherKey is the ed25519 PUBLIC key (32 raw bytes) of the MINT
	// APPROVER. Empty: nothing can be minted or renewed free.
	voucherKey string

	// The mint approver's own daily cap, counted apart from the granter's.
	// ZERO until the admin sets it.
	voucherCap  int
	voucherDay  int64
	voucherUsed int
)

// selfPath is this realm's own package path, read once at deploy. It goes
// into every voucher, so one signed for a rehearsal chain or an older
// generation is worth nothing here.
var selfPath string

func init() { selfPath = unsafe.CurrentRealm().PkgPath() }

// -- hashing --

func sum16(s string) string {
	h := sha256.Sum256([]byte(s))
	return string(h[:hashLen])
}

func rawOf(label, domainLabel string) string { return sum16(domainLabel + ":" + label) }

// HashOf is the reservation key of label*domain, as 32 hex characters.
func HashOf(label, domainLabel string) string { return hexOf(rawOf(label, domainLabel)) }

const hexDigits = "0123456789abcdef"

func hexOf(raw string) string {
	b := make([]byte, len(raw)*2)
	for i := 0; i < len(raw); i++ {
		b[2*i] = hexDigits[raw[i]>>4]
		b[2*i+1] = hexDigits[raw[i]&15]
	}
	return string(b)
}

// unhexTab maps a byte to its hex value, 0xff for anything that is not a
// lowercase hex digit. A table and not a function: measured under gno test,
// decoding a 2,000-entry batch through a per-character function call was
// half of the whole transaction's gas.
const unhexTab = "" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\x0a\x0b\x0c\x0d\x0e\x0f\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff" +
	"\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff"

// unhex decodes lowercase hex. Upper case is refused, so one reservation
// has exactly one spelling.
func unhex(s string) (string, bool) {
	if len(s)%2 != 0 {
		return "", false
	}
	b := make([]byte, len(s)/2)
	bad := byte(0)
	for i := 0; i < len(b); i++ {
		hi, lo := unhexTab[s[2*i]], unhexTab[s[2*i+1]]
		bad |= hi | lo
		b[i] = hi<<4 | lo
	}
	if bad > 15 {
		return "", false
	}
	return string(b), true
}

func be32(raw string) int64 {
	return int64(raw[0])<<24 | int64(raw[1])<<16 | int64(raw[2])<<8 | int64(raw[3])
}

// -- the store --

// bitAt is bit i of a raw hash, most significant first, as '0' or '1'.
func bitAt(raw string, i int) byte {
	if raw[i/8]>>(7-uint(i%8))&1 == 1 {
		return '1'
	}
	return '0'
}

// leafOf walks the trie to the leaf that holds, or would hold, a hash.
func leafOf(raw string) (key, data string) {
	k := []byte{}
	for {
		v := buckets.Get(string(k))
		if v == nil {
			return string(k), "" // only the root, before anything was written
		}
		if d := v.(string); d != splitMark {
			return string(k), d
		}
		k = append(k, bitAt(raw, len(k)))
	}
}

// putLeaf stores a leaf, splitting it in two on its next bit for as long
// as it holds more than leafMax entries.
func putLeaf(key, data string) {
	if len(data) <= leafMax*entryLen || len(key) >= maxDepth {
		buckets.Set(key, data)
		return
	}
	// Sorted by hash, and every hash here shares the prefix `key`, so the
	// entries whose next bit is 0 all come before those whose next bit is
	// 1: the split is one cut, and both halves stay sorted.
	cut := 0
	for cut < len(data) && bitAt(data[cut:cut+hashLen], len(key)) == '0' {
		cut += entryLen
	}
	buckets.Set(key, splitMark)
	putLeaf(key+"0", data[:cut])
	putLeaf(key+"1", data[cut:])
}

// find binary-searches a sorted leaf: the offset of the hash's entry, or
// of where it would go, and whether it is there.
func find(b, raw string) (int, bool) {
	lo, hi := 0, len(b)/entryLen
	for lo < hi {
		mid := (lo + hi) / 2
		h := b[mid*entryLen : mid*entryLen+hashLen]
		if h == raw {
			return mid * entryLen, true
		}
		if h < raw {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo * entryLen, false
}

func expiryAt(b string, i int) int64 { return be32(b[i+hashLen : i+entryLen]) }

func entry(raw string, expires int64) string {
	return raw + string([]byte{byte(expires >> 24), byte(expires >> 16), byte(expires >> 8), byte(expires)})
}

func removeAt(b string, i int) string { return b[:i] + b[i+entryLen:] }

// lookup reads one reservation by raw hash.
func lookup(raw string) (expires int64, ok bool) {
	_, b := leafOf(raw)
	i, ok := find(b, raw)
	if !ok {
		return 0, false
	}
	return expiryAt(b, i), true
}

func liveAt(raw string, now int64) bool {
	exp, ok := lookup(raw)
	return ok && now < exp
}

/*
work is one batch's view of the leaves it touches, so a batch of hundreds
reads and writes each leaf once instead of copying it once per entry.

A leaf is searched in the string the tree handed over (`orig`): rewriting
an entry in place never moves a hash, so offsets found there stay right.
Rewrites go to a byte copy made on first use; new entries to a list that is
sorted and merged in at the end. A hash is handled once per batch (`seen`),
which is what makes reading from `orig` sound.
*/
type leafWork struct {
	orig  string
	buf   []byte   // orig with entries rewritten in place; nil until one is
	added []string // new entries
}

type work struct {
	keys   []string
	leaves map[string]*leafWork
	seen   map[string]bool

	// The leaf the last entry landed in. A batch is handled in hash order,
	// so the next entry is nearly always in the same one, and checking a
	// few bits is far cheaper than walking the trie again: measured on a
	// local node at 50,000 names, the walk was most of a batch's gas.
	lastKey string
	last    *leafWork
}

// under reports whether a hash belongs under a leaf's bit prefix.
func under(raw, key string) bool {
	for i := 0; i < len(key); i++ {
		if bitAt(raw, i) != key[i] {
			return false
		}
	}
	return true
}

func newWork() *work {
	return &work{leaves: map[string]*leafWork{}, seen: map[string]bool{}}
}

// leaf returns the batch's copy of the leaf holding raw.
func (w *work) leaf(raw string) *leafWork {
	if w.last != nil && under(raw, w.lastKey) {
		return w.last
	}
	key, data := leafOf(raw)
	lw, ok := w.leaves[key]
	if !ok {
		lw = &leafWork{orig: data}
		w.leaves[key] = lw
		w.keys = append(w.keys, key)
	}
	w.lastKey, w.last = key, lw
	return lw
}

func (lw *leafWork) rewrite(i int, e string) {
	if lw.buf == nil {
		lw.buf = []byte(lw.orig)
	}
	copy(lw.buf[i:i+entryLen], e)
}

// merged is the leaf as it should be stored: the rewritten entries, with
// the new ones merged in by hash, in one pass.
func (lw *leafWork) merged() string {
	data := lw.orig
	if lw.buf != nil {
		data = string(lw.buf)
	}
	if len(lw.added) == 0 {
		return data
	}
	sort.Strings(lw.added)
	out := make([]byte, 0, len(data)+len(lw.added)*entryLen)
	i := 0
	for _, e := range lw.added {
		// Where the new entry goes, by binary search: the stored entries
		// before it are copied across in one piece, not walked one by one.
		j, _ := find(data, e[:hashLen])
		out = append(out, data[i:j]...)
		out = append(out, e...)
		i = j
	}
	out = append(out, data[i:]...)
	return string(out)
}

// flush writes back every leaf the batch changed.
func (w *work) flush() {
	for _, key := range w.keys {
		lw := w.leaves[key]
		if lw.buf == nil && len(lw.added) == 0 {
			continue
		}
		putLeaf(key, lw.merged())
	}
}

// -- who may call --

func assertNoSend(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("nsreserve: this function takes no payment; do not attach coins")
	}
}

func granter() address { return address(nsdata.GetGlobal(keyGranter)) }

func assertGranter(cur realm) {
	g := granter()
	if g == "" || cur.Previous().Address() != g {
		panic("nsreserve: restricted to the granter")
	}
}

// assertLogic lets through a realm the vault trusts as logic, and nothing
// else: never a wallet, never a run script (the vault's own rule).
func assertLogic(cur realm) {
	prev := cur.Previous()
	if prev.IsUser() || prev.IsEphemeral() || !nsdata.IsTrustedLogic(prev.Address()) {
		panic("nsreserve: restricted to a trusted logic realm")
	}
}

func assertNotPaused() {
	if paused {
		panic("nsreserve: paused")
	}
}

func isWarden(a address) bool {
	return a != "" && (a == nsdata.GetAdmin() || a == nsdata.GetGuardian() || a == nsdata.GetRecovery())
}

// -- the daily cap --

func rollDay(now int64) {
	if d := now / 86400; d != dayNo {
		dayNo, dayUsed = d, 0
	}
}

func usedToday(now int64) int {
	if now/86400 != dayNo {
		return 0
	}
	return dayUsed
}

// -- batches --

func term() int64 { return nsdata.GetTermLength() }

func requestRefusal(requestedAt, now int64) string {
	if requestedAt > now+maxSkewSecs {
		return "requested in the future"
	}
	if requestedAt < now-maxBackSecs {
		return "requested more than " + strconv.FormatInt(maxBackSecs/86400, 10) + " days ago"
	}
	return ""
}

// split cuts a batch of fixed-width hex entries into raw ones. A batch
// that is not well formed is the sender's bug and refuses the whole call.
func split(batch string, hexWidth int) ([]string, string) {
	if batch == "" {
		return nil, "empty batch"
	}
	if len(batch)%hexWidth != 0 {
		return nil, "malformed batch: its length is not a multiple of " + strconv.Itoa(hexWidth)
	}
	n := len(batch) / hexWidth
	if n > maxBatch {
		return nil, "too many entries: " + strconv.Itoa(n) + " > " + strconv.Itoa(maxBatch)
	}
	raw, ok := unhex(batch)
	if !ok {
		return nil, "malformed batch: lowercase hex only"
	}
	w := hexWidth / 2
	out := make([]string, n)
	for i := 0; i < n; i++ {
		out[i] = raw[i*w : (i+1)*w]
	}
	return out, ""
}

func mustSplit(batch string, hexWidth int) []string {
	es, r := split(batch, hexWidth)
	if r != "" {
		panic("nsreserve: " + r)
	}
	return es
}

func digest(batch string) string { return hexOf(sum16(batch)[:8]) }

func emitBatch(cur realm, name string, written, skipped int, batch string) {
	chain.Emit(name, "written", strconv.Itoa(written), "skipped", strconv.Itoa(skipped),
		"day", strconv.FormatInt(dayNo, 10), "used", strconv.Itoa(dayUsed), "cap", strconv.Itoa(dailyCap),
		"by", cur.Previous().Address().String(), "digest", digest(batch))
}

// The per-entry rules, each answering "" or why the entry is skipped, given
// what the store holds for its hash. The dry-run reads use them; the write
// paths apply the same rules inline, in the same order.

func freezeRule(e string, exp int64, found bool, now int64) string {
	if found && now < exp {
		return "already reserved"
	}
	return requestRefusal(be32(e[hashLen:]), now)
}

func renewRule(e string, exp int64, found bool, now int64) string {
	if !found || now >= exp {
		return "no live reservation"
	}
	if exp > now+renewWindow {
		return "not due: renewals open " + strconv.FormatInt(renewWindow/86400, 10) + " days before the expiry"
	}
	return ""
}

/*
FreezeNames writes one reservation per entry and returns how many it wrote.

GRANTER ONLY, once a day in the ordinary course, as many transactions as the
day's names need. An entry is hash + requestedAt, 40 hex characters, and
says nothing about who claimed it. The expiry is requestedAt plus the
vault's term.

A live reservation is never overwritten: that entry is skipped, so sending
a batch twice is harmless. An expired one is replaced in place. Entries past
the daily cap are skipped too, in hash order, not in the order sent.
*/
func FreezeNames(cur realm, batch string) int {
	assertNoSend(cur)
	assertGranter(cur)
	assertNotPaused()
	es := mustSplit(batch, freezeWidth)
	// In hash order (work.leaf). Two entries for one name then sit side by
	// side, the earlier request first, and the first one wins.
	sort.Strings(es)
	now := time.Now().Unix()
	oneTerm := term()
	rollDay(now)
	w := newWork()
	written := 0
	for _, e := range es {
		raw := e[:hashLen]
		requestedAt := be32(e[hashLen:])
		if dayUsed >= dailyCap || w.seen[raw] || requestedAt > now+maxSkewSecs || requestedAt < now-maxBackSecs {
			continue
		}
		lw := w.leaf(raw)
		i, found := find(lw.orig, raw)
		if found && now < expiryAt(lw.orig, i) {
			continue // live: never overwritten
		}
		ne := entry(raw, requestedAt+oneTerm)
		if found {
			lw.rewrite(i, ne) // an expired entry is replaced in place
		} else {
			lw.added = append(lw.added, ne)
			total++
		}
		w.seen[raw] = true
		dayUsed++
		written++
	}
	w.flush()
	emitBatch(cur, "NamesFrozen", written, len(es)-written, batch)
	return written
}

// RenewNames adds one term to live reservations inside their last
// renewWindow. Granter only; the entries are hashes, 32 hex characters
// each. Anything else is skipped.
func RenewNames(cur realm, hashes string) int {
	assertNoSend(cur)
	assertGranter(cur)
	assertNotPaused()
	hs := mustSplit(hashes, hashWidth)
	sort.Strings(hs) // in hash order (work.leaf)
	now := time.Now().Unix()
	oneTerm := term()
	rollDay(now)
	w := newWork()
	written := 0
	for _, raw := range hs {
		if dayUsed >= dailyCap || w.seen[raw] {
			continue
		}
		lw := w.leaf(raw)
		i, found := find(lw.orig, raw)
		if !found {
			continue
		}
		exp := expiryAt(lw.orig, i)
		if now >= exp || exp > now+renewWindow {
			continue // lapsed, or not due yet
		}
		lw.rewrite(i, entry(raw, exp+oneTerm))
		w.seen[raw] = true
		dayUsed++
		written++
	}
	w.flush()
	emitBatch(cur, "NamesRenewed", written, len(hs)-written, hashes)
	return written
}

/*
VOUCHERS: how a name is minted, and how a minted free name is renewed.

A reservation names nobody, so something else has to say which wallet may
have the name. That is the mint approver's voucher: the issuer signs, off
chain and for nothing, "this wallet may MINT (or RENEW) this name,
requested at this second, until this second", only after a fresh X sign-in
by the account that claimed it. The holder carries it in their own
transaction and pays for everything. Nothing is written here for a
voucher, so minting costs the project no gas and no storage.

IF THE NAME IS RESERVED, the voucher must carry the reservation's own
request time (its expiry is checked to the second) and the reservation is
spent. IF IT IS NOT, the name is being minted before the day's batch
landed, and the request time must be fresh: the last three days.

NO NONCE IS STORED, on purpose. A mint voucher names one name and one
wallet, and using it registers that name, after which it is refused for
good ("already registered"); a renew voucher sets one exact expiry, so a
second use changes nothing and is refused as "not an extension". Both die
with their validity, a day at most. A stored nonce would add a tree node
of permanent storage, paid by every holder, to prevent nothing.
*/

// Voucher kinds.
const (
	KindMint  = "mint"
	KindRenew = "renew"
)

// VoucherMessage is the exact text the mint approver signs.
func VoucherMessage(kind, label, domainLabel string, holder address, requestedAt, validUntil int64) string {
	return "mns-free-v2\n" + runtime.ChainID() + "\n" + selfPath + "\n" + kind + "\n" +
		domainLabel + "*" + label + "\n" + holder.String() + "\n" +
		strconv.FormatInt(requestedAt, 10) + "\n" + strconv.FormatInt(validUntil, 10)
}

func vouchersToday(now int64) int {
	if now/86400 != voucherDay {
		return 0
	}
	return voucherUsed
}

// VoucherRefusal is why this voucher could not be used right now, or "".
func VoucherRefusal(kind, label, domainLabel string, holder address, requestedAt, validUntil int64, sig string) string {
	now := time.Now().Unix()
	if paused {
		return "paused"
	}
	if kind != KindMint && kind != KindRenew {
		return "a voucher is for mint or renew"
	}
	if voucherKey == "" {
		return "free minting is off: no mint approver is set"
	}
	if now > validUntil {
		return "this voucher has expired; ask for a new one"
	}
	if validUntil > now+maxVoucherSecs {
		return "a voucher is valid for at most " + strconv.FormatInt(maxVoucherSecs/3600, 10) + " hours"
	}
	if requestedAt > now+maxSkewSecs {
		return "voucher requested in the future"
	}
	// A reserved name is minted on the reservation's own clock, whatever
	// its age; anything else needs a fresh request time.
	reservedExp, reserved := int64(0), false
	if kind == KindMint {
		if exp, ok := lookup(rawOf(label, domainLabel)); ok && now < exp {
			reservedExp, reserved = exp, true
		}
	}
	if reserved {
		if requestedAt+term() != reservedExp {
			return "this voucher does not carry the reservation's request time"
		}
	} else if r := requestRefusal(requestedAt, now); r != "" {
		return "voucher " + r
	}
	if vouchersToday(now) >= voucherCap {
		return "today's free mints are all used; try tomorrow"
	}
	rawSig, ok := unhex(sig)
	if !ok || len(rawSig) != 64 {
		return "a voucher signature is 128 lowercase hex characters"
	}
	msg := VoucherMessage(kind, label, domainLabel, holder, requestedAt, validUntil)
	if !ed25519.Verify([]byte(voucherKey), []byte(msg), []byte(rawSig)) {
		return "this voucher was not signed for this wallet, this name and this use"
	}
	return ""
}

/*
ConsumeVoucher checks a voucher for `holder`, counts it against the mint
approver's daily cap, spends the name's reservation if there is one, and
returns the expiry the voucher stands for: the request time plus the
vault's term. TRUSTED LOGIC ONLY: the logic realm passes the wallet that
called it, so a voucher works only from the wallet it names.
*/
func ConsumeVoucher(cur realm, kind, label, domainLabel string, holder address, requestedAt, validUntil int64, sig string) int64 {
	assertLogic(cur)
	if r := VoucherRefusal(kind, label, domainLabel, holder, requestedAt, validUntil, sig); r != "" {
		panic("nsreserve: " + r)
	}
	now := time.Now().Unix()
	if d := now / 86400; d != voucherDay {
		voucherDay, voucherUsed = d, 0
	}
	voucherUsed++
	exp := requestedAt + term()
	spent := "false"
	if kind == KindMint {
		raw := rawOf(label, domainLabel)
		k, b := leafOf(raw)
		// Live and matching was checked above; an expired leftover goes too.
		if i, found := find(b, raw); found {
			buckets.Set(k, removeAt(b, i))
			total--
			spent = "true"
		}
	}
	chain.Emit("VoucherConsumed", "kind", kind, "hash", HashOf(label, domainLabel), "holder", holder.String(),
		"expires", strconv.FormatInt(exp, 10), "reservation", spent,
		"used", strconv.Itoa(voucherUsed), "cap", strconv.Itoa(voucherCap))
	return exp
}

// SetVoucherDailyCap sets how many vouchers a day may be used. Trusted
// logic only; nslogic.SetVoucherDailyCap timelocks every raise.
func SetVoucherDailyCap(cur realm, n int) {
	assertLogic(cur)
	if n < 0 || n > maxDailyCap {
		panic("nsreserve: a daily cap is 0.." + strconv.Itoa(maxDailyCap))
	}
	voucherCap = n
	chain.Emit("VoucherCapSet", "cap", strconv.Itoa(n), "by", cur.Previous().Address().String())
}

// VoucherToday is the mint approver's day: the UTC day number, how many
// vouchers were used and the cap.
func VoucherToday() (day int64, used int, cap int) {
	now := time.Now().Unix()
	return now / 86400, vouchersToday(now), voucherCap
}

// SetVoucherKey names the mint approver: an ed25519 public key, 64
// lowercase hex characters. Trusted logic only; nslogic timelocks it.
func SetVoucherKey(cur realm, hexKey string) {
	assertLogic(cur)
	raw, ok := unhex(hexKey)
	if !ok || len(raw) != 32 {
		panic("nsreserve: a voucher key is an ed25519 public key, 64 lowercase hex characters")
	}
	voucherKey = raw
	chain.Emit("VoucherKeySet", "key", hexKey, "by", cur.Previous().Address().String())
}

// ClearVoucherKey turns free minting off at once. Admin, guardian or
// recovery, as a direct wallet call: the first thing to reach for if the
// issuer is in doubt.
func ClearVoucherKey(cur realm) {
	a := cur.Previous().Address()
	if !isWarden(a) {
		panic("nsreserve: restricted to the admin, the guardian or recovery")
	}
	voucherKey = ""
	chain.Emit("VoucherKeyCleared", "by", a.String())
}

func VoucherKey() string { return hexOf(voucherKey) }

// -- the admin's side, through the logic realm and its timelock --

// Clear deletes the named reservations, live or expired. A hash that is
// not stored is skipped. Trusted logic only (nslogic.ClearReservations).
func Clear(cur realm, hashes string) int {
	assertLogic(cur)
	hs := mustSplit(hashes, hashWidth)
	removed := 0
	for _, raw := range hs {
		k, b := leafOf(raw)
		if i, found := find(b, raw); found {
			buckets.Set(k, removeAt(b, i))
			removed++
		}
	}
	total -= removed
	chain.Emit("ReservationsCleared", "count", strconv.Itoa(removed), "digest", digest(hashes),
		"by", cur.Previous().Address().String())
	return removed
}

// SetDailyCap sets how many entries the granter may write in one UTC day.
// Trusted logic only; nslogic.SetReserveDailyCap timelocks every raise.
func SetDailyCap(cur realm, n int) {
	assertLogic(cur)
	if n < 0 || n > maxDailyCap {
		panic("nsreserve: a daily cap is 0.." + strconv.Itoa(maxDailyCap))
	}
	dailyCap = n
	chain.Emit("DailyCapSet", "cap", strconv.Itoa(n), "by", cur.Previous().Address().String())
}

// -- incident switches --

// Pause stops the granter's writes and every voucher, so nothing is
// frozen and nothing is minted or renewed free. Admin, guardian or
// recovery, as a direct wallet call. Reads, Clear and Prune keep working.
func Pause(cur realm) {
	a := cur.Previous().Address()
	if !isWarden(a) {
		panic("nsreserve: restricted to the admin, the guardian or recovery")
	}
	paused = true
	chain.Emit("ReservePaused", "by", a.String())
}

// Unpause lifts the pause. Recovery only, like the vault's own; the admin
// goes through nslogic.UnpauseReservations and the timelock.
func Unpause(cur realm) {
	a := cur.Previous().Address()
	if a == "" || a != nsdata.GetRecovery() {
		panic("nsreserve: restricted to recovery")
	}
	paused = false
	chain.Emit("ReserveUnpaused", "by", a.String())
}

// UnpauseByLogic is the admin's timelocked door to the same switch.
func UnpauseByLogic(cur realm) {
	assertLogic(cur)
	paused = false
	chain.Emit("ReserveUnpaused", "by", cur.Previous().Address().String())
}

/*
Prune deletes expired reservations from up to maxLeaves tree keys, starting
where the last call stopped and wrapping at the end.

GRANTER OR ADMIN, not everybody: deleting an entry refunds its storage
deposit to whoever signs, and that deposit was ours.
*/
func Prune(cur realm, maxLeaves int) int {
	assertNoSend(cur)
	a := cur.Previous().Address()
	if a == "" || (a != granter() && a != nsdata.GetAdmin()) {
		panic("nsreserve: restricted to the granter or the admin")
	}
	if maxLeaves < 1 || maxLeaves > maxPrune {
		panic("nsreserve: maxLeaves is 1.." + strconv.Itoa(maxPrune))
	}
	now := time.Now().Unix()
	keys := make([]string, 0, maxLeaves)
	buckets.Iterate(pruneCursor, "", func(k string, _ any) bool {
		keys = append(keys, k)
		return len(keys) >= maxLeaves
	})
	removed := 0
	for _, k := range keys {
		b := buckets.Get(k).(string)
		if b == splitMark {
			continue
		}
		kept := make([]byte, 0, len(b))
		for i := 0; i+entryLen <= len(b); i += entryLen {
			if now < expiryAt(b, i) {
				kept = append(kept, b[i:i+entryLen]...)
			} else {
				removed++
			}
		}
		if len(kept) != len(b) {
			buckets.Set(k, string(kept))
		}
	}
	if len(keys) < maxLeaves {
		pruneCursor = "" // reached the end: the next call starts over
	} else {
		pruneCursor = keys[len(keys)-1] + "~" // just past the last key read
	}
	total -= removed
	chain.Emit("ReservationsPruned", "removed", strconv.Itoa(removed), "cursor", pruneCursor, "by", a.String())
	return removed
}

// -- reads --

func rawHash(hash string) string {
	raw, ok := unhex(hash)
	if !ok || len(raw) != hashLen {
		panic("nsreserve: a hash is 32 lowercase hex characters")
	}
	return raw
}

// IsReserved reports whether an unexpired reservation holds this hash.
func IsReserved(hash string) bool { return liveAt(rawHash(hash), time.Now().Unix()) }

// Reserved is IsReserved for a name written out.
func Reserved(label, domainLabel string) bool {
	return liveAt(rawOf(label, domainLabel), time.Now().Unix())
}

// ReservationOf reports the stored entry for a hash, expired ones included
// until they are pruned.
func ReservationOf(hash string) (expires int64, exists bool) { return lookup(rawHash(hash)) }

func Count() int { return total }

func Today() (day int64, used int, cap int) {
	now := time.Now().Unix()
	return now / 86400, usedToday(now), dailyCap
}

func DailyCap() int        { return dailyCap }
func VoucherCap() int      { return voucherCap }
func IsPaused() bool       { return paused }
func MaxBatch() int        { return maxBatch }
func MaxBackDays() int     { return int(maxBackSecs / 86400) }
func RenewWindowDays() int { return int(renewWindow / 86400) }

// checkBatch is the dry run behind CheckFreeze and CheckRenew: "" when
// every entry would be written, else one line per problem, "<index>
// <reason>" for an entry that would be skipped (0-based, in the order
// sent) or "* <reason>" for a refusal of the whole call.
//
// It walks the batch the way the write does, in hash order with the leaf
// reused, so it says exactly which entries the cap or a repeat would skip,
// and so a 2,000-entry dry run fits a query's gas on a large store.
func checkBatch(batch string, hexWidth int, rule func(e string, exp int64, found bool, now int64) string) string {
	now := time.Now().Unix()
	out := ""
	if paused {
		out += "* paused\n"
	}
	if granter() == "" {
		out += "* no granter is named\n"
	}
	es, r := split(batch, hexWidth)
	if r != "" {
		return out + "* " + r + "\n"
	}
	order := make([]int, len(es))
	for i := range order {
		order[i] = i
	}
	sort.Sort(byEntry{es, order})
	room := dailyCap - usedToday(now)
	w := newWork()
	why := make([]string, len(es))
	for _, i := range order {
		e := es[i]
		raw := e[:hashLen]
		lw := w.leaf(raw)
		pos, found := find(lw.orig, raw)
		exp := int64(0)
		if found {
			exp = expiryAt(lw.orig, pos)
		}
		// The write's own order of tests: the cap, a repeat, then the rule.
		switch {
		case room <= 0:
			why[i] = "past the daily cap"
		case w.seen[raw]:
			why[i] = "twice in this batch"
		default:
			why[i] = rule(e, exp, found, now)
		}
		if why[i] == "" {
			w.seen[raw] = true
			room--
		}
	}
	for i, r := range why {
		if r != "" {
			out += strconv.Itoa(i) + " " + r + "\n"
		}
	}
	return out
}

// byEntry sorts positions in a batch by the entries they point at.
type byEntry struct {
	es    []string
	order []int
}

func (b byEntry) Len() int           { return len(b.order) }
func (b byEntry) Less(i, j int) bool { return b.es[b.order[i]] < b.es[b.order[j]] }
func (b byEntry) Swap(i, j int)      { b.order[i], b.order[j] = b.order[j], b.order[i] }

func CheckFreeze(batch string) string { return checkBatch(batch, freezeWidth, freezeRule) }

func CheckRenew(hashes string) string { return checkBatch(hashes, hashWidth, renewRule) }

func Render(path string) string {
	_, used, c := Today()
	_, vused, vc := VoucherToday()
	s := "# Reservations\n\n"
	s += "Free names held for their claimants until they mint. Hashed: nothing here names a holder.\n\n"
	s += "- stored: " + strconv.Itoa(total) + "\n"
	s += "- reserved today: " + strconv.Itoa(used) + " of " + strconv.Itoa(c) + "\n"
	s += "- minted or renewed free today: " + strconv.Itoa(vused) + " of " + strconv.Itoa(vc) + "\n"
	if voucherKey == "" {
		s += "- free minting: off (no mint approver)\n"
	}
	if paused {
		s += "- PAUSED\n"
	}
	return s
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// assertIsAdmin reads nsdata.GetAdmin() fresh every call — correct even
// immediately after a TransferAdmin, and correct for a freshly-deployed
// logic realm with no local state of its own to go stale.
//
// Note: admin authority to swap WHICH realm is trustedLogic, or to
// transfer admin itself, is deliberately NOT exposed here — those live
// only in nsdata's own admin.gno, callable solely by a direct wallet
// call from the current admin address, never proxied through logic.
// That's the one part of the system a compromised or buggy logic realm
// cannot touch.
func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != nsdata.GetAdmin() {
		panic("nslogic: restricted to project admin")
	}
}

// SetLabelPattern no longer changes anything, and refuses anything but
// the rule this realm actually implements.
//
// It used to compile an arbitrary regex and store it, with validateLabel
// reading it back. That flexibility cost 15 GNOT of permanent storage
// per deploy — see the measurements in validate.gno — for a rule that
// has never changed and should not change casually.
//
// It is kept rather than deleted so that an admin who reaches for it
// gets told what happened instead of a "function not found". And it
// refuses a different pattern rather than accepting one it will not
// enforce: a stored string describing rules the code does not apply is
// the exact silent divergence the caching version was written to avoid.
func SetLabelPattern(cur realm, pattern string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetLabelPattern", "pattern", pattern)
	if pattern != labelRule {
		panic("nslogic: the label rule is fixed in this realm (" + labelRule +
			"). Changing it means deploying a new logic realm — which is deliberate, " +
			"because a stored pattern the code does not enforce is worse than no setting at all.")
	}
	nsdata.SetLabelPatternRecord(cross(cur), pattern)
}

func SetLabelLengthLimits(cur realm, minLen, maxLen int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetLabelLengthLimits", "min", fmtI(minLen), "max", fmtI(maxLen))
	if minLen < 1 || maxLen < minLen {
		panic("nslogic: invalid length bounds")
	}
	nsdata.SetLabelLengthRecord(cross(cur), minLen, maxLen)
}

// SetDefaultNamePrice sets the fallback price in micro-USD, used by any
// domain that has not set its own base. BOUNDED (timelock.gno): a raise up
// to four times every ten minutes, a cut up to 25% once an hour, or a
// timelocked proposal for anything else.
func SetDefaultNamePrice(cur realm, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDefaultNamePrice", "microUsd", fmtInt(microUsd))
	if microUsd < 0 || microUsd > maxPriceUSD {
		panic("nslogic: a price is 0.." + strconv.FormatInt(maxPriceUSD, 10) + " micro-USD")
	}
	v := strconv.FormatInt(microUsd, 10)
	old := DefaultPriceUSD()
	authorizeTweak(cur, keyDefaultPrice, old, microUsd, microUsd > old, actionID("SetDefaultNamePrice", v))
	setGlobal(cur, keyDefaultPrice, v)
}

// SetUsdRate records how many ugnot one USD buys — the bridge between
// the USD price list and settlement on this chain.
//
// It is a MANUAL rate, not a market feed: it sits where it was last
// written. A stale rate during a sharp move sells names at the wrong
// price, and no amount of contract logic fixes that — keeping it current
// is an operational duty. Isolated as one global so a future logic realm
// can swap in a real oracle without touching the vault or restating a
// single price.
//
// BOUNDED (timelock.gno): a rate of 1 ugnot to the dollar used to be one
// call away from selling every name for dust. ASYMMETRIC (Ely,
// 2026-10-16): a higher rate — GNOT fell, names cost more GNOT — moves up
// to four times every ten minutes, so a 75% crash is followed in one
// update; a lower rate — the direction that sells names cheap — moves at
// most 25%, once an hour. Anything larger is a timelocked proposal.
//
// THE KEEPER may call this too (keeper.gno), and nothing else: the same
// bound and the same hourly slot, never the timelock, and KeeperAction on
// every move. Anybody who is neither gets the admin refusal, as before.
func SetUsdRate(cur realm, ugnotPerUsd int64) {
	assertNoSend(cur)
	if cur.Previous().Address() != nsdata.GetAdmin() {
		keeperSetRate(cur, ugnotPerUsd)
		return
	}
	assertIsAdmin(cur)
	emitAdmin(cur, "SetUsdRate", "ugnotPerUsd", fmtInt(ugnotPerUsd))
	if ugnotPerUsd <= 0 || ugnotPerUsd > maxRate {
		panic("nslogic: a rate is 1.." + strconv.FormatInt(maxRate, 10) + " ugnot per USD")
	}
	v := strconv.FormatInt(ugnotPerUsd, 10)
	old := RateUgnotPerUsd()
	authorizeTweak(cur, keyRate, old, ugnotPerUsd, ugnotPerUsd > old, actionID("SetUsdRate", v))
	setGlobal(cur, keyRate, v)
}

// SetTermLength / SetGracePeriod retune the lifecycle itself. Both were
// hardcoded constants in the vault until 2026-08-21 — meaning the 1-year
// term and 90-day grace could never have been changed, on a realm that
// is never redeployed. There was no reason to accept that.
// maxLifecycleDays bounds both setters. time.Duration is int64
// NANOSECONDS, so `days * 24h` overflows above ~106,751 days and wraps to
// a NEGATIVE duration — which would install a negative term and brick
// every registration and renewal in the registry. Guarding the input is
// what keeps the multiplication in range.
const maxLifecycleDays = 36500 // 100 years

// BOTH ARE TIMELOCKED (timelock.gno). A grace period of zero made every
// name in grace reclaimable by anybody on the spot — owners who could
// still have renewed lost their names to whoever registered first — and a
// term change reprices every renewal and moves every holder's tenure.
func SetTermLength(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetTermLength", "days", fmtInt(days))
	if days <= 0 || days > maxLifecycleDays {
		panic("nslogic: term out of range (1..36500 days)")
	}
	term := days * 24 * 60 * 60
	// Keep gracePeriod <= termLength. Anchoring a renewal to the previous
	// due date is only coherent while a renewal cannot happen more than
	// one full term after it; the vault clamps forward defensively, but
	// the combination should not be reachable in the first place.
	if nsdata.GetGracePeriod() > term {
		panic("nslogic: term must be at least the current grace period")
	}
	requireAction(cur, actionID("SetTermLength", strconv.FormatInt(days, 10)))
	nsdata.SetTermLengthRecord(cross(cur), term)
}

func SetGracePeriod(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetGracePeriod", "days", fmtInt(days))
	if days < 0 || days > maxLifecycleDays {
		panic("nslogic: grace period out of range (0..36500 days)")
	}
	grace := days * 24 * 60 * 60
	if grace > nsdata.GetTermLength() {
		panic("nslogic: grace period may not exceed the term length")
	}
	requireAction(cur, actionID("SetGracePeriod", strconv.FormatInt(days, 10)))
	nsdata.SetGracePeriodRecord(cross(cur), grace)
}

// SetTokenURIBase re-points TokenURI at a different renderer, so the NFT
// artwork can be replaced without touching the vault.
func SetTokenURIBase(cur realm, base string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetTokenURIBase", "base", base)
	nsdata.SetTokenURIBaseRecord(cross(cur), base)
}

func SetExtraLimits(cur realm, keyLen, valueLen, entries int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetExtraLimits", "keyLen", fmtI(keyLen), "valueLen", fmtI(valueLen), "entries", fmtI(entries))
	// NEVER BELOW WHAT THIS REALM ITSELF WRITES: the vault's own defaults
	// (32-byte keys, 512-byte values, 24 entries). One instant call to a
	// tiny limit used to make every later global write revert, the keeper's
	// rate and the instant revocations among them (re-audit L-2).
	if keyLen < minExtraKeyLen || valueLen < minExtraValueLen || entries < minExtraEntries {
		panic("nslogic: extra limits are at least " + fmtI(minExtraKeyLen) + " / " + fmtI(minExtraValueLen) +
			" / " + fmtI(minExtraEntries) + ", the sizes this realm writes")
	}
	nsdata.SetExtraLimitsRecord(cross(cur), keyLen, valueLen, entries)
}

const (
	minExtraKeyLen   = 32
	minExtraValueLen = 512
	minExtraEntries  = 24
)

// SetGlobalEntryLimit sets how many keys the vault's globals may hold —
// its own cap now, apart from the per-record extras SetExtraLimits bounds.
func SetGlobalEntryLimit(cur realm, entries int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetGlobalEntryLimit", "entries", fmtI(entries))
	if entries < 1 || entries > 1024 {
		panic("nslogic: the globals cap must be 1-1024")
	}
	nsdata.SetGlobalEntryLimitRecord(cross(cur), entries)
}

// SetAccountLimits bounds the vault's per-address store: field name,
// value, and fields per address. Small numbers, because whoever's
// transaction writes a field pays for it.
func SetAccountLimits(cur realm, keyLen, valueLen, entries int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetAccountLimits", "keyLen", fmtI(keyLen), "valueLen", fmtI(valueLen), "entries", fmtI(entries))
	// Never below what this realm writes (the vault's defaults, 16/128/8):
	// a tiny limit refused every later grant, redemption and referral
	// count, deletes included — L-2's bug on the per-address store
	// (review follow-up).
	if keyLen < 16 || keyLen > 64 || valueLen < 128 || valueLen > 1024 || entries < 8 || entries > 64 {
		panic("nslogic: account limits must be 16-64 / 128-1024 / 8-64")
	}
	nsdata.SetAccountLimitsRecord(cross(cur), keyLen, valueLen, entries)
}

/*
SetMarketFee is nsmarket's fee control, living here because this is the
realm the vault trusts.

nsmarket.SetFee could never work: it wrote through nsdata.SetGlobalRecord
from a realm deliberately outside the trusted set, so it passed its own
admin check and then panicked inside the vault for every caller. Rather
than grant nsmarket vault privileges — which would surrender the property
that realm is built around — the setter moved to the realm that already
has the grant, and the validation moved with it.

The spec grammar is nsmarket's, restated here rather than imported so
this realm does not take a dependency on the marketplace to set a number:
an amount in ugnot ("1000000"), or a percentage ("%2.5"); "0" for none,
because "" removes the key and nsmarket then charges its default of one
GNOT. A malformed spec would otherwise be read on every sale and resolve
silently to zero.

A CHANGE THAT COULD RAISE THE FEE IS TIMELOCKED. The fee is read at sale
time, so a raise lands on listings sellers made under the old one — up to
half of their sale, moved to the treasury, with no notice. A timelocked
raise is the notice: sellers see ActionProposed and may unlist. Lowering
it, or switching it off, stays instant.
*/
func SetMarketFee(cur realm, spec string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetMarketFee", "spec", spec)
	assertValidFeeSpec(spec)
	spec = strings.TrimSpace(spec)
	if feeCouldRise(nsdata.GetGlobal(keyMarketFee), spec) {
		requireAction(cur, actionID("SetMarketFee", spec))
	}
	setGlobal(cur, keyMarketFee, spec)
}

const (
	keyMarketFee = "marketfee"
	// nsmarket's fee when the global is unset: one GNOT, flat. Restated
	// rather than imported, like the grammar, so this realm takes no
	// dependency on the marketplace to set a number.
	defaultMarketFee = "1000000"
)

// feeCouldRise reports whether moving from the stored spec `old` to `next`
// could raise the fee on any sale. Both are read the way nsmarket reads
// them: unset means the default. A move to zero never rises; a change of
// kind — flat to percentage or back — rises on some price, so it counts.
func feeCouldRise(old, next string) bool {
	of, ob := feeParts(old)
	nf, nb := feeParts(next)
	switch {
	case nf == 0 && nb == 0:
		return false
	case of == 0 && ob == 0:
		return true
	case ob == 0 && nb == 0:
		return nf > of
	case of == 0 && nf == 0:
		return nb > ob
	}
	return true
}

// feeParts splits a spec into (flat ugnot, basis points), the way
// nsmarket.parseFee does; unset is the default fee, and an unreadable spec
// is zero — which is also how nsmarket charges it.
func feeParts(spec string) (flat, bps int64) {
	spec = strings.TrimSpace(spec)
	if spec == "" {
		spec = defaultMarketFee
	}
	if !strings.HasPrefix(spec, "%") {
		n, err := strconv.ParseInt(spec, 10, 64)
		if err != nil || n < 0 {
			return 0, 0
		}
		return n, 0
	}
	body := spec[1:]
	whole, frac := body, ""
	if dot := strings.Index(body, "."); dot >= 0 {
		whole, frac = body[:dot], body[dot+1:]
	}
	w, err := strconv.ParseInt("0"+whole, 10, 64)
	if err != nil {
		return 0, 0
	}
	bps = w * 100
	if frac != "" {
		f, err := strconv.ParseInt("0"+frac, 10, 64)
		if err != nil || len(frac) > 1 {
			return 0, 0
		}
		bps += f * 10
	}
	return 0, bps
}

// assertValidFeeSpec mirrors nsmarket.parseFee. Percentages are carried
// as basis points so a fee is expressible without floating point
// anywhere near money.
func assertValidFeeSpec(spec string) {
	spec = strings.TrimSpace(spec)
	if spec == "" {
		return
	}
	if !strings.HasPrefix(spec, "%") {
		n, err := strconv.ParseInt(spec, 10, 64)
		if err != nil || n < 0 {
			panic("nslogic: a fee is an amount in ugnot or a percentage like %2.5 — got " + spec)
		}
		return
	}
	body := spec[1:]
	whole, frac := body, ""
	if dot := strings.Index(body, "."); dot >= 0 {
		whole, frac = body[:dot], body[dot+1:]
	}
	// ONE decimal, matching nsmarket.parseFee exactly. I wrote two here
	// first, which made this validator MORE permissive than the parser
	// that has to read the value back — and a spec nsmarket refuses is
	// read as a zero fee on every sale, silently, forever. A validator
	// looser than its consumer is worse than no validator: it converts a
	// rejected input into a silent revenue leak.
	if len(frac) > 1 {
		panic("nslogic: a fee percentage carries at most one decimal — got " + spec)
	}
	for _, part := range []string{whole, frac} {
		for i := 0; i < len(part); i++ {
			if part[i] < '0' || part[i] > '9' {
				panic("nslogic: a fee percentage must be digits — got " + spec)
			}
		}
	}
	if whole == "" && frac == "" {
		panic("nslogic: a fee percentage needs a number — got " + spec)
	}
	// Basis points the same way parseFee computes them: whole*100 plus
	// one tenth-digit worth ten. Not two digits, and not a 100% ceiling
	// — nsmarket caps at maxFeeBps, which is 50%.
	w, _ := strconv.ParseInt("0"+whole, 10, 64)
	bp := w * 100
	if frac != "" {
		f, _ := strconv.ParseInt("0"+frac, 10, 64)
		bp += f * 10
	}
	if bp <= 0 || bp > 5000 {
		panic("nslogic: a fee percentage must be above zero and at most 50 — got " + spec)
	}
}

// SetGlobal writes an arbitrary project-wide key into the vault's
// package-level extension slot — the escape hatch for global state that
// does not exist yet, and for keys other realms read (cardfx). It refuses
// every key a setter here owns: the escape hatch used to walk round every
// bound and timelock on them. See managedGlobal.
func SetGlobal(cur realm, key, value string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetGlobal", "key", key, "value", value)
	if managedGlobal(key) {
		panic("nslogic: " + key + " has its own setter, with its own rules; use that")
	}
	setGlobal(cur, key, value)
}

func setGlobal(cur realm, key, value string) {
	/* THE RESTORE SEAL IS NOT AN ORDINARY GLOBAL.
	   restore.gno says sealing is "IRREVERSIBLE… There is no argument
	   that unseals it". One admin call writing key "restore" used to
	   reopen it. The vault now refuses both keys through its general
	   setter and refuses to change a seal through its reserved one, so a
	   logic swap cannot drop the guard; this check stays so the refusal
	   names the right door. */
	if key == keyRestore || key == keyRestoredCount {
		panic("nslogic: " + key + " is written by the restore machinery, not by SetGlobal")
	}
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic(err)
	}
}

// SetTreasury moves the revenue-receiving role — independent of
// nsdata's TransferAdmin, same reasoning as the original build's
// admin/treasury separation.
//
// TIMELOCKED. It took effect at once and said nothing, so a stolen admin
// key redirected every later sale — names, renewals, skins, market fees —
// in one call (audit M4). Now it is announced and waits, and recovery can
// cancel it.
func SetTreasury(cur realm, newTreasury address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetTreasury", "addr", newTreasury.String())
	if !newTreasury.IsValid() {
		panic("nslogic: invalid treasury address")
	}
	requireAction(cur, actionID("SetTreasury", newTreasury.String()))
	nsdata.SetTreasuryRecord(cross(cur), newTreasury)
}

// SelfAddress reports this deployed realm's own address — needed once,
// at wiring time, so admin knows what to pass to
// nsdata.ProposeTrustedLogicGrant.
func SelfAddress(cur realm) address {
	return cur.Address()
}

package nslogic

import (
	"strings"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

/*
THE BLOCK LIST: labels nobody may hold, at any price.

This is NOT the reserved list, and confusing the two would undo both.

	reserved (collections/reserved-labels.json, 232 labels) says
	"blocked from the free tier, buyable at list price like anything
	else". admin*meme being purchasable is deliberate: the harm it
	guards against is handing a phishing address out for nothing, not
	the existence of the name. That list is enforced by the issuer,
	which is the only place that decides what is free.

	THIS list says "not available, full stop". It is the small set where
	the answer does not change when somebody offers money: names that
	impersonate the registry itself, and the registry's own names.

WHY IT LIVES IN THE VAULT'S GLOBALS RATHER THAN IN THIS FILE.

Baking it in would mean a logic deploy to block a word, and the words
worth blocking are exactly the ones discovered after launch — the label
somebody tried yesterday that nobody thought of. Globals are writable by
the admin, survive a logic swap because they belong to the vault, and
cost storage only for what is actually stored.

Chunked because a global value is capped at 512 bytes. Eight chunks is
about four kilobytes, or several hundred labels, which is far more than
this list should ever need — if it grows past that, the thing being
built is a content policy and it belongs off chain where it can be
updated without a transaction.

FAILS OPEN, and that is the uncomfortable choice, so it is written down.
An unreadable chunk blocks nothing rather than blocking everything.
Failing closed here would mean one malformed global takes the whole
registry offline — every registration, for everyone, until an admin
notices. The harm from a blocked label slipping through is one bad name
that an admin can freeze; the harm from failing closed is total. The
list is also not the only defence: the issuer holds the reserved list,
and FreezeName exists for anything that gets past both.
*/

const (
	blockChunks   = 8
	blockKeyStem  = "block"
	blockChunkMax = 512
)

// blockKey is the global name for one chunk: block0 … block7.
func blockKey(i int) string {
	return blockKeyStem + string(rune('0'+i))
}

/*
BlockedLabel reports whether a label may not be registered at all.

Compares against the label as the registry stores it — lowercase, already
validated — so a caller cannot slip past with different casing. Every
comparison is exact: this list holds whole labels, not substrings,
because "contains" matching turns a list of a dozen words into an
unpredictable filter that refuses names nobody meant to refuse.
*/
func BlockedLabel(label string) bool {
	if label == "" {
		return false
	}
	want := strings.ToLower(label)
	for i := 0; i < blockChunks; i++ {
		v := nsdata.GetGlobal(blockKey(i))
		if v == "" {
			continue
		}
		for _, e := range strings.Split(v, ",") {
			if strings.ToLower(strings.TrimSpace(e)) == want {
				return true
			}
		}
	}
	return false
}

// BlockList returns one chunk, so the panel can show and edit what is
// actually stored rather than what somebody believes is stored.
func BlockList(i int) string {
	if i < 0 || i >= blockChunks {
		return ""
	}
	return nsdata.GetGlobal(blockKey(i))
}

// BlockChunks is the number of chunks, so the panel does not hard-code a
// constant that this file might later change.
func BlockChunks() int { return blockChunks }

/*
SetBlockList replaces one chunk. Admin only.

Replaces rather than appends: an append-only list has no way to correct a
mistake, and a mistake here refuses somebody a name for reasons nobody
can see. The panel reads the chunk, edits it, and writes it back whole.
*/
func SetBlockList(cur realm, i int, csv string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetBlockList", "chunk", fmtI(i), "csv", csv)
	if i < 0 || i >= blockChunks {
		panic("nslogic: chunk out of range")
	}
	if len(csv) > blockChunkMax {
		panic("nslogic: that chunk is longer than a global may be")
	}
	// Normalised on the way in, so the comparison above never has to
	// account for whatever spacing somebody typed into a form.
	parts := strings.Split(csv, ",")
	out := []string{}
	for _, p := range parts {
		p = strings.ToLower(strings.TrimSpace(p))
		if p != "" {
			out = append(out, p)
		}
	}
	setGlobal(cur, blockKey(i), strings.Join(out, ","))
}

// assertNotBlocked is the gate both doors pass through — the paid
// registration and the free grant. One function, called twice, because
// a block that only covers one route is not a block.
func assertNotBlocked(label string) {
	if BlockedLabel(label) {
		panic("nslogic: " + label + " is not available")
	}
}

package nslogic

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

/*
CREDITS: a free registration, granted to an address ahead of time.

WHY. Two plans need it (MAINNET.md §0):
  - the migration grant: every wallet that registered a name on testnet
    gets one free name on mainnet, of its own choosing;
  - onboarding: somebody who holds no GNOT at all is given a name, and
    the project registers it FOR them.

WHERE IT LIVES. In the vault's per-address store, never in this realm, so
a logic swap neither loses nor repeats anybody's credit — and not in
globals, which cannot hold an address-sized key at all.

THE RECORD is one field, "cr", holding "granted,used,expires,held,at":

	granted  credits issued in total. A grant SETS this number, it never
	         adds to it, so re-running a grant batch after people have
	         redeemed cannot hand anybody a second name;
	used     credits redeemed;
	expires  the unix second they lapse, 0 for none (the claim window
	         still bounds every credit);
	held     1: the name is minted with the free-tier hold — usable and
	         renewable, not sellable until upgraded at list price. Only a
	         grant made with sellable=false writes 1;
	at       the unix second of the grant (re-audit 2026-10-16, M-2), so
	         recovery can void what a stolen admin key granted
	         (nsdata.VoidGrantsSince) and the honest admin can grant again
	         what was legitimate. A record written before this field reads
	         as granted at 0.

AN INCIDENT CAN UNDO A GRANT. What a thief granted used to outlive its
eviction: the credits live in the vault, and nothing could touch them while
the logic was revoked and the registry paused, so the thief's wallets
redeemed in the block that unpaused it. Now the vault's incident switches
(nsdata incident.gno) hold: no credit is spent while the registry is
paused, while recovery's quarantine runs, or once recovery has voided the
time it was granted in; and the guardian's Disarm shuts the claim window.

SELLABLE BY DEFAULT (Ely, 2026-10-16). A credit buys a real name, minted
like a paid one and free to sell, unless the grant says otherwise: the
per-grant flag is `sellable`, and every caller passes true unless it means
to hand out a held name. The record keeps the hold bit, so its stored form
did not change; the API speaks in the direction the default runs.

WHO PAYS THE STORAGE DEPOSIT. Whoever SIGNS, and nobody else can. The
chain charges a call's storage deposit and its gas to the transaction's
signer (gno.land/pkg/sdk/vm keeper.go, lockStorageDeposit(ctx, caller,
...)); a realm cannot pay either on somebody's behalf, and this one holds
no coins to try. So there are two doors, and both spend the holder's
credit:

	RedeemCredit  the holder signs. The name costs nothing; the holder
	              pays the storage deposit (about 0.57 GNOT) and gas.
	RegisterFor   the admin or the granter signs and the project pays
	              both; the name goes to the holder. This is the only
	              path for a holder with no GNOT, who cannot sign at all.

WHAT A CREDIT BUYS. One ordinary registration at no price: any open
domain, any label the ordinary rules allow, up to a list price cap
(ClaimMaxPriceUSD) — the on-chain answer to MAINNET.md's "do premium names
count?", left settable rather than decided here. UNSET, THE CAP COVERS
NOTHING and no credit redeems (re-audit 2026-10-16, H-1): it used to fall
back to the default name price, and the default rises fast. The deploy
sets it explicitly (tools/deploy-gen.sh, CLAIMMAX).

GRANTED BY THE ADMIN, AND NOT TIMELOCKED, deliberately. A credit can only
create a registration of a name nobody holds: it never touches an
existing holder, moves no money, works only inside the claim window and
only under the price cap. A stolen admin key can gift itself cheap names
until it is rotated out — the same order of harm as the free tier, and
far smaller than anything the timelock guards. A 48-hour wait on every
grant would make "register it for them now" impossible.
*/

const (
	keyCredit   = "cr"       // account field: the record above
	keyClaimEnd = "claimend" // global: unix second the claim window closes; unset means closed
	keyClaimMax = "claimmax" // global: highest list price, micro-USD, a credit covers

	maxCreditsPerAddress = 100
	maxGrantBatch        = 100
	maxClaimWindowDays   = 730 // one setting cannot promise more than two years
)

type credit struct {
	granted, used, expires int64
	held                   bool
	at                     int64 // when granted; 0 for a record from before the field
}

// parseCredit FAILS CLOSED: anything it cannot read is no credit at all.
// A malformed record must never be read as a free name. Four fields is the
// record before the grant time existed; five carries it.
func parseCredit(v string) credit {
	if v == "" {
		return credit{}
	}
	f := strings.Split(v, ",")
	if (len(f) != 4 && len(f) != 5) || (f[3] != "0" && f[3] != "1") {
		return credit{}
	}
	g, e1 := strconv.ParseInt(f[0], 10, 64)
	u, e2 := strconv.ParseInt(f[1], 10, 64)
	x, e3 := strconv.ParseInt(f[2], 10, 64)
	if e1 != nil || e2 != nil || e3 != nil || g < 0 || u < 0 || x < 0 {
		return credit{}
	}
	c := credit{granted: g, used: u, expires: x, held: f[3] == "1"}
	if len(f) == 5 {
		at, e4 := strconv.ParseInt(f[4], 10, 64)
		if e4 != nil || at < 0 {
			return credit{}
		}
		c.at = at
	}
	return c
}

func (c credit) encode() string {
	h := "0"
	if c.held {
		h = "1"
	}
	return strconv.FormatInt(c.granted, 10) + "," + strconv.FormatInt(c.used, 10) + "," +
		strconv.FormatInt(c.expires, 10) + "," + h + "," + strconv.FormatInt(c.at, 10)
}

// voided reports whether recovery voided the time this credit was granted.
func (c credit) voided() bool { return c.granted > c.used && nsdata.GrantVoided(c.at) }

// available is how many may be redeemed at `now`.
func (c credit) available(now int64) int64 {
	if c.expires != 0 && now >= c.expires {
		return 0
	}
	if c.used >= c.granted {
		return 0
	}
	return c.granted - c.used
}

func readCredit(owner address) credit { return parseCredit(nsdata.GetAccount(owner, keyCredit)) }

func writeCredit(cur realm, owner address, c credit) {
	v := c.encode()
	// Nothing granted and nothing used is no record: free the storage.
	// A record with redemptions stays, because `used` is what stops a
	// repeated grant from handing out a second name.
	if c.granted == 0 && c.used == 0 {
		v = ""
	}
	if err := nsdata.SetAccountRecord(cross(cur), owner, keyCredit, v); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// CreditsOf reports an address's credits: how many it may redeem right
// now, and the record behind that answer. `sellable` is whether the names
// they buy come without the free-tier hold — true unless the grant said not.
// Credits recovery voided are not available; the window, a pause and a
// quarantine are the registry's state, reported by CreditRefusal.
func CreditsOf(owner address) (available, granted, used, expires int64, sellable bool) {
	c := readCredit(owner)
	a := c.available(time.Now().Unix())
	if c.voided() {
		a = 0
	}
	return a, c.granted, c.used, c.expires, !c.held
}

// CreditGrantedAt is when an address's credits were last granted (unix
// seconds; 0 for none, or for a record from before the field existed).
func CreditGrantedAt(owner address) int64 { return readCredit(owner).at }

// -- the window and the cap --

// ClaimWindowEnd is the unix second redemption closes, or 0 when no
// window is set — which means CLOSED. An entitlement nobody bounded is a
// liability that never ends, so the default is no window at all.
func ClaimWindowEnd() int64 {
	v := nsdata.GetGlobal(keyClaimEnd)
	if v == "" {
		return 0
	}
	end, err := strconv.ParseInt(v, 10, 64)
	if err != nil || end < 0 {
		return 0
	}
	return end
}

func ClaimWindowOpen() bool { return readClaimWindow(nsdata.GetGlobal(keyClaimEnd), time.Now().Unix()) }

// readClaimWindow fails closed on anything it cannot read, the same rule
// the free tier's window follows: a mistyped setting must not give names away.
func readClaimWindow(v string, now int64) bool {
	if v == "" {
		return false
	}
	end, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		return false
	}
	return now < end
}

// SetClaimWindow opens redemption until `end` (unix seconds), at most two
// years ahead, or closes it with 0. Closing is the one call to reach for
// on a Sunday when something about the grants looks wrong.
func SetClaimWindow(cur realm, end int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetClaimWindow", "end", fmtInt(end))
	if end == 0 {
		setGlobal(cur, keyClaimEnd, "")
		return
	}
	now := time.Now().Unix()
	if end <= now || end > now+maxClaimWindowDays*86400 {
		panic("nslogic: a claim window ends in the future and at most " +
			strconv.Itoa(maxClaimWindowDays) + " days ahead; 0 closes it")
	}
	setGlobal(cur, keyClaimEnd, strconv.FormatInt(end, 10))
}

/*
ClaimMaxPriceUSD is the highest list price, in micro-USD, a credit can be
spent on, or 0 while no cap is set — and while none is set no credit
redeems at all (ClaimCapSet).

IT NEVER FOLLOWS THE DEFAULT PRICE (re-audit 2026-10-16, H-1). It used to
fall back to DefaultPriceUSD while unset, which is how a registry is born.
The default moves fast in its "dearer" direction — four times, every ten
minutes, instantly — and premium prices do not move with it, so each
dearer step on the default carried the cap past another tier of premium
names: a stolen admin key took the $300 x*doge with a free credit in forty
minutes, never touching SetClaimMaxPrice, whose raise is meant to be the
slow step. So the cap stands on its own now, an unset or unreadable one
covers nothing, and the first cap is a decision (SetClaimMaxPrice).
*/
func ClaimMaxPriceUSD() int64 {
	p, _ := claimCap()
	return p
}

// ClaimCapSet reports whether a cap is set at all. Unset — or unreadable,
// which is read the same way — no credit can be spent on anything.
func ClaimCapSet() bool {
	_, ok := claimCap()
	return ok
}

func claimCap() (int64, bool) {
	v := nsdata.GetGlobal(keyClaimMax)
	if v == "" {
		return 0, false
	}
	p, err := strconv.ParseInt(v, 10, 64)
	if err != nil || p < 0 {
		return 0, false
	}
	return p, true
}

// SetClaimMaxPrice is BOUNDED like a price (timelock.gno), with the
// direction turned round: RAISING the cap is what makes names cheaper — a
// credit then covers pricier names, premium ones in the end — so a raise is
// the slow step (25%, once an hour) and a cut the fast one (down to a
// quarter, every ten minutes). Anything else is a timelocked proposal.
//
// THE FIRST CAP IS NOT A STEP. From no cap there is nothing to step from,
// so setting one is always the timelocked proposal: instant at a fresh
// vault's delay of zero, which is when the deploy sets it, and recovery's
// to veto once the delay is raised.
func SetClaimMaxPrice(cur realm, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetClaimMaxPrice", "microUsd", fmtInt(microUsd))
	if microUsd < 0 || microUsd > maxPriceUSD {
		panic("nslogic: the claim cap must be 0.." + strconv.FormatInt(maxPriceUSD, 10) + " micro-USD")
	}
	v := strconv.FormatInt(microUsd, 10)
	id := actionID("SetClaimMaxPrice", v)
	old, set := claimCap()
	if !set {
		requireAction(cur, id)
		// A cap from nothing is the cheaper direction for claimants: the
		// next raise waits the cheap clock's hour like any other.
		lastTweak.Set(clockKey(keyClaimMax, false), time.Now().Unix())
	} else {
		authorizeTweak(cur, keyClaimMax, old, microUsd, microUsd < old, id)
	}
	setGlobal(cur, keyClaimMax, v)
}

// -- granting --

// GrantCredits SETS how many free registrations `to` is entitled to in
// total, with an optional expiry (0 for none) and whether the names they
// buy are SELLABLE — true is the default to pass; false mints them with
// the free-tier hold. 0 revokes whatever is unredeemed. See the note at
// the top of this file on why a grant sets rather than adds.
func GrantCredits(cur realm, to address, n, expires int64, sellable bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "GrantCredits", "to", to.String(), "n", fmtInt(n), "expires", fmtInt(expires), "sellable", fmtBool(sellable))
	grantCredits(cur, to, n, expires, sellable, time.Now().Unix())
}

// GrantCreditsBatch is GrantCredits for a comma-separated list of
// addresses, up to 100 a call — the migration grant is one entry per
// testnet wallet. Returns how many were written. One bad address fails
// the whole batch, so a typo cannot silently leave somebody out.
func GrantCreditsBatch(cur realm, addrs string, n, expires int64, sellable bool) int {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "GrantCreditsBatch", "addrs", addrs, "n", fmtInt(n), "expires", fmtInt(expires), "sellable", fmtBool(sellable))
	parts := strings.Split(addrs, ",")
	if len(parts) > maxGrantBatch {
		panic("nslogic: at most " + strconv.Itoa(maxGrantBatch) + " addresses per batch")
	}
	now := time.Now().Unix()
	done := 0
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		grantCredits(cur, address(p), n, expires, sellable, now)
		done++
	}
	return done
}

func grantCredits(cur realm, to address, n, expires int64, sellable bool, now int64) {
	if !to.IsValid() {
		panic("nslogic: not an address: " + to.String())
	}
	if n < 0 || n > maxCreditsPerAddress {
		panic("nslogic: a grant is 0.." + strconv.Itoa(maxCreditsPerAddress) + " credits")
	}
	if expires != 0 && expires <= now {
		panic("nslogic: credits that have already expired are not a grant; pass 0 for no expiry")
	}
	c := readCredit(to)
	c.granted, c.expires, c.held, c.at = n, expires, !sellable, now
	writeCredit(cur, to, c)
}

// -- redeeming --

// RedeemCredit registers label*domain to the caller and spends one of the
// caller's credits. The caller signs, so the caller pays the storage
// deposit and gas; the name itself costs nothing.
func RedeemCredit(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	redeemCredit(cur, cur.Previous().Address(), label, domainLabel)
}

// RegisterFor registers label*domain to `owner` and spends one of
// OWNER'S credits — the project signs and pays the storage and gas, which
// is the only way a holder with no GNOT can get a name at all. Admin or
// granter: the same machine that issues free names relays these, and it
// can spend only credits the admin granted, only into the holder's own
// wallet.
func RegisterFor(cur realm, owner address, label, domainLabel string) {
	assertNoSend(cur)
	assertMayGrant(cur)
	emitAdmin(cur, "RegisterFor", "owner", owner.String(), "label", label, "domain", domainLabel)
	assertLegacyGrants() // a granter door: closed with the others (reserve.gno)
	if !owner.IsValid() {
		panic("nslogic: a registration needs a recipient")
	}
	redeemCredit(cur, owner, label, domainLabel)
}

// CreditRefusal is why `owner` could not spend a credit on label*domain
// right now, or "" when nothing about the credit stands in the way. For
// the site, before anybody signs; the label rules are checked separately.
func CreditRefusal(owner address, label, domainLabel string) string {
	return creditRefusal(owner, label, domainLabel, time.Now().Unix())
}

func creditRefusal(owner address, label, domainLabel string, now int64) string {
	if nsdata.IsPaused() {
		return "the registry is paused"
	}
	if q := nsdata.QuarantineUntil(); now < q {
		return "recovery has quarantined giveaways until unix " + strconv.FormatInt(q, 10)
	}
	// A credit buys a name that can be sold: it is a paid door, and it
	// stays shut while paid registration is (verify N-5).
	if !PaidOpen(domainLabel) {
		return "paid registration is closed on *" + domainLabel + ", and credits with it"
	}
	if !readClaimWindow(nsdata.GetGlobal(keyClaimEnd), now) {
		return "the claim window is closed"
	}
	c := readCredit(owner)
	if c.available(now) <= 0 {
		if c.granted > c.used && c.expires != 0 && now >= c.expires {
			return "this address's credits have expired"
		}
		return "this address has no credit to spend"
	}
	if c.voided() {
		return "recovery voided the credits granted to this address at unix " + strconv.FormatInt(c.at, 10) +
			"; the admin may grant them again"
	}
	most, set := claimCap()
	if !set {
		return "credits are off: no claim cap is set, and an unset cap covers nothing"
	}
	if p := NamePriceUSD(domainLabel, label); p > most {
		return "a credit covers names listed at up to " + strconv.FormatInt(most, 10) +
			" micro-USD, and this one lists at " + strconv.FormatInt(p, 10)
	}
	return ""
}

/*
redeemCredit is both doors. Every check runs before anything is written,
the registration lands before the credit is spent, and either failing
reverts the other: the credit cannot be spent on a name that did not
arrive, and a name cannot arrive without its credit being spent.
*/
func redeemCredit(cur realm, owner address, label, domainLabel string) {
	assertNotRestoring()
	validateLabel(label)
	assertNotBlocked(label)
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	assertNotReserved(label, domainLabel)
	now := time.Now().Unix()
	if r := creditRefusal(owner, label, domainLabel, now); r != "" {
		panic("nslogic: " + r)
	}
	c := readCredit(owner)
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, owner, now, !c.held); err != nil {
		panic(err)
	}
	c.used++
	writeCredit(cur, owner, c)
	chain.Emit("CreditRedeemed", "tid", label+"*"+domainLabel, "owner", owner.String(),
		"by", cur.Previous().Address().String())
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// RegisterDomain mints a new `*domain` — ADMIN-ONLY (2026-08-15 policy:
// domains are never sold or owned by third parties). No payment: the
// project isn't paying itself. Domains are also permanently
// non-transferable by users (see nft.gno's TransferFrom).
func RegisterDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "RegisterDomain", "label", label)
	validateLabel(label)
	caller := cur.Previous().Address()
	if err := nsdata.RegisterDomainRecord(cross(cur), label, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// RenewDomain extends a domain's expiry by exactly one year from its
// PREVIOUS due date, not from the payment date. No payment — domains are
// always project-owned, so this is self-service upkeep, not a sale.
// Deliberately does not call validateLabel — a tightened pattern only
// gates new registrations, never renewals of what's already registered.
func RenewDomain(cur realm, label string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if err := nsdata.RenewDomainRecord(cross(cur), label, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// ReassignDomain moves a domain record to a new owner. ADMIN-ONLY, and
// the deliberate exception to "domains are non-transferable".
//
// It exists because domain ownership is snapshotted into the record at
// registration time, while `admin` is a rotatable role. After the
// planned EOA-to-multisig rotation, the incoming admin could not renew
// or reprice any domain the outgoing key had registered — and if the
// rotation happened *because* the old key was compromised, the attacker
// could still reprice those domains afterwards. This is the recovery
// lever for exactly that situation.
//
// Not a loophole in the non-transferability policy: that policy exists
// to stop domains reaching third parties as tradeable assets, and this
// path is reachable only by the current admin, moving a project domain
// between project-controlled addresses.
//
// TIMELOCKED (timelock.gno): a stolen admin key could otherwise move every
// project domain to itself in one block. Genesis domains run ten years, so
// the honest recovery this exists for loses nothing by waiting.
func ReassignDomain(cur realm, label string, newOwner address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "ReassignDomain", "label", label, "to", newOwner.String())
	if !newOwner.IsValid() {
		panic("nslogic: invalid owner address")
	}
	requireAction(cur, actionID("ReassignDomain", label, newOwner.String()))
	/* THE STOPGAP IS GONE. This used to read the domain's settings back
	   and rewrite them around a token transfer, because that transfer
	   wiped them. Domains are records now, and nsdata moves the owner
	   without touching price, len, nm, open or maxterm. */
	if err := nsdata.ReassignDomainRecord(cross(cur), label, newOwner); err != nil {
		panic(err)
	}
}

// -- pricing controls (admin) --
//
// Every amount here is MICRO-USD (1 USD = 1_000_000). Nothing is priced
// in the chain token; ugnot is derived at payment time from the stored
// rate, so a second settlement token later is a second rate rather than
// a second price list.

// SetDomainOpen enables or disables registration of new names under a
// domain. Existing names are untouched: closing a domain stops new
// mints, it does not seize anything already held.
func SetDomainOpen(cur realm, label string, open bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainOpen", "label", label, "open", fmtBool(open))
	v := "1"
	if !open {
		v = "0"
	}
	setDomainExtra(cur, label, keyOpen, v)
}

// SetDomainBasePrice sets the domain's base price in micro-USD. Every
// "%N" rule under the domain is relative to this, so one call reprices
// the whole domain. BOUNDED (timelock.gno): a raise up to four times every
// ten minutes, a cut up to 25% once an hour; a move to or from free, or
// anything larger, is a timelocked proposal.
func SetDomainBasePrice(cur realm, label string, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainBasePrice", "label", label, "microUsd", fmtInt(microUsd))
	if microUsd < 0 || microUsd > maxPriceUSD {
		panic("nslogic: a price is 0.." + strconv.FormatInt(maxPriceUSD, 10) + " micro-USD")
	}
	v := strconv.FormatInt(microUsd, 10)
	old := DomainBasePriceUSD(label)
	own := keyPrice + ":" + label
	clocks := []string{own}
	if nsdata.GetDomainExtra(label, keyPrice) == "" {
		// Still on the default: its first own price is a move of the
		// default's too, on the default's clocks (timelock.gno, re-audit L-1),
		// and the domain takes the default's clocks with it — or a first
		// price EQUAL to the default, which moves nothing and stamps nothing,
		// left a fresh clock for the next cut (review follow-up).
		inheritClocks(own, keyDefaultPrice)
		clocks = append(clocks, keyDefaultPrice)
	}
	authorizeTweakOn(cur, clocks, old, microUsd, microUsd > old,
		actionID("SetDomainBasePrice", label, v))
	setDomainExtra(cur, label, keyPrice, v)
}

// SetDomainLengthRules prices by label length: "3:2000000,4:%150,5:0"
// means 3-char names cost $2.00, 4-char names cost 150% of the domain
// base, and 5-char names are free.
//
// TIMELOCKED, with the price rules below: one rule can make any length
// free ("3:0"), so a rule set is not a tweak whatever it says. Propose the
// NORMALISED form, which the refusal prints.
func SetDomainLengthRules(cur realm, label, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainLengthRules", "label", label, "rules", rules)
	norm := normalizeRules(rules, true)
	requireAction(cur, actionID("SetDomainLengthRules", label, norm))
	setDomainExtra(cur, label, keyLens, norm)
}

// SetDomainNameOverrides prices specific labels: "420:5000000,gm:%500".
// Highest precedence — this beats length rules and the base. TIMELOCKED,
// like the length rules: "premiumname:0" was a one-call way to take one.
func SetDomainNameOverrides(cur realm, label, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainNameOverrides", "label", label, "rules", rules)
	norm := normalizeRules(rules, false)
	requireAction(cur, actionID("SetDomainNameOverrides", label, norm))
	setDomainExtra(cur, label, keyNames, norm)
}

// SetDomainField writes an arbitrary key on a domain, for whatever a
// future feature needs without a vault change — the domain's art among
// them. It refuses the keys this realm's own setters own, which it used
// to write straight past ("price" to zero, with no bound).
func SetDomainField(cur realm, label, key, value string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainField", "label", label, "key", key, "value", value)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	if managedDomainKey(key) {
		panic("nslogic: " + key + " has its own setter, with its own rules; use that")
	}
	setDomainExtra(cur, label, key, value)
}

func setDomainExtra(cur realm, label, key, value string) {
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic(err)
	}
}

// FreezeDomain / UnfreezeDomain: project-only power to permanently block
// re-registration of a domain even after its grace period lapses.
// DeleteDomain destroys a domain and every name beneath it.
//
// THE VAULT PRIMITIVE EXISTED BEFORE THIS DID, AND THAT MADE IT
// UNREACHABLE. nsdata.DeleteDomainRecord gates on assertIsTrustedLogic,
// so the only way to reach it is a function in this realm — and there
// was not one. The capability shipped in the vault and could not be
// used, which is worse than not shipping it, because it reads as
// present.
//
// Bounded by the vault at maxDeletePerCall names per call. It returns
// how many it removed and whether it finished, so a large domain is
// several calls rather than a transaction that cannot fit in a block.
// Repeat until done is true; calling it on a domain that is already gone
// reports done rather than panicking, so a loop terminates cleanly.
//
// ADMIN ONLY, and deliberately not owner-callable: domains are
// project-owned (SPEC.md §17b) and this destroys other people's names.
//
// TIMELOCKED (timelock.gno). It burned every live name under a domain at
// once — and paid the deleter the holders' storage deposits, about 57 GNOT
// per hundred names. One proposal, "DeleteDomain <label>", covers every
// call of a multi-call deletion while it stays matured, and is spent by
// the call that finishes; recovery can cancel it between calls.
func DeleteDomain(cur realm, label string) (removed int64, done bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "DeleteDomain", "label", label)
	id := actionID("DeleteDomain", label)
	assertActionReady(id)
	removed, done = nsdata.DeleteDomainRecord(cross(cur), label)
	if done {
		nsdata.ConsumeAction(cross(cur), id)
	}
	return removed, done
}

// SetDomainTTL sets how long a resolver may cache answers about this
// domain, in seconds, where 0 means never cache — the ENS rule. Admin
// only, since domains are project-owned.
func SetDomainTTL(cur realm, label string, seconds int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainTTL", "label", label, "seconds", fmtInt(seconds))
	if seconds < 0 || seconds > maxTTL {
		panic("nslogic: a ttl is 0.." + fmtInt(maxTTL) + " seconds")
	}
	if err := nsdata.SetDomainTTLRecord(cross(cur), label, seconds); err != nil {
		panic(err)
	}
}

func FreezeDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "FreezeDomain", "label", label)
	nsdata.SetDomainFrozen(cross(cur), label, true)
}

func UnfreezeDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "UnfreezeDomain", "label", label)
	nsdata.SetDomainFrozen(cross(cur), label, false)
}

package nslogic

import (
	"strconv"

	"chain"
)

/*
EVERY ADMIN ACTION EMITS AdminAction, with the signer and the call.

There was no event anywhere in this realm, so a stolen admin key's
treasury change, rate change or deletion was invisible until its effects
showed up somewhere else (audit M-4/M-6). The vault now says what changed
(nsdata/events.gno); this says who asked, through which call, with which
arguments — the line a monitor alerts on. A failed call emits nothing:
an aborted transaction keeps no events.

One event type, "AdminAction", with "fn" naming the call, so a monitor
subscribes once and a new admin call is covered without anybody updating
a list. Profile values replayed by a restore are not repeated here, only
their keys, for the reason given in nsdata/events.gno.
*/
func emitAdmin(cur realm, fn string, kv ...string) {
	attrs := []string{"fn", fn, "by", cur.Previous().Address().String()}
	chain.Emit("AdminAction", append(attrs, kv...)...)
}

func fmtInt(n int64) string { return strconv.FormatInt(n, 10) }

func fmtI(n int) string { return strconv.Itoa(n) }

func fmtBool(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

package nslogic

import (
	"strconv"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
	"gno.land/r/nym-mnsrehearsal001/nsreserve/v3"
)

/*
READ THIS FIRST (2026-11-12). What follows describes the FIRST free tier:
a record with no token, granted per name by the project, which paid for it.
Two things have changed since, and the text below is kept for its reasoning,
not as a description of the code:

  - since the second generation every name is a token; a free one carries
    the free HOLD (no transfer, no approval, no listing) until
    UpgradeFreeName lifts it (audit I-5);

  - for the free launch, free names are RESERVATIONS minted by their
    holders (reserve.gno, realm nsreserve). GrantFreeName, GrantFreeRenewal
    and RegisterFor in this file and credits.gno are CLOSED behind
    SetLegacyGrants, and UpgradeFreeName waits for paid registration to
    open. The granter key only writes reservations.

THE FREE TIER: a name somebody can hold without ever owning a wallet.

The vault has supported this since it was written — RegisterNameRecord
takes mintNFT=false and stores a record with no GRC-721 token, and
UpgradeFreeRecord is described there as "the paid free-tier upgrade".
Nothing in the logic realm ever reached either. This is that wiring.

WHY A RECORD WITHOUT A TOKEN IS THE RIGHT SHAPE, and not a compromise:

	IT IS A REAL NAME. Owned, resolvable, renewable, on chain, visible
	to anyone. Not a promise, not a queue position, not a row in our
	database. Everything the paid tier does except be sold.

	IT CANNOT BE SOLD, and that is what makes giving it away safe.
	nsmarket escrows a TOKEN, and there is no token — so a squatter who
	farms a thousand of these has farmed a thousand things nobody can
	buy from them. The anti-abuse property falls out of the data model
	rather than out of a rule somebody has to enforce.

	IT BECOMES SELLABLE BY BECOMING PAID. UpgradeFreeName takes the full
	list price and mints the token. So the same name costs nothing and
	costs full price, and which one depends entirely on whether you want
	to sell it.

WHY THE PROJECT PAYS. The whole point is somebody with no GNOT, and
possibly no wallet, who is going to put this name in front of an
audience. Measured on Pearl: a registration is about 0.04 GNOT of fee
plus a small storage deposit, and a free-tier record is smaller than a
paid one because there is no token and no ledger entry. That is a
marketing cost per name, bounded by a daily cap we apply off chain,
where it can be changed without a deploy.

WHAT IS DELIBERATELY NOT HERE. No wordlist: storage is 100 ugnot a byte,
so a ten-thousand-word dictionary is about 57 GNOT paid forever to
encode a marketing decision that will change. The contract carries the
structural rules in reserved.gno and nothing else; the lists live off
chain with the issuer, which is us, because the free path is granted
rather than bought. See tools/gen-reserved.py.
*/

const (
	keyFreeDomain = "free"     // per-domain: "1" means the free tier is open here
	keyGrantEnd   = "grantend" // global: unix seconds, or "never"
	keyGranter    = "granter"  // global: the address allowed to issue grants
)

/*
THE GRANTER IS NOT THE ADMIN, and that separation is the point.

Free names are issued by a machine — something has to sign the grant
after a person proves an X account, and that key has to sit somewhere
warm. If that key were the admin key, a compromise of the issuing
machine would be a compromise of the registry: DeleteDomain destroys
every name under a domain and burns their tokens, instantly, with no
timelock.

So there is a second role that can do exactly one kind of thing: give
names away on the project's behalf — free-tier grants and renewals, and
RegisterFor, which spends a holder's own credit into the holder's own
wallet (credits.gno). Worst case for a stolen granter key is that
somebody gives away free names, or spends people's credits on names they
did not pick, until we notice and clear the role — a bounded, reversible,
embarrassing loss rather than an unbounded one.

Stored in the vault's globals rather than in this realm, so it survives
a logic redeploy. Unset means nobody but the admin may grant, which is
the right default for a role that exists to be delegated deliberately.
*/
func Granter() address {
	return address(nsdata.GetGlobal(keyGranter))
}

// SetGranter delegates grant issuance, or withdraws it. Passing the
// empty address is the revocation, and it is the first thing to reach
// for if the issuing machine is ever in doubt — instant, always.
//
// NAMING a granter is TIMELOCKED (timelock.gno): a stolen admin key would
// otherwise hand itself a second, quieter key that gives names away and
// spends people's credits, and keep it after the admin key is rotated out.
func SetGranter(cur realm, a address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetGranter", "addr", a.String())
	if a != "" && !a.IsValid() {
		panic("nslogic: not an address")
	}
	if a != "" {
		requireAction(cur, actionID("SetGranter", a.String()))
	}
	setGlobal(cur, keyGranter, a.String())
}

/*
SetFreeLengths tunes which lengths the free tier will issue.

In the panel rather than in a redeploy: nslogic is about 22 GNOT to
deploy, and "should four-character names be free this month" is a
marketing question that should cost a signature, not a deployment.

IT DOES NOT REACH BACKWARDS. Raising the minimum stops NEW issuance of
short names; every one already granted stays granted and keeps renewing
free. FreeLabelAllowed is called by GrantFreeName and by nothing else,
which is what makes that true — see the note on it in reserved.gno.
*/
func SetFreeLengths(cur realm, min, max int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetFreeLengths", "min", fmtI(min), "max", fmtI(max))
	if min < 1 || max > 63 || min > max {
		panic("nslogic: a free-tier length range must sit inside 1..63 and be the right way round")
	}
	setGlobal(cur, keyFreeMin, strconv.Itoa(min))
	setGlobal(cur, keyFreeMax, strconv.Itoa(max))
}

func assertMayGrant(cur realm) {
	caller := cur.Previous().Address()
	if caller == nsdata.GetAdmin() {
		return
	}
	g := Granter()
	if g == "" || caller != g {
		panic("nslogic: only the admin or the granter may issue free names")
	}
}

// DomainFree reports whether a domain accepts free-tier registrations.
// Off by default, and per-domain on purpose: the free tier is a
// promotion aimed at a few domains, not a property of the registry.
func DomainFree(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyFreeDomain) == "1"
}

// SetDomainFree opens or closes the free tier for one domain.
func SetDomainFree(cur realm, domainLabel string, on bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetDomainFree", "label", domainLabel, "on", fmtBool(on))
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: no such domain")
	}
	v := ""
	if on {
		v = "1"
	}
	if err := nsdata.SetDomainExtraRecord(cross(cur), domainLabel, keyFreeDomain, v); err != nil {
		panic(err)
	}
}

/*
GrantWindowOpen reports whether free grants are being issued at all.

A single global switch that closes everything at once, because the
failure this guards against is not a clever attack — it is noticing on a
Sunday that something is wrong and wanting one call that stops it. An
unset value means open; "never" means open with no end date, which is
what the admin panel already writes.
*/
func GrantWindowOpen() bool {
	return readGrantWindow(nsdata.GetGlobal(keyGrantEnd), time.Now().Unix())
}

// readGrantWindow is GrantWindowOpen with the clock and the stored value
// handed in, so the reading can be tested without a chain.
func readGrantWindow(v string, now int64) bool {
	if v == "" || v == "never" {
		return true
	}
	end, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		// An unparseable window is a misconfiguration, and the safe
		// reading of a misconfigured gate is "closed". Giving names away
		// because a setting was mistyped is the wrong way to fail.
		return false
	}
	return now < end
}

/*
GrantFreeName registers a free-tier record to somebody else.

ADMIN OR GRANTER, and that is the whole trust model: the eligibility rules —
which Twitter account, how old, how many followers, whether the label is
a dictionary word — live off chain with the issuer. Putting them here
would freeze a marketing policy into a realm and cost storage to do it.
What the chain enforces is the part that must not depend on our
correctness: the label is structurally allowed, the domain opted in, and
the window is open.

`owner` may be an address the recipient generated in their browser
seconds ago and has never funded. That is the point.
*/
func GrantFreeName(cur realm, label, domainLabel string, owner address) {
	assertNoSend(cur)
	assertMayGrant(cur)
	emitAdmin(cur, "GrantFreeName", "label", label, "domain", domainLabel, "owner", owner.String())
	// CLOSED FOR THE FREE LAUNCH (reserve.gno): free names are reservations
	// their holders mint. The door answers only after SetLegacyGrants.
	assertLegacyGrants()
	assertNotRestoring()

	if !GrantWindowOpen() {
		panic("nslogic: free grants are closed")
	}
	// Recovery's quarantine holds every giveaway shut, whatever the window
	// says (nsdata incident.gno, re-audit 2026-10-16, M-2).
	if q := nsdata.QuarantineUntil(); time.Now().Unix() < q {
		panic("nslogic: recovery has quarantined giveaways until unix " + strconv.FormatInt(q, 10))
	}
	if !DomainFree(domainLabel) {
		panic("nslogic: *" + domainLabel + " does not offer free names")
	}
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	validateLabel(label)
	assertNotBlocked(label)
	// The structural backstop. The issuer has already applied the full
	// policy; this is what stops a bug there giving away a four-letter
	// name or a pure-numeric one.
	if !FreeLabelAllowed(label) {
		panic("nslogic: " + label + " is not available on the free tier")
	}
	// The same line the mint holds (audit M-1): no premium name and no name
	// priced above its domain's base is given away, whatever the issuer
	// thought.
	if PremiumFor(label) != "" {
		panic("nslogic: " + label + " is a premium name and is not given away")
	}
	if NamePriceUSD(domainLabel, label) > DomainBasePriceUSD(domainLabel) {
		panic("nslogic: " + label + " is priced above an ordinary name and is not given away")
	}
	assertNotReserved(label, domainLabel)
	if !owner.IsValid() {
		panic("nslogic: a grant needs a recipient")
	}
	// The granter's day is capped here as it is in nsreserve, by the same
	// number (audit M-2).
	countLegacyGrant()
	hadPrimary := nsdata.GetPrimary(owner) != ""

	// paid=false — a token minted with the free-tier hold already on it,
	// so it can never be approved or sold until UpgradeFreeName lifts it.
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, owner,
		time.Now().Unix(), false); err != nil {
		panic(err)
	}
	// No reverse pointer the recipient did not ask for and, having no GNOT,
	// could not remove (audit M-5).
	if !hadPrimary {
		nsdata.ClearPrimaryRecord(cross(cur), owner)
	}
}

// The per-name door's own count of the day, held to nsreserve's cap. Lost
// on a logic swap, which costs one day's count and nothing else.
var (
	legacyDay   int64
	legacyCount int
)

func countLegacyGrant() {
	if d := time.Now().Unix() / 86400; d != legacyDay {
		legacyDay, legacyCount = d, 0
	}
	if legacyCount >= nsreserve.DailyCap() {
		panic("nslogic: today's free names are all given (the daily cap)")
	}
	legacyCount++
}

/*
UpgradeFreeName mints the token for a free-tier record, at full price.

This is the only way a free name becomes sellable, and the price is the
ordinary list price with no referral discount — a discount is for
bringing somebody new, and this person is already here.

`newOwner` exists because the common case is somebody who has decided to
sell and, in the same moment, wants the name in a wallet they actually
control rather than the browser key they were given. The vault handles
that move inside UpgradeFreeRecord.

Callable by the record's current owner only. Anyone may PAY for
somebody else's upgrade in the sense that they can hand over the money,
but they cannot perform it — a stranger promoting your name into a token
and choosing where it lands is a theft with a receipt.
*/
func UpgradeFreeName(cur realm, label, domainLabel string, newOwner address) {
	// Not during a restore window: the price rules may not be back yet, and
	// the name would be made sellable at the genesis price (restore.gno).
	assertNotRestoring()
	// An upgrade is a sale, and it is what makes a free name sellable: it
	// waits for paid registration to open (reserve.gno).
	assertPaidOpen(domainLabel)
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: this name has expired")
	}
	if newOwner == "" {
		newOwner = caller
	}
	if !newOwner.IsValid() {
		panic("nslogic: invalid destination address")
	}

	// Full list price, resolved now rather than at grant time — the
	// name's worth is what it is worth today, and a free name held for a
	// year should not be upgradable at last year's rate.
	takePaymentSplit(cur, NamePrice(domainLabel, label), "", 0)

	if err := nsdata.UpgradeFreeRecord(cross(cur), label, domainLabel, newOwner); err != nil {
		panic(err)
	}
}

/*
GrantFreeRenewal extends a free-tier name at no charge.

THE DEAL IS THE DISPLAY, and it is checked off chain: the issuer signs
somebody in on X, reads their display name, and finds the name in it.
That single act proves both halves at once — that a real account still
exists, and that it is still carrying the name — which is why renewal is
one click a year rather than a form.

FREE-TIER RECORDS ONLY. A paid name renewed for nothing is revenue given
away by accident, and the two are told apart by whether a token was ever
minted — now, whether the token still carries the free-tier hold. The
hold is the registry's flag, read through GetNameInfo's `paid`.

NO OWNERSHIP PROOF IS ASKED FOR, and that is deliberate rather than
missing. Renewing somebody else's name is a GIFT — it takes nothing,
moves nothing, and grants the caller no power over it. The only cost of
allowing it is ours, and the vault's renewal cap already bounds how far
any single name can be pushed. A proof requirement here would buy
nothing and would cost the one-click renewal that makes the deal work.

RenewNameRecord insists the caller is the owner, so the owner is looked
up and passed. That is not a bypass: this realm is the trusted logic,
and what it is asserting is exactly true — this renewal is on that
owner's behalf.
*/
func GrantFreeRenewal(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertMayGrant(cur)
	emitAdmin(cur, "GrantFreeRenewal", "label", label, "domain", domainLabel)
	// Closed with the grant door: a renewal bound to nobody let the granter
	// key push any free name forward (verify N-2). RenewFree, on a voucher, replaces it.
	assertLegacyGrants()
	// A free renewal is a giveaway too: not during a restore window, and not
	// while recovery's quarantine holds (review follow-up).
	assertNotRestoring()
	if q := nsdata.QuarantineUntil(); time.Now().Unix() < q {
		panic("nslogic: recovery has quarantined giveaways until unix " + strconv.FormatInt(q, 10))
	}

	if !nsdata.NameExists(label, domainLabel) {
		panic("nslogic: no such name")
	}
	owner, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel)
	if paid {
		panic("nslogic: " + label + "*" + domainLabel +
			" is a paid name — free renewal is for free-tier records")
	}
	if RenewalsLeft(label, domainLabel) <= 0 {
		panic("nslogic: this name is already paid as far ahead as a name may run")
	}
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, owner,
		time.Now().Unix()); err != nil {
		panic(err)
	}
}

// IsFreeTier reports whether a name is a record without a token — the
// free tier. Exported because the site and the issuer both need to ask
// before offering a free renewal, and neither should infer it.
func IsFreeTier(label, domainLabel string) bool {
	if !nsdata.NameExists(label, domainLabel) {
		return false
	}
	_, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel)
	return !paid
}

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// Answering "what does this address hold" in ONE read.
//
// The site used to ask the chain for every name in the REGISTRY and then
// throw away the ones that did not match — one HTTP round trip per name
// in the world to draw one person's collection. Six names took three
// seconds, and it gets linearly worse for everybody every time anybody
// else registers anything.
//
// The scan itself is unavoidable: nsdata keys names by domain*label and
// has no index by owner, and nsdata is the permanent vault so no index
// can be added to it now. But the scan does not have to happen across
// the network. nslogic is swappable and can walk the same records inside
// a single query, which turns N round trips into one.
//
// Nothing is cached and nothing is trusted from the caller: every row is
// read from the vault at the moment of the query, exactly as before.
//
// Paged, because a query has a gas ceiling of its own and a registry
// with fifty thousand names in it must not become one enormous read that
// nobody can complete. `after` is the vault's own cursor, so paging here
// is the same paging ExportNames already does.
const maxHoldingsPage = 200

// NamesOwnedBy returns rows of `label*domain,registered,expires,streak,frozen`
// separated by ";", plus the cursor to continue from. Labels are
// restricted to [a-z0-9-] so neither separator can appear inside a field.
//
// `next` is empty when the scan has reached the end of the registry. It
// is NOT empty merely because this page found no matches: a page of two
// hundred names belonging to other people returns no rows and a cursor,
// and the caller keeps going.
func NamesOwnedBy(owner address, after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	var b strings.Builder
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		// The tree key is domain*label; the token ID is label*domain.
		at := strings.Index(key, "*")
		if at < 0 {
			continue
		}
		domainLabel, label := key[:at], key[at+1:]

		o, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
		if o != owner {
			continue
		}
		if b.Len() > 0 {
			b.WriteString(";")
		}
		b.WriteString(ufmt.Sprintf("%s*%s,%d,%d,%d,%t",
			label, domainLabel, registered, expires, streak, frozen))
	}
	return b.String(), nxt
}

// CountNamesOwnedBy is the same walk without the strings, for a header
// that wants a number before the list has finished arriving.
func CountNamesOwnedBy(owner address, after string, limit int) (n int, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		at := strings.Index(key, "*")
		if at < 0 {
			continue
		}
		if nsdata.GetNameOwner(key[at+1:], key[:at]) == owner {
			n++
		}
	}
	return n, nxt
}

// Everything the profile page draws, in ONE read.
//
// It was making seventeen queries: three to establish that the name
// exists and when it expires, then fourteen more — one per extension
// slot — that could not start until the first three had come back. Two
// waves, and the node serves only a few at a time, so a profile took
// seconds to assemble out of values that all live in the same record.
//
// Values come back in the ORDER THE KEYS WERE ASKED FOR rather than as
// key=value pairs. An extension key is allowed to contain "=" (only
// commas and newlines are forbidden), so a pair encoding would have an
// ambiguous split; positional has none.
//
// Line 0 is the record: owner, registered, expires, streak, frozen, and
// the grace period, which is global but is one more query the page would
// otherwise have to make on its own.
//
// An empty return means the name is not registered. That is a real
// answer rather than an error: asking about a name nobody owns is the
// normal case on a profile URL somebody typed.
func ProfileOf(label, domainLabel, keys string) string {
	if !nsdata.NameExists(label, domainLabel) {
		return ""
	}
	owner, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("%s,%d,%d,%d,%t,%d",
		owner.String(), registered, expires, streak, frozen, nsdata.GetGracePeriod()))

	for _, k := range strings.Split(keys, ",") {
		b.WriteString("\n")
		if k == "" {
			continue
		}
		v := nsdata.GetNameExtra(label, domainLabel, k)

		// THE GNO.LAND ADDRESS ANSWERS EVEN WHEN NOBODY SAVED ONE.
		//
		// A name is an NFT held by an address, so the owner is already
		// public — it is the first field of the record above. Returning
		// it here as well costs no storage and means a name can be paid
		// without its holder ever having opened a profile editor, which
		// is most of them, and without a transaction to back-fill the
		// ones registered before this existed.
		//
		// Doing it in the realm rather than in the website is the whole
		// point: any client asking this realm for the gno key gets the
		// same answer our pages do. A front end that derived it locally
		// would leave every other reader with nothing.
		//
		// "off" is the opt-out, and it has to be a sentinel. An empty
		// value is indistinguishable from never having set one, so an
		// empty gno field would simply hand the derived address back on
		// the next read.
		if k == "gno" {
			if v == "off" {
				v = ""
			} else if v == "" {
				v = owner.String()
			}
		}
		b.WriteString(escapeValue(v))
	}
	return b.String()
}

// Extension VALUES are free text — a bio can hold anything a person can
// type, newlines included — so they cannot be newline-separated raw.
// Escaping is done here rather than stripping, because silently eating a
// line break out of somebody's bio is data loss on a read path.
func escapeValue(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, "\n", `\n`)
	return strings.ReplaceAll(s, "\r", `\r`)
}

// RecentNames answers "what has just been registered" in one read.
//
// The site used to build this by listing every key and then reading each
// record one at a time — the same shape NamesOwnedBy replaced for a
// wallet's holdings, and the same problem: fine at thirteen names, one
// query per name forever after. A feed that gets slower every time
// somebody registers is a feed that eventually stops loading on the busy
// day you most wanted it.
//
// Returns rows of "label*domain,registered,expires,owner", newest first,
// and a cursor. Sorting happens across a PAGE, not the whole registry:
// the vault stores names alphabetically and there is no index by date,
// so a caller that wants the true newest reads every page and merges.
// That is one query per 200 names instead of one per name — enough of a
// difference to stop mattering, without pretending the vault has an
// index it does not have.
func RecentNames(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	type row struct {
		text string
		at   int64
	}
	var found []row
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		// The tree key is domain*label; the token ID is label*domain.
		at := strings.Index(key, "*")
		if at < 1 {
			continue
		}
		domainLabel, label := key[:at], key[at+1:]
		owner, registered, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
		found = append(found, row{
			text: ufmt.Sprintf("%s*%s,%d,%d,%s", label, domainLabel, registered, expires, owner.String()),
			at:   registered,
		})
	}

	// Insertion sort, newest first. The page is at most 200 entries and
	// gno has no sort in scope here; anything cleverer would be more code
	// than the problem deserves.
	for i := 1; i < len(found); i++ {
		v := found[i]
		j := i - 1
		for j >= 0 && found[j].at < v.at {
			found[j+1] = found[j]
			j--
		}
		found[j+1] = v
	}

	var b strings.Builder
	for _, r := range found {
		if b.Len() > 0 {
			b.WriteString(";")
		}
		b.WriteString(r.text)
	}
	return b.String(), nxt
}

package nslogic

import (
	"chain"
	"strconv"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

/*
THE KEEPER: a hot key that moves the GNOT/USD rate and nothing else
(Ely, 2026-10-16).

WHY A ROLE. The rate is MANUAL (pricing.gno, SetUsdRate): it sits where it
was last written, and a stale rate during a sharp move sells names at the
wrong price. Keeping it current is a job for a bot, and a bot lives on a
server. The admin key must not, so the bot gets a key of its own that can
do exactly one thing.

WHAT IT CAN DO. Call SetUsdRate inside the bounds every instant change
obeys (timelock.gno): a higher rate — GNOT fell — up to four times at once,
every ten minutes, so a crash is followed at once; a lower rate — the
direction that sells names cheap — at most 25%, once an hour. The clocks
are the SAME ones the admin's instant moves use, so the two keys together
still cheapen names one step an hour. Never through the timelock: a
matured proposal belongs to the admin, and the keeper's call refuses an
out-of-bound value even while one is waiting. Every other function refuses
it, because every other function asks for the admin; the admin keeps
SetUsdRate as before.

WHAT ITS THEFT COSTS. Names a quarter cheaper each hour, in public — each
move emits KeeperAction — until the admin, recovery or the guardian calls
ClearKeeper, which is instant; or names made too dear to buy, an outage.
Bounded in size, in rate and in time, and it never touches a name or a
coin directly.

NAMED THROUGH THE TIMELOCK, CLEARED AT ONCE. SetKeeper waits out the vault's
action delay ("SetKeeper <addr>" through nsdata.ProposeAction), like naming
a granter: otherwise a stolen admin key installs a second key that survives
its own rotation. Clearing is the safe direction and is open to all three
governance roles. An admin rotation does not clear the keeper by itself;
the incident runbook does (MAINNET.md §1b).

NEVER THE ADMIN, NEVER RECOVERY. A keeper on the admin's address adds
nothing, and one on recovery's puts the cold key's address on a server.
Both are refused when it is named, and recovery is refused again at call
time, in case a later rotation moved recovery onto the keeper's address.

Stored in the vault's globals like the granter, so a logic swap keeps it,
and listed in managedGlobal, so SetGlobal cannot write round the timelock.
*/

const keyKeeper = "keeper" // global: the address that may move the rate

// Keeper is the address allowed to move the rate, or "" for none.
func Keeper() address { return address(nsdata.GetGlobal(keyKeeper)) }

// SetKeeper names the keeper. Admin only, and TIMELOCKED: propose exactly
// "SetKeeper <addr>" with nsdata.ProposeAction, then call once it matures.
// ClearKeeper removes the role.
func SetKeeper(cur realm, a address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetKeeper", "addr", a.String())
	if !a.IsValid() {
		panic("nslogic: not an address; ClearKeeper removes the keeper")
	}
	if a == nsdata.GetAdmin() || a == nsdata.GetRecovery() {
		panic("nslogic: the keeper is a key of its own, never the admin or the recovery key")
	}
	requireAction(cur, actionID("SetKeeper", a.String()))
	setGlobal(cur, keyKeeper, a.String())
}

// ClearKeeper removes the keeper at once. Admin, recovery or guardian —
// the guardian bot's answer to a KeeperAction it did not expect. Clearing
// when there is no keeper does nothing and still succeeds, so a bot may
// call it without reading first.
func ClearKeeper(cur realm) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if !isGovernor(caller) {
		panic("nslogic: only the admin, recovery or the guardian may clear the keeper")
	}
	chain.Emit("KeeperCleared", "keeper", Keeper().String(), "by", caller.String())
	setGlobal(cur, keyKeeper, "")
}

// isGovernor is the vault's three roles, read fresh. An unset role matches
// nobody.
func isGovernor(a address) bool {
	if a == "" {
		return false
	}
	return a == nsdata.GetAdmin() || a == nsdata.GetRecovery() || a == nsdata.GetGuardian()
}

// assertIsKeeper lets the keeper through and nobody else, with the refusal
// a stranger has always had from an admin call.
func assertIsKeeper(caller address) {
	k := Keeper()
	if k == "" || caller != k {
		panic("nslogic: restricted to project admin")
	}
	if k == nsdata.GetRecovery() {
		panic("nslogic: the keeper's address is now the recovery key's; name a new keeper")
	}
}

/*
keeperSetRate is SetUsdRate for the keeper: the same range check, the
bound and the shared hourly slot, and no door into the timelock. Every
move emits KeeperAction, with the value it replaced.
*/
func keeperSetRate(cur realm, ugnotPerUsd int64) {
	caller := cur.Previous().Address()
	assertIsKeeper(caller)
	old := RateUgnotPerUsd()
	chain.Emit("KeeperAction", "fn", "SetUsdRate", "by", caller.String(),
		"ugnotPerUsd", fmtInt(ugnotPerUsd), "was", fmtInt(old))
	if ugnotPerUsd <= 0 || ugnotPerUsd > maxRate {
		panic("nslogic: a rate is 1.." + strconv.FormatInt(maxRate, 10) + " ugnot per USD")
	}
	keeperStep(keyRate, old, ugnotPerUsd)
	setGlobal(cur, keyRate, strconv.FormatInt(ugnotPerUsd, 10))
}

// keeperStep is authorizeTweak with the timelock door bricked up: an
// instant step inside its direction's bound, after that direction's rest,
// or a refusal. It writes the same clocks, so the admin's next instant
// move in that direction waits the same time.
func keeperStep(setting string, old, next int64) {
	if next == old {
		return
	}
	dearer := next > old // the rate: higher means names cost more GNOT
	if !withinStep(old, next, dearer) {
		panic("nslogic: for the keeper, " + stepRefusal(setting, old, next, dearer) +
			"; a larger move is the admin's, through the vault timelock")
	}
	now := time.Now().Unix()
	if !clockRested(setting, dearer, now) {
		panic("nslogic: " + restRefusal(setting, dearer) + "; the keeper waits for the next step")
	}
	lastTweak.Set(clockKey(setting, dearer), now)
}

package nslogic

import (
	"chain"
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// Profile field names inside a name's extension slot. The vault stores
// them as opaque strings and bounds their size; what they MEAN is this
// realm's convention, so new profile fields need no vault change.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
	keyAvatar      = "avatar"
)

// RegisterName mints `label*domain` under an existing domain. Anyone may
// call this. Minting still works while the parent domain is past its own
// due date, as long as its grace period hasn't fully lapsed and it isn't
// frozen — nsdata's RegisterNameRecord enforces that.
func RegisterName(cur realm, label, domainLabel string) {
	registerName(cur, label, domainLabel, "")
}

// RegisterNameRef is RegisterName with a referral code — the NAME of
// whoever sent the buyer here, as it appears in the link.
//
// It is a second entry point rather than a third argument on the first
// one because the first one is already deployed and already being called
// by wallets and by the site. Changing its arity would break every one
// of those callers at the same instant, which is exactly the failure the
// voting realm produced last time; adding a function breaks nothing and
// lets the front end pick whichever the deployed realm actually has.
//
// A code that does not earn — misspelt, lapsed, the buyer's own name, a
// free-tier name, or one not yet held for thirty days (referral.gno) — is
// IGNORED, not rejected. The registration goes through at list price.
// Refusing to sell somebody a name because they mistyped somebody else's
// would be an absurd way to lose a sale.
func RegisterNameRef(cur realm, label, domainLabel, refName string) {
	registerName(cur, label, domainLabel, refName)
}

func registerName(cur realm, label, domainLabel, refName string) {
	assertNotRestoring()
	// PAID REGISTRATION IS CLOSED until the admin opens it behind the
	// timelock, on every domain (reserve.gno). And a label somebody has
	// reserved is theirs to mint, nobody's to buy.
	assertPaidOpen(domainLabel)
	validateLabel(label)
	assertNotBlocked(label)
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	assertNotReserved(label, domainLabel)
	caller := cur.Previous().Address()

	// Resolved BEFORE anything is written, so the code is judged in the
	// world the buyer was quoted in.
	ref := resolveReferrer(refName, caller)
	price := NamePrice(domainLabel, label)
	if ref != "" {
		if _, pct := RefRates(); pct > 0 {
			price -= price * pct / 100
		}
	}
	payTo, cut := referralCut(ref, price)
	takePaymentSplit(cur, price, payTo, cut)

	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, caller, time.Now().Unix(), true); err != nil {
		panic(err)
	}

	// Written after the record exists, because the extension slot is
	// created by registration. Only recorded when the cut was actually
	// paid: the record says who brought this buyer, and a referrer who
	// earned nothing did not.
	if ref != "" && cut > 0 {
		setExtra(cur, label, domainLabel, keyRef, ref.String())
		creditReferral(cur, ref)
		// Money left the treasury's share: say so, so a monitor can add up
		// what referral rules are costing without reading every tx.
		chain.Emit("ReferralPaid", "tid", label+"*"+domainLabel, "referrer", ref.String(),
			"amount", fmtInt(cut), "price", fmtInt(price))
	}
}

// RenewName — same anchoring rule as RenewDomain: extends from the
// previous due date, not from the payment date. Deliberately does not
// call validateLabel — an already-registered name must keep renewing
// under whatever pattern was in force when it was minted.
func RenewName(cur realm, label, domainLabel string) {
	// Not while a restore window is open: the prices may not be back yet
	// (restore.gno, assertNotRestoring; review follow-up).
	assertNotRestoring()
	// FIRST YEAR ONLY (referral.gno): a renewal pays the full price, all
	// of it to the treasury, and nobody's cut. Renewals used to pay the
	// referrer for as long as the name survived, which made a second
	// wallet's code a permanent discount on its owner's own renewals.
	assertRoomToRenew(label, domainLabel)
	// A year SOLD to a free-tier holder is a sale, so it waits for paid
	// registration to open; a free name renews with RenewFree. A paid
	// name renews whatever the switch says: closing the shop must not let
	// what was already bought lapse.
	if IsFreeTier(label, domainLabel) {
		assertPaidOpen(domainLabel)
	}
	takePayment(cur, NamePrice(domainLabel, label))

	caller := cur.Previous().Address()
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// SetProfile writes the four conventional profile fields. Each lands in
// the name's extension slot, where the vault enforces size bounds.
func SetProfile(cur realm, label, domainLabel, displayName, bio, website, avatar string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	setExtra(cur, label, domainLabel, keyDisplayName, displayName)
	setExtra(cur, label, domainLabel, keyBio, bio)
	setExtra(cur, label, domainLabel, keyWebsite, website)
	setExtra(cur, label, domainLabel, keyAvatar, avatar)
}

// SetNameField writes a single arbitrary key — cross-chain addresses and
// anything else a future feature needs, with no vault change required.
// Keys used by this realm's own machinery are reserved.
func SetNameField(cur realm, label, domainLabel, key, value string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	// `ref` decides who gets paid out of every renewal of this name. A
	// holder who could write it would set it to an address they control
	// and take a permanent cut of their own renewals out of the
	// treasury — so the one key that moves money is the one key its
	// owner may not touch.
	if key == keyRef {
		panic("nslogic: '" + keyRef + "' is set at registration and cannot be edited")
	}
	setExtra(cur, label, domainLabel, key, value)
}

func setExtra(cur realm, label, domainLabel, key, value string) {
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic(err)
	}
}

func assertNameOwner(cur realm, label, domainLabel string) {
	if nsdata.GetNameOwner(label, domainLabel) != cur.Previous().Address() {
		panic("nslogic: restricted to name owner")
	}
}

// SetPrimaryName lets a wallet explicitly choose (and later change) which
// of its names is used for reverse resolution.
func SetPrimaryName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if err := nsdata.SetPrimaryRecord(cross(cur), caller, label, domainLabel); err != nil {
		panic(err)
	}
}

/*
ClearPrimaryName switches reverse resolution OFF for the caller.

WHY THIS HAS TO EXIST, and it is a hole rather than a feature request.

nsdata sets the reverse pointer AUTOMATICALLY on a wallet's first
registration — RegisterNameRecord does it, and nothing asked the person
first. From that moment their address answers with their name, so anybody
who sees that address anywhere can find the persona attached to it, and
every transaction it has ever made becomes attributable. Retroactively:
the chain is permanent and indexers keep copies.

And until now there was NO WAY OUT. ClearPrimaryRecord is gated to
trusted logic, and no logic realm exposed it, so the one person the
pointer is about could not remove it. A name service is a bridge between
a persona and a wallet; publishing that bridge without consent and
without an exit is the worst version of it.

This is the exit. It takes no arguments on purpose: a wallet has exactly
one reverse pointer, and the only address it can clear is its own, so
there is nothing to pass and nothing to get wrong.

WHAT IT DOES NOT DO, said plainly because a promise we cannot keep would
be worse than the hole: clearing stops FUTURE lookups. It does not
unpublish what was already visible, and it cannot — the history is on
chain and other people have copies. The honest sequence is to choose
before publishing, which is why the site now shows what the link exposes
before it offers to make it.
*/
func ClearPrimaryName(cur realm) {
	assertNoSend(cur)
	nsdata.ClearPrimaryRecord(cross(cur), cur.Previous().Address())
}

// maxTTL caps a cache policy, a name's or a domain's: 2^31-1 seconds,
// about 68 years, the ceiling DNS itself uses (RFC 2181). Anything longer
// reads as forever to every resolver, and an unbounded value did not
// survive a snapshot (restore.gno, ttlSecs).
const maxTTL = int64(1<<31 - 1)

// SetNameTTL is the owner's cache policy for their own name, in
// seconds, where 0 MEANS NEVER CACHE — copied from the ENS registry so
// integrators need not read anything of ours to handle it.
//
// The owner sets it rather than the registry because only they know the
// risk: a name being used to receive payments wants 0, since a cached
// answer after a sale pays the previous owner; a name used as a display
// handle can safely be cached for a long time. At most maxTTL.
func SetNameTTL(cur realm, label, domainLabel string, seconds int64) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if seconds < 0 || seconds > maxTTL {
		panic("nslogic: a ttl is 0.." + fmtInt(maxTTL) + " seconds")
	}
	if err := nsdata.SetNameTTLRecord(cross(cur), label, domainLabel, seconds); err != nil {
		panic(err)
	}
}

func FreezeName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "FreezeName", "label", label, "domain", domainLabel)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
}

// UnfreezeName is TIMELOCKED (timelock.gno); freezing stays instant. A
// freeze is the takedown and dispute lever — a disputed or stolen name is
// held while it is sorted out — so releasing one instantly would let a
// stolen admin key free a name and move it in the same transaction.
func UnfreezeName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "UnfreezeName", "label", label, "domain", domainLabel)
	requireAction(cur, actionID("UnfreezeName", label, domainLabel))
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, false)
}

// UnfreezeNames releases several names behind ONE timelocked action:
// propose exactly "UnfreezeNames a*meme,b*doge,…" (token ids, comma-
// separated, at most maxUnfreezeBatch). A stolen key freezes names one call
// each and instantly, about a thousand a block; releasing them one action
// each, with at most 32 actions pending, took ⌈N/32⌉ timelocks (re-audit
// 2026-10-16, L-3). One unknown or malformed name refuses the whole call.
const maxUnfreezeBatch = 64

func UnfreezeNames(cur realm, tids string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "UnfreezeNames", "tids", tids)
	list := strings.Split(tids, ",")
	if tids == "" || len(list) > maxUnfreezeBatch {
		panic("nslogic: 1.." + fmtI(maxUnfreezeBatch) + " token ids, comma-separated")
	}
	type ref struct{ label, domain string }
	refs := make([]ref, 0, len(list))
	for _, tid := range list {
		label, domainLabel := splitTokenID(tid)
		if label == "" || domainLabel == "" || !nsdata.NameExists(label, domainLabel) {
			panic("nslogic: not a registered name: " + tid)
		}
		refs = append(refs, ref{label, domainLabel})
	}
	requireAction(cur, actionID("UnfreezeNames", tids))
	for _, r := range refs {
		nsdata.SetNameFrozen(cross(cur), r.label, r.domain, false)
	}
}

// -- resolution --

func ResolveName(label, domainLabel string) address {
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: name is expired")
	}
	return nsdata.GetNameOwner(label, domainLabel)
}

// ResolveAddress performs reverse resolution: address -> name.
//
// It must verify the ownership it is asserting, not merely that the
// pointed-at name exists and is unexpired. nsdata's `primary` tree is a
// record of what an address last SELECTED, not proof of what it still
// owns — and although nsdata now clears the pointer on transfer and
// reclaim, this check is the half that lives in the swappable realm and
// therefore stays correct even against pointers written by an older
// version of the logic. Without it, an address that sold or lost a name
// kept reverse-resolving to it, impersonating the new owner.
func ResolveAddress(addr address) string {
	tid := nsdata.GetPrimary(addr)
	if tid == "" {
		return ""
	}
	label, domainLabel := splitTokenID(tid)
	if !nsdata.IsNameValid(label, domainLabel) {
		return ""
	}
	if nsdata.GetNameOwner(label, domainLabel) != addr {
		return ""
	}
	return tid
}

// splitTokenID splits a `label*domain` token ID.
func splitTokenID(tid string) (label, domainLabel string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

package nslogic

import (
	"strings"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// This realm only exposes the WRITE side of the GRC-721 surface. Reads
// (BalanceOf, OwnerOf, TokenURI, GetApproved, IsApprovedForAll, and
// every listing/status/profile query) have no authorization check to
// perform and are served directly by nsdata — no reason to duplicate
// them here.

func isDomainToken(tid string) bool {
	return strings.HasPrefix(tid, "*")
}

// isTokenValid checks the underlying domain/name's expiry via nsdata's
// own validity reads — the anti-scam pattern (an expired name must not
// be sellable) enforced at the transfer boundary, not just at read time.
func isTokenValid(tid string) bool {
	if isDomainToken(tid) {
		return nsdata.IsDomainValid(tid[1:])
	}
	label, domainLabel := splitTokenID(tid)
	return nsdata.IsNameValid(label, domainLabel)
}

// assertNotFrozen is the check that made freezing mean something.
//
// FreezeName set a bit that only ever gated RE-REGISTRATION after a
// lapse. Transfer, approval, listing and sale all ignored it, so the one
// manual lever the takedown process relies on did nothing about the case
// it exists for: a disputed or stolen name could be approved to a fresh
// wallet, listed and sold while the interface showed it as frozen.
//
// The bit was already stored and already readable — GetNameInfo returns
// it — so this needs no change to the permanent vault, only the read
// that was never performed.
func assertNotFrozen(tid string) {
	label, domainLabel := splitTokenID(tid)
	_, _, _, _, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
	if frozen {
		panic("nslogic: this name is frozen and cannot be transferred or approved")
	}
}

/*
THERE ARE NO TRANSFER OR APPROVAL FUNCTIONS HERE ANY MORE.

Approve, SetApprovalForAll, TransferFrom and SafeTransferFrom lived in this
realm, and they could only work while this realm was the one place a
transfer could happen. In this generation ownership is in nsnft, and nsnft
sees whoever calls it as the caller — so a logic realm calling in on a
user's behalf would be refused as not approved, correctly. A logic realm
that COULD move people's tokens would be a logic realm that could steal
them.

So: holders approve and transfer on nsnft directly, and marketplaces —
ours included — settle as approved operators there.

The two policies these wrappers enforced moved to where they bind every
path, not just ours:
  - frozen names: a hold bit on the token in nsnft (nsdata.SetNameFrozen)
  - free-tier names: a hold bit set at mint (nsdata.RegisterNameRecord)
Expired names are refused by our marketplace and never resolve; an
external marketplace can move an expired token, as with any NFT. See
MIGRATION.md, second attempt, rule 6.

The helpers above stay because the marketplace-facing reads use them.
*/

package nslogic

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// takePayment verifies the attached send-envelope covers `price` ugnot,
// forwards the price to the treasury, and refunds any overpayment to the
// caller in the same transaction. Nothing is ever retained: every ugnot
// that arrives leaves again, as either payment or refund.
//
// It used to take a `beneficiary` and split the price fee/remainder,
// routing the remainder to treasury only while `beneficiary == admin`.
// That comparison was a proxy for "is this a project-owned domain", and
// it silently broke the moment `admin` rotated — the planned EOA-to-
// multisig step — because a domain's owner is frozen into its record at
// registration time. After a rotation, every registration's remainder
// would have been paid to the retired key instead of the treasury, with
// no error and no log line.
//
// The heuristic is gone rather than patched. Domains are admin-only to
// create and permanently non-transferable, so every domain is
// project-owned by construction and 100% of every payment belongs to the
// treasury. `platformFeeBps` stays in nsdata's config for a future logic
// realm that reintroduces third-party domain ownership; reinstating the
// split is then a logic-realm swap, not a migration.
func takePayment(cur realm, price int64) {
	takePaymentSplit(cur, price, "", 0)
}

// takePaymentSplit is takePayment with a referrer's cut carved out of the
// same price. The buyer pays exactly what they were quoted; the cut is
// not added on top, it is a share of what the treasury would otherwise
// have received.
//
// All three legs settle inside the buyer's own transaction — treasury,
// referrer, refund — so this realm's balance is the same after the call
// as before it. That is not a stylistic preference: holding a referrer's
// cut until they claim it would make this an account you can have a
// balance in, and that is a different kind of thing to operate, subject
// to a different set of rules, run by people with licences. The cut is
// paid now or it is not paid.
func takePaymentSplit(cur realm, price int64, cutTo address, cut int64) {
	if !cur.Previous().IsUserCall() {
		panic("nslogic: only direct wallet calls may attach payment")
	}
	caller := cur.Previous().Address()
	sent := unsafe.OriginSend()
	assertOnlyUgnot(sent)

	paid := sent.AmountOf(ugnot)
	if paid < price {
		panic(ufmt.Sprintf("nslogic: insufficient payment: need %d ugnot, got %d", price, paid))
	}
	excess := paid - price

	// Belt and braces. referralCut already caps the percentage, but this
	// is the line where the arithmetic becomes money leaving an address,
	// and a bug upstream must not be able to pay out more than came in.
	if cut < 0 || cut > price || cutTo == "" {
		cut = 0
	}

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	pkgAddr := cur.Address()
	if cut > 0 {
		b.SendCoins(pkgAddr, cutTo, chain.Coins{chain.NewCoin(ugnot, cut)})
	}
	if price-cut > 0 {
		b.SendCoins(pkgAddr, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, price-cut)})
	}
	if excess > 0 {
		b.SendCoins(pkgAddr, caller, chain.Coins{chain.NewCoin(ugnot, excess)})
	}
}

// assertOnlyUgnot rejects any other denomination outright. Only the
// ugnot amount was ever accounted for, and neither realm has a
// withdrawal path, so a foreign coin sent alongside a payment would have
// been stranded in this realm's address permanently. Refusing the whole
// transaction is simpler than sweeping it back and keeps the
// "this realm never retains funds" invariant absolute.
func assertOnlyUgnot(sent chain.Coins) {
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nslogic: only ugnot is accepted, got: " + c.Denom)
		}
	}
}

// assertNoSend guards every entry point that has no price. Without it,
// coins attached to a free call (a renewal of a project domain, a
// profile edit, an admin setter) would land in this realm's address with
// no way back out.
//
// IT APPLIES TO DIRECT WALLET CALLS ONLY, and that qualification is not
// a loosening — it is the guard finally matching its own reason.
//
// OriginSend() reports what the TRANSACTION carried, not what this call
// received. Measured on sapphire-1 with a pair of probe realms: a user
// attaches 500000ugnot to realm A, A calls realm B, and B's OriginSend()
// reads 500000ugnot even though every one of those coins is sitting in
// A's address. B never saw them and cannot strand them.
//
// So for a realm-to-realm call this was rejecting a payment this realm
// never received. It is the reason a marketplace could not transfer a
// name inside the same transaction that pays for it — the transfer is a
// free call, the transaction is not, and the two are unrelated. A
// two-transaction sale is the alternative, and that means somebody's
// money or somebody's name sitting somewhere in between. Not here.
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return // the coins went to whoever called us, not to us
	}
	if !unsafe.OriginSend().IsZero() {
		panic("nslogic: this function takes no payment; do not attach coins")
	}
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// Global pricing layers that sit ACROSS every domain rather than inside
// one — see SPEC.md §27.
//
// Two of them, and they work at different points:
//
//	GLOBAL LENGTH RULES are a FLOOR beneath each domain's own length
//	rules, consulted only when the domain has nothing to say about that
//	length. "three-character names cost $5 everywhere" becomes one entry
//	instead of an edit to all twenty-seven domains, and a domain that
//	wants its own answer still overrides it.
//
//	GLOBAL NAME PREMIUMS are an ADJUSTMENT applied after the price has
//	already resolved. Making `og` premium is one entry covering
//	`og*degen`, `og*meme` and every domain invented later. Deliberately
//	not the per-name override, which REPLACES a price outright: "this
//	name costs exactly X here" and "this name is worth more everywhere"
//	are different tools and both are worth having.
//
// Full order, most specific first:
//
//  1. per-name override      (domain "nm")
//  2. per-domain length rule (domain "len")
//  3. global length rule     (global "glen")
//  4. domain base price      (domain "price")
//  5. global default         (global "defaultPrice")
//     then the global name premium modifies the result,
//     then any referral discount comes off what is left.
const (
	keyGlobalLens = "glen"    // global length rules
	keyPremium    = "premium" // premium1, premium2, ... see below

	// The vault caps an extension value at maxExtraValueLen (512 bytes),
	// which is roughly 40-60 premium entries. The list is therefore split
	// across numbered keys rather than pretending one will do; a list
	// that silently truncated at the 512th byte would drop exactly the
	// entries nobody checked.
	maxPremiumKeys = 8
)

// GlobalLengthRule returns the global rule for a label length, if any.
func GlobalLengthRule(n int) (string, bool) {
	return lookupRule(nsdata.GetGlobal(keyGlobalLens), strconv.Itoa(n))
}

// PremiumFor returns the raw modifier for a name across all premium
// keys, or "" when the name is not premium anywhere.
func PremiumFor(label string) string {
	for i := 1; i <= maxPremiumKeys; i++ {
		csv := nsdata.GetGlobal(keyPremium + strconv.Itoa(i))
		if csv == "" {
			continue
		}
		if v, ok := lookupRule(csv, label); ok {
			return v
		}
	}
	return ""
}

// applyPremium adjusts an already-resolved price.
//
// ZERO ALWAYS STAYS ZERO. A fixed "+$2.00" would otherwise silently undo
// a giveaway tier set months earlier, and a free tier that quietly stops
// being free is worse than never having offered one. This is decided
// explicitly rather than inherited from the percentage case happening to
// work out at zero.
//
// Forms: "%5" / "+%5" five percent more · "-%10" ten percent less ·
// "2.00" two dollars more · "-0.25" twenty-five cents less ·
// "=5.00" exactly five dollars, ignoring everything resolved above.
func applyPremium(mod string, price int64) int64 {
	mod = strings.TrimSpace(mod)
	if mod == "" || price <= 0 {
		return price
	}

	// "=X" replaces outright. Checked before the sign handling because
	// an exact price is not a delta and has no direction.
	if strings.HasPrefix(mod, "=") {
		v, ok := parseUSD(mod[1:])
		if !ok || v < 0 {
			return price
		}
		return v
	}

	neg := false
	switch {
	case strings.HasPrefix(mod, "-"):
		neg, mod = true, mod[1:]
	case strings.HasPrefix(mod, "+"):
		mod = mod[1:]
	}

	var delta int64
	if strings.HasPrefix(mod, "%") {
		pct, err := strconv.ParseInt(mod[1:], 10, 64)
		// Out of range reads as malformed (see applyRule): an unbounded
		// percentage would wrap into a wrong price rather than a high one.
		if err != nil || pct < 0 || pct > maxRulePct || price > maxPriceUSD {
			return price
		}
		delta = price * pct / 100
	} else {
		v, ok := parseUSD(mod)
		if !ok || v < 0 {
			return price
		}
		delta = v
	}

	if neg {
		// A discount may take a name to free, but never below it: a
		// negative price would be a payout, and this realm never pays
		// anybody to register.
		if delta >= price {
			return 0
		}
		return price - delta
	}
	return price + delta
}

// parseUSD reads a human dollar figure — "2", "2.5", "2.50", "0.069" —
// into micro-USD. Written by hand rather than with floats: a float would
// make "0.07" cost a different number of micro-dollars depending on the
// platform, and prices must be exact.
func parseUSD(s string) (int64, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, false
	}
	whole, frac := s, ""
	if i := strings.IndexByte(s, '.'); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	if whole == "" {
		whole = "0"
	}
	w, err := strconv.ParseInt(whole, 10, 64)
	// Capped at maxPriceUSD, so w*microUSD below cannot wrap.
	if err != nil || w < 0 || w > maxPriceUSD/microUSD {
		return 0, false
	}
	// Pad or truncate the fraction to exactly six digits of micro-USD.
	if len(frac) > 6 {
		frac = frac[:6]
	}
	for len(frac) < 6 {
		frac += "0"
	}
	var f int64
	if frac != "" {
		f, err = strconv.ParseInt(frac, 10, 64)
		if err != nil || f < 0 {
			return 0, false
		}
	}
	return w*microUSD + f, true
}

// SetGlobalLengthRules writes the project-wide length rules:
// "1:300000000,2:150000000,3:60000000" prices one, two and three
// character names everywhere a domain has not said otherwise.
//
// IT HAD NO SETTER UNTIL NOW, which meant the only way to write it was
// the generic SetGlobal escape hatch — straight past normalizeRules, so
// a typo stored fine and then vanished at lookup time, because
// lookupRule skips a malformed pair in silence. A pricing layer whose
// only writer cannot validate is a pricing layer that fails open.
//
// TIMELOCKED (timelock.gno), like every price rule set: "3:0" here makes
// short names free on every domain that has no rule of its own.
func SetGlobalLengthRules(cur realm, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetGlobalLengthRules", "rules", rules)
	norm := normalizeRules(rules, true)
	requireAction(cur, actionID("SetGlobalLengthRules", norm))
	setGlobal(cur, keyGlobalLens, norm)
}

// SetPremiumNames writes one page of the premium keyword list, 1-based.
// The list is paged because the vault caps an extension value at 512
// bytes; see maxPremiumKeys.
//
// Same gap as above: normalizePremiums existed and nothing exported
// called it.
func SetPremiumNames(cur realm, page int, csv string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetPremiumNames", "page", fmtI(page), "csv", csv)
	if page < 1 || page > maxPremiumKeys {
		panic("nslogic: premium page must be 1-" + strconv.Itoa(maxPremiumKeys))
	}
	v := normalizePremiums(csv)
	if len(v) > 512 {
		panic("nslogic: premium page " + strconv.Itoa(page) +
			" is " + strconv.Itoa(len(v)) + " bytes; the vault caps a value at 512. Split it across pages.")
	}
	// TIMELOCKED: a premium of "=0" or "-%100" makes a name free everywhere.
	requireAction(cur, actionID("SetPremiumNames", strconv.Itoa(page), v))
	setGlobal(cur, keyPremium+strconv.Itoa(page), v)
}

// PremiumNames reads one page back, so the admin panel can show what is
// stored rather than what it last sent.
func PremiumNames(page int) string {
	if page < 1 || page > maxPremiumKeys {
		return ""
	}
	return nsdata.GetGlobal(keyPremium + strconv.Itoa(page))
}

// GlobalLengthRules returns the whole rule string, for the same reason.
func GlobalLengthRules() string { return nsdata.GetGlobal(keyGlobalLens) }

// normalizePremiums validates a premium list before storage. Same
// reasoning as normalizeRules: a malformed entry must never reach the
// vault, because every later lookup would carry it.
func normalizePremiums(csv string) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad premium, want name:modifier — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" || strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in premium — " + k)
		}
		if seen[k] {
			panic("nslogic: duplicate premium name — " + k)
		}
		if !validPremiumValue(v) {
			panic("nslogic: bad premium modifier for " + k + " — " + v)
		}
		seen[k] = true
		out = append(out, k+":"+v)
	}
	return strings.Join(out, ",")
}

func validPremiumValue(v string) bool {
	if v == "" {
		return false
	}
	if strings.HasPrefix(v, "=") {
		_, ok := parseUSD(v[1:])
		return ok
	}
	if strings.HasPrefix(v, "-") || strings.HasPrefix(v, "+") {
		v = v[1:]
	}
	if strings.HasPrefix(v, "%") {
		p, err := strconv.ParseInt(v[1:], 10, 64)
		return err == nil && p >= 0 && p <= maxRulePct
	}
	_, ok := parseUSD(v)
	return ok
}

package nslogic

import (
	"math"
	"strconv"
	"strings"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// Pricing lives here, not in the vault. The vault stores numbers as
// opaque strings and has no opinion about what they mean, so the whole
// model can be replaced by swapping this realm.
//
// PRICES ARE DENOMINATED IN USD, held as MICRO-USD (1 USD = 1_000_000)
// so fractions of a cent are expressible — a name that costs about a
// gumball needs that. Nothing is stored in ugnot: the chain's token is
// just the settlement rail, converted at payment time from a stored
// rate. Accepting a second token later is then only a second rate, not
// a second price list.
//
// PRECEDENCE — most specific wins:
//
//  1. per-name override      (keyNames: "420:5000000,gm:%500")
//  2. per-length rule        (keyLens:  "3:2000000,4:%150,5:0")
//  3. GLOBAL length rule     (global keyGlobalLens — see premium.gno)
//  4. domain base price      (keyPrice: "500000"  = $0.50)
//  5. global default         (global keyDefaultPrice)
//
// then the GLOBAL NAME PREMIUM adjusts the result, and a referral
// discount comes off last. Both live in premium.gno.
//
// A rule value is either an absolute micro-USD amount or "%N", meaning N
// percent of that domain's base — so repricing a domain once carries
// every relative rule under it. "0" means free, which is how giveaway
// tiers are expressed: "all five-character names under *pleb are free"
// is just a length rule resolving to zero.
//
// Rules are stored as CSV in ONE key each rather than one key per rule.
// The vault caps extension keys at 32 bytes and 24 entries per record; a
// key like "nm:somelongname" breaks the first and a few dozen premium
// names break the second. Two CSV keys sidestep both.
const (
	keyPrice        = "price" // domain base, micro-USD
	keyLens         = "len"   // length rules
	keyNames        = "nm"    // per-name overrides
	keyOpen         = "open"  // "0" closes the domain to new names
	keyDefaultPrice = "defaultPrice"
	keyRate         = "rateUgnotPerUsd" // ugnot equal to 1 USD

	microUSD         = int64(1_000_000)
	fallbackPriceUSD = int64(500_000) // $0.50
	// TESTNET PEG: $0.069 per GNOT, so 1 USD = 1/0.069 GNOT = 14.492753
	// GNOT = 14_492_753 ugnot. Deliberately a fixed number while we are on
	// a testnet whose token has no market price at all -- a "real" rate
	// there would be fiction dressed as precision. Replaced with a genuine
	// conversion before mainnet; tracked in MAINNET.md.
	fallbackRate = int64(14_492_753)
	maxRules     = 64

	// The most any single USD price setting may say: one million dollars.
	// Far above any name this registry will list, and low enough that the
	// arithmetic on it stays far from overflow (see NamePrice).
	maxPriceUSD = int64(1_000_000) * microUSD

	// The largest "%N" a price rule or premium may carry: a hundredfold.
	maxRulePct = 10_000
)

// DomainOpen reports whether names may currently be registered under a
// domain. An absent key means open — a domain created before this
// existed must not silently close.
func DomainOpen(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyOpen) != "0"
}

// -- USD side --

func DefaultPriceUSD() int64 {
	if v := nsdata.GetGlobal(keyDefaultPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return fallbackPriceUSD
}

func DomainBasePriceUSD(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return DefaultPriceUSD()
}

// NamePriceUSD resolves the four inputs in precedence order and returns
// micro-USD. This is the authoritative price; ugnot is derived from it.
func NamePriceUSD(domainLabel, label string) int64 {
	return applyPremium(PremiumFor(label), resolveBeforePremium(domainLabel, label))
}

// resolveBeforePremium runs steps 1-5. Separated from NamePriceUSD so
// the admin panel can show WHY a price is what it is: the figure before
// the premium and the figure after are both meaningful, and a single
// function returning only the total makes a wrong price impossible to
// diagnose.
func resolveBeforePremium(domainLabel, label string) int64 {
	base := DomainBasePriceUSD(domainLabel)
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyNames), label); ok {
		return applyRule(v, base)
	}
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyLens), strconv.Itoa(len(label))); ok {
		return applyRule(v, base)
	}
	// The global length rule is a floor, not a replacement: it applies
	// only where the domain itself had nothing to say about this length.
	if v, ok := GlobalLengthRule(len(label)); ok {
		return applyRule(v, base)
	}
	return base
}

// ExplainPriceUSD returns each stage of the resolution, so the control
// panel can show the arithmetic rather than assert a total. Returns the
// price before any premium, the premium modifier that applied (empty if
// none), and the final price.
func ExplainPriceUSD(domainLabel, label string) (beforePremium int64, modifier string, final int64) {
	before := resolveBeforePremium(domainLabel, label)
	mod := PremiumFor(label)
	return before, mod, applyPremium(mod, before)
}

// -- settlement side --

// RateUgnotPerUsd is how many ugnot one USD buys.
//
// This is a MANUALLY MAINTAINED rate, not a market oracle: an admin
// writes it and it sits there until rewritten. That is a real
// operational hazard — a stale rate during a sharp move sells names at
// the wrong price in whichever direction hurts — and the mitigation is
// keeping it fresh, not anything this code can do. Kept as one global so
// a future logic realm can swap in a real oracle without touching the
// vault or restating a single price.
func RateUgnotPerUsd() int64 {
	if v := nsdata.GetGlobal(keyRate); v != "" {
		if r, err := strconv.ParseInt(v, 10, 64); err == nil && r > 0 {
			return r
		}
	}
	return fallbackRate
}

// NamePrice converts the USD price to ugnot for settlement. Rounds UP,
// so rounding never sells a name below its listed price; a free name
// stays exactly free.
//
// IT REFUSES TO OVERFLOW. usd*rate is int64 arithmetic, which wraps
// silently, and a wrapped product is a price of millions of GNOT or a
// negative one — and a negative price made takePaymentSplit refund more
// than was paid (audit L5). A price that cannot be computed is refused,
// which fails closed: no sale, never a wrong one.
func NamePrice(domainLabel, label string) int64 {
	usd := NamePriceUSD(domainLabel, label)
	if usd <= 0 {
		return 0
	}
	rate := RateUgnotPerUsd()
	if usd > (math.MaxInt64-microUSD)/rate {
		panic("nslogic: this name's price does not fit in a ugnot amount; the price list needs fixing")
	}
	return (usd*rate + microUSD - 1) / microUSD
}

// -- rule plumbing --

// applyRule reads a stored rule. An out-of-range one is treated like a
// malformed one — the base applies — because stored values can arrive by
// the restore window, unvalidated, and an unbounded percentage would wrap
// the multiplication into a small, wrong, price.
func applyRule(v string, base int64) int64 {
	if strings.HasPrefix(v, "%") {
		pct, err := strconv.ParseInt(v[1:], 10, 64)
		if err != nil || pct < 0 || pct > maxRulePct || base > maxPriceUSD {
			return base
		}
		return base * pct / 100
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil || n < 0 || n > maxPriceUSD {
		return base
	}
	return n
}

func lookupRule(csv, want string) (string, bool) {
	if csv == "" {
		return "", false
	}
	for _, pair := range strings.Split(csv, ",") {
		parts := strings.SplitN(strings.TrimSpace(pair), ":", 2)
		if len(parts) != 2 {
			continue
		}
		if strings.TrimSpace(parts[0]) == want {
			return strings.TrimSpace(parts[1]), true
		}
	}
	return "", false
}

// normalizeRules validates and canonicalises a rule string before it is
// stored, so a malformed entry can never reach storage and poison every
// later lookup.
func normalizeRules(csv string, numericKeys bool) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad rule, want key:value — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" {
			panic("nslogic: empty rule key")
		}
		if numericKeys {
			if n, err := strconv.Atoi(k); err != nil || n <= 0 {
				panic("nslogic: length must be a positive number — got " + k)
			}
		} else if strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in rule — " + k)
		}
		// Bounded as well as well-formed: an amount above maxPriceUSD or a
		// percentage above maxRulePct is a typo, and an unbounded one could
		// overflow the price arithmetic downstream.
		if strings.HasPrefix(v, "%") {
			if p, err := strconv.ParseInt(v[1:], 10, 64); err != nil || p < 0 || p > maxRulePct {
				panic("nslogic: bad percentage (0-" + strconv.Itoa(maxRulePct) + ") — " + v)
			}
		} else if n, err := strconv.ParseInt(v, 10, 64); err != nil || n < 0 || n > maxPriceUSD {
			panic("nslogic: bad amount — " + v)
		}
		if seen[k] {
			panic("nslogic: duplicate rule key — " + k)
		}
		seen[k] = true
		out = append(out, k+":"+v)
		if len(out) > maxRules {
			panic("nslogic: too many rules (max 64)")
		}
	}
	return strings.Join(out, ",")
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// The referral programme.
//
// THE RULES, decided by the owner on 2026-10-16 and bounded in code:
//
//	ONE FLAT TIER. A referrer's cut and a buyer's discount are two fixed
//	percentages. Nothing escalates with how old a name is or how long
//	its holder has been here: tenure could be bought (an old name keeps
//	its registration date through a sale), and an escalating table was
//	the reason a second wallet's code was worth up to 37% off.
//
//	AT MOST 10% TOGETHER. Cut plus discount never exceeds maxRefPercent,
//	whatever an admin stores; SetReferralRules refuses more, and the
//	reader clamps anything stored before. An admin can lower it, never
//	raise it.
//
//	FIRST YEAR ONLY. The cut and the discount apply to the registration,
//	which buys the first term. Renewals pay full price and pay nobody.
//
//	A CODE MUST HAVE BEEN HELD. A code earns only when it names a PAID
//	(not free-tier) name that its holder has kept for refHoldDays, by
//	the registry's own holding clock (nsdata.GetNameHeldSince). A wallet
//	made this morning, with a name bought this morning, is no referrer.
//
// What that does to the second-wallet trick: a buyer who quotes the code
// of a second wallet they control saves the discount and recovers the cut
// — at most 10% of the price, after waiting thirty days with a paid name
// in that wallet. TestASecondWalletEarnsAtMostTenPercent pins the number.
//
// SINGLE LEVEL, ALWAYS. One buyer, one referrer, one cut, taken out of
// an actual sale. There is no downline, no override on somebody else's
// referrals, and no bonus for recruiting other referrers — and there is
// no code here that could be extended into one without being obvious
// about it. That is the line between an affiliate programme and the
// other thing, and this realm stays on the near side of it.
//
// WHERE THE LINK LIVES. The referrer is recorded on the REFERRED NAME,
// in its extension slot, at the moment it is registered — a record of
// who brought the buyer, nothing that pays out any more. The vault
// destroys a name's extras when a lapsed name is re-registered and hides
// them the moment it changes hands, so a name that lapses or is sold
// forgets its referrer with no code here to make it so.
//
// WHO GETS PAID. The referrer's own address, fixed, at the moment of the
// sale (see PayoutFor). Nothing accrues and nothing is owed later: the
// cut is paid inside the registration or not at all.
//
// SELF-REFERRAL IS REFUSED. Otherwise the informed apply their own code
// and the cut becomes a silent discount for people who read the source.
//
// EVERYTHING SETTLES IN ONE TRANSACTION. Buyer pays, treasury is paid,
// referrer is paid, overpayment goes back — all inside the message the
// buyer signed. No escrow, no float, not for a block.
const (
	keyRef      = "ref"     // on a NAME: the referrer's address
	keyRefCut   = "refcut"  // global: the referrer's percentage, stored "0:N"
	keyRefDisc  = "refdisc" // global: the buyer's discount, stored "0:N"
	keyRefCount = "rc"      // ACCOUNT field (nsdata's per-address store): how many referred
	keyRefWin   = "refwin"  // global: days a captured code stays valid

	maxRefPercent = 10 // cut plus discount, together; an admin may lower it, never exceed it
	refHoldDays   = 30 // a code earns only once its holder has kept a paid name this long
)

// -- the rates --

// tierPercent reads a stored rate. The canonical form is a one-tier table
// at year zero, "0:N", which every reader of the old escalating tables —
// the site among them — reads as N at any tenure. A legacy multi-tier
// table counts only at year zero (RefRates asks for nothing else), so a
// table that once escalated cannot escalate now. Junk entries are
// skipped, not fatal, so one bad character cannot stop every sale; a
// percentage above the cap is clamped.
func tierPercent(spec string, years int64) int64 {
	best := int64(0)
	bestAt := int64(-1) // the threshold of the tier `best` came from
	for _, part := range strings.Split(spec, ",") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) != 2 {
			continue
		}
		at, err1 := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64)
		pct, err2 := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err1 != nil || err2 != nil || at < 0 || pct < 0 {
			continue
		}
		if pct > maxRefPercent {
			pct = maxRefPercent
		}
		// The highest tier that applies, not the biggest number in the
		// table, so a table that tapers means what it reads as.
		if years >= at && at >= bestAt {
			bestAt = at
			best = pct
		}
	}
	return best
}

// RefRates is the flat cut and discount in force, in percent, clamped so
// that together they never exceed maxRefPercent whatever is stored. The
// discount is kept and the cut gives way: what a buyer was quoted is the
// promise, the cut is the treasury's to shrink.
func RefRates() (cutPct, discountPct int64) {
	return clampRates(tierPercent(RefCutRules(), 0), tierPercent(RefDiscountRules(), 0))
}

// clampRates is the 10% ceiling on its own, so it can be tested without a
// vault: negative inputs are zero, the discount is capped first, and the
// cut takes whatever room is left.
func clampRates(cut, disc int64) (int64, int64) {
	if cut < 0 {
		cut = 0
	}
	if disc < 0 {
		disc = 0
	}
	if disc > maxRefPercent {
		disc = maxRefPercent
	}
	if cut > maxRefPercent-disc {
		cut = maxRefPercent - disc
	}
	return cut, disc
}

// THE PRESET THE PROJECT LAUNCHES WITH: five percent to the referrer, five
// off for the buyer — the whole 10% the owner allowed, split evenly.
// Written here rather than typed into the admin panel at launch because a
// number that exists only in somebody's memory of a conversation gets set
// wrong once and noticed a month later. It is a DEFAULT, not a policy:
// SetReferralRules overwrites it, and empty rates switch the programme off.
const (
	defaultRefCut      = "0:5"
	defaultRefDiscount = "0:5"
)

// DefaultReferralRules lets the site show the presets before anybody
// commits them.
func DefaultReferralRules() (cut, discount string) {
	return defaultRefCut, defaultRefDiscount
}

// SeedReferralRules writes the presets, and ONLY into empty rates. Not an
// init(): at init a fresh logic realm is not yet trusted by the vault.
// Refusing to overwrite makes it safe to call twice and safe to call by
// mistake.
func SeedReferralRules(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if nsdata.GetGlobal(keyRefCut) != "" || nsdata.GetGlobal(keyRefDisc) != "" {
		panic("nslogic: referral rules are already set; use SetReferralRules to change them")
	}
	SetReferralRules(cur, defaultRefCut, defaultRefDiscount)
}

func RefCutRules() string      { return nsdata.GetGlobal(keyRefCut) }
func RefDiscountRules() string { return nsdata.GetGlobal(keyRefDisc) }

// RefWindowDays is how long a clicked link keeps counting for. It is
// enforced by the browser that captured the code, not by this realm —
// the chain never sees the click, only the registration that quotes a
// code — so it is stored here purely to be ONE number rather than a
// constant baked separately into the site, the FAQ and the rules page.
// Zero means the default; the site treats an absent value the same way.
func RefWindowDays() int64 {
	d := parseInt64(nsdata.GetGlobal(keyRefWin))
	if d <= 0 {
		return 30
	}
	return d
}

func SetReferralWindow(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetReferralWindow", "days", fmtInt(days))
	if days < 0 || days > 3650 {
		panic("nslogic: window must be 0-3650 days")
	}
	setGlobal(cur, keyRefWin, strconv.FormatInt(days, 10))
}

// ReferralQuote is what a code is worth, answered before anybody signs
// anything. One call rather than four, because the site needs all of it
// at once to show a price.
//
// A referrer of "" means the code does not earn — it did not resolve, it
// is the buyer's own, it names a free-tier name, or its holder has not
// kept it for refHoldDays — and both percentages are then zero. `tenure`
// is the referrer's years held, for display only: it no longer moves
// either percentage.
func ReferralQuote(refName string, buyer address) (referrer address, tenure, discountPct, cutPct int64) {
	ref := resolveReferrer(refName, buyer)
	if ref == "" {
		return "", 0, 0, 0
	}
	cut, disc := RefRates()
	return ref, TenureYears(ref), disc, cut
}

// SetReferralRules sets both rates at once, because setting one without
// the other is how a cut ends up larger than the margin. Each is "N" or
// "0:N" (percent), or empty for none; two empties switch the programme
// off. Together they may not exceed maxRefPercent. A multi-tier table is
// refused: the programme has one tier.
func SetReferralRules(cur realm, cutSpec, discountSpec string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetReferralRules", "cut", cutSpec, "discount", discountSpec)
	cut, cutPct := normalizeRate(cutSpec)
	disc, discPct := normalizeRate(discountSpec)
	if cutPct+discPct > maxRefPercent {
		panic("nslogic: a referrer's cut plus a buyer's discount may be at most " +
			strconv.Itoa(maxRefPercent) + "% — got " + strconv.FormatInt(cutPct+discPct, 10) + "%")
	}
	setGlobal(cur, keyRefCut, cut)
	setGlobal(cur, keyRefDisc, disc)
}

// normalizeRate reads one rate as an admin types it — "5", "0:5", or ""
// — and returns its stored form, "0:5" or "" for none, and the percent.
// Anything else panics before it can reach storage.
func normalizeRate(spec string) (stored string, pct int64) {
	s := strings.TrimSpace(spec)
	if s == "" {
		return "", 0
	}
	if kv := strings.SplitN(s, ":", 2); len(kv) == 2 {
		if strings.TrimSpace(kv[0]) != "0" {
			panic("nslogic: the referral programme has one flat tier; write N or 0:N — got " + spec)
		}
		s = strings.TrimSpace(kv[1])
	}
	p, err := strconv.ParseInt(s, 10, 64)
	if err != nil || p < 0 || p > maxRefPercent {
		panic("nslogic: a referral rate is a whole percent, 0-" + strconv.Itoa(maxRefPercent) + " — got " + spec)
	}
	if p == 0 {
		return "", 0
	}
	return "0:" + strconv.FormatInt(p, 10), p
}

// -- tenure, for display --

// TenureYears is how long a wallet counts as having been here, measured
// from its PRIMARY name. It used to pick the referral tier; it moves no
// money now, and stays because the referral page shows it.
//
// A lapsed or missing primary is zero years, not an error.
func TenureYears(who address) int64 {
	/* RESOLVED, NOT READ RAW. GetPrimary reports what an address last
	   SELECTED, not what it still holds — and a sale on the token ledger
	   no longer clears the seller's pointer. ResolveAddress re-checks the
	   owner and the expiry. */
	tid := ResolveAddress(who)
	at := strings.Index(tid, "*")
	if at < 1 {
		return 0
	}
	_, _, _, streak, _, _ := nsdata.GetNameInfo(tid[:at], tid[at+1:])
	return streak
}

// -- where it gets paid --

// Commissions go to the referring wallet. There is no way to redirect
// them, and that is a decision rather than an omission.
//
// There WAS a redirect — SetReferralPayout, "a forwarding address, not a
// transferable right". It does not survive the obvious question: how
// would this realm tell somebody moving money between their own two
// wallets from somebody who has sold the stream to a stranger? It
// cannot. Nothing on chain distinguishes those, and a rule that cannot
// be enforced is not a rule, it is a sentence in a document.
//
// So the destination is the referrer's own address, fixed. Selling the
// entitlement now means handing over private keys, which is a deterrent
// no contract clause could match.
func PayoutFor(who address) address { return who }

// -- the record on a name --

// ReferrerOf reads the wallet credited with a name, or the empty address.
func ReferrerOf(label, domainLabel string) address {
	v := nsdata.GetNameExtra(label, domainLabel, keyRef)
	if a := address(v); v != "" && a.IsValid() {
		return a
	}
	return ""
}

/*
resolveReferrer turns a claimed referring NAME into the wallet to credit,
or the empty address if the claim does not stand up. Every rejection is
silent on purpose: a mistyped code should not fail somebody's
registration, it should simply earn nobody anything.

THE CODE ITSELF must qualify: a paid name, live, held by its current
holder for refHoldDays. Checking the code rather than "any name the
referrer has" is one lookup instead of a registry walk, and the site
builds a holder's link from a name that qualifies.
*/
func resolveReferrer(refName string, buyer address) address {
	at := strings.Index(refName, "*")
	if refName == "" || at < 1 || at == len(refName)-1 {
		return ""
	}
	label, domainLabel := refName[:at], refName[at+1:]
	if !nsdata.NameExists(label, domainLabel) || !nsdata.IsNameValid(label, domainLabel) {
		return "" // a lapsed name is not a working code
	}
	owner := nsdata.GetNameOwner(label, domainLabel)
	if owner == buyer {
		return "" // no referring yourself
	}
	if !nsdata.IsNamePaid(label, domainLabel) {
		return "" // a free-tier name is not a code
	}
	if !heldLongEnough(nsdata.GetNameHeldSince(label, domainLabel), time.Now().Unix()) {
		return "" // not held long enough, or bought and not yet seen by the registry
	}
	return owner
}

// heldLongEnough is the thirty-day rule on its own. A zero `since` means
// the registry has not seen the current holder yet — never long enough.
func heldLongEnough(since, now int64) bool {
	return since > 0 && now >= since && now-since >= refHoldDays*86400
}

/*
StartReferralClock starts the holding clock on a name the caller BOUGHT,
so that thirty days later it can be a referral code.

A sale that settles on the token ledger never calls the registry, so the
registry first sees a buyer at their first write to the name. A buyer who
never edits a profile would otherwise never qualify. This is that first
write, with nothing in it: it clears the seller's stale data, which every
read already hides, and stamps the clock. Names you registered yourself
start their clock at registration and need nothing.
*/
func StartReferralClock(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if err := nsdata.FreshenNameRecord(cross(cur), label, domainLabel); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// -- the money --

// PriceWithReferral is what a buyer actually pays given the code they
// arrived with. Exported so the site can display the number the chain
// will charge instead of computing its own and hoping they agree.
func PriceWithReferral(domainLabel, label, refName string, buyer address) int64 {
	price := NamePrice(domainLabel, label)
	if price <= 0 {
		return 0 // free is free, and a percentage of nothing is nothing
	}
	if resolveReferrer(refName, buyer) == "" {
		return price
	}
	_, disc := RefRates()
	return price - price*disc/100
}

// referralCut is what leaves for a qualifying referrer out of a
// registration's payment of `price` (already discounted). Returns the
// destination and the amount; the caller pays it in the same call that
// pays the treasury. Registration only: renewals pay nobody.
func referralCut(ref address, price int64) (address, int64) {
	if ref == "" || price <= 0 {
		return "", 0
	}
	cutPct, _ := RefRates()
	cut := price * cutPct / 100
	if cut <= 0 {
		return "", 0
	}
	return PayoutFor(ref), cut
}

// -- the scoreboard --

// creditReferral records one paid referral against a wallet.
//
// The COUNT and nothing else. There was a running total of micro-USD
// beside it, and it is gone, because a number stored in the vault is a
// number anyone with an RPC endpoint can read — there is no such thing
// as an admin-only global on a public chain, and building the site as
// though there were would be the kind of privacy that works right up
// until somebody checks.
//
// Not storing it is the only real reduction available. The payments are
// still in the block history and always will be, so anyone determined
// can add them up; what we can decline to do is publish a convenient
// running total ourselves. tools/referrals.py reconstructs it from the
// chain when we want it, which costs no storage and publishes nothing.
//
// The registrant's transaction pays for this entry: one small field,
// written once per referrer and overwritten after — the price of the
// discount they just received.
//
// IT LIVES IN THE VAULT'S PER-ADDRESS STORE, and until it did, no referred
// registration ever succeeded. It was the global "ref:" + address, 44
// bytes against a 32-byte cap on global keys; the vault refused it, this
// panicked, and the whole purchase reverted after the price was taken —
// on every chain the programme ran on. A key that short would only have
// moved the failure: globals held at most 24 entries, shared with the
// price list, so it would have broken again at about the twenty-first
// referrer. An address is a key there now, and each wallet's fields are
// bounded on their own.
func creditReferral(cur realm, ref address) {
	if ref == "" {
		return
	}
	if err := nsdata.SetAccountRecord(cross(cur), ref, keyRefCount,
		strconv.FormatInt(ReferralCount(ref)+1, 10)); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// ReferralCount is how many paid registrations a wallet has been
// credited with. Public, like everything in the vault.
func ReferralCount(who address) int64 {
	return parseInt64(nsdata.GetAccount(who, keyRefCount))
}

func parseInt64(s string) int64 {
	v, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		return 0
	}
	return v
}

// How many vault pages one ReferralBoard call may scan.
const refBoardPages = 5

// ReferralBoard pages through every credited wallet for the
// leaderboard: one "address,count" row per line.
//
// It walks the vault's per-address store, where other fields (credits)
// sit beside the counters, so a page can scan more keys than it returns.
// `next` is an opaque cursor — pass it back as `after` — and is non-empty
// whenever the walk stopped before the end, including when it stopped on
// its scanning budget with fewer rows than asked for. A caller keeps
// going until `next` is empty.
func ReferralBoard(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > 200 {
		limit = 200
	}
	var out []string
	from := after
	for page := 0; page < refBoardPages; page++ {
		keys, more := nsdata.ExportAccounts(from, 200)
		if keys == "" {
			return strings.Join(out, "\n"), ""
		}
		for _, k := range strings.Split(keys, ",") {
			from = k
			at := strings.Index(k, ":")
			if at < 0 || k[at+1:] != keyRefCount {
				continue
			}
			addr := k[:at]
			n := ReferralCount(address(addr))
			if n <= 0 {
				continue
			}
			out = append(out, addr+","+strconv.FormatInt(n, 10))
			if len(out) >= limit {
				return strings.Join(out, "\n"), k
			}
		}
		if more == "" {
			return strings.Join(out, "\n"), ""
		}
	}
	return strings.Join(out, "\n"), from
}

package nslogic

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
	"gno.land/r/nym-mnsrehearsal001/nsreserve/v3"
)

/*
FREE NAMES ARE RESERVATIONS NOW, and the holder mints.

The launch gives names away to X accounts and sells nothing. A claim needs
the X sign-in and nothing else. A free name is a record in our worker plus
a hashed reservation in the nsreserve realm that names nobody, written by
the granter in one daily batch for a fraction of a cent. Minting it into a
real record and a token is the holder's own transaction, paid by the
holder, let through by a voucher from the mint approver; the project pays
nothing for it.

THREE THINGS LIVE HERE.

 1. THE BLOCK. Every door that creates a name refuses a label somebody has
    reserved: paid registration, credits, the old per-name grant. The only
    way through a reservation is MintFree with a voucher for that name.

 2. THE MINT. MintFree runs every label rule again, at mint time, because
    the rules may have moved since the claim; gives the name the expiry the
    claim earned (the request time plus one term), not a fresh year; and
    leaves the token on the free hold: not transferable, not approvable,
    not listable, until UpgradeFreeName, which needs paid registration
    open. RenewFree extends it a year at a time, on a voucher too.

 3. THE PAID SWITCH. Paid registration is CLOSED on every domain until the
    admin opens it behind the timelock. Closing is instant, for the admin,
    the guardian and recovery. It does not touch the free mint.
*/

const (
	keyPaid   = "paid"      // global AND domain extra: "1" opens paid registration
	keyLegacy = "freegrant" // global: "1" reopens the per-name grant doors
)

// isWarden: the keys that may always move a switch the SAFE way.
func isWarden(a address) bool {
	return a != "" && (a == nsdata.GetAdmin() || a == nsdata.GetGuardian() || a == nsdata.GetRecovery())
}

func assertWarden(cur realm) {
	if !isWarden(cur.Previous().Address()) {
		panic("nslogic: restricted to the admin, the guardian or recovery")
	}
}

// -- the paid switch --

// PaidOpen reports whether names under a domain are for sale: only when
// the registry-wide switch AND the domain's own are both on. Both are off
// until somebody opens them, on every domain.
func PaidOpen(domainLabel string) bool {
	return nsdata.GetGlobal(keyPaid) == "1" && nsdata.GetDomainExtra(domainLabel, keyPaid) == "1"
}

func assertPaidOpen(domainLabel string) {
	if !PaidOpen(domainLabel) {
		panic("nslogic: paid registration is closed on *" + domainLabel)
	}
}

// SetPaidOpen moves the registry-wide paid switch. OPENING is the admin's,
// TIMELOCKED: it turns a giveaway into a shop. CLOSING is instant, for the
// admin, the guardian and recovery.
func SetPaidOpen(cur realm, on bool) {
	assertNoSend(cur)
	emitAdmin(cur, "SetPaidOpen", "on", fmtBool(on))
	if !on {
		assertWarden(cur)
		setGlobal(cur, keyPaid, "")
		return
	}
	assertIsAdmin(cur)
	requireAction(cur, actionID("SetPaidOpen", "true"))
	setGlobal(cur, keyPaid, "1")
}

// SetDomainPaid is the same switch for one domain, with the same rule.
func SetDomainPaid(cur realm, domainLabel string, on bool) {
	assertNoSend(cur)
	emitAdmin(cur, "SetDomainPaid", "label", domainLabel, "on", fmtBool(on))
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: no such domain")
	}
	if !on {
		assertWarden(cur)
		setDomainExtra(cur, domainLabel, keyPaid, "")
		return
	}
	assertIsAdmin(cur)
	requireAction(cur, actionID("SetDomainPaid", domainLabel, "true"))
	setDomainExtra(cur, domainLabel, keyPaid, "1")
}

// -- the old per-name grant doors --

// LegacyGrantsOpen reports whether GrantFreeName, GrantFreeRenewal and
// RegisterFor answer at all. Off unless the admin reopened them.
func LegacyGrantsOpen() bool { return nsdata.GetGlobal(keyLegacy) == "1" }

func assertLegacyGrants() {
	if !LegacyGrantsOpen() {
		panic("nslogic: the per-name grant path is closed; free names are reservations (nsreserve) minted by their holders")
	}
}

// SetLegacyGrants reopens or closes the per-name grant doors. Opening is
// the admin's, timelocked; closing is instant for admin, guardian, recovery.
func SetLegacyGrants(cur realm, on bool) {
	assertNoSend(cur)
	emitAdmin(cur, "SetLegacyGrants", "on", fmtBool(on))
	if !on {
		assertWarden(cur)
		setGlobal(cur, keyLegacy, "")
		return
	}
	assertIsAdmin(cur)
	requireAction(cur, actionID("SetLegacyGrants", "true"))
	setGlobal(cur, keyLegacy, "1")
}

// -- the block --

// assertNotReserved is on every door that creates a name except the
// reservation's own.
func assertNotReserved(label, domainLabel string) {
	if nsreserve.Reserved(label, domainLabel) {
		panic("nslogic: " + label + "*" + domainLabel + " is reserved")
	}
}

// -- the mint --

/*
freeNameRefusal is every rule a label must pass to be given away, asked at
mint time: "" or the reason. The claim was checked by the issuer, possibly
months ago; this is the chain's own answer today.

NOT the claim cap (credits.gno): that is a price ceiling for credits, the
free launch sets it to zero, and tying the two together would refuse every
free name (verify N-6). The free tier's own line is: no premium name, and
no name priced above its domain's base.
*/
func freeNameRefusal(label, domainLabel string) (why string) {
	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok {
				why = strings.TrimPrefix(s, "nslogic: ")
			} else {
				why = "this label is not allowed"
			}
		}
	}()
	if st, _ := readRestoreState(nsdata.GetGlobal(keyRestore), time.Now().Unix()); st == "open" {
		return "the registry is being restored"
	}
	if nsdata.IsPaused() {
		return "the registry is paused"
	}
	if q := nsdata.QuarantineUntil(); time.Now().Unix() < q {
		return "recovery has quarantined giveaways until unix " + strconv.FormatInt(q, 10)
	}
	if !nsdata.DomainExists(domainLabel) || !DomainFree(domainLabel) {
		return "*" + domainLabel + " does not offer free names"
	}
	if !DomainOpen(domainLabel) {
		return "this domain is not accepting new names"
	}
	validateLabel(label)
	assertNotBlocked(label)
	if !FreeLabelAllowed(label) {
		return label + " is not available on the free tier"
	}
	if PremiumFor(label) != "" {
		return label + " is a premium name and is not given away"
	}
	if NamePriceUSD(domainLabel, label) > DomainBasePriceUSD(domainLabel) {
		return label + " is priced above an ordinary name and is not given away"
	}
	return ""
}

func nameTaken(label, domainLabel string) bool {
	if !nsdata.NameExists(label, domainLabel) {
		return false
	}
	_, _, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	now := time.Now().Unix()
	return now < expires || now-expires < nsdata.GetGracePeriod()
}

// MintRefusal is why `holder` could not MintFree label*domain with this
// voucher right now, or "". For the site, before the wallet is asked.
func MintRefusal(holder address, label, domainLabel string, requestedAt, validUntil int64, sig string) string {
	if r := freeNameRefusal(label, domainLabel); r != "" {
		return r
	}
	if nameTaken(label, domainLabel) {
		return label + "*" + domainLabel + " is already registered"
	}
	return nsreserve.VoucherRefusal(nsreserve.KindMint, label, domainLabel, holder, requestedAt, validUntil, sig)
}

/*
MintFree is the one door a free name is minted through.

THE CALLER IS THE HOLDER, and pays: gas and the storage deposit come out of
the wallet that signs; the project pays nothing. What lets them through is
a voucher from the mint approver, issued by our worker only after a fresh X
sign-in by the account that claimed the name, saying: this wallet, this
name, requested at this second, valid until that one. nsreserve checks the
signature against the key the admin named, checks the wallet is
cur.Previous(), counts it against the approver's daily cap, and:

	if the name is RESERVED, requires the voucher to carry the
	reservation's own request time and spends the reservation;

	if it is NOT (the claimant is minting before the day's batch landed),
	requires a request time from the last three days.

Either way the name's expiry is the request time plus one term: minting is
never a fresh year. A voucher copied out of the mempool mints nothing for
anybody else, and nothing a second time: the name exists.
*/
func MintFree(cur realm, label, domainLabel string, requestedAt, validUntil int64, sig string) {
	assertNoSend(cur)
	if r := freeNameRefusal(label, domainLabel); r != "" {
		panic("nslogic: " + r)
	}
	caller := cur.Previous().Address()
	expires := nsreserve.ConsumeVoucher(cross(cur), nsreserve.KindMint, label, domainLabel, caller, requestedAt, validUntil, sig)
	now := time.Now().Unix()
	if expires <= now {
		panic("nslogic: this claim's year has already run out")
	}
	hadPrimary := nsdata.GetPrimary(caller) != ""
	// paid=false: the free hold is on the token from the instant it exists.
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, caller, now, false); err != nil {
		panic(err)
	}
	// THE CLOCK STARTED AT THE CLAIM. The vault just wrote now + one term;
	// the name gets what the claim earned instead.
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
	// NO REVERSE POINTER WITHOUT BEING ASKED (audit M-5). The vault points
	// a wallet's first name back at it; for a name given away that is a
	// public wallet-to-persona link nobody chose. SetPrimaryName is the
	// holder's own call.
	if !hadPrimary {
		nsdata.ClearPrimaryRecord(cross(cur), caller)
	}
	chain.Emit("NameMinted", "tid", label+"*"+domainLabel, "owner", caller.String(),
		"expires", strconv.FormatInt(expires, 10))
}

// renewRefusal is everything RenewFree checks before the voucher.
func renewRefusal(holder address, label, domainLabel string) string {
	if st, _ := readRestoreState(nsdata.GetGlobal(keyRestore), time.Now().Unix()); st == "open" {
		return "the registry is being restored"
	}
	if nsdata.IsPaused() {
		return "the registry is paused"
	}
	if q := nsdata.QuarantineUntil(); time.Now().Unix() < q {
		return "recovery has quarantined giveaways until unix " + strconv.FormatInt(q, 10)
	}
	if !nsdata.NameExists(label, domainLabel) || nsdata.GetNameOwner(label, domainLabel) != holder {
		return "restricted to name owner"
	}
	if _, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel); paid {
		return label + "*" + domainLabel + " is a paid name; it renews with RenewName"
	}
	return ""
}

// RenewRefusal is why `holder` could not RenewFree label*domain with this
// voucher right now, or "".
func RenewRefusal(holder address, label, domainLabel string, requestedAt, validUntil int64, sig string) string {
	if r := renewRefusal(holder, label, domainLabel); r != "" {
		return r
	}
	if _, _, was, _, _, _ := nsdata.GetNameInfo(label, domainLabel); requestedAt+nsdata.GetTermLength() <= was {
		return "not an extension: the name already runs to unix " + strconv.FormatInt(was, 10)
	}
	return nsreserve.VoucherRefusal(nsreserve.KindRenew, label, domainLabel, holder, requestedAt, validUntil, sig)
}

/*
RenewFree extends a minted free name on a RENEW voucher.

THE RENEWAL IS BOUND TO THE HOLDER (verify N-2). The old GrantFreeRenewal
asked for no proof, and anybody holding the granter key could push any free
name forward. Here the issuer checks X again and signs a voucher for the
wallet that holds the name; only that wallet can use it, it pays the gas,
and the name's expiry becomes the renewal request plus one term. A renew
voucher is its own kind: it cannot mint, and a mint voucher cannot renew.
*/
func RenewFree(cur realm, label, domainLabel string, requestedAt, validUntil int64, sig string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if r := renewRefusal(caller, label, domainLabel); r != "" {
		panic("nslogic: " + r)
	}
	_, _, was, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	expires := nsreserve.ConsumeVoucher(cross(cur), nsreserve.KindRenew, label, domainLabel, caller, requestedAt, validUntil, sig)
	if expires <= was {
		panic("nslogic: not an extension: the name already runs to unix " + strconv.FormatInt(was, 10))
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
	chain.Emit("NameRenewedFree", "tid", label+"*"+domainLabel, "expires", strconv.FormatInt(expires, 10))
}

// -- the admin's levers on reservations --

const maxReserveBatch = 64

func assertHashBatch(hashes string) {
	if hashes == "" || len(hashes)%32 != 0 || len(hashes) > 32*maxReserveBatch {
		panic("nslogic: 1.." + fmtI(maxReserveBatch) + " hashes, 32 hex characters each, no separators")
	}
}

/*
ClearReservations deletes reservations: a wrong grant, a stolen granter's
squats, a name that has to be given up.

TIMELOCKED (audit H-1 asked for exactly this lever, and for the wait): it
takes a name away from whoever was promised it, so it is proposed in the
vault as `ClearReservations <hashes>`, waits, and recovery can veto it. Up
to 64 hashes behind one action.
*/
func ClearReservations(cur realm, hashes string) int {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "ClearReservations", "hashes", hashes)
	assertHashBatch(hashes)
	requireAction(cur, actionID("ClearReservations", hashes))
	return nsreserve.Clear(cross(cur), hashes)
}

/*
RevokeFreeNames ends MINTED free names: each one's expiry is set past the
grace period, so the label is reclaimable at once and the token is burned by
the next registration. Paid names are refused. TIMELOCKED, up to 64 token
ids (`a*meme,b*meme`) behind one action.

It reaches a name only while it is still on the free hold. That holds as
long as paid registration is closed, because UpgradeFreeName is behind the
paid switch: before opening paid, revoke what needs revoking (verify N-6).
*/
func RevokeFreeNames(cur realm, tids string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "RevokeFreeNames", "tids", tids)
	list := strings.Split(tids, ",")
	if tids == "" || len(list) > maxReserveBatch {
		panic("nslogic: 1.." + fmtI(maxReserveBatch) + " token ids, comma-separated")
	}
	type ref struct{ label, domain string }
	refs := make([]ref, 0, len(list))
	for _, tid := range list {
		label, domainLabel := splitTokenID(tid)
		if label == "" || domainLabel == "" || !IsFreeTier(label, domainLabel) {
			panic("nslogic: not a free-tier name: " + tid)
		}
		refs = append(refs, ref{label, domainLabel})
	}
	requireAction(cur, actionID("RevokeFreeNames", tids))
	gone := time.Now().Unix() - nsdata.GetGracePeriod() - 1
	for _, r := range refs {
		nsdata.SetNameExpiryRecord(cross(cur), r.label, r.domain, gone)
	}
}

// SetReserveDailyCap sets how many reservations and vouchers a day may
// carry. LOWERING is instant; RAISING is timelocked: the cap is what bounds
// a stolen granter or voucher key, and a stolen admin key must not lift it
// in the same breath.
func SetReserveDailyCap(cur realm, n int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetReserveDailyCap", "cap", fmtI(n))
	if n > nsreserve.DailyCap() {
		requireAction(cur, actionID("SetReserveDailyCap", fmtI(n)))
	}
	nsreserve.SetDailyCap(cross(cur), n)
}

// SetVoucherKey names the mint approver: the ed25519 public key that signs
// mint-now vouchers.
// TIMELOCKED: whoever holds the other half gives names away. Turning it
// off is nsreserve.ClearVoucherKey, instant, for admin, guardian, recovery.
func SetVoucherKey(cur realm, hexKey string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetVoucherKey", "key", hexKey)
	requireAction(cur, actionID("SetVoucherKey", hexKey))
	nsreserve.SetVoucherKey(cross(cur), hexKey)
}

// SetVoucherDailyCap sets how many names a day may be minted on vouchers:
// the mint approver's own cap, apart from the granter's. Lowering is
// instant, raising is timelocked.
func SetVoucherDailyCap(cur realm, n int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetVoucherDailyCap", "cap", fmtI(n))
	if n > nsreserve.VoucherCap() {
		requireAction(cur, actionID("SetVoucherDailyCap", fmtI(n)))
	}
	nsreserve.SetVoucherDailyCap(cross(cur), n)
}

// UnpauseReservations lifts nsreserve's pause. TIMELOCKED for the admin;
// recovery lifts it directly there.
func UnpauseReservations(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "UnpauseReservations")
	requireAction(cur, actionID("UnpauseReservations"))
	nsreserve.UnpauseByLogic(cross(cur))
}

package nslogic

import (
	"strconv"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// GENERATED BY tools/gen-reserved.py FROM collections/reserved-labels.json.
// Do not edit by hand: the site reads the same source, and a change made
// in one place only is a label the site offers and the chain refuses.
//
// STRUCTURAL RULES ONLY. The wordlists live off chain, in that JSON,
// because storage is 100 ugnot per byte and a ten-thousand-word
// dictionary is about 57 GNOT paid forever to encode a marketing
// decision that will change. This is the backstop against a bug in the
// issuer, not the place the policy lives.
//
// THE NUMBERS ARE SETTABLE, the shape is not. A minimum length is a
// promotion knob and belongs in the panel — redeploying this realm to
// change a 5 to a 4 costs about 22 GNOT. So the lengths read from the
// vault's globals and fall back to the values generated here; the
// pattern rules are structural facts about what a handle looks like and
// stay in code.

const (
	defaultFreeMinLength = 5
	defaultFreeMaxLength = 63

	keyFreeMin = "freemin"
	keyFreeMax = "freemax"
)

// FreeMinLength is the shortest label the free tier will issue. Settable
// from the panel, because which lengths are worth money is a commercial
// judgement that moves.
func FreeMinLength() int {
	if v := nsdata.GetGlobal(keyFreeMin); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 63 {
			return n
		}
	}
	return defaultFreeMinLength
}

func FreeMaxLength() int {
	if v := nsdata.GetGlobal(keyFreeMax); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 63 {
			return n
		}
	}
	return defaultFreeMaxLength
}

/*
FreeLabelAllowed reports whether a label may be ISSUED on the free tier.

ISSUED, and never renewed. This is called by GrantFreeName and by
nothing else, deliberately: if the minimum length rises from three to
five, somebody who already holds a three-character free name keeps it
and keeps renewing it free. Tightening a rule must not reach backwards
and take away what was already given — that is the single fastest way to
make a giveaway cost more trust than it ever bought.

A name that LAPSES and is registered again is a new issuance, and gets
whatever the rules say that day. That is not retroactive; it is a
different name event.
*/
func FreeLabelAllowed(label string) bool {
	n := len(label)
	if n < FreeMinLength() || n > FreeMaxLength() {
		return false
	}
	// Pure digits: 1337, 420, years. Collectible, and no handle is one.
	digits := true
	for i := 0; i < n; i++ {
		if label[i] < '0' || label[i] > '9' {
			digits = false
			break
		}
	}
	if digits {
		return false
	}
	// aaaa — every character the same.
	same := true
	for i := 1; i < n; i++ {
		if label[i] != label[0] {
			same = false
			break
		}
	}
	if same {
		return false
	}
	// abab — a two-character cycle. Also collectible, also not a handle.
	if n >= 4 {
		cycle := true
		for i := 2; i < n; i++ {
			if label[i] != label[i-2] {
				cycle = false
				break
			}
		}
		if cycle {
			return false
		}
	}
	return true
}

package nslogic

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

/*
REBUILDING THE REGISTRY ON A NEW CHAIN.

WHY THIS EXISTS. gno.land replaces testnets rather than preserving them:
topaz-1 was superseded by sapphire-1 on twenty-four hours' notice and
every name registered on it went to zero. tools/snapshot.js keeps a
complete off-chain copy of the vault for exactly that morning. This is
the other half — the path that turns a snapshot back into a live
registry, so that people who paid for a name get that name back rather
than an apology.

THIS IS A BACKDOOR, AND IT IS TREATED AS ONE.

A function that can mint any name, to any address, with any registration
date, is precisely the thing that would make every name here worthless
if it could be reached whenever the admin felt like it. Ownership means
nothing if history is editable on demand. So the capability is not
merely admin-gated — admin-gated is what everything else here already
is, and it is not enough for this. It is a ONE-SHOT:

  - it starts closed, and on a chain where nothing needs restoring it is
    sealed immediately and can never be used at all;
  - opening it is a deliberate, separate, announced act with a deadline
    attached, so forgetting to close it is not the same as leaving it
    open forever;
  - sealing is IRREVERSIBLE. Sealed cannot be reopened. There is no
    argument that unseals it, including a good one;
  - it refuses to touch a name that already exists. It fills gaps in an
    empty registry; it cannot rewrite a live one.

WHERE THE SEAL LIVES, AND WHY IT IS NOT HERE. This realm holds no state
at all — that is the whole reason prices and names survive a logic
upgrade untouched. If the seal lived in this realm's variables it would
reset to "never opened" the moment a new generation was deployed, which
would make "irreversible" a lie with a two-hour shelf life. It lives in
the vault's global slot instead, so a new logic generation inherits a
seal it cannot talk its way out of.

WHAT THAT DOES AND DOES NOT GUARANTEE. It is a real barrier against
every accident and against this realm being reached later for something
it was not built for. It is not a barrier against the admin themselves,
who can deploy a further logic realm and have the vault trust it — but
that is already total control by definition, and no flag in a realm the
admin can replace was ever going to change it. What the seal gives is
the thing that actually matters in practice: the state is public, it is
checkable by anybody at any time through RestoreStatus, and moving it
backwards leaves a permanent trace on chain.

WHAT IT DELIBERATELY DOES NOT RESTORE. Marketplace listings and open
votes. Those live in their own realms, are intentions rather than facts,
and are re-creatable by the people who made them in one transaction
each. Re-materialising somebody's month-old asking price as though they
had just set it would be inventing a decision on their behalf.
*/

// The vault key holding the state of this whole mechanism.
const keyRestore = "restore"

// Restore states, stored as a string in the vault's global slot.
const (
	restoreNever  = ""       // never opened; the normal state forever
	restoreSealed = "sealed" // closed permanently; cannot be reopened
	restoreOpen   = "open:"  // followed by the unix second it lapses
)

// The longest a restore window may be left open. A restore is a day of
// work, not a season, and an unbounded window is just "open forever"
// spelled differently — the failure here is nobody remembering to seal
// it, so the deadline seals it for them.
const maxRestoreDays = 30

// RestoreStatus reports the state of the restore mechanism in a form a
// person can read, and is deliberately PUBLIC AND UNAUTHENTICATED.
// Anybody at all can check whether this registry currently has a door in
// it, without asking us and without trusting the answer we would give.
//
// Returns the state ("never", "open", "expired" or "sealed"), the unix
// second an open window lapses (0 otherwise), and how many records have
// been restored in the lifetime of this vault.
func RestoreStatus() (state string, deadline int64, restored int64) {
	st, d := readRestoreState(nsdata.GetGlobal(keyRestore), time.Now().Unix())
	return st, d, restoredCount()
}

// readRestoreState is the state machine on its own, with the clock passed
// in. Split out so the one piece of logic that decides whether the door
// is open can be tested exhaustively without a chain under it.
func readRestoreState(raw string, now int64) (state string, deadline int64) {
	switch {
	case raw == restoreSealed:
		return "sealed", 0
	case strings.HasPrefix(raw, restoreOpen):
		d, err := strconv.ParseInt(raw[len(restoreOpen):], 10, 64)
		if err != nil || d <= 0 {
			// An unparseable deadline is read as NO permission. The safe
			// reading of a door whose lock is broken is "shut" — a corrupt
			// value must never widen what somebody is allowed to do.
			return "sealed", 0
		}
		if now >= d {
			return "expired", d
		}
		return "open", d
	}
	return "never", 0
}

const keyRestoredCount = "restored"

func restoredCount() int64 {
	if v := nsdata.GetGlobal(keyRestoredCount); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			return n
		}
	}
	return 0
}

/*
THE RESTORE KEYS GO THROUGH THE VAULT'S RESERVED DOOR, and every refusal
panics.

They used to go through SetGlobalRecord, written for the first vault,
which had no reserved keys. This vault refuses "restore" and "restored"
there — and the three call sites threw the error away. So SealRestore
returned success and sealed nothing, OpenRestore returned success and
opened nothing (every Restore* call then said "never been opened", in the
middle of a paused migration), and the counter never moved. A returned
error in gno does not revert anything; ignoring one is how a control
reads as live while doing nothing.

SetReservedGlobalRecord is the machinery's own door, and the vault now
refuses to change a seal through it as well: a sealed restore stays
sealed whatever any logic realm asks, so a future logic generation
cannot talk its way out of it either.
*/
func setRestoreKey(cur realm, key, value string) {
	if err := nsdata.SetReservedGlobalRecord(cross(cur), key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

func bumpRestored(cur realm, n int64) {
	setRestoreKey(cur, keyRestoredCount, strconv.FormatInt(restoredCount()+n, 10))
}

/*
assertNotRestoring CLOSES REGISTRATION WHILE A RESTORE WINDOW IS OPEN
(re-audit 2026-10-16, M-4). The window opens on an empty registry, and the
snapshots it replays are committed to the repository, so the list of who
held what is public: anybody could register a holder's name before its
batch arrived — at the genesis price, before the price rules were back —
and the holder never got it back, while the batch holding it reverted and
stopped the run. Every door that creates a name, or makes a free one
sellable, passes this: RegisterName and RegisterNameRef, RedeemCredit and
RegisterFor, GrantFreeName, UpgradeFreeName (and the lab's RegisterLabName).
Sealed, or lapsed, the registry sells again.
*/
func assertNotRestoring() {
	if st, _ := readRestoreState(nsdata.GetGlobal(keyRestore), time.Now().Unix()); st == "open" {
		panic("nslogic: the registry is being restored; registration reopens once the restore is sealed")
	}
}

// assertRestoring is the gate every Restore* function passes through.
func assertRestoring(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	state, _, _ := RestoreStatus()
	switch state {
	case "open":
		return
	case "sealed":
		panic("nslogic: restore was sealed and cannot be reopened. This is " +
			"not recoverable by design — a registry whose history can be " +
			"rewritten on request does not have owners, it has guests.")
	case "expired":
		panic("nslogic: the restore window has lapsed. Deploy a fresh vault " +
			"and open a new window there; an expired one does not reopen.")
	}
	panic("nslogic: restore has never been opened. Call OpenRestore first, " +
		"and mean it.")
}

// OpenRestore opens the window, once, for a bounded number of days.
//
// Only ever valid on a chain where the registry is EMPTY because the
// previous chain was retired. It cannot be called on a vault that has
// been sealed, and it cannot be called twice.
func OpenRestore(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "OpenRestore", "days", fmtInt(days))

	state, _, _ := RestoreStatus()
	if state != "never" {
		panic("nslogic: restore may be opened exactly once per vault; this " +
			"one is already " + state + ". A door that reopens is a door.")
	}
	if days < 1 || days > maxRestoreDays {
		panic("nslogic: a restore window must be between 1 and " +
			strconv.Itoa(maxRestoreDays) + " days")
	}
	/* THE PRECONDITION THE COMMENT ABOVE ALREADY CLAIMS.
	   "Only ever valid on a chain where the registry is EMPTY" was a
	   statement of intent that nothing enforced, so the window was
	   openable on a populated vault. The record restorers all refuse an
	   existing record, but RestoreNameField does not — it writes any
	   extension key on any EXISTING name, which includes the payment
	   addresses the site renders on a name's pay page. That is a way to
	   redirect somebody else's incoming money using only the admin key,
	   without the timelock and public event that granting a fresh logic
	   realm would cost. Now it is what it said it was. */
	/* NAMES ONLY, not domains. A registry is now born with its domains
	   (genesis), so "no domains" can never be true again and the guard
	   would have made disaster recovery impossible on every new chain.
	   The hazard it exists for is RestoreNameField writing onto EXISTING
	   NAMES — somebody's pay address — and only names carry that. */
	if _, n, _, _ := nsdata.Sizes(); n != 0 {
		panic("nslogic: restore is for a registry holding no names yet; " +
			"this one already holds records")
	}
	// TIMELOCKED (timelock.gno). This is the door that mints any name to
	// anybody with any date; on a fresh registry, before the first name and
	// before SealRestore, a stolen admin key could otherwise open it at once.
	requireAction(cur, actionID("OpenRestore", strconv.FormatInt(days, 10)))
	deadline := time.Now().Unix() + days*86400
	setRestoreKey(cur, keyRestore, restoreOpen+strconv.FormatInt(deadline, 10))
}

// SealRestore closes the door permanently. Valid from any state,
// including "never" — which is how it should be called on a chain that
// has nothing to restore, so that the capability is provably dead rather
// than merely unused.
//
// There is no matching unseal, and adding one later would defeat every
// word written at the top of this file.
func SealRestore(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SealRestore")
	setRestoreKey(cur, keyRestore, restoreSealed)
	// Read back, not assumed: this call used to report success while the
	// state stayed "never".
	if st, _, _ := RestoreStatus(); st != "sealed" {
		panic("nslogic: the seal did not land; restore reads " + st)
	}
}

/*
RestoreDomain re-creates one domain with its original dates.

ORDER MATTERS: domains before their names. The vault refuses to register
a name under a domain that does not exist or had lapsed at the moment
the name claims to have been registered, which is correct behaviour and
also exactly the order a snapshot should be replayed in.

The vault's own registration path sets `registered` to whatever instant
it is handed and derives the expiry from the term length, so the
registration date is restored by passing the ORIGINAL one, and the
expiry is then corrected to the recorded value rather than a computed
one. Anything else would quietly hand everybody a fresh term.
*/
func RestoreDomain(cur realm, label string, owner address, registered, expires, ttl int64, frozen bool) {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreDomain", "label", label, "owner", owner.String())
	if nsdata.DomainExists(label) {
		panic("nslogic: " + label + " already exists; restore fills an empty " +
			"registry and never overwrites a live record")
	}
	if registered <= 0 || expires <= 0 {
		panic("nslogic: a restored record needs its original dates")
	}
	if err := nsdata.RegisterDomainRecord(cross(cur), label, owner, registered); err != nil {
		panic("nslogic: " + err.Error())
	}
	nsdata.SetDomainExpiryRecord(cross(cur), label, expires)
	ttl = clampTTL(ttl)
	if ttl != 0 {
		if err := nsdata.SetDomainTTLRecord(cross(cur), label, ttl); err != nil {
			panic("nslogic: " + err.Error())
		}
	}
	if frozen {
		nsdata.SetDomainFrozen(cross(cur), label, true)
	}
	bumpRestored(cur, 1)
}

// RestoreName re-creates one name. See RestoreDomain on ordering and on
// why the dates are passed rather than computed.
//
// isNFT is carried across under its old name so snapshot blobs stay
// readable, and now means PAID: false restores a free-tier name with the
// hold on its token, so a restore can never quietly make a free name
// sellable.
func RestoreName(cur realm, label, domainLabel string, owner address, registered, expires, ttl int64, frozen, isNFT bool) {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreName", "label", label, "domain", domainLabel, "owner", owner.String())
	if nsdata.NameExists(label, domainLabel) {
		panic("nslogic: " + label + "*" + domainLabel + " already exists; " +
			"restore fills an empty registry and never overwrites a live record")
	}
	if registered <= 0 || expires <= 0 {
		panic("nslogic: a restored record needs its original dates")
	}
	// RestoreNameRecord, not RegisterNameRecord: it ADOPTS a token the
	// ledger already holds, which is the whole point of a migration —
	// records move, tokens do not. If the ledger's holder is not the
	// snapshot's owner, the record is written for the holder and the
	// snapshot's profile is not replayed onto it.
	if err := nsdata.RestoreNameRecord(cross(cur), label, domainLabel, owner, registered, isNFT); err != nil {
		panic("nslogic: " + err.Error())
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
	ttl = clampTTL(ttl)
	if ttl != 0 {
		if err := nsdata.SetNameTTLRecord(cross(cur), label, domainLabel, ttl); err != nil {
			panic("nslogic: " + err.Error())
		}
	}
	if frozen {
		nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
	}
	bumpRestored(cur, 1)
}

/*
RestoreNames replays many names in ONE transaction.

WHY A BLOB AND NOT A LOOP OF CALLS. A restore is done in one sitting
against a clock: the window is bounded and the people whose names are
missing are watching. One transaction per name is one signature per
name, and at a few hundred names that is an afternoon of clicking during
which a single mistimed refresh loses the thread. The compact form here
is unpleasant to read and it is the difference between a restore that
gets finished and one that gets abandoned half way.

The format is records separated by "|", fields separated by ",":

	label,domain,owner,registered,expires,ttl,frozen,isNFT

Neither a label nor a domain may contain "," or "|" — the character set
is enforced at registration — and an address contains neither, so the
split is unambiguous. tools/snapshot.js writes the JSON this is built
from; see tools/restore-blob.js for the conversion.

It stops at the first bad record and panics, taking the whole
transaction with it. That is deliberate: a partial batch that silently
skipped four names would leave four people without theirs and nothing
anywhere saying which four.
*/
func RestoreNames(cur realm, blob string) int {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreNames", "bytes", fmtI(len(blob)))
	if blob == "" {
		panic("nslogic: nothing to restore")
	}
	recs := strings.Split(blob, "|")
	if len(recs) > 50 {
		panic("nslogic: at most 50 records per call, or the transaction " +
			"runs out of gas half way and it is unclear what landed")
	}
	done := 0
	for i, rec := range recs {
		if rec == "" {
			continue
		}
		r := parseRestoreRecord(rec, i)
		if nsdata.NameExists(r.label, r.domain) {
			panic("nslogic: record " + strconv.Itoa(i) + " (" + r.label + "*" + r.domain +
				") already exists; restore never overwrites a live record")
		}
		if err := nsdata.RestoreNameRecord(cross(cur), r.label, r.domain, r.owner, r.registered, r.isNFT); err != nil {
			panic("nslogic: record " + strconv.Itoa(i) + ": " + err.Error())
		}
		nsdata.SetNameExpiryRecord(cross(cur), r.label, r.domain, r.expires)
		if r.ttl != 0 {
			if err := nsdata.SetNameTTLRecord(cross(cur), r.label, r.domain, r.ttl); err != nil {
				panic("nslogic: record " + strconv.Itoa(i) + ": " + err.Error())
			}
		}
		if r.frozen {
			nsdata.SetNameFrozen(cross(cur), r.label, r.domain, true)
		}
		done++
	}
	bumpRestored(cur, int64(done))
	return done
}

// restoreRec is one parsed line of the blob.
type restoreRec struct {
	label, domain string
	owner         address
	registered    int64
	expires, ttl  int64
	frozen, isNFT bool
}

/*
parseRestoreRecord reads one record and refuses anything it is not sure
about.

EVERY CHECK HERE IS A PANIC AND NOT A SKIP. The blob is machine-written
from a snapshot, so a malformed record does not mean "this one name is
odd", it means the file is not what it was believed to be — and the
worst outcome available is a restore that appears to succeed while
quietly dropping the records it could not read. Somebody would find out
months later when one person asked where their name went.
*/
func parseRestoreRecord(rec string, i int) restoreRec {
	f := strings.Split(rec, ",")
	if len(f) != 8 {
		panic("nslogic: record " + strconv.Itoa(i) + " has " +
			strconv.Itoa(len(f)) + " fields, expected 8 " +
			"(label,domain,owner,registered,expires,ttl,frozen,isNFT)")
	}
	if f[0] == "" || f[1] == "" {
		panic("nslogic: record " + strconv.Itoa(i) + " has no name")
	}
	out := restoreRec{
		label:      f[0],
		domain:     f[1],
		owner:      address(f[2]),
		registered: mustSecs(f[3], i, "registered"),
		expires:    mustSecs(f[4], i, "expires"),
		ttl:        ttlSecs(f[5], i),
		frozen:     f[6] == "1",
		isNFT:      f[7] == "1",
	}
	if !out.owner.IsValid() {
		panic("nslogic: record " + strconv.Itoa(i) + " has an invalid owner address")
	}
	if out.registered <= 0 || out.expires <= 0 {
		panic("nslogic: record " + strconv.Itoa(i) + " is missing its original dates")
	}
	// An expiry before the registration is not a record, it is a
	// corruption, and restoring it would create a name that was already
	// reclaimable the day it was bought.
	if out.expires < out.registered {
		panic("nslogic: record " + strconv.Itoa(i) + " expires before it was registered")
	}
	return out
}

func mustSecs(s string, i int, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v < 0 {
		panic("nslogic: record " + strconv.Itoa(i) + " has a bad " + what)
	}
	return v
}

/*
ttlSecs reads a TTL and caps it at maxTTL (name.gno). A holder may have set
any non-negative int64 before the cap existed, and a snapshot written by
JavaScript rounded such a value above 2^53 — MaxInt64 came back as
9223372036854776000, which no int64 holds — so the whole batch of fifty
reverted (re-audit 2026-10-16, M-3). A run of digits too large to parse is
read as the longest a TTL may be; anything else malformed still refuses
the record.
*/
func ttlSecs(s string, i int) int64 {
	if v, err := strconv.ParseInt(s, 10, 64); err == nil && v >= 0 {
		return clampTTL(v)
	}
	if s != "" && len(s) <= 40 && strings.Trim(s, "0123456789") == "" {
		return maxTTL
	}
	panic("nslogic: record " + strconv.Itoa(i) + " has a bad ttl")
}

func clampTTL(v int64) int64 {
	if v > maxTTL {
		return maxTTL
	}
	return v
}

// RestoreNameField and RestoreDomainField put back a record's extension
// keys — profiles, cross-chain addresses, tier markers, and a domain's
// pricing rules. Separate calls because the extension slot has no fixed
// shape by design, which is the same reason the snapshot captures it by
// enumeration rather than by schema.
func RestoreNameField(cur realm, label, domainLabel, key, value string) {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreNameField", "label", label, "domain", domainLabel, "key", key)
	/* ONLY ONTO A RECORD A RESTORE WROTE, AND ONLY FOR ITS HOLDER.

	   Profile fields include pay addresses, so replaying one is replaying
	   where money goes. Two audit findings meet here: a name sold between
	   the snapshot and the restore would have had the seller's addresses
	   written onto the buyer's name, and a name a user registered DURING
	   the restore window could have had its pay fields rewritten with the
	   admin key alone. RestoredFor is set only by RestoreNameRecord, and
	   only when the ledger's holder matched the snapshot.

	   Skipped rather than panicked, deliberately: a blob of fields rides in
	   one transaction, and one sold name must not abort everybody else's
	   restore. tools/restore-blob.js reads the fields back afterwards. */
	rf := nsdata.RestoredFor(label, domainLabel)
	if rf == "" || nsdata.GetNameOwner(label, domainLabel) != rf {
		return
	}
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

func RestoreDomainField(cur realm, label, key, value string) {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreDomainField", "label", label, "key", key, "value", value)
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestoreGlobal puts back the vault's global slot — where the default
// price, the referral tiers and the seasonal card effects live.
//
// It refuses to write the restore keys themselves. Without that, a
// snapshot taken while a window was open would, on being replayed,
// cheerfully restore the open window along with everything else — and a
// seal that a backup file can undo is not a seal.
func RestoreGlobal(cur realm, key, value string) {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreGlobal", "key", key, "value", value)
	if key == keyRestore || key == keyRestoredCount {
		panic("nslogic: the restore mechanism does not restore itself")
	}
	// NOR A ROLE, the rule genesis keeps (nsdata refusedInGenesis): the
	// granter, the keeper, the lab nomination or anything address-valued
	// is a power, set deliberately on the chain it belongs to, never by a
	// backup file round the timelock (re-audit 2026-10-16, L-7). SKIPPED,
	// not refused, like a stale reverse pointer: globals travel fifty to a
	// transaction, and one sandbox's lab nomination must not stop the whole
	// restore (review follow-up). The AdminAction above says it was asked.
	if key == keyGranter || key == keyKeeper || key == "labdomain" || looksLikeAddress(value) {
		chain.Emit("RestoreSkipped", "key", key, "why", "a role or an address; name it again through its own setter")
		return
	}
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestoreAccountField puts back one field of the per-address store —
// credits and their redemptions, referral counts. Without it a rebuilt
// registry would forget who had already spent their free name, and the
// migration grant could be claimed twice.
func RestoreAccountField(cur realm, owner address, key, value string) {
	assertRestoring(cur)
	emitAdmin(cur, "RestoreAccountField", "owner", owner.String(), "key", key, "value", value)
	// A credit's grant time is never in the future: one written through
	// this door would escape every void recovery could ever declare.
	if key == keyCredit && value != "" {
		if c := parseCredit(value); c.granted > 0 || c.used > 0 {
			if now := time.Now().Unix(); c.at > now {
				c.at = now
			}
			value = c.encode()
		}
	}
	if err := nsdata.SetAccountRecord(cross(cur), owner, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestorePrimary puts back reverse resolution — which name an address
// answers to. Registration already sets this for an owner who had none,
// so this exists for the owners who had chosen a different one.
//
// SKIPPED, NOT REFUSED, when the vault would refuse it — the name is not
// there, or the ledger says somebody else holds it (a sale leaves the
// seller's pointer behind): pointers travel fifty to a transaction, and one
// stale pointer must not revert everybody else's (re-audit 2026-10-16, M-3).
func RestorePrimary(cur realm, owner address, label, domainLabel string) {
	assertRestoring(cur)
	emitAdmin(cur, "RestorePrimary", "owner", owner.String(), "label", label, "domain", domainLabel)
	if !nsdata.NameExists(label, domainLabel) || nsdata.GetNameOwner(label, domainLabel) != owner {
		return
	}
	if err := nsdata.SetPrimaryRecord(cross(cur), owner, label, domainLabel); err != nil {
		panic("nslogic: " + err.Error())
	}
}

package nslogic

import (
	"strconv"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// How far ahead a name may be paid.
//
// Renewal was unbounded. RenewNameRecord adds one term to the previous
// due date and asks no further questions, so a holder pressing renew
// seven times bought seven years of runway, and nothing anywhere said
// that was not intended. It is a bug in two directions at once:
//
//   - Free domains have a base price of zero. Renewal is free too, so a
//     script could take every good name under *gnoland and hold it for a
//     century for the cost of gas. There is no economic brake on a free
//     name at all; the term limit IS the brake.
//   - A paid name held fifty years ahead is fifty years of a promise we
//     have made against a rate written by hand and a testnet that will
//     be replaced. Selling that is easy and honouring it is not.
//
// The limit is RUNWAY, not total lifetime: at most N years may be
// outstanding at any moment. Nobody is stopped from holding a name
// forever — they renew as the runway burns down, which is the same
// arrangement every domain registrar has always used and the one people
// already understand.
//
// Per domain first, then a project-wide default, so a free domain can be
// capped at one year without capping anything else.
const (
	keyMaxTerm      = "maxterm" // domain extra AND global: years of runway
	defaultMaxTerm  = int64(5)
	maxMaxTermYears = int64(100)
)

// MaxTermYears is the cap that applies to names under this domain.
func MaxTermYears(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyMaxTerm); v != "" {
		if y, err := strconv.ParseInt(v, 10, 64); err == nil && y > 0 {
			return y
		}
	}
	if v := nsdata.GetGlobal(keyMaxTerm); v != "" {
		if y, err := strconv.ParseInt(v, 10, 64); err == nil && y > 0 {
			return y
		}
	}
	return defaultMaxTerm
}

// SetMaxTerm caps a single domain, or the whole project when the domain
// label is empty. A domain's own cap always wins, so tightening one free
// domain does not disturb the rest.
func SetMaxTerm(cur realm, domainLabel string, years int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	emitAdmin(cur, "SetMaxTerm", "domain", domainLabel, "years", fmtInt(years))
	if years < 1 || years > maxMaxTermYears {
		panic("nslogic: term cap must be 1-100 years")
	}
	v := strconv.FormatInt(years, 10)
	if domainLabel == "" {
		setGlobal(cur, keyMaxTerm, v)
		return
	}
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: unknown domain")
	}
	if err := nsdata.SetDomainExtraRecord(cross(cur), domainLabel, keyMaxTerm, v); err != nil {
		panic(err)
	}
}

// RenewalsLeft is how many more years may be added to a name right now.
// Zero means the renew button should be off, and the site reads this
// rather than doing the arithmetic itself — the cap can be per domain,
// and a page that guesses it will guess wrong on exactly the domains
// where it matters.
//
// An unregistered name reports the full allowance: nothing is holding
// runway yet.
func RenewalsLeft(label, domainLabel string) int64 {
	maxYears := MaxTermYears(domainLabel)
	if !nsdata.NameExists(label, domainLabel) {
		return maxYears
	}
	term := nsdata.GetTermLength()
	if term <= 0 {
		return 0
	}
	_, _, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	return renewalsLeft(expires, time.Now().Unix(), term, maxYears)
}

// renewalsLeft is the arithmetic on its own, so it can be tested without
// a chain under it.
//
// Runway is measured from NOW, not from the registration date, so a name
// deep in its grace period counts as zero rather than as a negative that
// would then read as extra room. Years already bought round UP: a name
// with thirteen months left is holding two of its five, because the
// alternative lets somebody sit permanently at four-years-and-eleven-
// months and renew every month forever.
func renewalsLeft(expires, now, term, maxYears int64) int64 {
	if term <= 0 {
		return 0
	}
	runway := expires - now
	if runway < 0 {
		runway = 0
	}
	left := maxYears - (runway+term-1)/term
	if left < 0 {
		return 0
	}
	return left
}

// assertRoomToRenew is the enforcement. It runs before payment is taken,
// so a rejected renewal costs gas and nothing else — taking the money
// first and reverting would work too, but only because a panic reverts,
// and depending on that for a refund is a habit that eventually meets a
// path where it is not true.
func assertRoomToRenew(label, domainLabel string) {
	if RenewalsLeft(label, domainLabel) > 0 {
		return
	}
	panic(ufmt.Sprintf(
		"nslogic: %s*%s is already paid %d years ahead, which is the limit. Renew again when it has run down.",
		label, domainLabel, MaxTermYears(domainLabel)))
}

package nslogic

import (
	"math"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

/*
THE ADMIN KEY IS NOT THE REGISTRY ANY MORE.

Until this file, every admin call here was instant, and an audit used them
to take a paid name from its holder, make every name in grace reclaimable,
delete live names and redirect all revenue — in one transaction, with a
48-hour timelock in force and nothing ever proposed (audit H-1). The
vault's timelock guarded only the trust set and the roles.

So the calls are now in three classes:

	TIMELOCKED — anything that destroys or moves names or money, or
	rewrites pricing rules a single edit could zero: DeleteDomain,
	SetTermLength, SetGracePeriod, SetTreasury, ReassignDomain,
	UnfreezeName and UnfreezeNames (up to 64 names behind one action),
	SetGranter and SetKeeper (naming one; removing stays
	instant), SetDomainLengthRules, SetDomainNameOverrides,
	SetGlobalLengthRules, SetPremiumNames, OpenRestore, and SetMarketFee
	whenever the change could raise a fee. The admin proposes the exact call in the vault —
	nsdata.ProposeAction("<Function> <arg> <arg>…") — waits out the
	vault's delay, during which recovery can cancel it, and then makes
	the call, which spends the proposal. A refusal names the exact id to
	propose.

	BOUNDED — the price levers that must move day to day: SetUsdRate,
	SetDefaultNamePrice, SetDomainBasePrice, SetClaimMaxPrice. Instant
	inside a bound that depends on WHICH WAY the change moves a name's
	cost (Ely, 2026-10-16); anything bigger, or sooner, goes through the
	timelock the same way.

	  CHEAPER — the direction a thief needs: the rate down, a price cut,
	  the credit cap raised. At most cheapMaxPct of the current value at
	  once, at most once per cheapCooldown (an hour). A stolen key can
	  move each lever a quarter an hour, in public — the rate and a base
	  price compound, so a name's price can fall by about 44% in the first
	  hour (0.75 x 0.75), and to 0.5625^h of list after h hours — rather
	  than take every name for dust in one block. Two levers per name, not
	  three: an unpriced domain's first own price shares the default's
	  clocks (authorizeTweakOn).

	  DEARER — the rate up after GNOT crashes, a price raised, the credit
	  cap cut. Up to dearMaxFactor at once (four times: GNOT falling 75%
	  is followed in ONE update), at most once per dearCooldown (ten
	  minutes). Its theft costs an outage — names too dear to buy — never
	  a name or a coin. Which is only true while no lever is tied to
	  another: the credit cap used to fall back to the default price, so a
	  dearer default walked the cap the cheap way, four times every ten
	  minutes (re-audit 2026-10-16, H-1). It stands alone now, and unset it
	  covers nothing (credits.gno).

	Each direction keeps its own clock, so a dearer step in between does
	not reopen the cheaper hour. The guardian bot revoking the logic realm
	on the first AdminAction it did not expect is what keeps that hour
	short. The KEEPER (keeper.gno) moves the rate inside the same bounds,
	on the same clocks as the admin, and never through the timelock.

	INSTANT — everything that cannot take anything from anybody: freezing
	(the protective direction), opening and closing domains, the block
	list, free-tier and credit grants, limits, TTLs, art, and ClearKeeper.

THE CLOCK IS THE VAULT'S, deliberately: a new logic realm cannot shorten a
delay it does not hold, and the delay itself only changes through the
vault's own timelock.
*/

// actionID is the canonical name of one call: the function and its
// arguments, separated by single spaces, an empty argument written "".
// It is what the admin proposes and what the call spends, so a proposal
// authorizes exactly one change with exactly those arguments.
func actionID(fn string, args ...string) string {
	id := fn
	for _, a := range args {
		if a == "" {
			a = `""`
		}
		if strings.ContainsAny(a, " \t\n\r") {
			panic("nslogic: an argument to a timelocked call may not contain spaces: " + a)
		}
		id += " " + a
	}
	return id
}

// assertActionReady explains, before anything is written, why a
// timelocked call cannot run yet. The vault's ConsumeAction is the
// authority; this only makes the refusal say what to do.
func assertActionReady(id string) {
	if nsdata.EvictionPending() {
		panic("nslogic: recovery is replacing the admin; timelocked changes wait until that lands, and the admin's proposals die with it")
	}
	at, expires, _ := nsdata.GetAction(id)
	now := time.Now().Unix()
	switch {
	case at == 0:
		panic("nslogic: this change waits out the vault timelock. Propose exactly `" + id +
			"` with nsdata.ProposeAction from the admin key, then call again once it matures; recovery may cancel it until then")
	case now < at:
		panic("nslogic: `" + id + "` is proposed and matures at unix " + strconv.FormatInt(at, 10))
	case now >= expires:
		panic("nslogic: `" + id + "` expired at unix " + strconv.FormatInt(expires, 10) + "; propose it again")
	}
	if !nsdata.ActionReady(id) {
		panic("nslogic: `" + id + "` was proposed by a previous admin; propose it again")
	}
}

// requireAction lets a timelocked call through only on a matured proposal
// for exactly this call, and spends it.
func requireAction(cur realm, id string) {
	assertActionReady(id)
	nsdata.ConsumeAction(cross(cur), id)
}

// -- bounded instant changes --

const (
	// A move that makes names CHEAPER (the rate down, a price cut, the
	// credit cap raised) is at most this much of the current value, and a
	// setting moves that way instantly at most once per cheapCooldown.
	cheapMaxPct   = 25
	cheapCooldown = 60 * 60

	// A move that makes names DEARER may go up to dearMaxFactor times (or
	// down to 1/dearMaxFactor, for the credit cap) at once — four: GNOT
	// falling 75% is followed in one update — at most once per dearCooldown.
	dearMaxFactor = 4
	dearCooldown  = 10 * 60

	// The highest rate SetUsdRate accepts: a million GNOT to the dollar.
	// Like maxPriceUSD, a ceiling no real market reaches, low enough that
	// price times rate cannot overflow unnoticed (see NamePrice).
	maxRate = int64(1_000_000_000_000)
)

/*
lastTweak is the ONE piece of state this realm keeps: when each bounded
setting last moved, one clock per direction. Not a record — losing it
costs nothing but one early tweak — so it lives here rather than in the
vault, and a logic swap simply starts it empty.
*/
var lastTweak avl.Tree

func clockKey(setting string, dearer bool) string {
	if dearer {
		return setting + ":dear"
	}
	return setting + ":cheap"
}

/*
authorizeTweak lets a bounded setting move from `old` to `next` instantly
when the move stays inside its direction's bound and that direction's clock
has rested; otherwise it needs a matured proposal of `id`, which it spends.
`dearer` says whether the move makes names dearer — for the rate and the
prices that is a rise, for the credit cap a fall — and the caller, which
knows what its setting means, decides it. A move to or from zero is never
an instant step: a free domain, or a price restored from free, is a
decision.
*/
func authorizeTweak(cur realm, setting string, old, next int64, dearer bool, id string) {
	authorizeTweakOn(cur, []string{setting}, old, next, dearer, id)
}

/*
authorizeTweakOn is authorizeTweak for a move that rides more than one
clock: every clock named must have rested, and all of them are stamped.

An unpriced domain's base price IS the default, so its first price of its
own is measured against the default — after the default has already been
cut, on a clock of its own. Rate, default and domain then each took 25% in
one block: 0.75^3 of the price, 58% off, not the two levers (about 44%)
this file promises (re-audit 2026-10-16, L-1). So that first own price
rides the default's clocks too (domain.gno): in any hour, either the
default or an unpriced domain's first own price moves, never both.
*/
func authorizeTweakOn(cur realm, settings []string, old, next int64, dearer bool, id string) {
	if next == old {
		return
	}
	now := time.Now().Unix()
	if nsdata.ActionReady(id) {
		nsdata.ConsumeAction(cross(cur), id)
		for _, st := range settings {
			lastTweak.Set(clockKey(st, dearer), now)
		}
		return
	}
	setting := settings[0]
	if !withinStep(old, next, dearer) {
		panic("nslogic: " + stepRefusal(setting, old, next, dearer) +
			"; anything larger waits out the vault timelock: propose `" + id +
			"` with nsdata.ProposeAction and call again once it matures")
	}
	for _, st := range settings {
		if !clockRested(st, dearer, now) {
			panic("nslogic: " + restRefusal(st, dearer) +
				"; wait, or put this through the vault timelock: propose `" + id + "` with nsdata.ProposeAction")
		}
	}
	for _, st := range settings {
		lastTweak.Set(clockKey(st, dearer), now)
	}
}

// withinStep is the bound on its own. New values are capped (maxPriceUSD,
// maxRate); an old value stored before the caps, or by a restore, is not,
// so anything too large to multiply safely is simply not an instant step.
func withinStep(old, next int64, dearer bool) bool {
	if old <= 0 || next <= 0 || old > math.MaxInt64/100 || next > math.MaxInt64/100 {
		return false
	}
	if dearer {
		hi, lo := next, old
		if lo > hi {
			hi, lo = lo, hi
		}
		return hi <= lo*dearMaxFactor
	}
	d := next - old
	if d < 0 {
		d = -d
	}
	return d*100 <= old*cheapMaxPct
}

// inheritClocks gives `to` every last-move time of `from` that is later
// than its own, in both directions: a setting that starts out as another
// one's value starts on that one's clocks.
func inheritClocks(to, from string) {
	for _, dearer := range []bool{true, false} {
		f := lastTweak.Get(clockKey(from, dearer))
		if f == nil {
			continue
		}
		if t := lastTweak.Get(clockKey(to, dearer)); t == nil || t.(int64) < f.(int64) {
			lastTweak.Set(clockKey(to, dearer), f.(int64))
		}
	}
}

func clockRested(setting string, dearer bool, now int64) bool {
	rest := int64(cheapCooldown)
	if dearer {
		rest = dearCooldown
	}
	v := lastTweak.Get(clockKey(setting, dearer))
	return v == nil || now-v.(int64) >= rest
}

func stepRefusal(setting string, old, next int64, dearer bool) string {
	span := strconv.FormatInt(old, 10) + " to " + strconv.FormatInt(next, 10)
	if dearer {
		return setting + " may make names dearer by at most " + strconv.Itoa(dearMaxFactor) + "x at once (" + span + ")"
	}
	return setting + " may make names cheaper by at most " + strconv.Itoa(cheapMaxPct) + "% at once (" + span + ")"
}

func restRefusal(setting string, dearer bool) string {
	if dearer {
		return setting + " made names dearer less than ten minutes ago"
	}
	return setting + " made names cheaper less than an hour ago"
}

// LastTweak reports when a bounded setting last moved instantly in each
// direction (unix seconds, 0 for never), so the panel can say when the
// next step each way is due: dearer after ten minutes, cheaper after an hour.
func LastTweak(setting string) (dearer, cheaper int64) {
	if v := lastTweak.Get(clockKey(setting, true)); v != nil {
		dearer = v.(int64)
	}
	if v := lastTweak.Get(clockKey(setting, false)); v != nil {
		cheaper = v.(int64)
	}
	return dearer, cheaper
}

// -- keys only their own setters may write --

/*
managedGlobal reports whether SetGlobal must refuse a key, because a
setter in this realm owns it — bounded, timelocked or validated. The
escape hatch wrote any key, so it walked straight round every one of those
rules: SetGlobal("rateUgnotPerUsd", "1") was a one-call way to sell every
name for dust.
*/
func managedGlobal(key string) bool {
	switch key {
	case keyDefaultPrice, keyRate, keyMarketFee, keyGranter, keyKeeper, keyGlobalLens,
		keyRefCut, keyRefDisc, keyRefWin, keyMaxTerm, keyFreeMin, keyFreeMax,
		keyClaimEnd, keyClaimMax, keyRestore, keyRestoredCount, keyPaid, keyLegacy, "labdomain":
		return true
	}
	return strings.HasPrefix(key, keyPremium) || strings.HasPrefix(key, blockKeyStem)
}

// managedDomainKey is the same rule for SetDomainField.
func managedDomainKey(key string) bool {
	switch key {
	case keyPrice, keyLens, keyNames, keyOpen, keyFreeDomain, keyMaxTerm, keyPaid:
		return true
	}
	return false
}

// Package nslogic is the swappable "business rules" half of the split
// (NOTES.md §9t). It holds every piece of policy that might reasonably
// change — pricing, character validation, payment/refund, freeze rules,
// transfer restrictions — and no persistent records of its own. (One
// throttle, not a record: when each bounded price setting last moved,
// timelock.gno's lastTweak. A logic swap starts it empty and loses
// nothing.)
//
// Every mutation here ends by calling into nsdata's narrow Record/Raw
// API via cross(cur). nsdata trusts whichever address is currently wired
// up as trustedLogic to have done its own authorization checks
// correctly, so THIS realm is where "is the caller allowed to do this"
// actually lives. If a bug is found here, admin deploys a fixed nslogic
// and re-points the vault at it (ProposeTrustedLogicGrant, then
// ExecutePending after the timelock) — no data migration,
// records and config untouched.
//
// Deliberately reads config fresh from nsdata on every call rather than
// caching it. The one thing that cannot be read fresh is a COMPILED
// regex — avl trees store the pattern string, not the compiled object —
// so that one value is cached, and the cache is validated against
// nsdata on every use.
package nslogic

const (
	ugnot    = "ugnot"
	bpsDenom = 10_000
)

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nym-mnsrehearsal001/nsdata/v3"
)

// THE LABEL RULE IS WRITTEN OUT, NOT COMPILED.
//
// It used to be a regexp, and that regexp was the single most expensive
// thing in this realm — by a wide margin, and not by a little. Measured
// on sapphire-1 with vm/qstorage against purpose-built probe realms:
//
//	a realm with code and no package-level state      2,711 bytes
//	the same realm plus ONE compiled regexp         154,877 bytes
//
// A compiled regexp is an object graph, and gno charges 100 ugnot for
// every byte of it, forever. That one variable was 15.2 GNOT of the
// 22.5 GNOT it costs to deploy this realm — about 68% of the bill, to
// enforce a rule that fits in thirty lines.
//
// The second regexp was worse, because it was compiled LAZILY and cached
// in a package-level var. That does not avoid the cost, it MOVES it: the
// first person to register a name after a fresh deploy would have had
// their transaction grow this realm's storage by 150KB and been charged
// ~15 GNOT of deposit for it. Confirmed by probe, not inferred — a realm
// deployed at 2,711 bytes went to 154,149 the moment one call compiled
// and cached a regexp, billed to the caller. Somebody buying a ten-cent
// name would have been asked for fifteen GNOT.
//
// The hand-written version is also 6x cheaper in gas on every call
// (1.06M against 6.67M), so there is no axis on which the regexp was
// the better choice. It read better. That was the whole of its case.
//
// WHAT THIS COSTS US. The pattern is no longer admin-tunable at runtime:
// changing the rule now means redeploying this realm. That is a fair
// trade at 7 GNOT a deploy, it was never a rule that should change
// casually, and SetLabelPattern refuses anything but the implemented
// pattern so the stored string can never describe rules the code does
// not enforce.

// labelRule is the pattern this realm implements, kept as a string so
// nsdata, the error messages and the site all quote the same thing.
const labelRule = `^[a-z0-9]+(-[a-z0-9]+)*$`

// matchesLabelRule is that pattern, by hand: lowercase letters and
// digits, single hyphens between them, none at either end.
func matchesLabelRule(s string) bool {
	if s == "" {
		return false
	}
	prevHyphen := true // a leading hyphen is not allowed
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
			prevHyphen = false
		case c == '-':
			if prevHyphen {
				return false // leading, or two in a row
			}
			prevHyphen = true
		default:
			return false
		}
	}
	return !prevHyphen // nor a trailing one
}

// looksLikeAddress was `^g1[a-z0-9]{20,38}$`. Anything shaped like a real
// gno.land address is refused as a label, so a name can never be mistaken
// for a raw wallet address in a UI.
func looksLikeAddress(s string) bool {
	if len(s) < 22 || len(s) > 40 || !strings.HasPrefix(s, "g1") {
		return false
	}
	for i := 2; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') {
			return false
		}
	}
	return true
}

// validateLabel — same policy as the original single-realm build (see
// NOTES.md for the ENS/Starname/r/sys/users research behind it). The
// length bounds are still read from nsdata, so they survive a swap of
// this realm; the character rule is now this realm's own.
//
// Call sites, and why: RegisterName/RegisterDomain only (both the
// first-ever mint AND reclaiming a past-grace slot — a reclaim is a
// genuine new mint with a new owner). RenewName/RenewDomain deliberately
// do NOT call this — an already-registered name must keep renewing under
// whatever rule was in force when it was minted.
func validateLabel(label string) {
	minLen, maxLen := nsdata.GetLabelLength()
	if len(label) < minLen || len(label) > maxLen {
		panic(ufmt.Sprintf("nslogic: label must be %d-%d characters", minLen, maxLen))
	}
	// Structural invariant, enforced regardless of what the pattern
	// happens to allow: "*" is the separator in both the token ID
	// (label*domain) and nsdata's storage key (domain*label). A label or
	// domain containing one would make those encodings ambiguous and let
	// two different names collide onto a single record.
	if strings.Contains(label, "*") {
		panic("nslogic: label may not contain '*'")
	}
	if !matchesLabelRule(label) {
		panic("nslogic: a name is lowercase letters, digits and single hyphens between them — " + labelRule)
	}
	if looksLikeAddress(label) {
		panic("nslogic: label looks like a wallet address, not allowed")
	}
}
